/// Opens the contact-info / chat-settings screen from an open chat.
///
/// By tapping the NAME, which is the only route now: the overflow menu that
/// used to carry "Contact & chat settings" is gone from the chat's bar.
Future<void> openChatSettings(WidgetTester tester) async {
  // The header avatar carries a distinguishing heroTag — needed since the
  // Messenger-style per-message avatars mean UserAvatar can now also appear
  // in the transcript, so `.first` is no longer reliably the header's.
  await tester.tap(find.byWidgetPredicate(
      (w) => w is UserAvatar && w.heroTag == 'chatHeaderAvatar'));
  await tester.pumpAndSettle();
}

/// Scrolls the contact-info ListView until [finder] is on screen, then taps
/// it — the chat-settings tiles live below the fold.
Future<void> tapInSettings(WidgetTester tester, Finder finder) async {
  await tester.scrollUntilVisible(finder, 120,
      scrollable: find.byType(Scrollable).first);
  await tester.pumpAndSettle();
  await tester.tap(finder);
  await tester.pumpAndSettle();
}

/// Opens Settings the way the app does now that the profile left the bottom
/// bar: through the drawer's Settings row (its gear used to be the You tab's).
Future<void> openSettingsForTest(WidgetTester tester) async {
  await tester.tap(find.byTooltip('Open navigation menu'));
  await tester.pumpAndSettle();
  final settings = find.text('Settings');
  await tester.scrollUntilVisible(settings, 120,
      scrollable: find.descendant(
          of: find.byType(Drawer), matching: find.byType(Scrollable)));
  await tester.pumpAndSettle();
  await tester.tap(settings);
  await tester.pumpAndSettle();
}

/// Opens the You/profile tab through the drawer's profile card — its bottom
/// pill is gone, so the card at the top of the drawer is the way in.
Future<void> openYouTabForTest(WidgetTester tester) async {
  await tester.tap(find.byTooltip('Open navigation menu'));
  await tester.pumpAndSettle();
  await tester.tap(find
      .descendant(of: find.byType(Drawer), matching: find.byType(InkWell))
      .first);
  await tester.pumpAndSettle();
}

/// Switches to the Servers tab through the drawer's Servers row — it left the
/// bottom bar for the drawer, so this is the way in.
Future<void> openServersTabForTest(WidgetTester tester) async {
  await tester.tap(find.byTooltip('Open navigation menu'));
  await tester.pumpAndSettle();
  // The drawer is a scrolling list; on a short viewport the Servers row can sit
  // below the fold, so bring it into view before tapping — the same thing a
  // person does.
  await tester.dragUntilVisible(
    find.text('Servers'),
    find.byType(ListView).first,
    const Offset(0, -120),
  );
  await tester.pumpAndSettle();
  await tester.tap(find.text('Servers'));
  await tester.pumpAndSettle();
}

void main() {
  // Singletons persist across tests; reset them so each starts clean. Most
  // tests assume a signed-in user so they land on the home screen; the
  // phone-login test signs out first.
  setUp(() {
    SharedPreferences.setMockInitialValues({});
    ChatStore.instance.reset();
    AppState.resetForTest();
    Session.instance.signInForTest();
    // Most tests assume the current terms are already accepted; the consent
    // tests reset this themselves.
    LegalConsent.instance.resetForTest();
    Scheduler.instance.resetForTest();
    CallService.instance.resetForTest();
    // A live Timer.periodic that outlives the test fails flutter_test's own
    // "no pending Timer" invariant, and addTearDown-registered cleanup runs
    // too late to satisfy it — see CallService.debugDisableMailboxPoll's own
    // doc comment. Off for the whole suite except the handful of tests that
    // explicitly re-enable it to exercise the poll itself.
    CallService.debugDisableMailboxPoll = true;
    AppLock.instance.resetForTest();
    CommunityStore.instance.resetForTest();
    ChatsTab.filtersVisible.value = false;
    LiveLocationStore.instance.resetForTest();
    SavedPlacesStore.instance.resetForTest();
    // Plugin platform channels never complete inside the fake-async test
    // zone, so resolve GPS lookups immediately (with no fix) in tests.
    debugGeolocationOverride = () async => null;
    // The cancellable (dio) tile provider leaves timeout timers pending in
    // the test zone — use the plain provider, whose requests 400 instantly.
    debugTileProviderOverride = NetworkTileProvider.new;
    FollowStore.instance.resetForTest();
    FeedStore.instance.resetForTest();
    PublicFeedAlerts.instance.resetForTest();
    FavouritesStore.instance.resetForTest();
    // Treat the new-user nudge as already dismissed so it doesn't overlay
    // unrelated Chats-tab tests; the onboarding test opts back in.
    OnboardingStore.instance.markDoneForTest();
  });

  testWidgets('App boots with Chats and Calls tabs (no Status)',
      (tester) async {
    await tester.pumpWidget(const OkayMessagingApp());
    await tester.pumpAndSettle();

    // Chats wears the MARK, not the app's name — the name moved to the top
    // of the sidebar (the owner's call), so it is nowhere on this screen.
    expect(
        find.descendant(
            of: find.byType(AppBar), matching: find.byType(BrandMark)),
        findsOneWidget);
    expect(find.text('OkayMessenger'), findsNothing);
    // Every pill wears its label under the icon now; Chats is the only pill
    // named 'Chats', so still exactly one.
    expect(find.text('Chats'), findsOneWidget);
    expect(find.text('Status'), findsNothing);

    // The Calls destination exists; selecting it reveals its label (and the
    // app bar title also reads "Calls", so it appears more than once).
    expect(find.byIcon(Icons.call_outlined), findsOneWidget);
    await tester.tap(find.byIcon(Icons.call_outlined));
    await tester.pumpAndSettle();
    expect(find.text('Calls'), findsWidgets);

    // The profile is no longer a bottom pill; it opens from the drawer card,
    // and the app bar then titles it "You".
    await openYouTabForTest(tester);
    expect(find.text('You'), findsWidgets);
  });

