  group('Links become cards, and YouTube plays', () {
    test('a YouTube id is read from every shape of its URL', () {
      const id = 'dQw4w9WgXcQ';
      for (final url in [
        'https://www.youtube.com/watch?v=$id',
        'https://youtube.com/watch?v=$id&t=42',
        'https://youtu.be/$id',
        'https://www.youtube.com/shorts/$id',
        'https://m.youtube.com/watch?v=$id',
      ]) {
        expect(youtubeIdOf(Uri.parse(url)), id, reason: url);
      }
      // Shape-checked, so a path that is not an id cannot become a dead
      // player.
      expect(youtubeIdOf(Uri.parse('https://youtube.com/shorts/about')), '');
      expect(youtubeIdOf(Uri.parse('https://example.com/watch?v=$id')), '');
    });

    test('a reel is recognised, and is honestly not playable', () {
      final reel = Uri.parse('https://www.instagram.com/reel/Cxyz123/');
      expect(linkKindOf(reel), LinkKind.reel);
      // The card must not offer a play button for something that will
      // hand the viewer to another app.
      expect(
          const LinkPreview(url: 'x', kind: LinkKind.reel).playable, isFalse);
      expect(
          const LinkPreview(
                  url: 'x', kind: LinkKind.youtube, videoId: 'dQw4w9WgXcQ')
              .playable,
          isTrue);
    });

    test('the first link is found, and trailing punctuation is not part of it',
        () {
      expect(firstLinkIn('see https://example.com/a. thanks')?.toString(),
          'https://example.com/a');
      expect(firstLinkIn('no links here'), isNull);
      // One card per message: the first link is the one somebody meant.
      expect(firstLinkIn('https://a.com and https://b.com')?.host, 'a.com');
    });

    test('Open Graph is read out of real-shaped markup', () {
      const html = '''
        <html><head>
        <meta name="twitter:card" content="summary">
        <meta content="A title" property="og:title">
        <meta property='og:image' content='https://x.test/i.jpg'>
        <title>Fallback &amp; ignored</title>
        </head></html>''';
      final og = parseOpenGraph(html);
      // Attributes in either order, either quote style, and entities
      // unescaped.
      expect(og['og:title'], 'A title');
      expect(og['og:image'], 'https://x.test/i.jpg');
      // <title> only fills in when og:title is absent.
      const bare = '<html><head><title>Only &quot;this&quot;</title></head>';
      expect(parseOpenGraph(bare)['og:title'], 'Only "this"');
    });

    test('the preview is built by the SENDER, and embeds its thumbnail',
        () async {
      LinkPreviewService.debugFetchHtml = (url) async =>
          '<meta property="og:title" content="Never Gonna">';
      LinkPreviewService.debugFetchBytes =
          (url) async => Uint8List.fromList([1, 2, 3, 4]);
      addTearDown(() {
        LinkPreviewService.debugFetchHtml = null;
        LinkPreviewService.debugFetchBytes = null;
      });

      final preview = await LinkPreviewService.instance
          .forText('watch this https://youtu.be/dQw4w9WgXcQ');
      expect(preview, isNotNull);
      expect(preview!.kind, LinkKind.youtube);
      expect(preview.videoId, 'dQw4w9WgXcQ');
      expect(preview.title, 'Never Gonna');
      // A data URI, never a remote URL — the recipient's device must not
      // have to fetch anything to draw the card.
      expect(preview.thumbnail.startsWith('data:image/'), isTrue);
      expect(LinkPreview.decode(preview.encode())!.videoId, 'dQw4w9WgXcQ');
    });

    test('a page that says nothing gets no card at all', () async {
      LinkPreviewService.debugFetchHtml = (url) async => '<html></html>';
      addTearDown(() => LinkPreviewService.debugFetchHtml = null);
      // A rectangle saying only "example.com" is worse than the blue link
      // it would replace.
      expect(
          await LinkPreviewService.instance.forUrl(
              Uri.parse('https://example.com/a')),
          isNull);
    });

    testWidgets('the card sits under the words, never instead of them',
        (tester) async {
      const preview = LinkPreview(
        url: 'https://youtu.be/dQw4w9WgXcQ',
        kind: LinkKind.youtube,
        title: 'Never Gonna',
        host: 'youtu.be',
        videoId: 'dQw4w9WgXcQ',
      );
      var played = 0;
      await tester.pumpWidget(MaterialApp(
        home: Scaffold(
          body: MessageBubble(
            message: Message(
              id: 'm1',
              text: 'look at this https://youtu.be/dQw4w9WgXcQ',
              time: DateTime(2026, 8, 14),
              isMe: false,
              linkPreview: preview.encode(),
            ),
            onPlayVideo: () => played++,
          ),
        ),
      ));
      await tester.pump();
      expect(find.textContaining('look at this'), findsOneWidget);
      expect(find.text('Never Gonna'), findsOneWidget);
      expect(find.text('Play'), findsOneWidget);
      await tester.tap(find.byType(LinkPreviewCard));
      await tester.pump();
      expect(played, 1);
    });
  });

  group('A profile says when they joined and how they are verified', () {
    setUp(AccountVerification.resetForTest);
    tearDown(AccountVerification.resetForTest);

    test('the three facts ride the profile and are applied as sent', () {
      ChatStore.instance.reset();
      addTearDown(ChatStore.instance.reset);
      final bob = ChatStore.instance.chatWithContact('u_bob')!;
      final joined = DateTime(2026, 3, 2);
      ChatStore.instance.updateContactProfile(bob.contact.id,
          joinedAt: joined, phoneVerified: true, emailVerified: true);
      var c = ChatStore.instance.chatById(bob.id)!.contact;
      expect(c.joinedAt, joined);
      expect(c.phoneVerified, isTrue);

      // Applied AS SENT, like the business flag: an account that stops
      // being email-verified has to clear on other people's devices.
      ChatStore.instance
          .updateContactProfile(bob.contact.id, emailVerified: false);
      c = ChatStore.instance.chatById(bob.id)!.contact;
      expect(c.emailVerified, isFalse);
      // But a message from an older build carries none of it, and must not
      // erase a join date it never knew about.
      ChatStore.instance.updateContactProfile(bob.contact.id, name: 'Bob');
      expect(ChatStore.instance.chatById(bob.id)!.contact.joinedAt, joined);
    });

    test('a join date survives the profile round trip', () {
      const u = AppUser(
          id: 'u',
          name: 'Ada',
          avatarColor: '#000000',
          phoneVerified: true,
          emailVerified: true);
      final back = AppUser.fromJson(u.toJson());
      expect(back.phoneVerified, isTrue);
      expect(back.emailVerified, isTrue);
      // Absent rather than invented on an account that predates the field.
      expect(back.joinedAt, isNull);
    });

    testWidgets('a stranger shows nothing rather than three grey chips',
        (tester) async {
      // The directory carries none of this, so claiming "not verified"
      // about somebody would be a finding about US, not about them.
      await tester.pumpWidget(const MaterialApp(
          home: Scaffold(body: ProfileTrust(user: null, isMe: false))));
      await tester.pump();
      expect(find.textContaining('verified'), findsNothing);
      expect(find.textContaining('Joined'), findsNothing);
    });

    test('the join date reads as a month, never a day', () {
      // X's line, and the reason it is a static rather than inline in the
      // widget: the metadata row draws it now, and only ProfileTrust
      // decides who is allowed to know it.
      expect(
          ProfileTrust.joinedLabel(DateTime(2026, 3, 2)), 'Joined March 2026');
      const ada = AppUser(id: 'u', name: 'Ada', avatarColor: '#000000');
      expect(ProfileTrust.joinedFor(user: ada, isMe: false), isNull);
      expect(ProfileTrust.joinedFor(user: null, isMe: false), isNull);
    });

    testWidgets('a contact shows marks only for what they actually proved',
        (tester) async {
      await tester.pumpWidget(const MaterialApp(
        home: Scaffold(
          body: ProfileTrust(
            isMe: false,
            user: AppUser(
              id: 'u_ada',
              name: 'Ada',
              avatarColor: '#000000',
              phoneVerified: true,
              verified: true,
            ),
          ),
        ),
      ));
      await tester.pump();
      // By TOOLTIP, not by text: these are three green glyphs beside the
      // name now, not three "Phone verified" chips (2026-08-15). The word is
      // still the tooltip and therefore still the semantics name, which is
      // the whole reason an icon here is not a loss — so pinning the tooltip
      // pins the accessible label too.
      expect(find.byTooltip('Phone verified'), findsOneWidget);
      expect(find.byTooltip('ID verified'), findsOneWidget);
      // Not claimed, so not drawn — never as a grey "unverified" glyph.
      expect(find.byTooltip('Email verified'), findsNothing);
      // And no words: the row is glyphs, or the chips came back.
      expect(find.byType(Text), findsNothing);
    });
  });

  group('Choosing the app icon', () {
    tearDown(() {
      AppIconStore.debugChannelOverride = null;
      AppIconStore.instance.resetForTest();
    });

    test('every icon is a pair somebody can actually find on a home screen',
        () {
      // The same rule the QR presets follow, and the reason there is no free
      // colour picker here: an icon is read at about forty points among a
      // hundred others, so a tile and a bubble that do not separate is an app
      // nobody can find. Measured, not eyeballed — nobody here can look at a
      // home screen.
      for (final o in appIconOptions) {
        expect(o.contrast, greaterThanOrEqualTo(4.5),
            reason: '${o.name} is ${o.contrast.toStringAsFixed(1)}:1');
      }
      // Distinct names, distinct ids, and exactly one default.
      expect(appIconOptions.map((o) => o.id).toSet().length,
          appIconOptions.length);
      expect(appIconOptions.where((o) => o.id.isEmpty), hasLength(1));
      expect(appIconOptions.first.id, isEmpty,
          reason: 'the shipped icon leads the list');
    });

    test('the default is never named as an alternate', () {
      // setAlternateIconName(nil) is the primary icon. Handing iOS the string
      // "AppIcon" instead would be naming a set that is not an alternate,
      // which fails — and would fail silently on the home screen.
      expect(appIconOptions.first.bundleName, '');
      expect(appIconFor('').id, isEmpty);
      expect(appIconFor('AppIcon-Ocean').name, 'Ocean');
      // A name from a NEWER build reads as the default rather than as no
      // selection at all.
      expect(appIconFor('AppIcon-FromTheFuture').id, isEmpty);
    });

    test('the generator paints through the app bar\'s own mask', () {
      // The icon and the app-bar mark are the same artwork through the same
      // ramp. Two copies of the arithmetic would drift the first time either
      // moved, so the tool's constants are pinned against BrandMark's.
      expect(icons.maskGain, BrandMark.gain);
      expect(icons.maskBias, BrandMark.bias);
      expect(icons.lumR, BrandMark.lumR);
      expect(icons.lumG, BrandMark.lumG);
      expect(icons.lumB, BrandMark.lumB);
      // White is all bubble, the tile colour is all tile — the two ends the
      // gain and bias exist to force. #101820 is the real tile, about 9%
      // luminance, which plain luminance alone would leave as a ghost.
      expect(icons.bubbleAt(255, 255, 255), 1);
      expect(icons.bubbleAt(0x10, 0x18, 0x20), 0);
    });

    test('a recoloured icon is opaque and carries the pair it was given', () {
      final src = img.Image(width: 2, height: 1, numChannels: 3)
        ..setPixelRgb(0, 0, 0x10, 0x18, 0x20) // tile
        ..setPixelRgb(1, 0, 255, 255, 255); // bubble
      const ocean =
          AppIconOption(id: 'Ocean', name: 'Ocean', tile: 0x0B3D5C, bubble: 0xFFFFFF);
      final out = icons.recolour(src, ocean);
      // Three channels, no alpha. Apple says so outright for an app icon, and
      // a PNG written from an image that still HAS an alpha channel is not
      // flattened even when every pixel in it is opaque.
      expect(out.numChannels, 3);
      final tile = out.getPixel(0, 0);
      expect([tile.r.toInt(), tile.g.toInt(), tile.b.toInt()],
          [0x0B, 0x3D, 0x5C]);
      final bubble = out.getPixel(1, 0);
      expect([bubble.r.toInt(), bubble.g.toInt(), bubble.b.toInt()],
          [255, 255, 255]);
    });

    test('every alternate is generated, declared to Xcode, and complete', () {
      // Three files have to agree or the icon silently does not exist: the
      // asset catalog, the build setting that tells the compiler these sets
      // are alternates, and the Dart list the picker draws from.
      final pbx =
          File('ios/Runner.xcodeproj/project.pbxproj').readAsStringSync();
      for (final option in appIconOptions) {
        if (option.id.isEmpty) continue;
        final dir = Directory(
            'ios/Runner/Assets.xcassets/${option.bundleName}.appiconset');
        expect(dir.existsSync(), isTrue,
            reason: '${option.bundleName} was never generated — run '
                'dart run tool/build_app_icons.dart');
        final contents = File('${dir.path}/Contents.json').readAsStringSync();
        for (final slot in icons.slots) {
          final name = slot.fileName(option.id);
          expect(contents, contains(name));
          expect(File('${dir.path}/$name').existsSync(), isTrue,
              reason: '$name is named in Contents.json and is not there');
        }
        // An alternate set must NOT claim the App Store slot; the listing
        // shows the primary icon.
        expect(contents, isNot(contains('ios-marketing')));
        expect(pbx, contains('"${option.bundleName}"'),
            reason: '${option.bundleName} exists but no build configuration '
                'declares it, so iOS would refuse it at runtime');
      }
      // All three Runner configurations, not just Release — a Debug build
      // that cannot change its icon is a bug nobody would find until they
      // tried it on a device.
      expect('ASSETCATALOG_COMPILER_ALTERNATE_APPICON_NAMES'.allMatches(pbx),
          hasLength(3));
      expect(
          'ASSETCATALOG_COMPILER_INCLUDE_ALL_APPICON_ASSETS = YES;'
              .allMatches(pbx),
          hasLength(3));
    });

    testWidgets('the picker offers every icon and asks the platform for one',
        (t) async {
      final asked = <String>[];
      AppIconStore.debugChannelOverride = (method, args) async {
        switch (method) {
          case 'available':
            return true;
          case 'current':
            return '';
          case 'set':
            asked.add(args['name'] as String? ?? '');
            return true;
        }
        return null;
      };
      await t.pumpWidget(const MaterialApp(home: AppIconScreen()));
      await t.pumpAndSettle();

      for (final o in appIconOptions) {
        expect(find.text(o.name), findsOneWidget);
      }
      await t.tap(find.text('Ocean'));
      await t.pumpAndSettle();
      expect(asked, ['AppIcon-Ocean']);
      expect(AppIconStore.instance.current.name, 'Ocean');

      // Picking the one already in use asks the platform nothing.
      await t.tap(find.text('Ocean'));
      await t.pumpAndSettle();
      expect(asked, ['AppIcon-Ocean']);
    });

    testWidgets('a refused change leaves the selection where it was',
        (t) async {
      // A failure here is invisible on the home screen, so the app has to say
      // so — and must not move the tick to an icon that was never applied.
      AppIconStore.debugChannelOverride = (method, args) async =>
          method == 'available' ? true : (method == 'current' ? '' : false);
      await t.pumpWidget(const MaterialApp(home: AppIconScreen()));
      await t.pumpAndSettle();
      await t.tap(find.text('Ember'));
      await t.pumpAndSettle();
      expect(AppIconStore.instance.current.id, isEmpty);
      expect(find.text("Couldn't change the icon"), findsOneWidget);
    });

    testWidgets('a build with no home screen says so rather than pretending',
        (t) async {
      AppIconStore.debugChannelOverride = (method, args) async =>
          method == 'available' ? false : null;
      await t.pumpWidget(const MaterialApp(home: AppIconScreen()));
      await t.pumpAndSettle();
      expect(find.textContaining('works on iPhone'), findsOneWidget);
      // The grid still draws — it is what the icons look like — but nothing
      // in it does anything.
      await t.tap(find.text('Forest'));
      await t.pumpAndSettle();
      expect(AppIconStore.instance.current.id, isEmpty);
    });

    test('the Swift side needs no availability guard, and says why', () {
      // setAlternateIconName is iOS 10.3, far under the 15 floor — but two
      // archives have already been lost to an unguarded newer API, so the
      // reasoning is in the file rather than in somebody's head.
      final swift = File('ios/Runner/AppIcon.swift').readAsStringSync();
      expect(swift, contains('setAlternateIconName'));
      expect(swift, contains('supportsAlternateIcons'));
      // The GUARD, not the word: the file's own comment says "#available"
      // while explaining why there is none, and banning the word would fail
      // on the explanation rather than on a mistake.
      expect(swift, isNot(contains('if #available')));
      expect(swift, contains('iOS 15 floor'),
          reason: 'the reasoning is written down, not remembered');
      // Registered, or the channel answers nothing on a real device.
      expect(File('ios/Runner/AppDelegate.swift').readAsStringSync(),
          contains('OkayAppIcon.register'));
    });
  });

  group('Customizing the QR card', () {
    setUp(() {
      SharedPreferences.setMockInitialValues({});
      QrStyleStore.instance.resetForTest();
    });
    tearDown(QrStyleStore.instance.resetForTest);

    test('every preset stays scannable', () {
      // The whole safety of the feature: presets are authored as PAIRS, so
      // there is no way to pick a beautiful code no camera can read. A
      // scanner needs nearer 3:1 than text's 4.5:1 — held to the higher bar
      // because a code gets read in bad light, at an angle, through a
      // scratched lens.
      for (final s in qrStyles) {
        expect(s.contrast, greaterThanOrEqualTo(4.5),
            reason: '${s.name} is not contrasty enough to scan');
      }
      // Ids are what gets persisted, so a duplicate would silently make one
      // preset unreachable.
      expect(qrStyles.map((s) => s.id).toSet(), hasLength(qrStyles.length));
      // The default is the plain one: somebody who never opens the picker
      // still gets the most scannable code there is.
      expect(qrStyles.first.id, 'classic');
      expect(qrStyles.first.module, const Color(0xFF0F1419));
    });

    test('the ink on a card is chosen by the card, not the app theme', () {
      expect(qrStyleById('ink').wantsLightInk, isTrue);
      expect(qrStyleById('sand').wantsLightInk, isFalse);
    });

    test('a style saved by a newer build falls back, never blanks', () {
      expect(qrStyleById('a-look-from-the-future').id, 'classic');
      expect(QrModuleShape.fromId('hexagons'), QrModuleShape.square);
    });

    test('the chosen look persists and comes back', () async {
      await QrStyleStore.instance.load();
      expect(QrStyleStore.instance.style.id, 'classic');
      await QrStyleStore.instance.setStyle(qrStyleById('ocean'));
      await QrStyleStore.instance.setShape(QrModuleShape.round);
      await QrStyleStore.instance.setShowAvatar(false);

      QrStyleStore.instance.resetForTest();
      await QrStyleStore.instance.load();
      expect(QrStyleStore.instance.style.id, 'ocean');
      expect(QrStyleStore.instance.shape, QrModuleShape.round);
      expect(QrStyleStore.instance.showAvatar, isFalse);
    });

    testWidgets(
        'picking a look repaints the card, and what the code SAYS never '
        'changes with it', (tester) async {
      const me = AppUser(
          id: '+1 555 0143',
          name: 'Ada',
          avatarColor: '#64B5F6',
          phone: '+1 555 0143',
          username: 'ada');
      AppState.profile.value = me;
      addTearDown(AppState.resetForTest);
      final before = MyQrScreen.payloadFor(me);

      await tester.pumpWidget(const MaterialApp(home: MyQrScreen()));
      await tester.pumpAndSettle();
      QrImageView code() =>
          tester.widget<QrImageView>(find.byType(QrImageView));
      expect(code().dataModuleStyle.color, qrStyleById('classic').module);

      // The fourth swatch is Forest; a swatch is the only way to change it.
      await tester.tap(find.byType(GestureDetector).at(3));
      await tester.pumpAndSettle();
      expect(code().dataModuleStyle.color, qrStyleById('forest').module);
      expect(QrStyleStore.instance.style.id, 'forest');

      // Colour is paint. The payload is untouched by all of it.
      expect(MyQrScreen.payloadFor(me), before);
    });

    testWidgets('the code carries the highest error correction, photo or not',
        (tester) async {
      AppState.profile.value = const AppUser(
          id: '+1 555 0144',
          name: 'Ada',
          avatarColor: '#64B5F6',
          phone: '+1 555 0144');
      addTearDown(AppState.resetForTest);
      await tester.pumpWidget(const MaterialApp(home: MyQrScreen()));
      await tester.pumpAndSettle();
      QrImageView code() =>
          tester.widget<QrImageView>(find.byType(QrImageView));
      // Cutting a hole in the middle for the photo is only safe because of
      // this, and it is set unconditionally — so turning the photo off can
      // never leave a code that had been relying on it.
      expect(code().errorCorrectionLevel, QrErrorCorrectLevel.H);

      await tester.tap(find.byType(Switch));
      await tester.pumpAndSettle();
      expect(QrStyleStore.instance.showAvatar, isFalse);
      expect(code().errorCorrectionLevel, QrErrorCorrectLevel.H);
    });
  });

  group('Planning a meeting in chat', () {
    Message meeting({
      DateTime? at,
      Map<String, int> votesBy = const {},
      int myVote = -1,
      String place = '',
    }) =>
        Message(
          id: 'meet_1',
          text: '',
          time: DateTime(2026, 8, 14, 9),
          isMe: false,
          isMeeting: true,
          meetingTitle: 'Coffee',
          meetingAt: at ?? DateTime(2026, 8, 20, 15),
          meetingPlace: place,
          isPoll: true,
          pollOptions: MeetingRsvp.options,
          pollVotes: const [0, 0, 0],
          pollVotesBy: votesBy,
          pollMyVote: myVote,
        );

    test('an RSVP is a poll vote, so it moves rather than duplicating', () {
      ChatStore.instance.reset();
      final bob = ChatStore.instance.chatWithContact('u_bob')!;
      ChatStore.instance.addMessage(bob.id, meeting());

      // Going, then Can't — the poll machinery underneath does the work,
      // which is the whole reason a meeting is built as a poll.
      ChatStore.instance.votePoll(bob.id, 'meet_1', MeetingRsvp.going.index,
          voter: '15550100');
      ChatStore.instance.votePoll(bob.id, 'meet_1', MeetingRsvp.cant.index,
          voter: '15550100');
      // Someone else says yes.
      ChatStore.instance.applyRemotePollVote(
          bob.id, 'meet_1', MeetingRsvp.going.index, -1,
          voter: '15550142');

      final m = ChatStore.instance
          .chatById(bob.id)!
          .messages
          .firstWhere((x) => x.id == 'meet_1');
      expect(m.pollVotesBy, {'15550100': 2, '15550142': 0});
      final counts = meetingRsvpCounts(m.pollVotesBy);
      expect(counts[MeetingRsvp.going.index], 1);
      expect(counts[MeetingRsvp.cant.index], 1);
      expect(counts[MeetingRsvp.maybe.index], 0);
    });

    test('the headcount counts people, never a weighted tally', () {
      // A group admin's vote can weigh two when the room is DECIDING
      // something; "3 going" has to mean three people.
      final counts = meetingRsvpCounts(const {'a': 0, 'b': 0, 'c': 1});
      expect(counts, [2, 1, 0]);
      // An option outside the three is ignored rather than counted.
      expect(meetingRsvpCounts(const {'a': 9}), [0, 0, 0]);
    });

    test('a reminder is only scheduled when there is time left for one', () {
      final now = DateTime(2026, 8, 20, 12);
      expect(meetingReminderAt(DateTime(2026, 8, 20, 15), now: now),
          DateTime(2026, 8, 20, 14, 30));
      // Ten minutes away: the lead time is already gone, and iOS delivers a
      // past trigger instantly, which reads as a bug rather than a reminder.
      expect(meetingReminderAt(DateTime(2026, 8, 20, 12, 10), now: now),
          isNull);
    });

    test('a meeting says it is a meeting, never a poll', () {
      final m = meeting();
      // It really is a poll underneath, so the order of these checks in
      // typeLabel is load-bearing.
      expect(m.isPoll, isTrue);
      expect(m.typeLabel, '📅 Meeting');
      expect(m.previewLabel, '📅 Coffee');
    });

    test('what a meeting is survives the round trip', () {
      final json = meeting(place: 'The corner place').toJson();
      final back = Message.fromJson(json);
      expect(back.isMeeting, isTrue);
      expect(back.meetingTitle, 'Coffee');
      expect(back.meetingAt, DateTime(2026, 8, 20, 15));
      expect(back.meetingPlace, 'The corner place');
      // And a message from before this existed decodes as not-a-meeting
      // rather than throwing.
      expect(
          Message.fromJson({
            'id': 'x',
            'text': 'hi',
            'isMe': false,
            'time': DateTime(2026, 8, 1).toIso8601String(),
          }).isMeeting,
          isFalse);
    });

    testWidgets('the card draws when, where and the three answers',
        (tester) async {
      await tester.pumpWidget(MaterialApp(
        home: Scaffold(
          body: MessageBubble(
            message: meeting(
                at: DateTime.now().add(const Duration(days: 2)),
                place: 'The corner place',
                votesBy: const {'a': 0, 'b': 0, 'c': 1}),
            onPollVote: (_) {},
            onShowMeetingGuests: () {},
          ),
        ),
      ));
      await tester.pump();
      expect(find.text('Meeting'), findsOneWidget);
      expect(find.text('Coffee'), findsOneWidget);
      expect(find.text('The corner place'), findsOneWidget);
      expect(find.text('Going 2'), findsOneWidget);
      expect(find.text('Maybe 1'), findsOneWidget);
      expect(find.text("Can't"), findsOneWidget);
      expect(find.textContaining('2 people are going'), findsOneWidget);
      // A poll bubble would have drawn instead if the meeting branch were
      // not checked first — it carries pollOptions either way.
      expect(find.byType(PollBubble), findsNothing);
    });

    testWidgets('a meeting already past keeps the record and drops the buttons',
        (tester) async {
      await tester.pumpWidget(MaterialApp(
        home: Scaffold(
          body: MessageBubble(
            message: meeting(
                at: DateTime.now().subtract(const Duration(days: 1)),
                votesBy: const {'a': 0}),
            onPollVote: (_) => fail('a past meeting cannot be answered'),
          ),
        ),
      ));
      await tester.pump();
      expect(find.text('Meeting · past'), findsOneWidget);
      expect(find.text('1 going'), findsOneWidget);
      expect(find.text('Going'), findsNothing);
    });

    testWidgets('planning one from the attachment panel sends it and asks '
        'for a reminder', (tester) async {
      SharedPreferences.setMockInitialValues({});
      ChatStore.instance.reset();
      Session.instance.signInForTest();
      final scheduled = <String, ({String title, String body, DateTime at})>{};
      PushService.debugScheduled = scheduled;
      addTearDown(() {
        PushService.debugScheduled = null;
        ChatStore.instance.reset();
      });
      const contact = AppUser(
          id: '+1 555 0199',
          name: 'Iman',
          avatarColor: '#64B5F6',
          phone: '+1 555 0199');
      ChatStore.instance
          .upsert(const Chat(id: 'chat_meet', contact: contact, messages: []));
      await tester.pumpWidget(MaterialApp(
          home: ChatScreen(chat: ChatStore.instance.chatById('chat_meet')!)));
      await tester.pumpAndSettle();

      await tester.tap(find.byTooltip('Attach'));
      await tester.pumpAndSettle();
      await tester.tap(find.text('Meeting'));
      await tester.pumpAndSettle();
      // Scoped to the sheet: the chat's own composer is a TextField too, and
      // typing into that one leaves the meeting nameless and the button off.
      await tester.enterText(
          find
              .descendant(
                  of: find.byType(MeetingComposerSheet),
                  matching: find.byType(TextField))
              .first,
          'Standup');
      await tester.pump();
      await tester.tap(find.text('Send meeting'));
      await tester.pumpAndSettle();

      final sent = ChatStore.instance
          .chatById('chat_meet')!
          .messages
          .lastWhere((m) => m.isMeeting);
      expect(sent.meetingTitle, 'Standup');
      // It carries the poll underneath — that is how an RSVP travels.
      expect(sent.isPoll, isTrue);
      expect(sent.pollOptions, MeetingRsvp.options);
      // Whoever planned it is reminded without having to RSVP to their own
      // meeting. The default is tomorrow, so there is time for one.
      expect(scheduled['meet_${sent.id}']?.title, 'Standup');
    });

    testWidgets('the composer refuses a meeting with no name', (tester) async {
      await tester.pumpWidget(const MaterialApp(
          home: Scaffold(body: MeetingComposerSheet())));
      await tester.pump();
      VoidCallback? button() => tester
          .widget<FilledButton>(
              find.widgetWithText(FilledButton, 'Send meeting'))
          .onPressed;
      expect(button(), isNull);
      await tester.enterText(find.byType(TextField).first, 'Standup');
      await tester.pump();
      expect(button(), isNotNull);
    });
  });

