  group('Call signaling', () {
    setUp(() => CallService.instance.resetForTest());

    AppUser peer() => const AppUser(
          id: '+1 555 0199',
          name: 'Grace',
          avatarColor: '#64B5F6',
          about: 'Available',
          phone: '+1 555 0199',
        );

    test('outgoing call is ringing, then connects when the peer answers', () {
      final call = CallService.instance;
      call.startOutgoing(peer(), video: false);
      expect(call.current.value?.status, CallStatus.ringing);
      expect(call.isBusy, isTrue);

      call.onRemoteAnswer(call.current.value!.callId);
      expect(call.current.value?.status, CallStatus.connected);
      expect(call.current.value?.connectedAt, isNotNull);
    });

    test('call ids carry real entropy, not a predictable counter', () {
      // Closes the bootstrap-hole follow-up in docs/call_presence.sql: the
      // old id shape ('call_${digits}_${epochMs}_${seq}') was guessable
      // within a narrow window. The new suffix is 128 bits from
      // Random.secure() — 32 hex characters — so every id, even ones minted
      // back-to-back inside the same test run, must both match that shape
      // and never repeat.
      final call = CallService.instance;
      final ids = <String>{};
      for (var i = 0; i < 20; i++) {
        call.startOutgoing(peer(), video: false);
        final id = call.current.value!.callId;
        expect(RegExp(r'^call_\d+_\d+_[0-9a-f]{32}$').hasMatch(id), isTrue,
            reason: 'unexpected call id shape: $id');
        ids.add(id);
        call.resetForTest();
      }
      expect(ids.length, 20,
          reason: 'every call id must be unique, even generated in rapid '
              'succession within the same millisecond');
    });

    test('a declined outgoing call moves to declined', () {
      final call = CallService.instance;
      call.startOutgoing(peer(), video: true);
      call.onRemoteDecline(call.current.value!.callId);
      expect(call.current.value?.status, CallStatus.declined);
    });

    test('a busy reply moves an outgoing call to busy, distinctly from '
        'declined', () {
      final call = CallService.instance;
      call.startOutgoing(peer(), video: true);
      call.onRemoteBusy(call.current.value!.callId);
      expect(call.current.value?.status, CallStatus.busy);
    });

    test(
        'an offer arriving while already on a call is refused with a real '
        'busy signal and files a missed-call record, not a silent drop',
        () {
      CallLog.instance.resetForTest();
      ChatStore.instance.clearAll();
      final call = CallService.instance;
      // Already on a call with Grace.
      call.onRemoteOffer(peer(), 'call_first', false);
      expect(call.current.value?.callId, 'call_first');

      // Someone else calls in the meantime.
      const other = AppUser(
        id: '+1 555 0177',
        name: 'Miles',
        avatarColor: '#81C784',
        about: 'Available',
        phone: '+1 555 0177',
      );
      call.onRemoteOffer(other, 'call_second', false);

      // The live call is untouched — the second offer never became current.
      expect(call.current.value?.callId, 'call_first');

      // But it's not as if nothing happened: Miles gets a call-log entry
      // and a chat record, both distinct from an ordinary missed call.
      expect(
          CallLog.instance.records.any((r) => r.id == 'call_second'), isTrue,
          reason: 'being called while busy must leave a trace, not vanish');
      final chat = ChatStore.instance.chatWithContact('+1 555 0177');
      expect(chat, isNotNull);
      final busyMsg =
          chat!.messages.firstWhere((m) => m.id == 'callmsg_call_second');
      expect(busyMsg.callEvent, 'busy');
      expect(busyMsg.isMe, isFalse);
    });

    test(
        'a mailbox poll runs while a call is active, as a backstop against a '
        'silently-dead live channel — the same failure class the server '
        'feed already needed pull-to-refresh for', () {
      // The suite disables this globally (see the global setUp) because a
      // live Timer.periodic left running past the end of a testWidgets test
      // fails flutter_test's own invariant check — re-enabled here since
      // this test means to exercise the real thing, and it's a plain test()
      // with no such binding to trip.
      CallService.debugDisableMailboxPoll = false;
      addTearDown(() => CallService.debugDisableMailboxPoll = true);
      final call = CallService.instance;
      expect(call.debugMailboxPollActive, isFalse);

      call.startOutgoing(peer(), video: false);
      expect(call.debugMailboxPollActive, isTrue,
          reason: 'a ringing call must be polling for a queued hang-up the '
              'live channel might have missed');

      call.onRemoteAnswer(call.current.value!.callId);
      expect(call.debugMailboxPollActive, isTrue,
          reason: 'a connected call still needs the backstop — the whole '
              'point is catching a hang-up the live channel missed');

      call.end();
      expect(call.debugMailboxPollActive, isFalse,
          reason: 'nothing to poll for once the call is over');
    });

    test('resetForTest leaves no mailbox-poll timer running', () {
      CallService.debugDisableMailboxPoll = false;
      addTearDown(() => CallService.debugDisableMailboxPoll = true);
      final call = CallService.instance;
      call.startOutgoing(peer(), video: false);
      expect(call.debugMailboxPollActive, isTrue);
      call.resetForTest();
      expect(call.debugMailboxPollActive, isFalse);
    });

    test('an incoming offer rings; accepting connects it', () {
      final call = CallService.instance;
      call.onRemoteOffer(peer(), 'call_abc', false);
      expect(call.current.value?.direction, CallDirection.incoming);
      expect(call.current.value?.status, CallStatus.ringing);

      call.accept();
      expect(call.current.value?.status, CallStatus.connected);
    });

    test('answering in-app reaches CallKit, and the echo cannot re-answer',
        () async {
      // The system call must be answered too ('accepted' → CXAnswerCallAction)
      // or iOS never activates the audio session and the call stays silent.
      // That action echoes back as a second accept(), which must be a no-op —
      // re-answering would tear down the WebRTC handshake mid-call.
      addTearDown(CallKitBridge.instance.resetForTest);
      CallKitBridge.instance.init();
      const channel = MethodChannel('okay/callkit');
      final invoked = <String>[];
      TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
          .setMockMethodCallHandler(channel, (c) async {
        invoked.add(c.method);
        return null;
      });
      addTearDown(() => TestDefaultBinaryMessengerBinding
          .instance.defaultBinaryMessenger
          .setMockMethodCallHandler(channel, null));

      final call = CallService.instance;
      call.onRemoteOffer(peer(), 'call_ck', false);
      call.accept();
      final connectedAt = call.current.value?.connectedAt;
      call.accept(); // the CallKit echo
      expect(call.current.value?.status, CallStatus.connected);
      expect(call.current.value?.connectedAt, connectedAt,
          reason: 'a second accept must not restart the call');
      await Future<void>.delayed(Duration.zero);
      expect(invoked, contains('incoming'));
      expect(invoked, contains('accepted'));
      expect(invoked.where((m) => m == 'accepted').length, 1);
    });

    test('a lock-screen answer parked before the offer completes on arrival',
        () {
      // The VoIP wake: CallKit rang and was ANSWERED before the app had the
      // offer (it was still coming in from the mailbox). The intent parks;
      // the offer's arrival must complete it without another tap. A decline
      // parked the same way must decline silently.
      final call = CallService.instance;
      call.noteVoipAnswer('c_voip');
      call.onRemoteOffer(peer(), 'c_voip', false);
      expect(call.current.value?.status, CallStatus.connected,
          reason: 'the parked answer must connect the call on arrival');
      call.end();
      call.clear();

      call.noteVoipDecline('c_voip2');
      call.onRemoteOffer(peer(), 'c_voip2', false);
      expect(call.current.value, isNull,
          reason: 'the parked decline must refuse silently — no ringing UI '
              'for a call already refused on the lock screen');
    });

    test('a duplicate offer for the ringing call never declines it', () {
      // Broadcast and the mailbox both deliver the offer, and a VoIP wake
      // fetches the queued copy right after the live one. The echo used to
      // fall through to the busy check — the call declined ITSELF, which
      // read as "calls sometimes don't go through".
      final call = CallService.instance;
      call.onRemoteOffer(peer(), 'c_dup', false);
      expect(call.current.value?.status, CallStatus.ringing);
      call.onRemoteOffer(peer(), 'c_dup', false); // the mailbox echo
      expect(call.current.value?.status, CallStatus.ringing,
          reason: 'the echo must not decline the call with itself');
    });

    test('a callmiss notice files a missed call once, log and chat both', () {
      // The live offer is never queued, so a call to a closed app only
      // exists on the callee's side through this notice — and a mailbox
      // replay of it must not double-file the entry.
      CallLog.instance.resetForTest();
      ChatStore.instance.reset();
      final call = CallService.instance;
      call.onRemoteMissed(peer(), 'c_missnotice', true);
      final rec = CallLog.instance.records.single;
      expect(rec.direction, callmodel.CallDirection.missed);
      expect(rec.type, callmodel.CallType.video);
      call.onRemoteMissed(peer(), 'c_missnotice', true); // the replay
      expect(CallLog.instance.records.length, 1);
      final chat = ChatStore.instance.chatWithContact('+1 555 0199');
      expect(chat!.messages.single.callEvent, 'missed');
      expect(chat.messages.single.isMe, isFalse);
    });

    test('a remote hang-up ends the connected call', () {
      final call = CallService.instance;
      call.onRemoteOffer(peer(), 'call_xyz', false);
      call.accept();
      call.onRemoteEnd('call_xyz');
      expect(call.current.value?.status, CallStatus.ended);
    });

    test('a stale callId is ignored', () {
      final call = CallService.instance;
      call.onRemoteOffer(peer(), 'call_1', false);
      call.onRemoteEnd('some_other_call');
      // Still ringing — the end was for a different call.
      expect(call.current.value?.status, CallStatus.ringing);
    });

    test('silence unknown callers: strangers are muted, contacts still ring',
        () {
      final call = CallService.instance;
      ChatStore.instance.reset();
      AppState.silenceUnknownCallers.value = true;

      // A stranger we've never chatted with is silently declined.
      call.onRemoteOffer(peer(), 'call_stranger', false);
      expect(call.current.value, isNull);

      // Someone we already have a chat with still rings through.
      final known = ChatStore.instance.chats.first.contact;
      call.onRemoteOffer(known, 'call_known', false);
      expect(call.current.value?.status, CallStatus.ringing);

      AppState.silenceUnknownCallers.value = false;
      call.resetForTest();
    });

    test('blocked numbers never ring', () {
      final call = CallService.instance;
      AppState.setBlocked(peer().phone, true);
      call.onRemoteOffer(peer(), 'call_blocked', false);
      expect(call.current.value, isNull);
      AppState.setBlocked(peer().phone, false);
    });

    test('leaveVoicemail records a voicemail voice message in the chat', () {
      ChatStore.instance.reset();
      final contact = ChatStore.instance.chats.first.contact;
      final ok = CallService.instance.leaveVoicemail(contact, 8);
      expect(ok, isTrue);
      final chat = ChatStore.instance.chatWithContact(contact.id)!;
      final vm = chat.messages.last;
      expect(vm.isVoicemail, isTrue);
      expect(vm.isVoice, isTrue);
      expect(vm.voiceSeconds, 8);
      expect(vm.isMe, isTrue);
    });

    test('leaveVoicemail rejects an empty recording', () {
      final contact = ChatStore.instance.chats.first.contact;
      expect(CallService.instance.leaveVoicemail(contact, 0), isFalse);
    });

    test('ending an outgoing call records it as outgoing in the log', () {
      CallLog.instance.resetForTest();
      final call = CallService.instance;
      call.startOutgoing(peer(), video: false);
      call.end();
      final rec = CallLog.instance.records.single;
      expect(rec.direction, callmodel.CallDirection.outgoing);
      expect(rec.type, callmodel.CallType.voice);
      expect(rec.user.phone, peer().phone);
    });

    test('an unanswered incoming call is logged as missed', () {
      CallLog.instance.resetForTest();
      final call = CallService.instance;
      call.onRemoteOffer(peer(), 'c_missed', true);
      call.onRemoteEnd('c_missed'); // caller gave up before we answered
      final rec = CallLog.instance.records.single;
      expect(rec.direction, callmodel.CallDirection.missed);
      expect(rec.type, callmodel.CallType.video);
    });

    test('an answered incoming call is logged as incoming', () {
      CallLog.instance.resetForTest();
      final call = CallService.instance;
      call.onRemoteOffer(peer(), 'c_in', false);
      call.accept();
      call.end();
      expect(CallLog.instance.records.single.direction,
          callmodel.CallDirection.incoming);
    });

    test('a call is only logged once', () {
      CallLog.instance.resetForTest();
      final call = CallService.instance;
      call.onRemoteOffer(peer(), 'c_once', false);
      call.accept();
      call.onRemoteEnd('c_once');
      call.end(); // no-op: already cleared
      expect(CallLog.instance.records.length, 1);
    });
  });

  group('Call log store', () {
    setUp(() => CallLog.instance.resetForTest());

    callmodel.CallRecord rec(String id, DateTime t) => callmodel.CallRecord(
          id: id,
          user: const AppUser(
            id: '+1 555 0110',
            name: 'Dora',
            avatarColor: '#4DB6AC',
            about: 'Available',
            phone: '+1 555 0110',
          ),
          time: t,
          type: callmodel.CallType.voice,
          direction: callmodel.CallDirection.outgoing,
        );

    test('call duration formats and round-trips through JSON', () {
      const user = AppUser(
          id: 'x', name: 'X', avatarColor: '#000000', phone: '+1 555 0110');
      callmodel.CallRecord withDuration(int s) => callmodel.CallRecord(
            id: 'd',
            user: user,
            time: DateTime(2024, 1, 1),
            type: callmodel.CallType.video,
            direction: callmodel.CallDirection.outgoing,
            durationSeconds: s,
          );
      expect(withDuration(0).durationLabel, isNull); // missed / unanswered
      expect(withDuration(65).durationLabel, '1:05');
      expect(withDuration(3661).durationLabel, '1:01:01');
      final back = callmodel.CallRecord.fromJson(withDuration(125).toJson());
      expect(back.durationSeconds, 125);
      expect(back.durationLabel, '2:05');
    });

    test('records are ordered newest-first by time and clear empties them', () {
      CallLog.instance.add(rec('a', DateTime(2024, 1, 1)));
      CallLog.instance.add(rec('b', DateTime(2024, 1, 3)));
      CallLog.instance.add(rec('c', DateTime(2024, 1, 2)));
      // Sorted by time descending regardless of insertion order.
      expect(
          CallLog.instance.records.map((r) => r.id).toList(), ['b', 'c', 'a']);
      expect(CallLog.instance.records.length, 3);

      CallLog.instance.clear();
      expect(CallLog.instance.isEmpty, isTrue);
    });

    test('CallRecord serializes round-trip through JSON', () {
      final original = rec('x', DateTime(2024, 5, 6, 7, 8));
      final restored = callmodel.CallRecord.fromJson(original.toJson());
      expect(restored.id, 'x');
      expect(restored.user.name, 'Dora');
      expect(restored.type, callmodel.CallType.voice);
      expect(restored.direction, callmodel.CallDirection.outgoing);
      expect(restored.time, DateTime(2024, 5, 6, 7, 8));
    });

    test('newMissedCount counts unseen missed calls; markSeen clears it', () {
      callmodel.CallRecord missed(String id, DateTime t) =>
          callmodel.CallRecord(
            id: id,
            user: const AppUser(
              id: '+1 555 0110',
              name: 'Dora',
              avatarColor: '#4DB6AC',
              about: 'Available',
              phone: '+1 555 0110',
            ),
            time: t,
            type: callmodel.CallType.voice,
            direction: callmodel.CallDirection.missed,
          );

      CallLog.instance.add(missed('m1', DateTime(2024, 1, 1)));
      CallLog.instance.add(missed('m2', DateTime(2024, 1, 2)));
      CallLog.instance.add(rec('o1', DateTime(2024, 1, 3))); // outgoing
      // Both missed calls are unseen; the outgoing one doesn't count.
      expect(CallLog.instance.newMissedCount, 2);

      CallLog.instance.markSeen();
      expect(CallLog.instance.newMissedCount, 0);
    });
  });

