  test('an upsert never names author_phone — the bug that broke publishing',
      () {
    // REPORTED as "when a user posts a listing other users can't see it", and
    // it was worse than that: the row never reached the server AT ALL, so the
    // table sat empty from the day the global marketplace shipped. Traced from
    // the live logs — POST /rest/v1/market_listings answering 403, with
    // Postgres saying `permission denied for table market_listings`, NOT the
    // RLS refusal an ownership problem would give.
    //
    // The cause: PostgREST's upsert compiles to
    //   on conflict (id) do update set author_phone = excluded.author_phone, …
    // and `excluded.author_phone` READS the one column deliberately withheld
    // from clients so a seller's number stays private. Postgres checks that at
    // PLAN time, so it failed even on a brand-new id that could never
    // conflict. Granting the column would have leaked every seller's phone to
    // anyone with the publishable key, so the client stops sending it instead
    // and the column defaults to the caller's own JWT phone server-side
    // (docs/market_upsert_fix.sql) — which it also cannot forge.
    //
    // tool/check_sql.sh proves the SQL half against a real Postgres. This
    // pins the client half: the key must stay out of both upsert bodies.
    //
    // THREE tables, not one. server_directory was nearly missed: a first
    // probe upserted it WITHOUT owner_phone in the DO UPDATE (which passes)
    // and that was read as "unaffected" — while what the app really sends
    // names the column, so publishing a public server to Discover was refused
    // the same way. Test the statement the CLIENT sends, not a stand-in.
    final src = File('lib/relay/relay_service.dart').readAsStringSync();
    const phoneKeyFor = {
      'publishMarketListing': "'author_phone'",
      'publishMarketReview': "'author_phone'",
      'publishServerDirectory': "'owner_phone'",
    };
    phoneKeyFor.forEach((fn, key) {
      final start = src.indexOf('Future<void> $fn(');
      expect(start, greaterThan(-1), reason: '$fn should exist');
      final body = src.substring(start, src.indexOf('\n  }', start));
      expect(body.contains('upsert('), isTrue, reason: '$fn still upserts');
      // Scoped to the UPSERT's own argument, not the whole function
      // (2026-08-15). The rule was never "the client may not name its phone"
      // — it is that an UPSERT may not, because `on conflict do update set
      // <col> = excluded.<col>` is a READ of a column no client may SELECT.
      // A plain INSERT generates no such clause, and publishMarketReview now
      // uses one precisely so the row lands whether or not the server-side
      // default is in place. Banning the string outright would forbid the
      // fix and keep the bug.
      final upsertArg = body.substring(body.indexOf('upsert('));
      final end = upsertArg.indexOf('onConflict');
      expect((end > 0 ? upsertArg.substring(0, end) : upsertArg).contains(key),
          isFalse,
          reason: '$fn must not send $key IN THE UPSERT — it makes the '
              'statement read a column no client may SELECT, and the whole '
              'write is refused');
    });
    // And the review path really does name it on its plain insert, which is
    // what makes it independent of the default having been applied.
    final reviewBody = src.substring(
        src.indexOf('Future<void> publishMarketReview('),
        src.indexOf('\n  }', src.indexOf('Future<void> publishMarketReview(')));
    expect(reviewBody.contains(".insert({...row, 'author_phone': phone})"),
        isTrue,
        reason: 'a review inserts its own phone; only the upsert may not');
    // The migration that makes the server fill it exists and says how.
    final sql = File('docs/market_upsert_fix.sql').readAsStringSync();
    expect(sql.contains('alter column author_phone set default'), isTrue);
    expect(sql.contains('alter column owner_phone set default'), isTrue);
    expect(sql.contains("auth.jwt() ->> 'phone'"), isTrue);
    // All three tables, not just the reported one.
    expect(sql.contains('public.market_listings'), isTrue);
    expect(sql.contains('public.market_reviews'), isTrue);
    expect(sql.contains('public.server_directory'), isTrue);
  });

  test('a seller\'s pre-fix listings get published, not stranded', () {
    // REPORTED: "if I post a new listing it shows, none of my old listings
    // show". Repairing the write path is only half of it — publishing was
    // refused for as long as the global table existed, so every listing made
    // before the fix lives ONLY on the device that made it, and nothing
    // re-publishes a listing nobody is editing. Without this the seller's
    // back catalogue would stay invisible forever while new listings worked.
    final src = File('lib/relay/relay_service.dart').readAsStringSync();
    final fn = src.substring(src.indexOf('Future<void> _backfillOwnListings('));
    final body = fn.substring(0, fn.indexOf('\n  }'));
    // Only what is MISSING — once a seller is up to date this costs nothing.
    expect(body.contains('alreadyUp.contains(post.id)'), isTrue);
    // Only the caller's OWN listings, including the pre-handle 'you' filing.
    expect(body.contains("author == 'you'"), isTrue);
    expect(body.contains('author == myHandle'), isTrue);
    expect(body.contains('publishMarketListing(post)'), isTrue);
    // A numberless account has no session to publish with.
    expect(body.contains("digits(me.phone).isEmpty"), isTrue);
    // The fetch has to collect ids for the comparison to mean anything, and
    // it must actually run the backfill.
    final fetch = src.substring(src.indexOf('Future<void> fetchMarketListings('));
    final fetchBody = fetch.substring(0, fetch.indexOf('\n  }'));
    expect(fetchBody.contains("select('id, payload')"), isTrue,
        reason: 'the fetch must ask for ids, not just payloads');
    expect(fetchBody.contains('_backfillOwnListings(seen)'), isTrue);
  });

  group('Reporting reaches the console from every surface', () {
    test('every user-generated surface offers a report', () {
      // A moderation queue only ever sees what somebody could reach a button
      // to send it, so a missing button is a missing report. Reporting had
      // grown on four surfaces and stopped: the PUBLIC FORUM (posts AND
      // comments — world-readable content anyone can find), the in-server
      // board and a server's channel messages offered no way to report
      // anything at all.
      const surfaces = {
        // already had it, and must keep it
        'lib/screens/public_feed_screen.dart': 'newsfeed post + profile',
        'lib/screens/feed_screen.dart': 'server feed post',
        'lib/screens/marketplace_screen.dart': 'listing',
        'lib/screens/contact_info_screen.dart': 'a person',
        // the gaps this closed
        'lib/screens/public_forum_screen.dart': 'forum post + comment',
        'lib/screens/forum_screen.dart': 'in-server board thread',
        'lib/screens/communities.dart': 'channel message',
      };
      surfaces.forEach((path, what) {
        final src = File(path).readAsStringSync();
        final has = src.contains('showReportSheet') ||
            src.contains('showReportOnlySheet') ||
            src.contains('reportMenuRow') ||
            src.contains('PlatformModeration.instance.report(');
        expect(has, isTrue, reason: '$what ($path) offers no way to report');
      });
    });

    test('a report locates the thing without carrying what it said', () {
      // The rule the server-feed report already set: "who and where, never
      // what". A server's content is end-to-end encrypted; a report that
      // smuggled the plaintext to a moderator would break the promise the
      // encryption exists to keep. The context is a LOCATOR.
      final src = File('lib/widgets/report_action.dart').readAsStringSync();
      for (final prefix in [
        'forum_post',
        'forum_comment',
        'server_forum_post',
        'channel_message',
      ]) {
        expect(src.contains("'$prefix'"), isTrue,
            reason: '$prefix needs a stable console prefix');
      }
      // The id and the placement go; the body never does.
      expect(src.contains(r"'${target.prefix}:$id'"), isTrue);
      expect(src.contains('.text'), isFalse,
          reason: 'a report must never read the message body');
    });

    test('a channel report names the server and channel, not just an id', () {
      // A bare message id locates nothing — a moderator cannot act on it.
      final src = File('lib/screens/communities.dart').readAsStringSync();
      final i = src.indexOf('ReportTarget.channelMessage');
      expect(i, greaterThan(-1));
      final near = src.substring(i, i + 260);
      expect(near.contains(r'server:$communityId'), isTrue);
      expect(near.contains(r'channel:$channelId'), isTrue);
      // Reporting your own message is not a thing worth offering.
      expect(src.substring(i - 400, i).contains('!message.isMe'), isTrue);
    });
  });

  testWidgets('the moderation audit trail is readable in the console',
      (t) async {
    // moderation_log has been written on every sanction, takedown and role
    // change since the console existed — moderation-act and roles-set both
    // insert into it, and moderation-queue already serves it under
    // what:"log". Nothing in the app ever ASKED for it, so the trail was
    // WRITE-ONLY: a complete record of who did what that no moderator could
    // read. Accountability nobody can inspect is not accountability.
    PlatformModeration.instance
        .debugSet(role: PlatformRole.admin, loaded: true);
    PlatformModeration.debugReportsOverride = () async => const [];
    PlatformModeration.debugSanctionsOverride = () async => const [];
    PlatformModeration.debugLogOverride = () async => [
          ModerationLogEntry(
            id: 1,
            createdAt: DateTime(2026, 8, 14, 9),
            actorPhone: '15550001111',
            actorRole: 'admin',
            targetPhone: '15550002222',
            action: 'ban',
            reason: 'spam',
          ),
        ];
    addTearDown(() {
      PlatformModeration.debugReportsOverride = null;
      PlatformModeration.debugSanctionsOverride = null;
      PlatformModeration.debugLogOverride = null;
      PlatformModeration.instance.resetForTest();
    });

    await t.pumpWidget(const MaterialApp(home: AdminScreen()));
    await t.pumpAndSettle();
    await t.tap(find.text('History'));
    await t.pumpAndSettle();

    expect(find.text('ban'), findsOneWidget);
    // The ACTOR is shown, not just the target — the sanctions tab already
    // says who is sanctioned; only this says who did it, and under what
    // authority at the time.
    expect(find.textContaining('by 15550001111'), findsOneWidget);
    expect(find.textContaining('(admin)'), findsOneWidget);
    expect(find.textContaining('on 15550002222'), findsOneWidget);
  });

  group('the audit trail is append-only, and says whether it still adds up',
      () {
    // Prevention and detection are two different things and the console has
    // to draw both: `moderation_log` refuses UPDATE and DELETE through a
    // trigger (which binds the service role, unlike a GRANT or RLS), and
    // every entry carries the hash of the one before it so an edit that got
    // past the trigger is still visible. What the app adds is the LOOKING —
    // a chain nobody checks is a chain nobody checks.
    Future<void> openHistory(WidgetTester t) async {
      await t.pumpWidget(const MaterialApp(home: AdminScreen()));
      await t.pumpAndSettle();
      await t.tap(find.text('History'));
      await t.pumpAndSettle();
    }

    setUp(() {
      PlatformModeration.instance
          .debugSet(role: PlatformRole.admin, loaded: true);
      PlatformModeration.debugReportsOverride = () async => const [];
      PlatformModeration.debugSanctionsOverride = () async => const [];
      PlatformModeration.debugLogOverride = () async => const [];
    });
    tearDown(() {
      PlatformModeration.debugReportsOverride = null;
      PlatformModeration.debugSanctionsOverride = null;
      PlatformModeration.debugLogOverride = null;
      PlatformModeration.debugChainOverride = null;
      PlatformModeration.instance.resetForTest();
    });

    testWidgets('an intact chain says so, and says over how many entries',
        (t) async {
      PlatformModeration.debugChainOverride = () async =>
          const AuditChainStatus(checked: true, ok: true, entries: 42);
      await openHistory(t);
      expect(find.text('Trail verified'), findsOneWidget);
      // The COUNT is the point of showing it: a chain over an emptied table
      // verifies perfectly, so "verified" alone would be a tick over nothing.
      expect(find.textContaining('42 entries'), findsOneWidget);
    });

    testWidgets('a broken chain names the first entry that stopped adding up',
        (t) async {
      PlatformModeration.debugChainOverride =
          () async => const AuditChainStatus(
                checked: true,
                ok: false,
                entries: 42,
                brokenId: 17,
                detail: 'entry has been altered',
              );
      await openHistory(t);
      expect(find.text('Trail does not verify'), findsOneWidget);
      expect(find.textContaining('#17'), findsOneWidget);
      expect(find.textContaining('entry has been altered'), findsOneWidget);
      expect(find.text('Trail verified'), findsNothing);
    });

    testWidgets('a check that could NOT run never draws as a pass', (t) async {
      // The one that matters most. A project that has not run
      // docs/audit_log_immutable.sql, or whose deployed moderation-queue
      // predates the verify action, has no verifier at all — and "we could
      // not check" rendered as a tick would be the single most misleading
      // thing this screen could say.
      PlatformModeration.debugChainOverride =
          () async => const AuditChainStatus();
      await openHistory(t);
      expect(find.text('Tamper check unavailable'), findsOneWidget);
      expect(find.text('Trail verified'), findsNothing);
      expect(find.text('Trail does not verify'), findsNothing);
    });

    test('the migration prevents AND detects, and closes the anon door',
        () async {
      final sql = await File('docs/audit_log_immutable.sql').readAsString();
      // Prevention: a trigger, not a revoke — a GRANT does not bind the
      // table's owner and RLS does not bind BYPASSRLS, so neither would stop
      // the only party that can reach this table.
      expect(sql.contains('before update on public.moderation_log'), isTrue);
      expect(sql.contains('before delete on public.moderation_log'), isTrue);
      // Detection: the chain, and something that walks it.
      expect(sql.contains('prev_hash'), isTrue);
      expect(sql.contains('sha256('), isTrue);
      expect(sql.contains('moderation_log_verify'), isTrue);
      // The hash is computed by the INSERT trigger, never accepted from the
      // writer — a hash the inserter supplies is a hash the inserter forges.
      expect(sql.contains('before insert on public.moderation_log'), isTrue);
      // PUBLIC as well as the two client roles: a new function is granted
      // EXECUTE to PUBLIC by Postgres itself, and revoking only anon leaves
      // it callable — the mirror of the find_people_by_hashes bug.
      expect(
          sql.contains('revoke all on function public.moderation_log_verify()\n'
              '  from public, anon, authenticated;'),
          isTrue);
      expect(
          sql.contains('revoke all on table public.moderation_log '
              'from anon, authenticated;'),
          isTrue);
    });

    test('the console asks the server, which is the only party that can look',
        () async {
      final fn = await File('supabase/functions/moderation-queue/index.ts')
          .readAsString();
      expect(fn.contains('what === "verify"'), isTrue);
      expect(fn.contains('moderation_log_verify'), isTrue);
      // An older deployment answering nothing must come back "not checked",
      // never a pass.
      expect(fn.contains('checked: false'), isTrue);

      final screen =
          await File('lib/screens/admin_screen.dart').readAsString();
      expect(screen.contains('verifyAuditLog()'), isTrue);
    });
  });

  group('Watching a YouTube or Twitch link', () {
    test('Twitch URL forms resolve to what should be embedded', () {
      String t(String u) => twitchTargetOf(Uri.parse(u));
      expect(t('https://twitch.tv/somestreamer'), 'channel/somestreamer');
      expect(t('https://www.twitch.tv/SomeStreamer'), 'channel/SomeStreamer');
      expect(t('https://m.twitch.tv/somestreamer'), 'channel/somestreamer');
      expect(t('https://twitch.tv/videos/1234567890'), 'video/1234567890');
      expect(t('https://twitch.tv/someone/clip/FunnySlug-x1'),
          'clip/FunnySlug-x1');
      expect(t('https://clips.twitch.tv/FunnySlug-x1'), 'clip/FunnySlug-x1');
      // The reserved-path list is the whole care here: twitch.tv/<anything>
      // is a channel, so without it these become players for streamers who
      // do not exist and will never load.
      for (final path in ['directory', 'settings', 'downloads', 'p', 'search']) {
        expect(t('https://twitch.tv/$path'), isEmpty, reason: path);
      }
      expect(t('https://twitch.tv/'), isEmpty);
      expect(t('https://twitch.tv/videos/notanumber'), isEmpty);
      expect(t('https://youtube.com/watch?v=dQw4w9WgXcQ'), isEmpty);
    });

    test('a Twitch link is playable and a YouTube live link still is', () {
      expect(linkKindOf(Uri.parse('https://twitch.tv/somestreamer')),
          LinkKind.twitch);
      // Already handled before this round, and pinned so it stays: a live
      // stream is an ordinary video id behind a /live/ path.
      expect(youtubeIdOf(Uri.parse('https://youtube.com/live/dQw4w9WgXcQ')),
          'dQw4w9WgXcQ');
    });

    test('a Twitch embed carries the parent its player demands', () {
      const p = LinkPreview(
          url: 'https://twitch.tv/somestreamer',
          kind: LinkKind.twitch,
          videoId: 'channel/somestreamer');
      expect(p.playable, isTrue);
      final url = p.embedUrlWithParent('okay.example');
      expect(url, contains('player.twitch.tv'));
      expect(url, contains('channel=somestreamer'));
      // Without this Twitch shows a refusal rather than a stream — it is the
      // one thing the embed will not do without.
      expect(url, contains('parent=okay.example'));

      const vod = LinkPreview(
          url: 'https://twitch.tv/videos/1',
          kind: LinkKind.twitch,
          videoId: 'video/1');
      expect(vod.embedUrlWithParent('h'), contains('video=1'));
      const clip = LinkPreview(
          url: 'https://clips.twitch.tv/S',
          kind: LinkKind.twitch,
          videoId: 'clip/S');
      expect(clip.embedUrlWithParent('h'), contains('clips.twitch.tv/embed'));

      // YouTube is unchanged and needs no parent — the proven path stays put.
      const yt = LinkPreview(
          url: 'https://youtu.be/dQw4w9WgXcQ',
          kind: LinkKind.youtube,
          videoId: 'dQw4w9WgXcQ');
      expect(yt.embedUrl, 'https://www.youtube.com/embed/dQw4w9WgXcQ'
          '?playsinline=1&rel=0');
    });

    test('the Watch field takes what plays and refuses what does not', () {
      LinkPreview? p(String s) => WatchScreen.previewFor(s);
      expect(p('https://twitch.tv/somestreamer')?.kind, LinkKind.twitch);
      expect(p('youtube.com/watch?v=dQw4w9WgXcQ')?.kind, LinkKind.youtube,
          reason: 'a pasted link usually has no scheme on it');
      expect(p('  https://youtu.be/dQw4w9WgXcQ  ')?.videoId, 'dQw4w9WgXcQ');
      // Refused, and the screen says why rather than opening a black box.
      // These are exactly the links the last conversation was about.
      for (final bad in [
        '',
        'not a url',
        'rtsp://camera.local/stream',
        'https://example.com/video.mkv',
        'https://example.com/live.m3u8',
      ]) {
        expect(p(bad), isNull, reason: bad);
      }
    });

    testWidgets('a link it cannot play is refused with the reason',
        (t) async {
      await t.pumpWidget(const MaterialApp(home: WatchScreen()));
      await t.enterText(find.byType(TextField), 'rtsp://camera.local/stream');
      // The button, not the app-bar title — both say Watch.
      await t.tap(find.widgetWithText(FilledButton, 'Watch'));
      await t.pumpAndSettle();
      expect(find.textContaining("isn't a YouTube video or a Twitch stream"),
          findsOneWidget);
      expect(find.byType(VideoPlayerScreen), findsNothing);
