    ]) {
      expect(File(f).readAsStringSync().contains("about: 'Available'"), isFalse,
          reason: '$f still invents a status for somebody');
    }

    // A fresh account has NO bio rather than a sentence the app wrote — but
    // the old placeholder still has to be recognised, because every account
    // made before this carries it on the wire and on other people's devices.
    const fresh = AppUser(id: 'u', name: 'Ada', avatarColor: '#000000');
    expect(fresh.about, isEmpty);
    expect(AppUser.legacyAbout, 'Hey there! I am using OkayMessenger.');
    // The placeholder still has to read as "no bio" — but that rule moved
    // OUT of the profile screen and into the model (2026-08-17), because
    // five other surfaces were rendering it as if the person had written it.
    const legacy = AppUser(
        id: 'u2',
        name: 'Ada',
        avatarColor: '#000000',
        about: AppUser.legacyAbout);
    expect(legacy.bio, isEmpty,
        reason: 'the old placeholder must still read as "no bio"');
    expect(
        File('lib/screens/public_feed_screen.dart')
            .readAsStringSync()
            .contains('known?.bio'),
        isTrue);
  });

  test('a deleted listing has a way to reach the devices that cached it', () {
    // Reported as "deleted posts still show for other users. On marketplace."
    // Deleting removes the row and broadcasts `fdel` — but `fdel` rides the
    // community bus and a global listing's communityId is '', so it reaches
    // nobody, while the fetch only ever ADDED. Every device that had seen the
    // listing kept it forever. Convergence has to come from the fetch,
    // because the fetch is the only thing the two devices share.
    final src = File('lib/relay/relay_service.dart').readAsStringSync();
    expect(src.contains('_pruneDeletedMarket'), isTrue);
    for (final fn in ['fetchMarketListings', 'fetchMarketReviews']) {
      final start = src.indexOf('Future<void> $fn(');
      final body = src.substring(start, src.indexOf('\n  }', start));
      expect(body.contains('_pruneDeletedMarket'), isTrue,
          reason: '$fn adds rows but never drops the ones that are gone');
    }
    final prune = src.substring(src.indexOf('void _pruneDeletedMarket('));
    final body = prune.substring(0, prune.indexOf('\n  }'));
    // The two guards, and both are load-bearing. Without the page guard this
    // deletes real listings for anyone whose marketplace is bigger than one
    // page — a far worse bug than the one being fixed.
    expect(body.contains('if (rowCount >= limit) return;'), isTrue,
        reason: 'a paged fetch cannot tell "gone" from "on the next page"');
    expect(body.contains("author == 'you'"), isTrue,
        reason: 'your own missing row is the stranding the backfill repairs, '
            'not a deletion');
    expect(body.contains('post.communityId.isNotEmpty'), isTrue,
        reason: "a listing sealed to a real server is that server's business");
  });

  test('an old listing sealed to a server converges on delete too', () {
    // The OTHER half of "deleted posts still show for other users", reported
    // again after the global prune shipped — and "OLD" is the tell. A listing
    // made before the marketplace went global carries a real communityId, and
    // the global prune skips exactly those. Its only convergence route was
    // the live `fdel` event, so a member who was offline when it fired kept
    // the listing forever: this fetch, the only other path, only ever added.
    final src = File('lib/relay/relay_service.dart').readAsStringSync();
    final fn = src.substring(src.indexOf('Future<void> fetchCommunityPosts('));
    final body = fn.substring(0, fn.indexOf('\n  }'));
    expect(body.contains('_pruneDeletedCommunityListings'), isTrue,
        reason: 'the durable fetch adds posts but never drops the gone ones');
    expect(body.contains('seen.add(post.id)'), isTrue,
        reason: 'it has to know what the server still has');

    final prune =
        src.substring(src.indexOf('void _pruneDeletedCommunityListings('));
    final pruneBody = prune.substring(0, prune.indexOf('\n  }'));
    // LISTINGS only. community_posts is the durable store for a whole server
    // feed, and pruning it wholesale would need certainty that every ordinary
    // post and reply lands there — a far bigger claim than this bug needs.
    expect(pruneBody.contains('if (!post.isListing) continue;'), isTrue,
        reason: 'the blast radius is listings, not a whole server feed');
    expect(pruneBody.contains('post.communityId != communityId'), isTrue,
        reason: 'one fetch answers for one server only');
    // The same two guards the global prune carries, for the same reasons.
    expect(pruneBody.contains('if (rowCount >= limit) return;'), isTrue);
    expect(pruneBody.contains("author == 'you'"), isTrue);
  });

  test('a failed marketplace write is recorded, not swallowed', () {
    // Three separate rounds of "it only shows on my phone" were debugged by
    // guessing, because every failure on this path was a bare catch: the row
    // simply never appeared and nothing on the device knew why.
    final src = File('lib/relay/relay_service.dart').readAsStringSync();
    expect(src.contains('String? lastMarketError;'), isTrue);
    for (final fn in ['publishMarketListing', 'publishMarketReview']) {
      final start = src.indexOf('Future<void> $fn(');
      final body = src.substring(start, src.indexOf('\n  }', start));
      expect(body.contains('lastMarketError = '), isTrue,
          reason: '$fn still fails silently');
      expect(body.contains('} catch (_) {\n      //'), isFalse,
          reason: '$fn still has a bare swallow');
    }
  });

  group('Marketplace reviews: verified and unverified, and they publish', () {
    setUp(() {
      SharedPreferences.setMockInitialValues({});
      FeedStore.instance.resetForTest();
      AppState.resetForTest();
    });
    tearDown(() {
      FeedStore.instance.resetForTest();
      AppState.resetForTest();
    });

    FeedPost listing(String id, {String seller = 'sam', String hash = ''}) =>
        FeedPost(
          id: id,
          communityId: '',
          authorName: 'Sam',
          authorUsername: seller,
          time: DateTime(2026, 8, 1),
          text: 'A bike',
          priceCents: 5000,
          saleCodeHash: hash,
        );

    test('a review with no sale code is real, and simply unconfirmed', () {
      AppState.profile.value = const AppUser(
          id: 'me', name: 'Ada', avatarColor: '#000000', username: 'ada');
      FeedStore.instance.debugSetPosts([listing('l1')]);

      expect(FeedStore.instance.addReview('l1', rating: 4, text: 'Fine'),
          isTrue);
      final reviews = FeedStore.instance.reviewsFor('l1');
      expect(reviews, hasLength(1));
      expect(reviews.single.rating, 4);
      expect(reviews.single.isReview, isTrue);
      // Unverified is not second-class — it counts toward the seller's
      // rating. The chip says how it was proved, not whether it is real.
      expect(reviews.single.confirmedPurchase, isFalse);
      final (avg, count) = FeedStore.instance.sellerRating('sam');
      expect(count, 1);
      expect(avg, 4);
    });

    test('the right code under the right handle earns the confirmed chip', () {
      AppState.profile.value = const AppUser(
          id: 'me', name: 'Ada', avatarColor: '#000000', username: 'ada');
      // What the seller minted at the sold handshake, bound to this buyer.
      final hash = FeedStore.saleCodeHashOf('123456', buyer: 'ada');
      FeedStore.instance.debugSetPosts([listing('l1', hash: hash)]);

      FeedStore.instance
          .addReview('l1', rating: 5, text: 'Great', saleCode: '123456');
      expect(FeedStore.instance.reviewsFor('l1').single.confirmedPurchase,
          isTrue);
    });

    test('the same code under somebody else\'s handle earns nothing', () {
      // The binding is the whole point: a leaked code, or one handed to a
      // friend, must not buy the chip for an account that never bought.
      final hash = FeedStore.saleCodeHashOf('123456', buyer: 'ada');
      AppState.profile.value = const AppUser(
          id: 'me', name: 'Mallory', avatarColor: '#000000', username: 'mal');
      FeedStore.instance.debugSetPosts([listing('l1', hash: hash)]);

      FeedStore.instance
          .addReview('l1', rating: 5, text: 'Trust me', saleCode: '123456');
      final r = FeedStore.instance.reviewsFor('l1').single;
      expect(r.confirmedPurchase, isFalse,
          reason: 'a code bound to another buyer must not confirm');
      // It still posts — an unbound opinion is allowed, it is just unproved.
      expect(r.rating, 5);
    });

    test('you cannot review your own listing', () {
      AppState.profile.value = const AppUser(
          id: 'me', name: 'Sam', avatarColor: '#000000', username: 'sam');
      FeedStore.instance.debugSetPosts([listing('l1', seller: 'sam')]);
      expect(FeedStore.instance.addReview('l1', rating: 5), isFalse);
      expect(FeedStore.instance.reviewsFor('l1'), isEmpty);
    });

    test('reviewing twice corrects, it does not stack the rating', () {
      AppState.profile.value = const AppUser(
          id: 'me', name: 'Ada', avatarColor: '#000000', username: 'ada');
      FeedStore.instance.debugSetPosts([listing('l1')]);
      FeedStore.instance.addReview('l1', rating: 1);
      FeedStore.instance.addReview('l1', rating: 5);
      expect(FeedStore.instance.reviewsFor('l1'), hasLength(1));
      expect(FeedStore.instance.sellerRating('sam'), (5.0, 1));
    });

    test('the seller can rate the buyer, and it is a separate score', () {
      // The other direction. A review of a PERSON, not a listing — so it
      // must not land in the seller's own rating, and the buyer gets a
      // score of their own.
      AppState.profile.value = const AppUser(
          id: 'me', name: 'Sam', avatarColor: '#000000', username: 'sam');
      FeedStore.instance.debugSetPosts([listing('l1', seller: 'sam')]);

      // Nobody recorded yet: there is nobody to review, and it says so
      // rather than inventing a target.
      expect(FeedStore.instance.addBuyerReview('l1', rating: 5), isFalse);

      // The sold-to handshake names the buyer, on this device only.
      FeedStore.instance.mintSaleCode('l1', buyerHandle: 'ada');
      expect(FeedStore.instance.soldTo('l1'), 'ada');

      expect(
          FeedStore.instance.addBuyerReview('l1', rating: 5, text: 'Easy sale'),
          isTrue);
      final (bAvg, bCount) = FeedStore.instance.buyerRating('ada');
      expect(bCount, 1);
      expect(bAvg, 5);
      final r = FeedStore.instance.buyerReviewsOf('ada').single;
      expect(r.isBuyerReview, isTrue);
      expect(r.buyerHandle, 'ada');
      // Confirmed by construction: the seller is the one who marked it sold.
      expect(r.confirmedPurchase, isTrue);

      // AND IT MUST NOT COUNT AS A REVIEW OF THE SELLER. It hangs off the
      // same listing, so an unfiltered reviewsFor would show a seller
      // rating themselves five stars.
      expect(FeedStore.instance.reviewsFor('l1'), isEmpty);
      expect(FeedStore.instance.sellerRating('sam'), (0.0, 0));
    });

    test('only the seller of that listing can rate its buyer', () {
      AppState.profile.value = const AppUser(
          id: 'me', name: 'Sam', avatarColor: '#000000', username: 'sam');
      FeedStore.instance.debugSetPosts([listing('l1', seller: 'sam')]);
      FeedStore.instance.mintSaleCode('l1', buyerHandle: 'ada');
      AppState.profile.value = const AppUser(
          id: 'me2', name: 'Mallory', avatarColor: '#000000', username: 'mal');
      expect(FeedStore.instance.addBuyerReview('l1', rating: 1), isFalse);
      expect(FeedStore.instance.buyerRating('ada'), (0.0, 0));
    });

    test('the two scores never blend into one another', () {
      // Being good to deal with as a buyer and being good to buy FROM are
      // different claims; averaging them would let one launder the other.
      AppState.profile.value = const AppUser(
          id: 'me', name: 'Ada', avatarColor: '#000000', username: 'ada');
      FeedStore.instance.debugSetPosts([listing('l1', seller: 'sam')]);
      FeedStore.instance.addReview('l1', rating: 2);
      expect(FeedStore.instance.sellerRating('sam'), (2.0, 1));
      expect(FeedStore.instance.buyerRating('sam'), (0.0, 0));
      expect(FeedStore.instance.buyerRating('ada'), (0.0, 0));
    });

    test('who a listing sold to never leaves the device', () {
      // A listing goes to a world-readable table. A soldTo FIELD on the post
      // would broadcast who bought what, for every sale, whether or not
      // anybody writes a review — so the record is a local map instead, and
      // only a buyer REVIEW (which the seller chooses to write) names them.
      final src = File('lib/state/feed_store.dart').readAsStringSync();
      expect(src.contains('final Map<String, String> _soldTo'), isTrue);
      final toJson = src.substring(src.indexOf('Map<String, dynamic> toJson()'));
      expect(
          toJson.substring(0, toJson.indexOf('\n      };')).contains('soldTo'),
          isFalse,
          reason: 'the sold-to record must not ride a published listing');
    });

    test('a review that never published is re-published, not stranded', () {
      // The same stranding the listings backfill repairs. A rating is what a
      // stranger trusts a seller on; it must not depend on which device the
      // reviewer happened to use.
      final src = File('lib/relay/relay_service.dart').readAsStringSync();
      final fn = src.substring(src.indexOf('Future<void> _backfillOwnReviews('));
      final body = fn.substring(0, fn.indexOf('\n  }'));
      expect(body.contains('alreadyUp.contains(post.id)'), isTrue);
      expect(body.contains('post.isReview'), isTrue);
      expect(body.contains('publishMarketReview(post)'), isTrue);
      final fetch =
          src.substring(src.indexOf('Future<void> fetchMarketReviews('));
      final fetchBody = fetch.substring(0, fetch.indexOf('\n  }'));
      expect(fetchBody.contains("select('id, payload')"), isTrue);
      expect(fetchBody.contains('_backfillOwnReviews(seen)'), isTrue);
    });

    testWidgets('the seller rates their buyer from their own listing',
        (tester) async {
      ChatStore.instance.reset();
      addTearDown(ChatStore.instance.reset);
      AppState.profile.value = const AppUser(
          id: 'me', name: 'Sam', avatarColor: '#000000', username: 'sam');
      final mine = FeedStore.instance.addListing('',
          title: 'Bike', priceCents: 5000, category: 'Other');
      // The sold handshake is what names a buyer; without it there is
      // nobody to rate and the button must not appear.
      await tester
          .pumpWidget(MaterialApp(home: ListingScreen(listingId: mine.id)));
      await tester.pump();
      expect(find.text('Rate the buyer'), findsNothing);

      FeedStore.instance.mintSaleCode(mine.id, buyerHandle: 'ada');
      await tester
          .pumpWidget(MaterialApp(home: ListingScreen(listingId: mine.id)));
      await tester.pump();
      await tester.scrollUntilVisible(find.text('Rate the buyer'), 200);
      await tester.tap(find.text('Rate the buyer'));
      await tester.pumpAndSettle();

      // Naming somebody publicly is said before the button, not after.
      expect(find.textContaining('names @ada publicly'), findsOneWidget);
      await tester.tap(find.byIcon(Icons.star_outline_rounded).at(4)); // 5th
      await tester.pump();
      await tester.tap(find.text('Post rating'));
      await tester.pumpAndSettle();

      final (avg, count) = FeedStore.instance.buyerRating('ada');
      expect(count, 1);
      expect(avg, 5);
      // And it stayed out of the seller's own score.
      expect(FeedStore.instance.sellerRating('sam').$2, 0);
      expect(find.text('Edit your rating'), findsOneWidget);
    });
  });

