  test('the server-session gate can only ever open, never close', () async {
    // The gates used to ask Session.isNumberless directly. They now ask
    // needsServerSession, which adds a second way to get through — so the
    // property that matters is that nobody who could use a screen before
    // has lost it. An account with a real number short-circuits on the
    // first term and never consults the claim at all.
    addTearDown(AccountVerification.resetForTest);
    addTearDown(Session.instance.signOut);

    // A real-number account: open, and open regardless of the claim.
    await Session.instance.signIn(phone: '+15005550123', name: 'Ada');
    expect(Session.instance.isNumberless, isFalse);
    for (final claim in [true, false]) {
      AccountVerification.debugServerSession = claim;
      expect(AccountVerification.needsServerSession, isFalse,
          reason: 'a number is enough on its own');
    }

    // A name-only account with no claim: still gated, exactly as before.
    await Session.instance.signOut();
    await Session.instance
        .signInWithoutNumber(username: 'grace', name: 'Grace');
    expect(Session.instance.isNumberless, isTrue);
    AccountVerification.debugServerSession = false;
    expect(AccountVerification.needsServerSession, isTrue);

    // The same account once it holds the phone CLAIM — what every RLS
    // policy and callerPhone() actually key on — is let through.
    AccountVerification.debugServerSession = true;
    expect(AccountVerification.needsServerSession, isFalse);
  });

  testWidgets('verifying by email upgrades the account in place', (tester) async {
    // The whole point of the email path: a name-only account ends up holding
    // the phone CLAIM, keeps its data, and stops being gated - without ever
    // touching a phone number.
    addTearDown(AccountVerification.resetForTest);
    addTearDown(Session.instance.signOut);
    await Session.instance
        .signInWithoutNumber(username: 'grace', name: 'Grace');
    final before = Session.instance.user.value!.username;
    expect(Session.instance.isNumberless, isTrue);

    await tester.pumpWidget(MaterialApp(
      home: EmailVerifyScreen(
        sendCode: (email) async {},
        // Stands in for verifyOTP -> email-account -> refreshSession, which
        // needs Supabase Auth the suite cannot stand up. It returns what the
        // real chain returns: the account code the server stamped.
        verify: (email, code) async => '001234567890',
      ),
    ));
    // Positional: the email field is the only TextField until a code is
    // sent, and the code field is the second one after.
    await tester.enterText(find.byType(TextField), 'grace@example.com');
    await tester.tap(find.widgetWithText(FilledButton, 'Send code'));
    await tester.pumpAndSettle();

    await tester.enterText(find.byType(TextField).at(1), '123456');
    await tester.tap(find.widgetWithText(FilledButton, 'Confirm'));
    await tester.pumpAndSettle();

    // Identity re-pointed at the stamped code, and the handle carried over -
    // this is an upgrade of the same account, not a new one.
    expect(Session.instance.user.value!.phone, '001234567890');
    expect(Session.instance.user.value!.username, before);
  });

  testWidgets('registering by email asks for a password before it lets go',
      (tester) async {
    // An account verified this way has NO phone number, so the only other way
    // back in is another emailed code — the one part of this flow that can
    // quietly not arrive. So the flow does not end at "verified"; it ends at
    // a password.
    PasswordHistory.debugRounds = 1;
    PasswordHistory.instance.reset();
    addTearDown(() {
      PasswordHistory.debugRounds = null;
      PasswordHistory.instance.reset();
      AccountVerification.resetForTest();
    });
    addTearDown(Session.instance.signOut);
    await Session.instance
        .signInWithoutNumber(username: 'grace', name: 'Grace');

    String? saved;
    await tester.pumpWidget(MaterialApp(
      home: EmailVerifyScreen(
        sendCode: (email) async {},
        verify: (email, code) async => '001234567890',
        setPassword: (p) async => saved = p,
      ),
    ));
    await tester.enterText(find.byType(TextField), 'grace@example.com');
    await tester.tap(find.widgetWithText(FilledButton, 'Send code'));
    await tester.pumpAndSettle();
    await tester.enterText(find.byType(TextField).at(1), '123456');
    await tester.tap(find.widgetWithText(FilledButton, 'Confirm'));
    await tester.pumpAndSettle();

    // Confirming lands on the password step rather than closing.
    expect(find.text('Set a password'), findsOneWidget);
    expect(find.text('Your email is confirmed.'), findsOneWidget);
    // And it says what skipping costs, rather than leaving it to be found out
    // on the day they need it.
    expect(find.textContaining('needs another emailed code'), findsOneWidget);

    // Too short is refused here, not at the server.
    await tester.enterText(find.byType(TextField), 'short');
    await tester.tap(find.widgetWithText(FilledButton, 'Set password'));
    await tester.pumpAndSettle();
    expect(saved, isNull);

    await tester.enterText(find.byType(TextField), 'a-real-password');
    await tester.tap(find.widgetWithText(FilledButton, 'Set password'));
    await tester.pumpAndSettle();
    expect(saved, 'a-real-password');
    // Recorded, so it cannot be set back to this one later.
    expect(await PasswordHistory.instance.problemFor('a-real-password'),
        isNotNull);
  });

