  test('Server roles: moderator can moderate but not manage; ranks order', () {
    CommunityStore.instance.resetForTest();
    final c = CommunityStore.instance.createCommunity('Guild');
    // Rank ordering, highest first.
    expect(roleRank(MemberRole.owner), greaterThan(roleRank(MemberRole.admin)));
    expect(roleRank(MemberRole.admin),
        greaterThan(roleRank(MemberRole.moderator)));
    expect(roleRank(MemberRole.moderator),
        greaterThan(roleRank(MemberRole.member)));

    // Permission helpers: moderators moderate, only admins+ manage.
    expect(roleCanModerate(MemberRole.moderator), isTrue);
    expect(roleCanManageServer(MemberRole.moderator), isFalse);
    expect(roleCanManageServer(MemberRole.admin), isTrue);
    expect(roleCanModerate(MemberRole.member), isFalse);

    // The owner can moderate and manage.
    expect(CommunityStore.instance.canModerate(c.id), isTrue);
    expect(CommunityStore.instance.canManageServer(c.id), isTrue);

    // Assigning the new Moderator role round-trips through JSON.
    final revived = Member.fromJson(
        const Member(id: 'x', name: 'Mo', role: MemberRole.moderator).toJson());
    expect(revived.role, MemberRole.moderator);
    expect(roleName(MemberRole.moderator), 'Moderator');
  });

  group('Custom server roles', () {
    setUp(() => CommunityStore.instance.resetForTest());

    test('effectiveRole lifts a member to their custom role\'s tier', () {
      const bob = Member(id: 'bob', name: 'Bob'); // base member
      const helper =
          CustomRole(id: 'r1', name: 'Helper', tier: MemberRole.moderator);
      const vip = CustomRole(id: 'r2', name: 'VIP'); // cosmetic
      final c = Community(
        id: 'c',
        name: 'C',
        color: '#000',
        roles: [helper, vip],
        members: [
          bob.copyWith(roleId: 'r1'),
          const Member(id: 'ann', name: 'Ann', role: MemberRole.admin)
              .copyWith(roleId: 'r2'),
          const Member(id: 'cal', name: 'Cal'),
        ],
      );
      // A base member wearing a moderator-tier role effectively moderates.
      expect(c.effectiveRole(c.members[0]), MemberRole.moderator);
      // A base admin wearing a cosmetic role keeps the higher of the two.
      expect(c.effectiveRole(c.members[1]), MemberRole.admin);
      // No role → the plain built-in role.
      expect(c.effectiveRole(c.members[2]), MemberRole.member);
      expect(c.roleById('r1'), helper);
      expect(c.roleById('nope'), isNull);
    });

    test('a role can never mint an owner, even from bad JSON', () {
      final r = CustomRole.fromJson(
          {'id': 'r', 'name': 'X', 'tier': 'owner', 'color': '#111'});
      expect(r.tier, MemberRole.member,
          reason: 'owner smuggled into a role tier reads as the floor');
      final store = CommunityStore.instance;
      final c = store.createCommunity('Guild');
      final made = store.addRole(c.id, 'Boss', tier: MemberRole.owner);
      expect(made!.tier, MemberRole.admin,
          reason: 'the highest a role grants is admin');
    });

    test('create, edit, assign, and delete roles (admin-gated)', () {
      final store = CommunityStore.instance;
      final c = store.createCommunity('Guild'); // me = owner
      store.addMember(c.id, const Member(id: 'bob', name: 'Bob'));

      final role = store.addRole(c.id, 'Helper',
          color: '#12B76A', tier: MemberRole.moderator);
      expect(role, isNotNull);
      expect(store.byId(c.id)!.roles.single.name, 'Helper');

      // Edit it.
      store.updateRole(c.id, role!.id, name: 'Mods', tier: MemberRole.admin);
      final edited = store.byId(c.id)!.roles.single;
      expect(edited.name, 'Mods');
      expect(edited.tier, MemberRole.admin);

      // Assign it to Bob; his effective role climbs to admin.
      store.assignRole(c.id, 'bob', role.id);
      final bob = store.byId(c.id)!.members.firstWhere((m) => m.id == 'bob');
      expect(bob.roleId, role.id);
      expect(store.byId(c.id)!.effectiveRole(bob), MemberRole.admin);

      // Assigning a role that doesn't exist is a no-op.
      store.assignRole(c.id, 'bob', 'ghost');
      expect(store.byId(c.id)!.members.firstWhere((m) => m.id == 'bob').roleId,
          role.id);

      // Deleting the role strips it from everyone wearing it.
      store.deleteRole(c.id, role.id);
      expect(store.byId(c.id)!.roles, isEmpty);
      expect(store.byId(c.id)!.members.firstWhere((m) => m.id == 'bob').roleId,
          '');
    });

    test('roles and assignments survive a JSON round trip; old JSON is empty',
        () {
      final store = CommunityStore.instance;
      final c = store.createCommunity('Guild');
      store.addMember(c.id, const Member(id: 'bob', name: 'Bob'));
      final role = store.addRole(c.id, 'VIP', color: '#EF5DA8', badge: '👑')!;
      store.assignRole(c.id, 'bob', role.id);

      final revived = Community.fromJson(store.byId(c.id)!.toJson());
      expect(revived.roles.single.name, 'VIP');
      expect(revived.roles.single.color, '#EF5DA8');
      expect(revived.roles.single.badge, '👑',
          reason: 'the emoji badge survives a round trip');
      expect(revived.members.firstWhere((m) => m.id == 'bob').roleId, role.id);

      // Roles ride the invite/structure so every member sees the same badges.
      final invite =
          store.exportInvite(c.id, myDigits: '15550100', myName: 'Me')!;
      expect((invite['roles'] as List).single['badge'], '👑',
          reason: 'roles (with badge) carry on the invite/structure wire');

      // A server from before the feature has no roles and no assignments.
      final oldJson = store.byId(c.id)!.toJson()..remove('roles');
      final old = Community.fromJson(oldJson);
      expect(old.roles, isEmpty);
    });

    test('an admin adds members directly; a member cannot', () {
      final store = CommunityStore.instance;
      final c = store.createCommunity('Guild'); // me = owner
      final snap = store.addMembersByAdmin(
        c.id,
        [const Member(id: 'u_15550142', name: 'Del')],
        myDigits: '15550100',
        myName: 'Me',
      );
      // The newcomer is on the roster now, and the snapshot to hand them is
      // flagged so their device joins on receipt.
      expect(
          store.byId(c.id)!.members.any((m) => m.id == 'u_15550142'), isTrue);
      expect(snap, isNotNull);
      expect(snap!['added'], isTrue);
      expect((snap['members'] as List).any((m) => m['id'] == 'u_15550142'),
          isTrue);

      // A plain member can't: a server I merely joined (me = member) refuses.
      final joined = store.joinFromInvite({
        'id': 'srv_x',
        'name': 'Someone else\'s',
        'secret': 'aa',
        'members': const [],
      }, myDigits: '15550100', myName: 'Me');
      expect(store.canManageServer(joined!.id), isFalse);
      expect(
          store.addMembersByAdmin(
              joined.id, [const Member(id: 'u_1', name: 'X')],
              myDigits: '15550100', myName: 'Me'),
          isNull);
      expect(store.byId(joined.id)!.members.any((m) => m.id == 'u_1'), isFalse);
    });

    test('an admin-add invite auto-joins on receipt; a plain/paid one does not',
        () {
      final store = CommunityStore.instance;
      final c = store.createCommunity('Team'); // me = owner
      final base =
          store.exportInvite(c.id, myDigits: '15550142', myName: 'Del')!;
      store.deleteCommunity(c.id); // stand in for the recipient not being in it
      expect(store.byId(c.id), isNull);

      // A plain invite (no flag) waits for a tap — no auto-join.
      RelayService.instance
          .maybeAutoJoinServer(jsonEncode(base), myPhone: '+1 555 0142');
      expect(store.byId(c.id), isNull);

      // Flagged `added` joins straight away.
      RelayService.instance.maybeAutoJoinServer(
          jsonEncode({...base, 'added': true}),
          myPhone: '+1 555 0142');
      expect(store.byId(c.id), isNotNull,
          reason: 'an admin-add invite joins on receipt');

      // A PAID server never auto-joins — the paywall stands.
      final p = store.createCommunity('Paid');
      final paidSnap =
          store.exportInvite(p.id, myDigits: '15550142', myName: 'D')!;
      store.deleteCommunity(p.id);
      RelayService.instance.maybeAutoJoinServer(
          jsonEncode(
              {...paidSnap, 'added': true, 'paid': true, 'priceCents': 500}),
          myPhone: '+1 555 0142');
      expect(store.byId(p.id), isNull,
          reason: 'a paid server needs a pass, not a free auto-join');

      // Source pins: the UI gates the add on admin rights and routes through
      // the admin funnel; the receive path only auto-joins accepted contacts.
      expect(
          File('lib/screens/communities.dart')
              .readAsStringSync()
              .contains('canManageServer(community.id)'),
          isTrue);
      final addScreen =
          File('lib/screens/add_server_members_screen.dart').readAsStringSync();
      expect(addScreen.contains('addMembersByAdmin'), isTrue);
      // The wire text reads from the recipient's side ("Added you to X"); the
      // adder's own chat copy reads from theirs ("You added X"), so the adder's
      // list doesn't look like the person added THEM.
      expect(addScreen.contains('Added you to "'), isTrue);
      expect(addScreen.contains('You added '), isTrue);
      final relay = File('lib/relay/relay_service.dart').readAsStringSync();
      expect(relay.contains('!knownChat.isRequest'), isTrue,
          reason: 'never auto-join from a stranger or a message request');
    });

    testWidgets('an admin builds a role and badges a member from the UI',
        (tester) async {
