  group('Okay AI assistant', () {
    setUp(() {
      AiAssistant.instance.resetForTest();
      AiMemory.instance.resetForTest();
      AiPassStore.instance.resetForTest();
      SharedPreferences.setMockInitialValues({});
    });
    tearDown(() {
      AiAssistant.instance.resetForTest();
      AiMemory.instance.resetForTest();
      AiPassStore.instance.resetForTest();
    });

    test('it remembers facts the model returns, deduped and capped', () async {
      await AiMemory.instance
          .addAll(['Likes short answers', 'Building an app']);
      expect(AiMemory.instance.items.length, 2);
      // A duplicate (case-insensitive) is not kept twice.
      await AiMemory.instance.addAll(['likes short answers']);
      expect(AiMemory.instance.items.length, 2);
      // Send absorbs new memories the function returns.
      AiAssistant.debugReplyOverride = (_) async => 'noted';
      // The override returns only a reply string, so memory comes from the
      // store API directly here; the send/absorb wiring is covered below.
      await AiMemory.instance.remove('Building an app');
      expect(AiMemory.instance.items, ['Likes short answers']);
      await AiMemory.instance.clear();
      expect(AiMemory.instance.isEmpty, isTrue);
    });

    test('the free daily allowance gates further messages until a pass',
        () async {
      AiAssistant.debugReplyOverride = (_) async => 'ok';
      expect(AiAssistant.instance.needsUpgrade, isFalse);
      // Spend the whole free allowance.
      for (var i = 0; i < AiAssistant.freePerDay; i++) {
        await AiAssistant.instance.send('q$i');
      }
      expect(AiAssistant.instance.remainingFreeToday, 0);
      expect(AiAssistant.instance.needsUpgrade, isTrue);
      // send now refuses (no user turn added).
      final before = AiAssistant.instance.turns.length;
      final ok = await AiAssistant.instance.send('one more');
      expect(ok, isFalse);
      expect(AiAssistant.instance.turns.length, before);
      // A pass lifts the gate.
      await AiPassStore.instance.debugGrant();
      expect(AiAssistant.instance.needsUpgrade, isFalse);
      expect(await AiAssistant.instance.send('now it works'), isTrue);
    });

    test('the app owner is never rate-limited', () async {
      addTearDown(PlatformModeration.instance.resetForTest);
      AiAssistant.debugReplyOverride = (_) async => 'ok';
      // A normal account hits the gate after the free allowance.
      for (var i = 0; i < AiAssistant.freePerDay; i++) {
        await AiAssistant.instance.send('q$i');
      }
      expect(AiAssistant.instance.needsUpgrade, isTrue);
      // The owner is exempt — no gate, unlimited remaining.
      PlatformModeration.instance.debugSet(role: PlatformRole.owner);
      expect(AiAssistant.instance.needsUpgrade, isFalse);
      expect(AiAssistant.instance.remainingFreeToday, greaterThan(1000));
    });

    test('the memory store holds no network path — it is on-device', () {
      final src = File('lib/state/ai_memory.dart').readAsStringSync();
      for (final banned in ['http', 'Supabase', 'functions.invoke']) {
        expect(src.contains(banned), isFalse,
            reason: 'per-user memory must stay on the device; found "$banned"');
      }
    });

    test('feedback is submitted only after consent; off by default', () async {
      AiConsent.instance.resetForTest();
      addTearDown(AiConsent.instance.resetForTest);
      AiAssistant.debugReplyOverride = (_) async => 'an answer';
      await AiAssistant.instance.send('a question');
      final replyIndex = AiAssistant.instance.turns.length - 1;

      final submitted = <(String, String, int)>[];
      AiAssistant.debugFeedbackOverride = (p, r, rating) async {
        submitted.add((p, r, rating));
      };

      // Consent OFF (the default): a thumbs-up marks locally but uploads
      // nothing.
      expect(AiConsent.instance.on, isFalse);
      final wentUp = await AiAssistant.instance.rate(replyIndex, 1);
      expect(wentUp, isFalse);
      expect(submitted, isEmpty);
      expect(AiAssistant.instance.turns[replyIndex].rating, 1);

      // Consent ON: the exchange + rating is submitted.
      await AiConsent.instance.set(true);
      final wentUp2 = await AiAssistant.instance.rate(replyIndex, -1);
      expect(wentUp2, isTrue);
      expect(submitted.single, ('a question', 'an answer', -1));
    });

    test('the training corpus is opt-in and only AI conversations', () {
      // A source pin: the consent copy names the assistant, not human chats,
      // and defaults off.
      final consent = File('lib/state/ai_consent.dart').readAsStringSync();
      expect(consent.contains('_on = false'), isTrue,
          reason: 'training consent must default off');
      // The feedback function only ever stores what the client sends it (an
      // assistant exchange), and lives behind the client\'s consent gate.
      final fn =
          File('supabase/functions/ai-feedback/index.ts').readAsStringSync();
      expect(fn.contains('ai_training_samples'), isTrue);
    });

    test('incognito leaves nothing on the device and restores the saved chat',
        () async {
      SharedPreferences.setMockInitialValues({});
      final ai = AiAssistant.instance;
      AiAssistant.debugReplyOverride = (_) async => 'ok';
      await ai.send('remember this');
      expect(ai.turns.length, 2);

      // Entering starts a fresh, ephemeral thread.
      await ai.setIncognito(true);
      expect(ai.incognito, isTrue);
      expect(ai.turns, isEmpty);
      await ai.send('a secret');
      expect(ai.turns.map((t) => t.text), contains('a secret'));

      // Nothing incognito reached disk — the saved thread is untouched.
      final prefs = await SharedPreferences.getInstance();
      final onDisk = prefs.getString('ai_assistant_history_v1') ?? '';
      expect(onDisk, isNot(contains('a secret')));
      expect(onDisk, contains('remember this'));

      // Leaving brings the saved chat back; the secret is gone for good.
      await ai.setIncognito(false);
      expect(ai.incognito, isFalse);
      expect(ai.turns.map((t) => t.text), contains('remember this'));
      expect(ai.turns.map((t) => t.text), isNot(contains('a secret')));
    });

    test('incognito never sends memory, never learns, never trains', () async {
      AiConsent.instance.resetForTest();
      addTearDown(AiConsent.instance.resetForTest);
      final ai = AiAssistant.instance;
      AiAssistant.debugReplyOverride = (_) async => 'ok';
      var uploaded = false;
      AiAssistant.debugFeedbackOverride = (_, __, ___) async {
        uploaded = true;
      };
      await ai.setIncognito(true);
      await ai.send('hello');
      // Even with consent ON, an incognito reply is never eligible to train.
      await AiConsent.instance.set(true);
      final idx = ai.turns.length - 1;
      final sent = await ai.rate(idx, 1);
      expect(sent, isFalse);
      expect(uploaded, isFalse);
      // The wiring that carries this is present in source.
      final src = File('lib/state/ai_assistant.dart').readAsStringSync();
      expect(src, contains("'learn': !_incognito"));
      expect(src, contains("if (!_incognito) 'memories'"));
    });

    test('personality presets and custom resolve to a style instruction',
