  group('VoIP / virtual number gate', () {
    test('toll-free, premium and non-geographic NANP ranges are refused', () {
      // Toll-free.
      expect(VoipNumbers.reason('+1 800 555 0100'), contains('Toll-free'));
      expect(VoipNumbers.reason('+1 833 555 0100'), isNotNull);
      // Premium 900.
      expect(VoipNumbers.reason('+1 900 555 0100'), contains('premium'));
      // Personal-communications / VoIP 5XX.
      expect(VoipNumbers.reason('+1 500 555 0100'), contains('VoIP'));
      expect(VoipNumbers.reason('+1 521 555 0100'), isNotNull);
    });

    test('an ordinary mobile number passes', () {
      expect(VoipNumbers.reason('+1 415 555 0132'), isNull);
      expect(VoipNumbers.reason('+1 212 555 0100'), isNull);
      // 11 digits with the leading country 1 is read the same way.
      expect(VoipNumbers.reason('+1 14155550132'), isNull);
    });

    test('the reviewer/demo account is exempt even on its 500 range', () {
      // App Review's account lives on a 500 code; blocking it would lock the
      // reviewer out. It must pass despite 500 being a refused range.
      expect(VoipNumbers.reason('+1 500 555 0006'), isNull);
      // A different 500 number is still refused.
      expect(VoipNumbers.reason('+1 500 555 0007'), isNotNull);
    });

    test('numbers outside the NANP are left alone (no false block)', () {
      // A UK mobile — we don't have a prefix map for it, so we don't guess.
      expect(VoipNumbers.reason('+44 7911 123456'), isNull);
      // Empty / partial input is the length validator's job, not this.
      expect(VoipNumbers.reason(''), isNull);
    });

    test('the login form runs the VoIP check', () {
      final src =
          File('lib/screens/auth/phone_login_screen.dart').readAsStringSync();
      expect(src, contains('VoipNumbers.reason'),
          reason: 'the phone field validator must call the gate');
    });
  });

  group('On-device translation', () {
    setUp(() => TranslateService.instance.resetForTest());
    tearDown(() => TranslateService.instance.resetForTest());

    test('translates through the channel and caches the answer', () async {
      TranslateService.debugAvailableOverride = true;
      var calls = 0;
      TranslateService.debugTranslateOverride = (text, target) async {
        calls++;
        return '[$target] $text';
      };
      final svc = TranslateService.instance;
      final out = await svc.translate('hello', into: 'es');
      expect(out, '[es] hello');
      // A second identical request is served from cache, not the framework.
      final again = await svc.translate('hello', into: 'es');
      expect(again, '[es] hello');
      expect(calls, 1, reason: 'the second call hits the cache');
    });

    test('blank text and an unavailable device both return null', () async {
      final svc = TranslateService.instance;
      TranslateService.debugAvailableOverride = true;
      expect(await svc.translate('   '), isNull);
      // Unavailable device: no translation, no crash.
      TranslateService.debugAvailableOverride = false;
      expect(await svc.translate('hello'), isNull);
    });

    test('the target language persists and only accepts known codes', () async {
      SharedPreferences.setMockInitialValues({});
      final svc = TranslateService.instance;
      await svc.setTarget('fr');
      expect(svc.target, 'fr');
      expect(svc.targetName(), 'French');
      // An unknown code is ignored.
      await svc.setTarget('zz');
      expect(svc.target, 'fr');
      // It survives a reload.
      svc.resetForTest();
      await svc.load();
      expect(svc.target, 'fr');
    });

    test('the service holds no network path — it is on-device only', () {
      final src = File('lib/state/translate_service.dart').readAsStringSync();
      for (final banned in ['http', 'Supabase', 'functions.invoke', 'Dio']) {
        expect(src.contains(banned), isFalse,
            reason: 'translation of encrypted chat must never leave the '
                'device; found "$banned"');
      }
    });
  });

  test('a server is born with its privacy settings, not wide open', () {
    CommunityStore.instance.resetForTest();
    final c = CommunityStore.instance.createCommunity(
      'Announcements',
      description: 'Read-only news',
      icon: '🚀',
      invitePolicy: invitePolicyAdmins,
      membersCanMessage: false,
      membersCanCreateChannels: false,
      membersCanPost: false,
      slowModeSeconds: 30,
    );
    expect(c.description, 'Read-only news');
    expect(c.icon, '🚀');
    expect(c.invitePolicy, invitePolicyAdmins);
    expect(c.membersCanMessage, isFalse);
    expect(c.membersCanCreateChannels, isFalse);
    expect(c.membersCanPost, isFalse);
    expect(c.slowModeSeconds, 30);

    // The new fields survive a JSON round trip…
    final revived = Community.fromJson(c.toJson());
    expect(revived.invitePolicy, invitePolicyAdmins);
    expect(revived.membersCanMessage, isFalse);
    // …and JSON from an older build (no such keys) reads as open, which is
    // the behaviour every existing server already had.
    final oldJson = c.toJson()
      ..remove('invitePolicy')
      ..remove('membersCanMessage');
    final old = Community.fromJson(oldJson);
    expect(old.invitePolicy, invitePolicyEveryone);
    expect(old.membersCanMessage, isTrue);

    // Defaults stay open when nothing is chosen.
    final open = CommunityStore.instance.createCommunity('Open');
    expect(open.invitePolicy, invitePolicyEveryone);
    expect(open.membersCanMessage, isTrue);
  });

  test('invite policy decides who may share the server', () {
    // The pure matrix, role by role.
    expect(roleCanInvite(MemberRole.member, invitePolicyEveryone), isTrue);
    expect(roleCanInvite(MemberRole.member, invitePolicyModerators), isFalse);
    expect(roleCanInvite(MemberRole.moderator, invitePolicyModerators), isTrue);
    expect(roleCanInvite(MemberRole.moderator, invitePolicyAdmins), isFalse);
    expect(roleCanInvite(MemberRole.admin, invitePolicyAdmins), isTrue);
    expect(roleCanInvite(MemberRole.owner, invitePolicyAdmins), isTrue);
    // A policy string this build doesn't know fails closed for members —
    // a privacy choice must not widen on devices that can't read it.
    expect(roleCanInvite(MemberRole.member, 'via-qr'), isFalse);
    expect(roleCanInvite(MemberRole.owner, 'via-qr'), isTrue);

    // Store level: the creator (owner) may always invite; the policy rides
    // inside the invite itself and binds a joiner from the first moment.
    CommunityStore.instance.resetForTest();
    final store = CommunityStore.instance;
    final c = store.createCommunity('Sealed', invitePolicy: invitePolicyAdmins);
    expect(store.canInvite(c.id), isTrue);
    final invite =
        store.exportInvite(c.id, myDigits: '15550101111', myName: 'Alice')!;
    expect(invite['invitePolicy'], invitePolicyAdmins);
    store.deleteCommunity(c.id);
    final joined = store.joinFromInvite(Map<String, dynamic>.from(invite),
        myDigits: '15550102222', myName: 'Bob')!;
    expect(joined.invitePolicy, invitePolicyAdmins);
    expect(store.canInvite(joined.id), isFalse);
  });

  test('a broadcast-only server silences members, not moderators', () {
    CommunityStore.instance.resetForTest();
    final store = CommunityStore.instance;
    final c = store.createCommunity('News', membersCanMessage: false);
    // The owner speaks freely in their own broadcast server.
    expect(store.canSendMessages(c.id), isTrue);

    // A joiner is read-only from the moment they join — the setting travels
    // inside the invite, not only in later structure broadcasts.
    final invite =
        store.exportInvite(c.id, myDigits: '15550101111', myName: 'Alice')!;
    store.deleteCommunity(c.id);
    store.joinFromInvite(Map<String, dynamic>.from(invite),
        myDigits: '15550102222', myName: 'Bob');
    expect(store.canSendMessages(c.id), isFalse);

    // The owner later opens the floor; the structure broadcast flips it
    // on Bob's device too.
    final opened = Map<String, dynamic>.from(invite);
    opened['membersCanMessage'] = true;
    opened['members'] = [
      ...(invite['members'] as List),
      const Member(id: 'u_15550102222', name: 'Bob').toJson(),
    ];
    store.applyRemoteStructure(opened, myDigits: '15550102222');
    expect(store.canSendMessages(c.id), isTrue);
  });

