          .addMember(id, const Member(id: 'm_grace', name: 'Grace Hopper'));
      expect(
          CommunityStore.instance
              .byId(id)!
              .members
              .any((m) => m.id == 'm_grace'),
          isFalse);

      CommunityStore.instance.unbanMember(id, 'm_grace');
      CommunityStore.instance
          .addMember(id, const Member(id: 'm_grace', name: 'Grace Hopper'));
      c = CommunityStore.instance.byId(id)!;
