      expect(CommunityStore.instance.byId(id)!.members.any((m) => m.id == 'me'),
          isTrue);
    });

    test('server invites: export, join on another device, sealed traffic', () {
      CommunityStore.instance.resetForTest();
      final c = CommunityStore.instance.createCommunity('Crew');
      // Every new server mints a real 32-byte secret.
      expect(c.secret, isNotEmpty);
      expect(c.secretBytes, hasLength(32));

      final invite = CommunityStore.instance
          .exportInvite(c.id, myDigits: '15550101111', myName: 'Alice')!;
      // The sender's 'me' travels as their wire id, and history stays home.
      final members = (invite['members'] as List).cast<Map>();
      expect(members.any((m) => m['id'] == 'me'), isFalse);
      expect(
          members
              .any((m) => m['id'] == 'u_15550101111' && m['name'] == 'Alice'),
          isTrue);
      expect(members.any((m) => m['role'] == 'owner'), isTrue);
      expect(
          (invite['channels'] as List).first.containsKey('messages'), isFalse);
      expect(invite['secret'], c.secret);

      // The recipient joins: same id and secret, themselves as a member.
      CommunityStore.instance.deleteCommunity(c.id);
      final joined = CommunityStore.instance.joinFromInvite(
          Map<String, dynamic>.from(invite),
          myDigits: '15550102222',
          myName: 'Bob')!;
      expect(joined.id, c.id);
      expect(joined.secret, c.secret);
      expect(joined.members.any((m) => m.id == 'me'), isTrue);
      expect(joined.members.any((m) => m.id == 'u_15550101111'), isTrue);
      expect(CommunityStore.instance.canModerate(joined.id), isFalse);
      // Joining twice is a no-op.
      expect(
          CommunityStore.instance
              .joinFromInvite(Map<String, dynamic>.from(invite),
                  myDigits: '15550102222', myName: 'Bob')!
              .id,
          joined.id);

      // The joiner shows up on the sender's roster via the relay event.
      CommunityStore.instance.applyRemoteJoin(
          joined.id, const Member(id: 'u_15550102222', name: 'Bob'));
      expect(
          CommunityStore.instance
              .byId(joined.id)!
              .members
              .any((m) => m.name == 'Bob'),
          isTrue);

      // Channel messages from members apply once, then dedupe.
      final chan = joined.channels.first;
      final msg = Message(
          id: 'r1',
          text: 'hi from Alice',
          time: DateTime.now(),
          isMe: false,
          senderName: 'Alice');
      CommunityStore.instance.addRemoteChannelMessage(joined.id, chan.id, msg);
      CommunityStore.instance.addRemoteChannelMessage(joined.id, chan.id, msg);
      expect(
          CommunityStore.instance
              .byId(joined.id)!
              .channels
              .first
              .messages
              .where((m) => m.id == 'r1'),
          hasLength(1));
      // Unknown servers/channels drop silently.
      CommunityStore.instance.addRemoteChannelMessage('nope', chan.id, msg);
      CommunityStore.instance.addRemoteChannelMessage(joined.id, 'nope', msg);

      // Wire ids round-trip to inbox digits for the offline fan-out; local
      // ids have no inbox.
      expect(CommunityStore.digitsOfWireId('u_15550101111'), '15550101111');
      expect(CommunityStore.digitsOfWireId('me'), isNull);
      expect(CommunityStore.digitsOfWireId('m_ada'), isNull);

      // The bus payload is sealed with the server secret and round-trips.
      final sealed =
          E2eCrypto.encrypt(joined.secretBytes!, 'channel plaintext');
      expect(sealed.contains('plaintext'), isFalse);
      expect(
          E2eCrypto.decrypt(joined.secretBytes!, sealed), 'channel plaintext');

      // Feed posts ride the same sealed bus: their body round-trips through
      // the server key and leaks nothing in ciphertext.
      final post = FeedPost(
          id: 'fp1',
          communityId: joined.id,
          authorName: 'Alice',
          authorUsername: 'alice',
          time: DateTime(2026, 1, 1),
          text: 'secret plans for the launch');
      final sealedPost = E2eCrypto.encrypt(
          joined.secretBytes!, jsonEncode({'post': post.toJson()}));
      expect(sealedPost.contains('secret plans'), isFalse);
      final opened =
          jsonDecode(E2eCrypto.decrypt(joined.secretBytes!, sealedPost)!)
              as Map;
      expect(
          FeedPost.fromJson(Map<String, dynamic>.from(opened['post'] as Map))
              .text,
          'secret plans for the launch');

      // An invite message survives the JSON round trip.
      final inviteMsg = Message(
          id: 'i1',
          text: 'Join my server',
          time: DateTime.now(),
          isMe: true,
          serverInvite: jsonEncode(invite));
      final decoded = Message.fromJson(inviteMsg.toJson());
      expect(decoded.isServerInvite, isTrue);
      expect(jsonDecode(decoded.serverInvite)['id'], c.id);
    });

    test('structure sync: members converge, kicked devices drop out', () {
      CommunityStore.instance.resetForTest();
      final store = CommunityStore.instance;
      // Alice's device: create a server and reshape it.
      final c = store.createCommunity('Crew');
      final changed = <String>[];
      store.onStructureChanged = changed.add;
      store.addChannel(c.id, 'plans');
      store.setSlowMode(c.id, 30);
      expect(changed, [c.id, c.id]); // every structural edit broadcasts

      final structure = store.exportStructure(c.id,
          myDigits: '15550101111', myName: 'Alice')!;
      expect(structure['slowModeSeconds'], 30);

      // Bob's device: joined earlier (fewer channels), then the update lands.
      final invite =
          store.exportInvite(c.id, myDigits: '15550101111', myName: 'Alice')!;
      store.deleteCommunity(c.id);
      store.joinFromInvite(Map<String, dynamic>.from(invite),
          myDigits: '15550102222', myName: 'Bob');
      // Bob has local history in general that a sync must not erase.
      final generalId = store.byId(c.id)!.channels.first.id;
      store.postMessage(c.id, generalId,
          Message(id: 'kept', text: 'hi', time: DateTime.now(), isMe: true));
      // Bob must appear in the incoming roster to stay a member.
      final withBob = Map<String, dynamic>.from(structure);
      withBob['members'] = [
        ...(structure['members'] as List),
        const Member(id: 'u_15550102222', name: 'Bob').toJson(),
      ];
      store.applyRemoteStructure(withBob, myDigits: '15550102222');
      final synced = store.byId(c.id)!;
      expect(synced.channels.any((ch) => ch.name == 'plans'), isTrue);
      expect(synced.slowModeSeconds, 30);
      expect(
          synced.channels
              .firstWhere((ch) => ch.id == generalId)
              .messages
              .any((m) => m.id == 'kept'),
          isTrue); // local history survived
      expect(synced.members.any((m) => m.id == 'me'), isTrue);

      // A roster that no longer lists Bob removes the server from his device.
      store.applyRemoteStructure(Map<String, dynamic>.from(structure),
          myDigits: '15550102222');
      expect(store.byId(c.id), isNull);
    });

    test(
        'applyAuthoritativeStructure reconciles against fetched rows, '
        'preserving local-only fields', () {
      // Phase 1 of "central authority" (2026-08-13): the durable Postgres
      // backstop over the same gossip protocol applyRemoteStructure already
      // handles. A SEPARATE method, a different input shape (column-map rows
      // from a SQL fetch, not one JSON snapshot), same preserve-local-fields
      // discipline.
      CommunityStore.instance.resetForTest();
      final store = CommunityStore.instance;
      final c = store.createCommunity('Crew');
      final generalId = c.channels.first.id;
      store.postMessage(c.id, generalId,
          Message(id: 'kept', text: 'hi', time: DateTime.now(), isMe: true));
      store.addChannel(c.id, 'plans');
      final plansId = store.byId(c.id)!.channels.last.id;

      store.applyAuthoritativeStructure(
        communityId: c.id,
        server: {
          'name': 'Renamed Crew',
          'slow_mode_seconds': 30,
        },
        channels: [
          // 'general' renamed, local history must survive; 'plans' dropped —
          // rebuild-deletes-by-omission, matching applyRemoteStructure's own
          // trick.
          {'id': generalId, 'name': 'lounge', 'type': 'text'},
        ],
        roles: [
          {'id': 'r1', 'name': 'VIP', 'tier': 'member', 'color': '#123456'},
        ],
        members: [
          {'member_phone': '15550101111', 'role': 'owner'},
          {'member_phone': '15550102222', 'role': 'moderator'},
        ],
        bans: [
          {'member_phone': '15550109999', 'member_name': 'Gone'},
        ],
        myDigits: '15550101111',
      );

      final synced = store.byId(c.id)!;
      expect(synced.name, 'Renamed Crew');
      expect(synced.slowModeSeconds, 30);
      // 'plans' is gone — no longer in the fetched channel set.
      expect(synced.channels.any((ch) => ch.id == plansId), isFalse);
      // 'general' kept its local history under its new name.
      final lounge = synced.channels.firstWhere((ch) => ch.id == generalId);
      expect(lounge.name, 'lounge');
      expect(lounge.messages.any((m) => m.id == 'kept'), isTrue);
      expect(synced.roles.single.name, 'VIP');
      // I am the owner (myDigits matches the fetched owner row) — my local
      // 'me' entry picks up that role.
      expect(synced.members.first.id, 'me');
      expect(synced.members.first.role, MemberRole.owner);
      expect(
          synced.members.any(
              (m) => m.id == 'u_15550102222' && m.role == MemberRole.moderator),
          isTrue);
      expect(synced.bannedMembers.single.name, 'Gone');
    });

    test(
        'applyAuthoritativeStructure sorts the owner to the front regardless '
        'of fetch order', () {
      // The rest of this app trusts members.first for who owns a server
      // (RelayService._syncCommunityStructure among others) — Postgres row
      // order is not guaranteed to put the owner first even with an ORDER BY,
      // so this is re-asserted rather than merely hoped for.
      CommunityStore.instance.resetForTest();
      final store = CommunityStore.instance;
      final c = store.createCommunity('Crew');
      store.applyAuthoritativeStructure(
        communityId: c.id,
        server: const {},
        members: [
          // Owner listed SECOND on purpose.
          {'member_phone': '15550102222', 'role': 'member'},
          {'member_phone': '15550101111', 'role': 'owner'},
        ],
        myDigits: '15550102222',
      );
      final synced = store.byId(c.id)!;
      expect(synced.members.first.role, MemberRole.owner);
      expect(synced.members.first.id, 'u_15550101111');
    });

    test('applyAuthoritativeStructure never creates a community from nothing',
        () {
      // Mirrors applyRemoteStructure's own guard: a fetch can only refine a
      // community this device already has a local copy of, from a real
      // invite/join/mesh sync — never materialize one out of a bare fetch.
      CommunityStore.instance.resetForTest();
      final store = CommunityStore.instance;
      store.applyAuthoritativeStructure(
        communityId: 'never_joined',
        server: const {'name': 'Ghost'},
        myDigits: '15550101111',
      );
      expect(store.byId('never_joined'), isNull);
    });

    test(
        'ChatStore.applyAuthoritativeChatStructure reconciles a group\'s '
        'roster and identity, preserving local-only fields', () {
      // Phase 3 of "central authority" (2026-08-13): the same durable
      // Postgres backstop as applyAuthoritativeStructure, now for group
      // chats (docs/chat_structure.sql), reconciled against gupd gossip.
      ChatStore.instance.reset();
      final store = ChatStore.instance;
      final chat = Chat(
        id: 'group_1',
        contact: const AppUser(
            id: 'group_1',
            name: 'Old Name',
            avatarColor: '#111111',
            about: 'old about',
            isGroup: true),
        messages: [
          Message(id: 'kept', text: 'hi', time: DateTime.now(), isMe: true)
        ],
        members: const [
          AppUser(
              id: '+15550101111',
              name: 'Me',
              avatarColor: '#222222',
              about: '',
              phone: '+15550101111'),
          AppUser(
              id: '+15550102222',
              name: 'Bob',
              avatarColor: '#333333',
              about: '',
              phone: '+15550102222'),
        ],
        unreadCount: 3,
        isPinned: true,
      );
      store.upsert(chat);

      store.applyAuthoritativeChatStructure(
        chatId: 'group_1',
        chat: const {
          'is_group': true,
          'name': 'New Name',
          'avatar_color': '#444444',
          'about': 'new about',
        },
        members: const [
          {'member_phone': '15550101111'},
          // Bob (102222) is gone — rebuild-deletes-by-omission; a new
          // member (103333) with no local name shows the fallback.
          {'member_phone': '15550103333'},
        ],
      );

      final synced = store.chatById('group_1')!;
      expect(synced.contact.name, 'New Name');
      expect(synced.contact.avatarColor, '#444444');
      expect(synced.contact.about, 'new about');
      // Me: name preserved from the existing local entry.
      expect(synced.members.firstWhere((m) => m.phone == '+15550101111').name,
          'Me');
      // Bob dropped, the new member added.
      expect(synced.members.any((m) => m.phone == '+15550102222'), isFalse);
      expect(synced.members.any((m) => m.phone == '15550103333'), isTrue);
      // Local-only fields untouched: chat_members carries no message
      // history, unread count or pin state.
      expect(synced.messages.any((m) => m.id == 'kept'), isTrue);
      expect(synced.unreadCount, 3);
      expect(synced.isPinned, isTrue);
    });

    test(
        'ChatStore.applyAuthoritativeChatStructure never creates a chat '
        'from nothing', () {
      ChatStore.instance.reset();
      final store = ChatStore.instance;
      store.applyAuthoritativeChatStructure(
        chatId: 'never_joined',
        chat: const {'is_group': true, 'name': 'Ghost'},
      );
      expect(store.chatById('never_joined'), isNull);
    });

    test(
        'ChatStore.applyAuthoritativeChatStructure is a no-op for a 1:1 — '
        'there is no roster or identity for a 1:1 to reconcile', () {
      // See docs/chat_structure.sql's own header: a 1:1's contact identity
      // is each side's own locally-chosen name for the other person, and
      // Chat.members stays empty for a 1:1 by definition — chat_structure
      // never publishes a name/avatar/about for one, so a fetch has
      // nothing to apply beyond the row existing at all.
      ChatStore.instance.reset();
      final store = ChatStore.instance;
      const chat = Chat(
        id: 'chat_+15550109999',
        contact: AppUser(
            id: '+15550109999',
            name: 'My Name For Them',
            avatarColor: '#555555',
            about: '',
            phone: '+15550109999'),
        messages: [],
      );
      store.upsert(chat);
      store.applyAuthoritativeChatStructure(
        chatId: 'chat_+15550109999',
        chat: const {'is_group': false},
        members: const [
          {'member_phone': '15550101111'},
          {'member_phone': '15550109999'},
        ],
      );
      final synced = store.chatById('chat_+15550109999')!;
      expect(synced.contact.name, 'My Name For Them');
      expect(synced.members, isEmpty);
    });

    test('unread badges count what this device has not seen', () {
      CommunityStore.instance.resetForTest();
      final store = CommunityStore.instance;
      final c = store.createCommunity('Team');
      final chan = c.channels.first;
      store.postMessage(c.id, chan.id,
          Message(id: 'u1', text: 'a', time: DateTime.now(), isMe: false));
      store.postMessage(c.id, chan.id,
          Message(id: 'u2', text: 'b', time: DateTime.now(), isMe: false));
      Channel channel() =>
          store.byId(c.id)!.channels.firstWhere((x) => x.id == chan.id);
      expect(store.unreadInChannel(channel()), 2);
      expect(store.unreadInCommunity(store.byId(c.id)!), 2);
      store.markChannelSeen(chan.id, channel().messages.length);
      expect(store.unreadInChannel(channel()), 0);
      // New arrivals count again.
      store.postMessage(c.id, chan.id,
          Message(id: 'u3', text: 'c', time: DateTime.now(), isMe: false));
      expect(store.unreadInChannel(channel()), 1);
    });

