    CommunityStore.instance.setMemberRole(c.id, 'me', MemberRole.member);
    expect(
        CommunityStore.instance
            .byId(c.id)!
            .members
            .firstWhere((m) => m.id == 'me')
            .role,
        MemberRole.owner); // owner can't be demoted
