    CommunityStore.instance.votePollInChannel(c.id, channelId, 'cpoll', 1);
    final poll = CommunityStore.instance
        .byId(c.id)!
        .channels
        .firstWhere((ch) => ch.id == channelId)
        .messages
        .firstWhere((m) => m.id == 'cpoll');
