  test('setOutgoingStatus upgrades only outgoing messages, never downgrades',
      () {
    ChatStore.instance.reset();
    // Bob's chat has an outgoing message at status read.
    ChatStore.instance.addMessage(
      'c_bob',
      Message(
        id: 'out1',
        text: 'yo',
        time: DateTime(2024),
        isMe: true,
        status: MessageStatus.sent,
      ),
    );

    // A 'delivered' receipt upgrades sent -> delivered.
    ChatStore.instance.setOutgoingStatus('c_bob', MessageStatus.delivered);
    final m1 = ChatStore.instance
        .chatById('c_bob')!
        .messages
        .firstWhere((m) => m.id == 'out1');
    expect(m1.status, MessageStatus.delivered);

    // A later 'read' receipt upgrades to read.
    ChatStore.instance.setOutgoingStatus('c_bob', MessageStatus.read);
    expect(
      ChatStore.instance
          .chatById('c_bob')!
          .messages
          .firstWhere((m) => m.id == 'out1')
          .status,
      MessageStatus.read,
    );

    // A stale 'delivered' receipt must not downgrade a read message.
    ChatStore.instance.setOutgoingStatus('c_bob', MessageStatus.delivered);
    expect(
      ChatStore.instance
          .chatById('c_bob')!
          .messages
          .firstWhere((m) => m.id == 'out1')
          .status,
      MessageStatus.read,
    );

    // Incoming messages are untouched.
    expect(
      ChatStore.instance
          .chatById('c_bob')!
          .messages
          .where((m) => !m.isMe)
          .every((m) => m.status != MessageStatus.read || m.id != 'out1'),
      isTrue,
    );
  });

  group('Relay (device-to-device delivery)', () {
    test('inbox channel id is derived from the phone digits', () {
      expect(RelayService.inboxChannel('+1 (555) 0199'), 'inbox_15550199');
      expect(RelayService.inboxChannel('15550199'),
          RelayService.inboxChannel('+1 555 0199'));
    });

    test('a chat is found by bare digits, the way a push addresses one', () {
      // A notification tap hands over '15550170170'; the chat was created
      // as '+1 555 017 0170'. An exact-id miss used to read as "no chat"
      // and bounce the tap to the system SMS handler — our own alert
      // opening iMessage.
      final store = ChatStore.instance;
      store.hydrate(const {'chats': []});
      addTearDown(store.reset);
      store.upsert(const Chat(
        id: 'chat_fmt',
        contact: AppUser(
            id: '+1 555 017 0170',
            name: 'Pia',
            avatarColor: '#111111',
            phone: '+1 555 017 0170'),
        messages: [],
      ));
      expect(store.chatWithContact('15550170170')?.id, 'chat_fmt');
      expect(store.chatWithContact('+15550170170')?.id, 'chat_fmt');
      expect(store.chatWithContact('15559999999'), isNull);
    });

    test('isOwnNumber matches across country-code formatting, not just exact',
        () {
      final store = ChatStore.instance;
      expect(
          store.isOwnNumber('+1 555 019 9000', myPhone: '15550199000'), isTrue);
      expect(
          store.isOwnNumber('5550199000', myPhone: '+1 555 019 9000'), isTrue);
      expect(store.isOwnNumber('5550199000', myPhone: '5550188000'), isFalse);
      expect(store.isOwnNumber('5550199000', myPhone: null), isFalse);
      expect(store.isOwnNumber('', myPhone: '5550199000'), isFalse);
    });

    test('noteToSelfChat is created once and reused on later calls', () {
      final store = ChatStore.instance;
      store.hydrate(const {'chats': []});
      addTearDown(store.reset);
      final first = store.noteToSelfChat(myAvatarColor: '#123456');
      expect(first.id, 'chat_self');
      expect(first.contact.id, 'self');
      expect(first.contact.phone, isEmpty,
          reason: 'phone-less so it never touches the relay');
      final second = store.noteToSelfChat(myAvatarColor: '#654321');
      expect(second.id, first.id,
          reason: 'the existing note-to-self chat is reused, not recreated');
    });

    test(
        'startChatWith redirects a real-number self-chat to Note to self '
        'instead of a peer chat the relay would silently drop', () {
      final store = ChatStore.instance;
      store.hydrate(const {'chats': []});
      addTearDown(store.reset);
      const me = AppUser(
          id: '+1 555 099 0000',
          name: 'Me',
          avatarColor: '#222222',
          phone: '+1 555 099 0000');
      final chat = store.startChatWith(me,
          myPhone: '15550990000', myAvatarColor: '#123456');
      expect(chat.contact.id, 'self');
      expect(chat.id, 'chat_self');
      // No phantom peer chat was created under the real number — the only
      // chat in the store is the note-to-self one.
      expect(store.chats.length, 1);
      expect(store.chatWithContact('+1 555 099 0000'), isNull);
    });

    test('startChatWith creates and reuses an ordinary peer chat otherwise',
        () {
      final store = ChatStore.instance;
      store.hydrate(const {'chats': []});
      addTearDown(store.reset);
      const bob =
          AppUser(id: 'u_bob2', name: 'Bob', avatarColor: '#333333', phone: '');
      final first = store.startChatWith(bob,
          myPhone: '15550990000', myAvatarColor: '#fff');
      expect(first.contact.id, 'u_bob2');
      final second = store.startChatWith(bob,
          myPhone: '15550990000', myAvatarColor: '#fff');
      expect(second.id, first.id);
    });

    test('an undecryptable message never shows its ciphertext', () {
      // Sealed to a key this device no longer holds (an account switch
      // minted a fresh identity, the old build kept encrypting to the
      // ghost) — the chat used to render the raw base64 as the message.
      final store = ChatStore.instance;
      store.hydrate(const {'chats': []});
      addTearDown(store.reset);
      final blob = base64Encode(List.generate(96, (i) => (i * 37) % 256));
      final added = RelayService.applyIncoming({
        'from': '+1 555 0166',
        'id': 'sealed_old_key_1',
        'c': blob,
        'enc': 2,
        'spk': base64Encode(List.filled(65, 4)),
      }, myPhone: '+1 555 0100', store: store);
      expect(added, isTrue);
      final msg = store.chatWithContact('+1 555 0166')!.messages.single;
      expect(msg.text.contains(blob), isFalse,
          reason: 'ciphertext must never be rendered as a message');
      expect(msg.text, contains('Couldn\'t unlock'),
          reason: 'the failure is said in words the reader can act on');
    });

    test('a key heal rides the mailbox and buries the ghost session', () async {
      // The live 'key' broadcast only reaches an OPEN app, and the peer who
      // sealed to a dead key almost never has theirs open at that moment —
      // "sealed to a key this device no longer has" came back hours apart,
      // forever, because every heal evaporated. The heal must queue too.
      final src = File('lib/relay/relay_service.dart').readAsStringSync();
      final heal = src.substring(src.indexOf('void healPeer('));
      expect(heal.substring(0, heal.indexOf('resync')).contains("event: 'key'"),
          isTrue,
          reason: 'healPeer must queue the re-introduction to the mailbox');
      expect(
          src
              .replaceAll(RegExp(r'\s+'), ' ')
              .contains("case 'key': applyKeyEvent(payload, myPhone: me);"),
          isTrue,
          reason: 'a queued heal must be applied when the mailbox drains');

      // And applying it behaves: a CHANGED key updates the record and
      // buries the ratchet session that belonged to the old identity.
      // ignore: invalid_use_of_visible_for_testing_member
      addTearDown(SecureKeyExchange.instance.resetForTest);
      // ignore: invalid_use_of_visible_for_testing_member
      addTearDown(DoubleRatchet.instance.resetForTest);
      await SecureKeyExchange.instance.load();
      final oldIdentity = SecureKeyExchange.freshForTest();
      final newIdentity = SecureKeyExchange.freshForTest();
      SecureKeyExchange.instance
          .rememberPeer('+1 555 0166', oldIdentity.myPublicKey!);
      DoubleRatchet.instance.encrypt('15550100', '15550166', 'seed session');
      expect(DoubleRatchet.instance.hasSession('15550166'), isTrue);
      RelayService.instance.applyKeyEvent({
        'from': '+1 555 0166',
        'pub': newIdentity.myPublicKey!,
      }, myPhone: '+1 555 0100');
      expect(DoubleRatchet.instance.hasSession('15550166'), isFalse,
          reason: 'the old identity\'s session must not outlive its key');
      expect(SecureKeyExchange.instance.peerKey('+1 555 0166'),
          newIdentity.myPublicKey);
    });

    test('a heal buries the session even when the key never changed', () async {
      // The old rule buried only on a CHANGED key. But a desynced ratchet
      // with the SAME identity fails exactly the same way on the far side —
      // and the heal arrived, matched the cached key, did nothing, and the
      // padlocks kept coming forever. A 'key' event marked as a heal buries
      // regardless, because a failed unlock is proof the session is dead
      // whatever the identity says.
      // ignore: invalid_use_of_visible_for_testing_member
      addTearDown(SecureKeyExchange.instance.resetForTest);
      // ignore: invalid_use_of_visible_for_testing_member
      addTearDown(DoubleRatchet.instance.resetForTest);
      await SecureKeyExchange.instance.load();
      final peer = SecureKeyExchange.freshForTest();
      SecureKeyExchange.instance.rememberPeer('+1 555 0188', peer.myPublicKey!);
      DoubleRatchet.instance.encrypt('15550100', '15550188', 'seed');
      expect(DoubleRatchet.instance.hasSession('15550188'), isTrue);
      // A plain announce with the same key is startup traffic and must not
      // kill a healthy session.
      RelayService.instance.applyKeyEvent({
        'from': '+1 555 0188',
        'pub': peer.myPublicKey!,
      }, myPhone: '+1 555 0100');
      expect(DoubleRatchet.instance.hasSession('15550188'), isTrue,
          reason: 'a routine announce must not bury a healthy session');
      // The same key marked as a heal does.
      RelayService.instance.applyKeyEvent({
        'from': '+1 555 0188',
        'pub': peer.myPublicKey!,
        'heal': true,
      }, myPhone: '+1 555 0100');
      expect(DoubleRatchet.instance.hasSession('15550188'), isFalse,
          reason: 'a failed unlock under the same identity is a dead session');
      // And a replayed heal envelope cannot keep killing each next session.
      DoubleRatchet.instance.encrypt('15550100', '15550188', 'again');
      RelayService.instance.applyKeyEvent({
        'from': '+1 555 0188',
        'pub': peer.myPublicKey!,
        'heal': true,
      }, myPhone: '+1 555 0100');
      expect(DoubleRatchet.instance.hasSession('15550188'), isTrue,
          reason: 'burials are rate-limited against replayed envelopes');
      // healPeer marks its re-introduction, so the far side can tell repair
      // from routine — the flag is the whole mechanism.
      final src = File('lib/relay/relay_service.dart').readAsStringSync();
      final heal = src.substring(src.indexOf('void healPeer('));
      expect(heal.substring(0, heal.indexOf('resync')).contains("'heal': true"),
          isTrue,
          reason: 'an unmarked heal is a plain announce and fixes nothing');
    });

    test('three failed heals in one run say so in the chat', () {
      // A heal that keeps not taking has one cause it can never fix: the
      // same number signed in on a second phone or a web tab, each with its
      // own keys, taking turns teaching the peer a key this device does not
      // hold. Silence leaves that reading as random breakage.
      final store = ChatStore.instance;
      store.upsert(const Chat(
        id: 'chat_healnote',
        contact: AppUser(
            id: 'p_healnote',
            name: 'Pat',
            avatarColor: '#7A5CFF',
            about: '',
            phone: '+1 555 0199'),
        messages: [],
      ));
      addTearDown(() => store.deleteChat('chat_healnote'));
      RelayService.instance.healPeer('+1 555 0199');
      RelayService.instance.healPeer('+1 555 0199');
      expect(store.chatById('chat_healnote')!.messages, isEmpty,
          reason: 'two failures are still the heal doing its job');
      RelayService.instance.healPeer('+1 555 0199');
      final msgs = store.chatById('chat_healnote')!.messages;
      expect(msgs.length, 1);
      expect(msgs.single.text, contains('another phone or a web browser'),
          reason: 'the notice names the one cause the heal cannot fix');
      RelayService.instance.healPeer('+1 555 0199');
      expect(store.chatById('chat_healnote')!.messages.length, 1,
          reason: 'said once, not once per failure');
    });

    test('a server join bootstraps under the shared secret, not a sender key',
        () {
      // The join bug: a fresh member's chjoin was sealed with a sender key the
      // owner didn't hold yet, so the owner dropped it — never added the member
      // to the roster, never backfilled the feed. Worse, the owner's existing
      // posts were sealed with the owner's key the joiner had no SKDM for, so
      // they saw nothing until the owner happened to post again. Three source
      // pins hold the fix, because it's transport wiring with no unit-testable
      // seam without a live relay:
      final src = File('lib/relay/relay_service.dart').readAsStringSync();
      final flat = src.replaceAll(RegExp(r'\s+'), ' ');

      // 1. sendServerJoin announces the join under the SHARED SECRET, so the
      //    owner can read it without already holding our sender key.
      final join = src.substring(src.indexOf('Future<void> sendServerJoin('));
      final joinBody = join.substring(0, join.indexOf('\n  }'));
      expect(joinBody.contains("viaSecret: true"), isTrue,
          reason: 'chjoin must ride the shared secret, not a sender key');
      // ...and hands every member our sender key so our future posts open.
      expect(joinBody.contains('_distributeSkdm(community)'), isTrue,
          reason: 'a join must distribute our SKDM to the room');

      // 2. _sendCommunityEvent's viaSecret path seals with the shared secret
      //    (a 'data' envelope the legacy receive path can always read).
      expect(
          flat.contains(
              "viaSecret ? {'data': E2eCrypto.encrypt(secret, jsonEncode(body))}"),
          isTrue,
          reason: 'viaSecret must seal under the shared secret');

      // 3. backfillFeedTo hands the joiner our SKDM BEFORE sending posts, so
      //    the sealed catch-up posts are readable the moment they arrive.
      final back = src.substring(src.indexOf('backfillFeedTo('));
      final skdmAt = back.indexOf('_distributeSkdm(community, toDigits: d)');
      final loopAt = back.indexOf('backfillFor(communityId)');
      expect(skdmAt >= 0 && skdmAt < loopAt, isTrue,
          reason: 'the SKDM must go out before the backfill posts');
    });

    test(
        'an existing member hands a new joiner their sender key on sight, '
        "not only if the joiner happens to catch a live message and ask", () {
      // #128 fixed the JOINER's side of this (their chjoin rides the shared
      // secret so the owner can read it, and backfillFeedTo hands the
      // joiner the owner's key before sending FEED posts) — but nothing
      // ever made the trip the other way for ongoing CHANNEL MESSAGES.
      // _sealCommunity only auto-distributes an existing member's own SKDM
      // on their FIRST-EVER send for a community; once established (true
      // for any member who has posted before today), it never re-fires.
      // So a brand-new joiner only got an existing member's key by
      // accident: fail to decrypt that member's NEXT live message, send
      // skreq, and hope the member posts again while the joiner is still
      // around. A server whose existing members simply hadn't posted since
      // the join left every channel looking permanently empty to the
      // joiner — reported as "servers aren't working ... text channels
      // don't show any messages" (2026-08-13). Wire-only fix, no
      // unit-testable seam without a live relay:
      final src = File('lib/relay/relay_service.dart').readAsStringSync();
      final joinCaseAt = src.indexOf("case 'chjoin':");
      final nextCaseAt = src.indexOf("case '", joinCaseAt + 1);
      final joinCase = src.substring(joinCaseAt, nextCaseAt);
      expect(joinCase.contains('applyRemoteJoin'), isTrue,
          reason: 'a chjoin must still add the member to the roster');
      expect(joinCase.contains('SenderKeyStore.instance.hasOwn(cid)'), isTrue,
          reason: 'only a member who has actually sent before has a key '
              'worth handing over');
      expect(
          joinCase
              .contains('_distributeSkdm(community, toDigits: joinedDigits)'),
          isTrue,
          reason: 'an existing member must hand the NEW joiner their key '
              'directly, the moment the join is seen — not wait for the '
              'joiner to fail a decrypt and ask');
    });

    test(
        'every join path pulls the durable feed backfill, so a new member '
        "isn't stuck reading an empty server", () {
      // #128 fixed the roster/sender-key bootstrap; new members could still
      // land with an empty feed because nothing actually asked for the old
      // posts — the durable community_posts fetch only ran at relay start
      // and on pull-to-refresh. Every place a device joins a server (a typed
      // code, a Discover-row/tapped-card snapshot, a tapped invite card, and
      // the silent admin-add auto-join) must call fetchCommunityPosts right
      // after announcing the join, or that join path stays affected.
      final communities =
          File('lib/screens/communities.dart').readAsStringSync();
      final bubble = File('lib/widgets/message_bubble.dart').readAsStringSync();
      final relay = File('lib/relay/relay_service.dart').readAsStringSync();

      // 1. joinByCodeFlow's submit().
      final codeAt = communities.indexOf('Future<void> joinByCodeFlow(');
      final codeBody =
          communities.substring(codeAt, communities.indexOf('\n}\n', codeAt));
      expect(codeBody.contains('fetchCommunityPosts()'), isTrue,
          reason: 'joining by a pasted code must backfill old posts');

      // 2. joinServerFromSnapshot (Discover directory + shared helper).
      final snapAt = communities.indexOf('Community? joinServerFromSnapshot(');
      final snapBody =
          communities.substring(snapAt, communities.indexOf('\n}\n', snapAt));
      expect(snapBody.contains('fetchCommunityPosts()'), isTrue,
          reason: 'joining from Discover must backfill old posts');

      // 3. The tapped invite-card handler.
      final joinAt = bubble.indexOf('void _join(');
      final joinBody =
          bubble.substring(joinAt, bubble.indexOf('\n  }', joinAt));
      expect(joinBody.contains('fetchCommunityPosts()'), isTrue,
          reason: 'tapping an invite card must backfill old posts');

      // 4. The silent admin-add auto-join — no screen to pull-to-refresh
      //    from, so this is the ONLY chance that member gets.
      final autoAt = relay.indexOf('void maybeAutoJoinServer(');
      final autoBody = relay.substring(autoAt, relay.indexOf('\n  }', autoAt));
      expect(autoBody.contains('fetchCommunityPosts()'), isTrue,
          reason: 'a silent admin-add join must backfill old posts too');
    });

    test(
        'every join path also registers with the authoritative structure '
        'tables (docs/community_structure.sql)', () {
      // Phase 1 of "central authority" (2026-08-13): community structure
      // moved from pure peer gossip to a durable, RLS-scoped backstop. The
      // same four join paths #128/#184 pinned for fetchCommunityPosts() must
      // also call joinCommunityAuthoritative — registering this device as a
      // real, server-verified member — and fetchCommunityStructure, or a
      // join path silently never converges with the authoritative tables.
      final communities =
          File('lib/screens/communities.dart').readAsStringSync();
      final bubble = File('lib/widgets/message_bubble.dart').readAsStringSync();
      final relay = File('lib/relay/relay_service.dart').readAsStringSync();

      final codeAt = communities.indexOf('Future<void> joinByCodeFlow(');
      final codeBody =
          communities.substring(codeAt, communities.indexOf('\n}\n', codeAt));
      expect(codeBody.contains('joinCommunityAuthoritative('), isTrue,
          reason: 'joining by a pasted code must register authoritatively');
      expect(codeBody.contains('fetchCommunityStructure('), isTrue,
          reason:
              'joining by a pasted code must pull the authoritative structure');

      final snapAt = communities.indexOf('Community? joinServerFromSnapshot(');
      final snapBody =
          communities.substring(snapAt, communities.indexOf('\n}\n', snapAt));
      expect(snapBody.contains('joinCommunityAuthoritative('), isTrue,
          reason: 'joining from Discover must register authoritatively');
      expect(snapBody.contains('fetchCommunityStructure('), isTrue,
          reason:
              'joining from Discover must pull the authoritative structure');

      final joinAt = bubble.indexOf('void _join(');
      final joinBody =
          bubble.substring(joinAt, bubble.indexOf('\n  }', joinAt));
      expect(joinBody.contains('joinCommunityAuthoritative('), isTrue,
          reason: 'tapping an invite card must register authoritatively');
      expect(joinBody.contains('fetchCommunityStructure('), isTrue,
          reason:
              'tapping an invite card must pull the authoritative structure');

      final autoAt = relay.indexOf('void maybeAutoJoinServer(');
      final autoBody = relay.substring(autoAt, relay.indexOf('\n  }', autoAt));
      expect(autoBody.contains('joinCommunityAuthoritative('), isTrue,
          reason: 'a silent admin-add join must register authoritatively too');
      expect(autoBody.contains('fetchCommunityStructure('), isTrue,
          reason:
              'a silent admin-add join must pull the authoritative structure');
    });

    test(
        'a structural change republishes to the authoritative structure '
        'tables', () {
      // main.dart's onStructureChanged is the one funnel every structural
      // mutation already calls (~25 CommunityStore methods, all through this
      // callback) — publishCommunityStructure has to hang off it, or every
      // one of those methods would need its own dual-write site.
      final main = File('lib/main.dart').readAsStringSync();
      final at = main.indexOf('onStructureChanged = (id) {');
      final body = main.substring(at, main.indexOf('\n    };', at));
      expect(body.contains('publishCommunityStructure(id)'), isTrue,
          reason: 'every structural change must republish the authoritative '
              'copy — including a member removal or ban, which reaches this '
              'same callback before onMemberRemoved');
    });

    test(
        'chat structure (docs/chat_structure.sql) is wired at every '
        'structural change and every relay sync point', () {
      // Phase 3 of "central authority" (2026-08-13): same backstop as
      // Phase 1, now for 1:1/group chats. sendGroupUpdate is the ONE funnel
      // every group structural change (create, rename, add/remove member)
      // already goes through — publishChatStructure hangs off it directly,
      // the same reasoning main.dart's onStructureChanged callback exists
      // for servers (fewer call sites here, so no separate funnel needed).
      final relay = File('lib/relay/relay_service.dart').readAsStringSync();
      final chatScreen =
          File('lib/screens/chat_screen.dart').readAsStringSync();

