      final sendBody = relay.substring(sendAt, relay.indexOf('\n  }', sendAt));
      expect(sendBody.contains('publishChatStructure('), isTrue,
          reason: 'every group structural change must republish the '
              'authoritative copy');

      // A 1:1's existence is published once, from the funnel every real-peer
      // send already passes through — not from a UI call site that could be
      // one of several.
      final deliverAt = chatScreen.indexOf('void _deliver(');
      final deliverBody = chatScreen.substring(
          deliverAt, chatScreen.indexOf('\n  }', deliverAt));
      expect(deliverBody.contains('publishDirectChatExistence('), isTrue,
          reason: 'sending the first message in a 1:1 must publish its '
              'existence to the authoritative table');

      // Relay start and pull-to-refresh both re-sync chat structure — same
      // two sites _syncCommunityStructure is wired at.
      final syncCount = '_syncChatStructure()'.allMatches(relay).length;
      expect(syncCount, greaterThanOrEqualTo(3),
          reason: '_syncChatStructure must be both DEFINED and CALLED at '
              'relay start and pull-to-refresh (3+ occurrences total)');

      expect(relay.contains('Future<void> publishChatStructure('), isTrue);
      expect(relay.contains('Future<void> fetchChatStructure('), isTrue);
      expect(
          relay.contains('Future<void> publishDirectChatExistence('), isTrue);
      expect(relay.contains("directChatsTable = 'direct_chats'"), isTrue);
      expect(relay.contains("chatMembersTable = 'chat_members'"), isTrue);
    });

    test(
        'call presence (docs/call_presence.sql) is wired at every real '
        'call-join and call-end point', () {
      // Phase 4 of "central authority" (2026-08-13): same backstop as
      // Phase 1-3, now for live calls. A call has no durable parent row (see
      // the SQL file's header), so publish/leave are wired at each real
      // signaling moment directly rather than one shared funnel.
      final relay = File('lib/relay/relay_service.dart').readAsStringSync();
      final call = File('lib/state/call_service.dart').readAsStringSync();

      String body(String needle, {int skip = 0}) {
        var at = call.indexOf(needle);
        for (var i = 0; i < skip; i++) {
          at = call.indexOf(needle, at + 1);
        }
        return call.substring(at, call.indexOf('\n  }', at));
      }

      expect(
          body('void startOutgoing(').contains('publishCallPresence('), isTrue,
          reason: 'starting an outgoing 1:1 call must found its roster');
      expect(
          body('void startGroupCall(').contains('publishCallPresence('), isTrue,
          reason: 'starting an outgoing group call must found its roster '
              'with the real dial list');

      final acceptBody = body('void accept(');
      expect('publishCallPresence('.allMatches(acceptBody).length,
          greaterThanOrEqualTo(2),
          reason: 'accepting must self-register on both the 1:1 and group '
              'branches');
      expect(acceptBody.contains('fetchCallPresence('), isTrue,
          reason: 'joining a group call must also pull today\'s ground '
              'truth, covering a device that missed some signaling events');
      expect(
          body('void onRemoteJoined(').contains('fetchCallPresence('), isTrue,
          reason: 'a group call the FOUNDER placed, connecting on the '
              'first join, must also pull ground truth — the mirror case '
              'accept() alone does not cover');

      expect(body('void end(').contains('leaveCallRoster('), isTrue,
          reason: 'hanging up must leave the durable roster');
      expect(body('void decline(').contains('leaveCallRoster('), isTrue,
          reason: 'declining must leave the durable roster');
      expect(body('void onRemoteDecline(').contains('leaveCallRoster('), isTrue,
          reason: 'the peer declining must also clear our own roster row');
      expect(body('void onRemoteEnd(').contains('leaveCallRoster('), isTrue,
          reason: 'the peer ending the call must also clear our own row');
      expect(body('void onRemoteLeft(').contains('leaveCallRoster('), isTrue,
          reason: 'a group call ending because everyone else left must '
              'clear this device\'s own row too');

      expect(relay.contains('Future<void> publishCallPresence('), isTrue);
      expect(relay.contains('Future<void> fetchCallPresence('), isTrue);
      expect(relay.contains('Future<void> leaveCallRoster('), isTrue);
      expect(relay.contains("callRostersTable = 'call_rosters'"), isTrue);
    });

    test(
        'opening a voice channel asks who is already there, rather than '
        'waiting out someone else\'s heartbeat', () {
      // Reported as "servers aren't in sync ... same server on another
      // account yet they can't see me in voice channel" (2026-08-13).
      // VoicePresenceStore.join() announces the JOINER immediately — that
      // reaches anyone with a live connection right away — but nothing ever
      // asked existing occupants to re-announce for a device that opened the
      // room screen AFTER they joined, or whose subscription had silently
      // died and was rebuilt. Wire-only fix (no unit-testable seam without a
      // live relay), so three source pins:
      final relay = File('lib/relay/relay_service.dart').readAsStringSync();
      final communities =
          File('lib/screens/communities.dart').readAsStringSync();

      // 1. Opening the room screen broadcasts the request.
      final initAt = communities.indexOf('void initState() {',
          communities.indexOf('class _VoiceChannelScreenState'));
      final initBody =
          communities.substring(initAt, communities.indexOf('\n  }', initAt));
      expect(initBody.contains('sendVoicePresenceRequest'), isTrue,
          reason: 'opening a voice channel must ask who is already there');

      // 2. The request is actually LISTENED for — an event missing from the
      //    community bus's onBroadcast roster arrives sealed and is silently
      //    dropped, the exact trap the sealed-inbox-roster tests exist for.
      expect(relay.contains("event: 'vpreq'"), isTrue,
          reason: 'vpreq must be registered on the community broadcast, or '
              'a real request from another device is dropped');

      // 3. A device already in this server's voice re-announces on request.
      final caseAt = relay.indexOf("case 'vpreq':");
      final nextCaseAt = relay.indexOf("case '", caseAt + 1);
      final caseBody = relay.substring(caseAt, nextCaseAt);
      expect(caseBody.contains('VoicePresenceStore.instance.announceNow()'),
          isTrue,
          reason: 'a vpreq must trigger an immediate re-announce, not wait '
              'for the next heartbeat');
    });

