    test('a contact who REMOVES their picture is seen to', () {
      // Reported plainly: "Giti and Jon both removed their profile picture but
      // it hasn't updated." The avatar fields were never-zeroed at BOTH
      // layers — the relay turned an empty one into null, and the store kept
      // the old value for null — so a removal went out as an empty string and
      // every reader read it as silence. Setting an avatar propagated;
      // clearing one never could.
      final store = ChatStore.instance;
      store.upsert(const Chat(
        id: 'chat_+1 555 0251',
        contact: AppUser(
            id: '+1 555 0251',
            name: 'Giti',
            avatarColor: '#111111',
            about: '',
            phone: '+1 555 0251',
            emoji: '🎧',
            avatarSeed: 'okay-3-9',
            avatarFace: '{"Eyes":"1"}',
            avatarGif: 'https://media.example.com/a.gif'),
        messages: [],
      ));
      addTearDown(() => store.deleteChat('chat_+1 555 0251'));

      // They took all of it off. The colour is still theirs — every account
      // has one — which is exactly what says the avatar bundle is on the wire.
      RelayService.instance.applyProfileUpdate({
        'from': '+1 555 0251',
        'fromAvatarColor': '#111111',
        'fromEmoji': '',
        'fromAvatarSeed': '',
        'fromAvatarFace': '',
        'fromAvatarGif': '',
      }, myPhone: '+1 555 0100');

      final c = store.chatById('chat_+1 555 0251')!.contact;
      expect(c.emoji, '');
      expect(c.avatarSeed, '');
      expect(c.avatarFace, '');
      expect(c.avatarGif, '');

      // But a payload that says NOTHING about the avatar still must not wipe
      // one — an older build, or a contact withholding their avatar by
      // privacy audience, both arrive with an empty colour.
      store.updateContactProfile('+1 555 0251',
          avatarSeed: 'okay-4-4', avatarColor: '#222222');
      RelayService.instance.applyProfileUpdate({
        'from': '+1 555 0251',
        'fromAvatarColor': '',
        'fromAvatarSeed': '',
        'fromAvatarFace': '',
        'fromAvatarGif': '',
      }, myPhone: '+1 555 0100');
      expect(store.chatById('chat_+1 555 0251')!.contact.avatarSeed,
          'okay-4-4',
          reason: 'a withheld or older payload is silence, not a removal');
    });

    test('an unreadable avatar GIF is not the same as a removed one', () {
      // Pure, and the distinction is the whole reason this rule is shared
      // between the two receive paths rather than written twice.
      expect(
          RelayService.incomingAvatarGif('', bundlePresent: false), isNull,
          reason: 'no bundle on the wire says nothing at all');
      expect(RelayService.incomingAvatarGif('', bundlePresent: true), '',
          reason: 'an empty one WITH the bundle is a real removal');
      expect(
          RelayService.incomingAvatarGif('https://media.example.com/a.gif',
              bundlePresent: true),
          'https://media.example.com/a.gif');
      expect(
          RelayService.incomingAvatarGif('http://insecure.example.com/a.gif',
              bundlePresent: true),
          isNull,
          reason: 'one we cannot draw is not one we were told is gone');
    });

    test('a profile update refreshes an existing contact right away', () {
      // The complaint: after someone changes their avatar/bio, the chat "takes
      // time to update" — because the new fields only piggybacked on their
      // NEXT message. A 'prof' event pushes them now and applies to the card.
      final store = ChatStore.instance;
      store.upsert(const Chat(
        id: 'chat_+1 555 0242',
        contact: AppUser(
            id: '+1 555 0242',
            name: 'Del',
            avatarColor: '#111111',
            about: 'old bio',
            phone: '+1 555 0242'),
        messages: [],
      ));
      addTearDown(() => store.deleteChat('chat_+1 555 0242'));

      RelayService.instance.applyProfileUpdate({
        'from': '+1 555 0242',
        'fromAvatarColor': '#22DD88',
        'fromAbout': 'new bio',
        'fromEmoji': '🎧',
        'fromVerified': true,
        'fromBusiness': true,
        'fromBusinessCategory': 'Coffee',
      }, myPhone: '+1 555 0100');

      final c = store.chatById('chat_+1 555 0242')!.contact;
      expect(c.avatarColor, '#22DD88');
      expect(c.about, 'new bio');
      expect(c.emoji, '🎧');
      expect(c.verified, isTrue);
      expect(c.isBusiness, isTrue);
      expect(c.businessCategory, 'Coffee');
      // Name is left alone, exactly as the message path leaves it.
      expect(c.name, 'Del');

      // A profile ping from a stranger never starts a conversation.
      RelayService.instance.applyProfileUpdate({
        'from': '+1 555 0243',
        'fromAvatarColor': '#FFFFFF',
      }, myPhone: '+1 555 0100');
      expect(store.chatById('chat_+1 555 0243'), isNull);

      // Source pins: the broadcast seals per contact (never in the clear), and
      // both edit surfaces trigger it so an edit or a badge change propagates.
      final relay = File('lib/relay/relay_service.dart').readAsStringSync();
      expect(relay.contains("sealedEnvelopeFor(phone, 'prof', inner)"), isTrue,
          reason: 'a profile broadcast must be sealed to each contact');
      expect(File('lib/screens/edit_profile_screen.dart').readAsStringSync(),
          contains('broadcastProfile()'));
      expect(File('lib/screens/score_screen.dart').readAsStringSync(),
          contains('broadcastProfile()'));
    });

    test('the recovery code seals an identity only the code opens', () {
      final code = IdentityRecovery.mintCode();
      // Read-back-over-the-phone safe: groups of four, no 0/O or 1/I.
      expect(RegExp(r'^[A-Z2-9]{4}(-[A-Z2-9]{4}){3}$').hasMatch(code), isTrue,
          reason: 'got $code');
      expect(code.contains(RegExp('[01OI]')), isFalse);
      expect(IdentityRecovery.mintCode(), isNot(code),
          reason: 'two mints must differ');

      const secretHex = 'deadbeef1234567890abcdef';
      final blob = IdentityRecovery.sealIdentity(secretHex, code);
      // The blob is what the server stores, so the key must not be in it.
      expect(blob.contains(secretHex), isFalse);
      expect(IdentityRecovery.openIdentity(blob, code), secretHex);
      // Typed sloppily is still the same code.
      expect(
          IdentityRecovery.openIdentity(
              blob, code.toLowerCase().replaceAll('-', ' ')),
          secretHex);
      // The wrong code opens nothing — and reads the same as no backup,
      // because GCM cannot tell tampering from a wrong key.
      expect(IdentityRecovery.openIdentity(blob, IdentityRecovery.mintCode()),
          isNull);
      expect(IdentityRecovery.openIdentity('not json', code), isNull);

      // The PIN path: 4–6 digits, the user's own choice — Messenger's
      // shape. The same seal, the same forgiveness for separators.
      expect(IdentityRecovery.pinProblem('1234'), isNull);
      expect(IdentityRecovery.pinProblem('432198'), isNull);
      expect(IdentityRecovery.pinProblem('123'), isNotNull);
      expect(IdentityRecovery.pinProblem('1234567'), isNotNull);
      expect(IdentityRecovery.pinProblem('12a4'), isNotNull);
      final pinBlob = IdentityRecovery.sealIdentity(secretHex, '432198');
      expect(IdentityRecovery.openIdentity(pinBlob, ' 43-21 98 '), secretHex);
      expect(IdentityRecovery.openIdentity(pinBlob, '432199'), isNull);
    });

    test('a restored identity is the SAME identity, and old seals open again',
        () async {
      // The whole point: after reinstall + restore, the shared secret with
      // every peer is what it was, so a message sealed before the phone
      // died is readable after.
      SharedPreferences.setMockInitialValues({});
      // ignore: invalid_use_of_visible_for_testing_member
      addTearDown(SecureKeyExchange.instance.resetForTest);
      // ignore: invalid_use_of_visible_for_testing_member
      addTearDown(DoubleRatchet.instance.resetForTest);
      final kx = SecureKeyExchange.instance;
      await kx.load();
      final peer = SecureKeyExchange.freshForTest();
      final originalPub = kx.myPublicKey!;
      final sealedBefore = E2eCrypto.encrypt(
          kx.sharedSecretWith(peer.myPublicKey!)!, 'from before the reinstall');
      final code = IdentityRecovery.mintCode();
      final backup = IdentityRecovery.sealIdentity(kx.exportPrivate(), code);

      // The reinstall: fresh prefs, fresh identity, the old one gone.
      SharedPreferences.setMockInitialValues({});
      kx.resetForTest();
      await kx.load();
      expect(kx.myPublicKey, isNot(originalPub));
      expect(
          E2eCrypto.decrypt(
              kx.sharedSecretWith(peer.myPublicKey!)!, sealedBefore),
          isNull,
          reason: 'this is exactly the padlock the code exists to prevent');

      // The restore.
      final hex = IdentityRecovery.openIdentity(backup, code)!;
      await kx.adoptIdentity(hex);
      expect(kx.myPublicKey, originalPub,
          reason: 'restore brings back the SAME identity, not a new one');
      expect(
          E2eCrypto.decrypt(
              kx.sharedSecretWith(peer.myPublicKey!)!, sealedBefore),
          'from before the reinstall');
      // And it persisted: the next launch loads the restored identity.
      kx.resetForTest();
      await kx.load();
      expect(kx.myPublicKey, originalPub);
    });

    testWidgets(
        'the recovery screen takes a chosen PIN, stores sealed, '
        'and restores', (tester) async {
      SharedPreferences.setMockInitialValues({});
      // ignore: invalid_use_of_visible_for_testing_member
      addTearDown(SecureKeyExchange.instance.resetForTest);
      // ignore: invalid_use_of_visible_for_testing_member
      addTearDown(DoubleRatchet.instance.resetForTest);
      addTearDown(() {
        IdentityRecovery.debugStore = null;
        IdentityRecovery.debugFetch = null;
      });
      await SecureKeyExchange.instance.load();
      final myHex = SecureKeyExchange.instance.exportPrivate();

      String? storedBlob;
      IdentityRecovery.debugFetch = (_) async => storedBlob;
      IdentityRecovery.debugStore = (inbox, blob) async {
        expect(inbox, '15550100');
        expect(blob.contains(myHex), isFalse,
            reason: 'the private key must never leave the device readable');
        expect(blob.contains('432198'), isFalse,
            reason: 'and neither may the PIN');
        storedBlob = blob;
        return true;
      };

      await tester.pumpWidget(
          const MaterialApp(home: RecoveryCodeScreen(debugInbox: '15550100')));
      await tester.pumpAndSettle();
      expect(find.text('No backup yet.'), findsOneWidget);

      await tester.tap(find.text('Create recovery PIN'));
      await tester.pumpAndSettle();
      // Choose the PIN: mismatched confirm is refused in place.
      final dialogFields = find.descendant(
          of: find.byType(AlertDialog), matching: find.byType(TextField));
      await tester.enterText(dialogFields.at(0), '432198');
      await tester.enterText(dialogFields.at(1), '432199');
      await tester.tap(find.text('Save PIN'));
      await tester.pumpAndSettle();
      expect(find.text('The PINs don\'t match.'), findsOneWidget);
      await tester.enterText(dialogFields.at(1), '432198');
      await tester.tap(find.text('Save PIN'));
      await tester.pumpAndSettle();
      expect(storedBlob, isNotNull);
      expect(IdentityRecovery.openIdentity(storedBlob!, '432198'), myHex);
      // Let the "Recovery PIN saved" snackbar run out, or the restore's own
      // snackbar queues invisibly behind it.
      await tester.pump(const Duration(seconds: 5));
      await tester.pumpAndSettle();

      // A "new phone": a different current identity, then a typed restore.
      final original = SecureKeyExchange.instance.myPublicKey;
      SharedPreferences.setMockInitialValues({});
      SecureKeyExchange.instance.resetForTest();
      await SecureKeyExchange.instance.load();
      expect(SecureKeyExchange.instance.myPublicKey, isNot(original));

      await tester.enterText(find.byType(TextField), '4321 98');
      await tester.pumpAndSettle();
      await tester.tap(find.text('Restore encryption'));
      await tester.pumpAndSettle();
      expect(SecureKeyExchange.instance.myPublicKey, original,
          reason: 'typing the PIN brings the old identity back');
      expect(find.textContaining('Encryption restored'), findsOneWidget);
    });

    test('key material moves to the keychain, out of the backed-up plist',
        () async {
      // SharedPreferences is an NSUserDefaults plist that rides device
      // backups; the identity private key used to live there. In tests
      // there is no keychain channel, so SecureStore falls back to prefs
      // under a 'sec_' prefix — which is exactly what lets this test watch
      // the migration happen.
      SharedPreferences.setMockInitialValues({
        'device_ec_priv_v1': 'deadbeef01',
      });
      // ignore: invalid_use_of_visible_for_testing_member
      addTearDown(SecureKeyExchange.instance.resetForTest);
      await SecureKeyExchange.instance.load();
      final prefs = await SharedPreferences.getInstance();
      expect(prefs.getString('device_ec_priv_v1'), isNull,
          reason: 'the plist copy must be DELETED — the next backup must '
              'not carry the one secret everything hangs off');
      expect(prefs.getString('sec_device_ec_priv'), 'deadbeef01',
          reason: 'migrated into the secure store, same identity');
      expect(SecureKeyExchange.instance.exportPrivate(), 'deadbeef01');

      // A fresh identity is born straight into the secure store — the
      // plist never sees it at all.
      SharedPreferences.setMockInitialValues({});
      SecureKeyExchange.instance.resetForTest();
      await SecureKeyExchange.instance.load();
      final fresh = await SharedPreferences.getInstance();
      expect(fresh.getString('device_ec_priv_v1'), isNull);
      expect(fresh.getString('sec_device_ec_priv'), isNotNull);

      // The ratchet's chain keys follow the same road.
      SharedPreferences.setMockInitialValues({
        'double_ratchet_v1': '{}',
        'sender_keys_v1': '{}',
      });
      // ignore: invalid_use_of_visible_for_testing_member
      addTearDown(DoubleRatchet.instance.resetForTest);
      await DoubleRatchet.instance.load();
      await SenderKeyStore.instance.load();
      final after = await SharedPreferences.getInstance();
      expect(after.getString('double_ratchet_v1'), isNull);
      expect(after.getString('sender_keys_v1'), isNull);
      expect(after.getString('sec_double_ratchet'), '{}');
      expect(after.getString('sec_sender_keys'), '{}');
    });

    testWidgets('messaging waits for the recovery code, X-style',
        (tester) async {
      SharedPreferences.setMockInitialValues({});
      // ignore: invalid_use_of_visible_for_testing_member
      addTearDown(SecureKeyExchange.instance.resetForTest);
      // ignore: invalid_use_of_visible_for_testing_member
      addTearDown(DoubleRatchet.instance.resetForTest);
      addTearDown(() {
        IdentityRecovery.debugStore = null;
        IdentityRecovery.debugFetch = null;
        debugRecoveryGateNeeded = null;
        // ignore: invalid_use_of_visible_for_testing_member
        IdentityRecovery.resetReadyForTest();
      });
      await SecureKeyExchange.instance.load();

      // Where there is nothing to protect the gate never fires — this build
      // has no relay, and the whole test suite messages freely because of
      // exactly this property.
      expect(recoveryGateNeeded(), isFalse);

      debugRecoveryGateNeeded = true;
      String? storedBlob;
      IdentityRecovery.debugFetch = (_) async => storedBlob;
      IdentityRecovery.debugStore = (_, blob) async {
        storedBlob = blob;
        return true;
      };

      var allowed = false;
      await tester.pumpWidget(MaterialApp(
        home: Scaffold(
          body: Builder(
            builder: (context) => FilledButton(
              onPressed: () async {
                allowed =
                    await ensureRecoveryReady(context, debugInbox: '15550100');
              },
              child: const Text('send'),
            ),
          ),
        ),
      ));

      // A fresh account gets the CREATE flow, and declining blocks the send.
      await tester.tap(find.text('send'));
      await tester.pumpAndSettle();
      expect(find.text('Create your recovery PIN'), findsOneWidget);
      await tester.tap(find.text('Not now'));
      await tester.pumpAndSettle();
      expect(allowed, isFalse, reason: 'no PIN, no messaging');

      // Accepting asks for a chosen PIN, stores the sealed blob, unblocks.
      await tester.tap(find.text('send'));
      await tester.pumpAndSettle();
      await tester.tap(find.text('Choose PIN'));
      await tester.pumpAndSettle();
      final pinFields = find.descendant(
          of: find.byType(AlertDialog), matching: find.byType(TextField));
      await tester.enterText(pinFields.at(0), '4321');
      await tester.enterText(pinFields.at(1), '4321');
      await tester.tap(find.text('Save PIN'));
      await tester.pumpAndSettle();
      expect(allowed, isTrue);
      expect(IdentityRecovery.ready.value, isTrue);
      expect(IdentityRecovery.openIdentity(storedBlob!, '4321'),
          SecureKeyExchange.instance.exportPrivate());

      // A "new phone": the backup exists, so the gate asks to TYPE the PIN
      // — and a wrong one is refused in place, not accepted quietly.
      // ignore: invalid_use_of_visible_for_testing_member
      IdentityRecovery.resetReadyForTest();
      final original = SecureKeyExchange.instance.myPublicKey;
      SharedPreferences.setMockInitialValues({});
      SecureKeyExchange.instance.resetForTest();
      await SecureKeyExchange.instance.load();
      expect(SecureKeyExchange.instance.myPublicKey, isNot(original));

      allowed = false;
      await tester.tap(find.text('send'));
      await tester.pumpAndSettle();
      expect(find.text('Enter your recovery PIN'), findsOneWidget);
      await tester.enterText(find.byType(TextField), '9999');
      await tester.tap(find.text('Restore'));
      await tester.pumpAndSettle();
      expect(find.textContaining('doesn\'t open'), findsOneWidget);
      await tester.enterText(find.byType(TextField), '4321');
      await tester.tap(find.text('Restore'));
      await tester.pumpAndSettle();
      expect(allowed, isTrue);
      expect(SecureKeyExchange.instance.myPublicKey, original,
          reason: 'typing the PIN brings the old keys to the new phone');

      // And the chat screen actually stands behind the rule: offered when a
      // chat opens, enforced when a message is sent.
      final chat = File('lib/screens/chat_screen.dart').readAsStringSync();
      expect(chat.contains('maybePromptRecoverySetup'), isTrue);
      expect(chat.contains('recoveryGateNeeded()'), isTrue);
    });

    test('numberless accounts: a way back in, and no false verified claims',
        () {
      // Signing out of a numberless account used to be goodbye: the
      // username lookup read the directory table as anon (which RLS answers
      // with nothing), and even a found account would have been texted an
      // SMS at a number that does not exist.
      final login =
          File('lib/screens/auth/phone_login_screen.dart').readAsStringSync();
      expect(login.contains('AccountCode.isCode(phone)'), isTrue,
          reason: 'a username resolving to an account code must not be '
              'sent an SMS');
      expect(login.contains('_numberlessPinSignIn'), isTrue,
          reason: 'the recovery PIN is the numberless way back in');
      final svc = File('lib/state/account_service.dart').readAsStringSync();
      final lookup = svc.substring(svc.indexOf('accountForUsername'));
      expect(
          lookup
              .substring(0, lookup.indexOf('sendEmailCode'))
              .contains("rpc('find_people'"),
          isTrue,
          reason: 'a signed-out lookup must go through the RPC — the table '
              'answers anon with empty rows, which read as "no account"');
      // And the account never claims a verification it cannot have.
      final profile =
          File('lib/screens/profile_screen.dart').readAsStringSync();
      expect(profile.contains("'No phone number'"), isTrue,
          reason: 'a numberless profile must not say "Phone verified"');
      final score = File('lib/screens/score_screen.dart').readAsStringSync();
      // It used to read `isNumberless`. That is now TRUE for an
      // email-verified account — which has no phone number but does hold a
      // server session — so the raw flag refused the one kind of account the
      // email path exists to let through. The intent is unchanged: explain
      // rather than fail into a snackbar; the condition is the precondition
      // that actually matters.
      expect(score.contains('AccountVerification.needsServerSession'), isTrue,
          reason: 'Get verified says why it cannot run without a session '
              'instead of failing into a snackbar');
    });

    testWidgets('typing… expires on its own instead of sticking forever',
