  group('Payment security (trusted places + contacts)', () {
    setUp(() {
      SharedPreferences.setMockInitialValues({});
      PaymentSecurityStore.instance.resetForTest();
    });
    tearDown(() {
      debugGeolocationOverride = null;
      PaymentSecurityStore.instance.resetForTest();
    });

    test('haversine measures a degree of latitude at ~111 km', () {
      expect(
          PaymentSecurityStore.distanceMeters(40, -73, 40, -73), lessThan(1));
      expect(PaymentSecurityStore.distanceMeters(40, -73, 41, -73),
          closeTo(111195, 3000));
    });

    test('off by default — nothing is asked', () async {
      final store = PaymentSecurityStore.instance;
      final d = await store.assess('+1 555 0001');
      expect(d, StepUpDecision.off);
      expect(d.needsStepUp, isFalse);
    });

    test('a trusted contact skips the check without reading location',
        () async {
      final store = PaymentSecurityStore.instance;
      await store.load();
      await store.setEnabled(true);
      store.setTrustedContact('+1 555 0001', true);
      // Would throw if the location were read — proves the short-circuit.
      debugGeolocationOverride =
          () async => throw StateError('location must not be read');
      expect(await store.assess('+15550001'), StepUpDecision.trustedContact);
    });

    test('inside a trusted place passes; outside needs the step-up', () async {
      final store = PaymentSecurityStore.instance;
      await store.load();
      await store.setEnabled(true);
      store.addPlace(const TrustedPlace(
          name: 'Home', lat: 40, lng: -73, radiusMeters: 150));

      debugGeolocationOverride = () async => (lat: 40.0005, lng: -73.0005);
      expect(await store.assess('+15550002'), StepUpDecision.inTrustedPlace);

      debugGeolocationOverride = () async => (lat: 41.0, lng: -74.0);
      final out = await store.assess('+15550002');
      expect(out, StepUpDecision.outsideTrustedPlace);
      expect(out.needsStepUp, isTrue);
    });

    test('an unreadable location fails closed (asks for the PIN)', () async {
      final store = PaymentSecurityStore.instance;
      await store.load();
      await store.setEnabled(true);
      store.addPlace(const TrustedPlace(name: 'Home', lat: 40, lng: -73));
      debugGeolocationOverride = () async => null;
      final d = await store.assess('+15550003');
      expect(d, StepUpDecision.locationUnknown);
      expect(d.needsStepUp, isTrue);
    });

    test('sendMoney refuses a P2P send that skipped the trusted-place check',
        () async {
      final svc = PaymentService.instance;
      final store = PaymentSecurityStore.instance;
      await store.load();
      await store.setEnabled(true);
      store.addPlace(const TrustedPlace(name: 'Home', lat: 40, lng: -73));
      debugGeolocationOverride = () async => (lat: 41.0, lng: -74.0); // away
      final was = svc.testMode.value;
      svc.testMode.value = true; // the backstop runs before the test-mode exit
      addTearDown(() => svc.testMode.value = was);

      // Unverified P2P send from outside a trusted place is refused.
      await expectLater(
        svc.sendMoney(toPhone: '+15550004', amountCents: 500),
        throwsA(isA<PaymentException>()),
      );
      // The same send, with the check already passed, goes through.
      expect(
          await svc.sendMoney(
              toPhone: '+15550004', amountCents: 500, stepUpVerified: true),
          isTrue);
      // A spark on a post (no phone recipient) is exempt.
      expect(await svc.sendMoney(sparkPostId: 'p1', amountCents: 500), isTrue);
      // A trusted contact is exempt even unverified.
      store.setTrustedContact('+15550004', true);
      expect(
          await svc.sendMoney(toPhone: '+15550004', amountCents: 500), isTrue);
    });
  });

  group('Abuse guard', () {
    test('blocks link-shortener URLs, not ordinary links', () {
      expect(AbuseGuard.blockedUrlIn('check bit.ly/abc out'), 'bit.ly');
      expect(AbuseGuard.blockedUrlIn('https://tinyurl.com/x'), 'tinyurl.com');
      expect(
          AbuseGuard.blockedUrlIn('CUTT.LY/Y'), 'cutt.ly'); // case-insensitive
      // No false positive on a host that merely contains a blocked one.
      expect(AbuseGuard.blockedUrlIn('orbit.lyric.com/song'), isNull);
      // An ordinary link is fine.
      expect(AbuseGuard.blockedUrlIn('see https://okay.chat/join/abc'), isNull);
    });

    test('throttles hammering, blasting, and inhuman bursts', () {
      final g = AbuseGuard.instance;
      g.resetForTest();
      addTearDown(g.resetForTest);
      final t0 = DateTime(2026, 6, 1, 12);

      // A normal message is allowed.
      expect(g.messageBlockReason('15550001', now: t0), isNull);

      // Six sends within four seconds reads as not-a-human.
      for (var i = 0; i < 6; i++) {
        g.noteSend('1555000$i', now: t0.add(Duration(milliseconds: i * 200)));
      }
      expect(
          g.messageBlockReason('15559999',
              now: t0.add(const Duration(seconds: 2))),
          contains('faster than a person'));

      // Hammering ONE person within the minute.
      g.resetForTest();
      for (var i = 0; i < 20; i++) {
        g.noteSend('15550001', now: t0.add(Duration(seconds: i * 2)));
      }
      expect(
          g.messageBlockReason('15550001',
              now: t0.add(const Duration(seconds: 41))),
          contains('this person'));

      // Blasting many NEW people within the minute.
      g.resetForTest();
      for (var i = 0; i < 8; i++) {
        g.noteSend('155500$i', now: t0.add(Duration(seconds: i * 3)));
      }
      expect(
          g.messageBlockReason('15559999',
              now: t0.add(const Duration(seconds: 25))),
          contains('lot of new people'));
      // ...but continuing an existing conversation is never throttled by that.
      expect(
          g.messageBlockReason('1555000',
              now: t0.add(const Duration(seconds: 25))),
          isNull);

      // The URL block wins over everything.
      expect(g.outgoingBlockReason('grab bit.ly/x', '15550001', now: t0),
          contains('bit.ly'));
    });

    test('caps new accounts per device per day', () async {
      SharedPreferences.setMockInitialValues({});
      final g = AbuseGuard.instance;
      g.resetForTest();
      addTearDown(g.resetForTest);
      await g.load();
      final t0 = DateTime(2026, 6, 1, 9);

      expect(g.accountCreateAllowed(now: t0), isTrue);
      await g.noteAccountCreated(now: t0);
      await g.noteAccountCreated(now: t0.add(const Duration(hours: 1)));
      await g.noteAccountCreated(now: t0.add(const Duration(hours: 2)));
      // Three in the window is the cap.
      expect(g.accountCreateAllowed(now: t0.add(const Duration(hours: 3))),
          isFalse);
      // A day later the window has rolled and it's allowed again.
      expect(g.accountCreateAllowed(now: t0.add(const Duration(hours: 25))),
          isTrue);
    });

    test('flags a new-device sign-in, but not a fresh signup', () async {
      SharedPreferences.setMockInitialValues({});
      final g = AbuseGuard.instance;
      g.resetForTest();
      addTearDown(g.resetForTest);
      await g.load();

      // A brand-new signup is never a suspicious new device.
      expect(await g.registerSignIn('15550001', isSignup: true), isFalse);
      // That account signing in again on this device is known — no flag.
      expect(await g.registerSignIn('15550001', isSignup: false), isFalse);
      // A different account, created elsewhere, signing in here for the first
      // time IS a new device.
      expect(await g.registerSignIn('15550002', isSignup: false), isTrue);
      // ...and only the first time.
      expect(await g.registerSignIn('15550002', isSignup: false), isFalse);

      // Source pins: the send path, signup throttle, sign-in flag, and the
      // incoming filter all route through the guard.
      expect(
          File('lib/screens/chat_screen.dart')
              .readAsStringSync()
              .contains('AbuseGuard.instance.outgoingBlockReason'),
          isTrue);
      expect(
          File('lib/screens/auth/phone_login_screen.dart')
              .readAsStringSync()
              .contains('accountCreateAllowed'),
          isTrue);
      expect(
          File('lib/state/session.dart')
              .readAsStringSync()
              .contains('registerSignIn'),
          isTrue);
      expect(
          File('lib/app_state.dart')
              .readAsStringSync()
              .contains('blockedUrlIn'),
          isTrue);
    });
  });

  group('Payments test mode', () {
    test('prices show the store\'s own currency, falling back to USD', () {
      final sp = StorePrices.instance;
      sp.resetForTest();
      addTearDown(sp.resetForTest);

      // No store answer (web / test / before load) → a plain USD figure from
      // the cents, so a price always shows.
      expect(sp.money(299, productId: 'x'), '\$2.99');
      expect(sp.money(3499, productId: 'y'), '\$34.99');
      expect(StorePrices.usd(1200), '\$12.00'); // always two decimals

      // Once the store answers, its localized string wins — CAD for a
      // Canadian buyer, and matching exactly what was set in App Store Connect.
      sp.debugSet({'x': 'CA\$3.99'});
      expect(sp.money(299, productId: 'x'), 'CA\$3.99');
      // A product the store didn't price still falls back cleanly.
      expect(sp.money(299, productId: 'z'), '\$2.99');
      // And no product id is always the fallback.
      expect(sp.money(299), '\$2.99');
    });

    test('a price the store will not charge is never printed', () {
      // The mismatch, stated exactly: a card read "$1.99" beside a purchase
      // sheet charging CA$2.99. The card's number was the hardcoded USD
      // fallback, shown for a product the store does not sell — an invented
      // amount in the wrong currency. Once the store has answered, the only
      // amounts on screen are its own.
      final sp = StorePrices.instance;
      sp.resetForTest();
      addTearDown(sp.resetForTest);

      // Before any store answers (web, payments-test, first frame) the
      // fallback still stands — there is nothing better to say.
      expect(sp.money(199, productId: 'storage10'), '\$1.99');
      expect(sp.isUnavailable('storage10'), isFalse);

      // A reachable store answered, and it sells only one of these.
      sp.debugSet({'storage10': 'CA\$2.99'}, answered: true);
      expect(sp.money(199, productId: 'storage10'), 'CA\$2.99');
      // The other is genuinely not on sale — say so instead of inventing a
      // USD figure to sit beside a CAD one.
      expect(
          sp.money(399, productId: 'storage20'), StorePrices.unavailableLabel);
      expect(sp.isUnavailable('storage20'), isTrue);

      // Currency follows the buyer's store, because the string IS the
      // store's — the app never converts or guesses one.
      expect(sp.money(199, productId: 'storage10'), startsWith('CA\$'));
    });

    test(
        'a fresh store answer replaces the cache, so a withdrawn product '
        'stops showing its old price', () {
      final sp = StorePrices.instance;
      sp.resetForTest();
      addTearDown(sp.resetForTest);
      sp.absorb({'a': 'CA\$2.99', 'b': 'CA\$5.99'}, reachable: true);
      expect(sp.money(0, productId: 'b'), 'CA\$5.99');
      // 'b' is pulled from sale; the next full answer must forget it rather
      // than keep quoting a price that no longer exists.
      sp.absorb({'a': 'CA\$3.99'}, reachable: true);
      expect(sp.money(0, productId: 'a'), 'CA\$3.99');
      expect(sp.isUnavailable('b'), isTrue);
      // A PARTIAL answer (the tips-only check) must not cull everything
      // else — it only ever heard about its own four products.
      sp.absorb({'c': 'CA\$1.99'});
      expect(sp.money(0, productId: 'a'), 'CA\$3.99');
    });

    test('every purchase surface renders the store price, not a hardcoded \$',
        () {
      for (final f in const [
        'lib/widgets/subscribe_sheet.dart', // creator subscriptions
        'lib/screens/okay_pro_screen.dart', // developer tips
        'lib/screens/cloud_sync_screen.dart', // storage plans
        'lib/widgets/message_bubble.dart', // paid-server invite
      ]) {
        expect(
            File(f).readAsStringSync().contains('StorePrices.instance'), isTrue,
            reason: '$f must show the store price, not a computed dollar');
      }
      // Prices are fetched once at startup so a build() has them.
      expect(
          File('lib/main.dart')
              .readAsStringSync()
              .contains('StorePrices.instance.load()'),
          isTrue);
      // And RE-fetched when a purchase surface opens: Apple's product
      // metadata can lag a price change made in App Store Connect, and a
      // launch-time answer cached for the whole session showed one price
      // while the purchase sheet charged another (the $1.99/$2.99 tip).
      for (final f in const [
        'lib/screens/okay_pro_screen.dart',
        'lib/widgets/subscribe_sheet.dart',
        'lib/screens/cloud_sync_screen.dart',
      ]) {
        expect(
            File(f).readAsStringSync().contains('StorePrices.instance.load()'),
            isTrue,
            reason: '$f must re-ask the store for prices when it opens');
      }
      // The tips screen's "check the store" hears the freshest answer of
      // all — it must feed the visible cards, not just the dialog.
      expect(
          File('lib/screens/okay_pro_screen.dart')
              .readAsStringSync()
              .contains('StorePrices.instance.absorb'),
          isTrue);
    });

    test('the store catalogue lists every product the app can sell', () {
      final c = StorePurchases.catalogue();
      // Every id the price layer knows must be on the checklist, or a
      // product could be missing from App Store Connect and the in-app
      // check would report all-clear.
      final catalogued = {for (final p in c) p.id};
      expect(catalogued, equals(StorePrices.allIds()));
      // 10 storage + 4 tips + 4 creator + 4 community + BOTH candidate ids
      // for the AI pass, which is how this screen settles which name App
      // Store Connect actually has — exactly one should come back on sale.
      expect(c.length, 24);
      expect(c.where((p) => p.group == 'Okay AI').map((p) => p.id).toList(),
          StorePurchases.aiPassProductIds);
      // No blank ids, and each carries the price the app assumes so the
      // store's answer can be compared against something.
      expect(c.any((p) => p.id.isEmpty), isFalse);
      final storage = c.where((p) => p.group == 'Cloud storage').toList();
      expect(storage.first.cents, 199);
      expect(storage.last.cents, 1999);
      // The storage ladder must be strictly increasing — a bigger plan
      // priced below a smaller one is the App Store Connect mistake this
      // list exists to make visible.
      for (var i = 1; i < storage.length; i++) {
        expect(storage[i].cents, greaterThan(storage[i - 1].cents));
      }
      // The AI pass is the one product the app never prices.
      expect(c.firstWhere((p) => p.group == 'Okay AI').cents, 0);
    });

    test('the Okay AI pass can be bought before running out of messages', () {
      // It used to be reachable ONLY through the out-of-messages sheet, so
      // an owner — never rate-limited — could never buy or screenshot it.
      final src = File('lib/screens/ai_chat_screen.dart').readAsStringSync();
      expect(src.contains("value: 'pro'"), isTrue);
      expect(src.contains('Okay AI Pro'), isTrue);
    });

    test('the owner can publish prices, and a real store price still wins',
        () async {
      // The owner asked to change prices without waiting for a build. This is
      // the safe shape of that: what is published fills in where StoreKit has
      // no answer, and NEVER overrides one it does — so nothing set here can
      // advertise a price different from the charge.
      final p = PricingStore.instance;
      final sp = StorePrices.instance;
      p.resetForTest();
      sp.resetForTest();
      addTearDown(p.resetForTest);
      addTearDown(sp.resetForTest);

      // Built-in defaults until something is published.
      expect(p.isCustomized, isFalse);
      expect(StorageStore.priceCentsFor(10), 199);
      expect(p.tierCents, AppUser.subscriptionTiersCents);

      Map<String, dynamic>? sent;
      PricingStore.debugPublishOverride = (prices) async {
        sent = prices;
        return true;
      };
      expect(
          await p.publish({
            'storagePerGbCents': 27,
            'tierCents': [399, 699, 1399, 2799],
            'tipCents': {'com.okaymessaging.tip.coffee': 499},
          }),
          isTrue);
      expect(sent, isNotNull);
      expect(p.isCustomized, isTrue);

      // The whole ladder moves off the published rate, still landing on .99.
      expect(StorageStore.priceCentsFor(10), 299); // 10 x 27c -> $2.99
      expect(StorageStore.priceCentsFor(100), 2699);
      expect(p.tierCents, [399, 699, 1399, 2799]);
      expect(
          StorePurchases.tipCentsFor('com.okaymessaging.tip.coffee', 299), 499);
      // A tip with no published figure keeps its built-in one.
      expect(
          StorePurchases.tipCentsFor('com.okaymessaging.tip.snack', 599), 599);

      // THE INVARIANT: once the store has answered, its price is what shows.
      // The owner's number cannot contradict what Apple charges.
      sp.debugSet({'com.okaymessaging.tip.coffee': 'CA\$5.99'}, answered: true);
      expect(
          sp.money(499, productId: 'com.okaymessaging.tip.coffee'), 'CA\$5.99');
    });

    test('a published price that makes no sense is ignored, not rendered', () {
      final p = PricingStore.instance;
      p.resetForTest();
      addTearDown(p.resetForTest);

      // A tier ladder that goes backwards is exactly the App Store Connect
      // mistake this surface exists to keep out of the app — refused here as
      // well as in the publisher, so an older build can't render one either.
      p.debugApply({
        'tierCents': [999, 499, 1399, 2799]
      });
      expect(p.tierCents, AppUser.subscriptionTiersCents);
      // Wrong length, or a zero, is equally ignored.
      p.debugApply({
        'tierCents': [399, 699, 1399]
      });
      expect(p.tierCents, AppUser.subscriptionTiersCents);
      p.debugApply({
        'tierCents': [399, 0, 1399, 2799]
      });
      expect(p.tierCents, AppUser.subscriptionTiersCents);
      // A sane one is taken.
      p.debugApply({
        'tierCents': [399, 699, 1399, 2799]
      });
      expect(p.tierCents, [399, 699, 1399, 2799]);
    });

    test('storage prices are set per size, so the ladder can match the store',
        () async {
      // "The prices don't match no matter what I do" was a true report about
      // cloud storage: the ladder came from ONE per-GB rate, so the ten sizes
      // were locked in relation to each other and no rate could line all of
      // them up with App Store Connect. Per-size prices are the fix.
      final p = PricingStore.instance;
      p.resetForTest();
      addTearDown(p.resetForTest);

      // With nothing published, the derived ladder still stands.
      expect(StorageStore.priceCentsFor(10), 199);
      expect(StorageStore.priceCentsFor(20), 399);

      // A shape no single rate can produce: 10 GB at $2.99 and 20 GB at
      // $3.99. Any rate matching the first gives 20 GB at $5.99 or more.
      p.debugApply({
        'storageCents': {'10': 299, '20': 399}
      });
      expect(StorageStore.priceCentsFor(10), 299);
      expect(StorageStore.priceCentsFor(20), 399);
      // A size with no price of its own still comes off the rate.
      expect(StorageStore.priceCentsFor(30), 599);

      // A ladder where a bigger plan costs less — the exact App Store Connect
      // fault that started this — is dropped whole, not half-applied.
      p.resetForTest();
      p.debugApply({
        'storageCents': {'10': 299, '20': 199}
      });
      expect(StorageStore.priceCentsFor(10), 199, reason: 'back to the rate');

      // And a real store price still beats anything published here.
      final sp = StorePrices.instance;
      sp.resetForTest();
      addTearDown(sp.resetForTest);
      p.debugApply({
        'storageCents': {'10': 299}
      });
      sp.debugSet({StorePurchases.storageProductId(10): 'CA\$4.99'},
          answered: true);
      expect(
          sp.money(StorageStore.priceCentsFor(10),
              productId: StorePurchases.storageProductId(10)),
          'CA\$4.99');
    });

    test('an unreachable store shows no price rather than inventing one', () {
      // The hole under the mismatch: with a real store on the device that
      // could not be reached, every surface fell back to the cents the code
      // assumes and printed them as USD — a number Apple may well contradict,
      // shown indefinitely. A dash is the honest answer.
      final sp = StorePrices.instance;
      sp.resetForTest();
      addTearDown(sp.resetForTest);
      const id = 'com.okaymessaging.tip.coffee';

      // Nothing asked yet (web, test mode, the first frame) — the fallback is
      // right there, because there is no charge that could contradict it.
      expect(sp.money(299, productId: id), '\$2.99');
      expect(sp.pricesUnknown, isFalse);

      // A store exists and could not be reached: no invented figure.
      sp.debugSet(const {}, unreachable: true);
      expect(sp.pricesUnknown, isTrue);
      expect(sp.money(299, productId: id), StorePrices.unknownLabel);

      // It answers: the real price, and never the placeholder again.
      sp.debugSet({id: 'CA\$3.99'}, answered: true);
      expect(sp.pricesUnknown, isFalse);
      expect(sp.money(299, productId: id), 'CA\$3.99');
      // Something it does not sell is still named as such, not dashed.
      expect(sp.money(599, productId: 'com.okaymessaging.tip.snack'),
          StorePrices.unavailableLabel);
    });

    test('publishing applies what the server stored, not what was sent',
        () async {
      // The function sanitizes. If the device showed the SENT values, a field
      // the deployed function is too old to understand would look published
      // and then vanish on next launch — a silent no-op, and the owner back
      // to prices that don't match with nothing naming the cause.
      final p = PricingStore.instance;
      p.resetForTest();
      addTearDown(p.resetForTest);

      // A stale function that drops storageCents echoes what it kept.
      PricingStore.debugPublishOverride = (sent) async => true;
      expect(
          await p.publish({
            'storagePerGbCents': 20,
            'storageCents': {'10': 299},
          }),
          isTrue);
      // With no echo (the override path) the sent map still applies.
      expect(p.storageCents[10], 299);

      // Now the real shape: the echo is the authority.
      p.resetForTest();
      p.debugApply({
        'storagePerGbCents': 20,
        // storageCents absent — what an older function returns.
      });
      expect(p.storageCents, isEmpty);
      expect(StorageStore.priceCentsFor(10), 199);
    });

    testWidgets('a voice note draws its controls in the bubble\'s own colours',
        (tester) async {
      // The bug: the play button was drawn in the theme's PRIMARY, and in
      // both themes that is exactly the outgoing bubble's background —
      // #E7E9EA on dark, #0F1419 on light. A voice note you sent painted its
      // control the same colour as the bubble under it and vanished, while
      // an incoming one looked fine. Hence "sometimes".
      await tester.pumpWidget(const MaterialApp(
        home: Scaffold(
          body: VoiceNoteBubble(
            seconds: 18,
            audioUrl: 'data:audio/mp4;base64,AAAA',
            audioPath: null,
            audioKey: null,
            textColor: Color(0xFF0F1419),
            metaColor: Colors.black54,
          ),
        ),
      ));
      await tester.pump();

      final icon = tester.widget<Icon>(find.byIcon(Icons.play_arrow));
      expect(icon.color, const Color(0xFF0F1419),
          reason: 'the control takes the bubble\'s text colour, not the '
              'theme accent that equals the bubble background');
    });

    test('the voice bubble never reaches for the theme accent', () {
      // A source pin, because the wrong colour looked perfectly reasonable:
      // AppColors.accentOn(context) is the right call almost everywhere else
      // in the app, just not on top of a bubble.
      final src = File('lib/widgets/voice_note_bubble.dart').readAsStringSync();
      expect(src.contains('AppColors.accentOn(context)'), isFalse,
          reason: 'that colour IS the outgoing bubble background');
      expect(src, contains('final accent = widget.textColor'));
    });

    test('a failed price query on a phone stops the USD fallback', () {
      // "Shows USD even when I change currency." load() caught a thrown
      // query and left the fallback alone, so a device whose store could not
      // be read kept printing the cents hardcoded in the source — and those
      // are dollars. Changing App Store region could not move a number the
      // app was making up.
      final src = File('lib/payments/store_prices.dart').readAsStringSync();
      expect(src, contains('AppleIap.hasRealStore'),
          reason: 'the catch must distinguish a phone from the test suite');

      // And the discriminator has to be the one that actually differs.
      // AppleIap.isSupported reads defaultTargetPlatform, which flutter_test
      // overrides to android — it is true in this very run, so it cannot
      // tell a test from an iPhone. dart:io Platform reports the host.
      expect(AppleIap.isSupported, isTrue,
          reason: 'documents WHY isSupported is the wrong signal here');
      expect(AppleIap.hasRealStore, isFalse,
          reason: 'the suite is not a phone, so the plain figure stands');

      // Which means the fallback still works everywhere it should.
      final sp = StorePrices.instance;
      sp.resetForTest();
      addTearDown(sp.resetForTest);
      expect(
          sp.money(299, productId: 'com.okaymessaging.tip.coffee'), '\$2.99');
    });

    test('a purchase surface shows Apple\'s string and adds nothing', () {
      // The app used to append the ISO code so a Canadian buyer could tell
      // CA\$ from US\$. Well meant and wrong: Apple's own purchase sheet
      // prints "\$7.99" with no code, so a card reading "\$5.99 USD" beside it
      // cannot look like the same system even when both numbers are right —
      // and it reads as the app having chosen the currency. It never does.
      final sp = StorePrices.instance;
      sp.resetForTest();
      addTearDown(sp.resetForTest);
      const id = 'com.okaymessaging.tip.coffee';
      sp.debugSet({id: '\$1.99'}, answered: true, currencies: {id: 'CAD'});
      expect(sp.priceFor(id), '\$1.99');
      expect(sp.money(299, productId: id), '\$1.99');
      // No ISO code reaches a price, whichever currency the store quoted.
      sp.debugSet({id: '\$5.99'}, answered: true, currencies: {id: 'USD'});
      expect(sp.money(599, productId: id), '\$5.99');
      expect(sp.money(599, productId: id).contains('USD'), isFalse);

      // labelled() survives for the storefront DIAGNOSTICS, where naming the
      // currency is the whole point — but no purchase surface may call it.
      expect(StorePrices.labelled('\$1.99', 'CAD'), '\$1.99 CAD');
      expect(StorePrices.labelled('CA\$1.99', 'CAD'), 'CA\$1.99');
      expect(StorePrices.labelled('\$1.99', null), '\$1.99');
      for (final f in const [
        'lib/widgets/store_price_label.dart',
        'lib/screens/cloud_sync_screen.dart',
      ]) {
        expect(File(f).readAsStringSync().contains('StorePrices.labelled('),
            isFalse,
            reason: '\$f puts a currency code on a price again');
      }
      sp.debugSet({id: '\$1.99'}, answered: true, currencies: {id: 'CAD'});
      // The no-store fallback is a plain figure, not a claim about currency:
      // there is no charge behind it to be wrong about.
      expect(sp.money(299, productId: 'com.okaymessaging.tip.snack'),
          StorePrices.unavailableLabel);
    });

    test('money the app itself moves names its own currency', () {
      // The other half of "it shows USD": a Stripe wallet, a transfer and a
      // cash-out are NOT store prices — the app owns those numbers end to
      // end. Each already carried its currency (WalletStatus.currency off
      // the account, PaymentRecord.currency off the transaction,
      // sendCurrency off the sender) and every screen printed a bare '$'
      // instead, so a CAD balance read as USD.
      expect(Money.format(5000, 'cad'), 'CA\$50.00');
      expect(Money.format(5000, 'usd'), 'US\$50.00');
      expect(Money.format(5000, 'aud'), 'A\$50.00');
      // A currency with a symbol of its own keeps it — nothing to clarify.
      expect(Money.format(400, 'gbp'), '£4.00');
      expect(Money.format(400, 'eur'), '€4.00');
      // Case doesn't matter: Stripe returns 'cad', the sheet holds 'CAD'.
      expect(Money.format(199, 'CAD'), Money.format(199, 'cad'));
      // trimWhole is for the compact places that showed '$12', not '$12.00'.
      expect(Money.format(1200, 'cad', trimWhole: true), 'CA\$12');
      expect(Money.format(1250, 'cad', trimWhole: true), 'CA\$12.50');
      // An unknown code names itself rather than borrowing a '$'.
      expect(Money.format(100, 'jpy'), 'JPY 1.00');

      // The wallet balance reads in the currency STRIPE holds it in.
      const cad = WalletStatus(
          onboarded: true,
          chargesEnabled: true,
          payoutsEnabled: true,
          availableCents: 5000,
          currency: 'cad');
      expect(cad.money(cad.availableCents), 'CA\$50.00');
      const usd = WalletStatus(
          onboarded: true,
          chargesEnabled: true,
          payoutsEnabled: true,
          availableCents: 5000,
          currency: 'usd');
      expect(usd.money(usd.availableCents), 'US\$50.00');

      // CAD used to fall through symbolFor to a bare '$' — which is exactly
      // what a US price looks like, and the whole complaint.
      expect(PaymentService.symbolFor('cad'), isNot('\$'));
      expect(PaymentService.symbolFor('cad'), 'CA\$');
    });

    test('no money surface prints a bare dollar sign of its own', () {
      // A source pin, because the bug was not one bad formatter — it was
      // eight screens each rolling their own, every one of them dropping a
