      for (final f in const [
        'lib/screens/wallet_screen.dart',
        'lib/screens/payment_history_screen.dart',
        'lib/payments/payment_amount_sheet.dart',
      ]) {
        final src = File(f).readAsStringSync();
        expect(src, contains('Money.'),
            reason: '$f must route money through the one formatter');
        expect(RegExp(r"'\\\$\$\{\(").hasMatch(src), isFalse,
            reason: '$f still inlines a bare-dollar amount');
      }
    });

    test('the store check names the storefront behind the currency', () async {
      // "It's charging me USD." Nothing in the app can change that — the
      // currency follows the country on the Apple ID signed in to the App
      // Store — so the useful thing is to be able to SEE which store is
      // quoting, instead of guessing at it from the price.
      final src =
          File('lib/screens/store_products_screen.dart').readAsStringSync();
      expect(src, contains('AppleIap.storefront()'));
      expect(src, contains('Store region:'));
      // And it must say where the currency really comes from, since the two
      // things people reach for first (device region, App Store Connect) are
      // both wrong.
      expect(src, contains('country on the Apple ID'));
      // And the TestFlight trap, which cost several debugging rounds: a
      // TestFlight build ALWAYS reports USA here whatever country the
      // account is in — Apple's own long-standing bug
      // (developer.apple.com/forums/thread/794932) — and prices from the US
      // store to match, while the sheet bills the real account in its own
      // currency. "$9.99" on the card beside CA$12.99 in the sheet is two
      // Apple environments disagreeing, and reads exactly like a bug in this
      // app. Three separate devices all reporting USA is what finally
      // identified it: no per-account misconfiguration reaches all of them.
      expect(src, contains('Sandbox Account'));
      expect(src, contains('IN TESTFLIGHT'));
      expect(src, contains('two Apple'));
      // It must also say the thing that actually reassures: production is
      // unaffected and needs no change.
      expect(src, contains('installed from the App Store'));

      // Apple's OWN name for each product, shown when it differs from the
      // app's label. The app calls one product "Okay AI Pro" while App Store
      // Connect calls it "Okay AI Premuim" — until both are on screen there
      // is no way to tell WHICH row a price change was applied to, and
      // editing the wrong one looks exactly like the price not taking.
      expect(src, contains('App Store Connect calls this'));
      expect(src, contains('storeName'));
      expect(File('lib/payments/purchase_outcome.dart').readAsStringSync(),
          contains('titles'));
      expect(File('lib/payments/apple_iap_native.dart').readAsStringSync(),
          contains('p.id: p.title'));

      // Neither reading the storefront nor asking for prices may THROW.
      // Both talk to a billing channel that has no host side off-device, and
      // an escaping PlatformException surfaces later as an unhandled async
      // error blamed on whatever test happens to be running by then — which
      // is exactly how this one first went red.
      final native =
          File('lib/payments/apple_iap_native.dart').readAsStringSync();
      expect(native, contains('storeReachable: false, notOffered'),
          reason: 'an unreachable store is REPORTED, not thrown');
      await expectLater(AppleIap.storefront(), completion(''));
      final q = await AppleIap.query({'com.okaymessaging.tip.coffee'});
      expect(q.storeReachable, isFalse);
      expect(q.onSale, isEmpty);
    });

    test('on a phone the app never prints a price of its own', () {
      // "Cloud storage and tips are wrong too — the code should be reading
      // App Store Connect prices." It does, via StoreKit, which is the only
      // channel there is. What it ALSO used to do was fall back to its own
      // cents when the store had not answered — an invented figure beside a
      // Buy button, which the charge need not match. The AI pass avoided it
      // by carrying cents: 0; tips and storage carried real fallbacks.
      final src = File('lib/payments/store_prices.dart').readAsStringSync();
      expect(src, contains('if (AppleIap.hasRealStore) return unknownLabel;'));

      final sp = StorePrices.instance;
      sp.resetForTest();
      addTearDown(sp.resetForTest);
      const tip = 'com.okaymessaging.tip.coffee';

      // Off-device (this suite, and the web build) the plain figure stands —
      // there is no store to be contradicted by and nothing purchasable.
      expect(AppleIap.hasRealStore, isFalse);
      expect(sp.money(299, productId: tip), '\$2.99');

      // Apple's answer always wins, on any platform — and is shown exactly
      // as Apple formatted it, with no ISO code bolted on.
      sp.debugSet({tip: '\$3.49'}, answered: true, currencies: {tip: 'USD'});
      expect(sp.money(299, productId: tip), '\$3.49');

      // And a product the store answered about but does not sell is named,
      // never quietly given the app's number.
      expect(sp.money(599, productId: 'com.okaymessaging.tip.snack'),
          StorePrices.unavailableLabel);
    });

    test('the Store names the App Store its prices came from', () {
      // "I want the currency on the store to match currency of Apple." It
      // does — for the storefront StoreKit can see. What it could not do was
      // SAY which Apple that was, so a bare "$9.99" looked like a claim
      // about the buyer rather than about a store. Now the screen names it.
      //
      // No pre-purchase API exposes the PURCHASE account's currency
      // (queryProductDetails answers for the device storefront only), so
      // naming the source is the strongest guarantee available: the card can
      // never imply a currency it does not own.
      final src = File('lib/screens/store_screen.dart').readAsStringSync();
      expect(src, contains('AppleIap.storefront()'));
      expect(src, contains('Prices from the \$_storeName App Store'));
      // Unmapped countries keep Apple's own code rather than being guessed
      // into a country name.
      expect(src, contains('_ => _storefront,'));
      // And the line is absent rather than wrong when the storefront could
      // not be read — which is every off-device build, including this one.
      expect(src, contains('if (_storefront.isNotEmpty)'));
    });

    test('the app supplies no price to the purchase sheet', () {
      // Settling an argument that cost three rounds: when App Store Connect,
      // the card and Apple's sheet disagree, the app cannot be the one
      // inventing a number. It hands Apple a product REFERENCE and no
      // amount; Apple draws that sheet from its own data.
      final iap = File('lib/payments/apple_iap_native.dart').readAsStringSync();
      expect(iap, contains('PurchaseParam(productDetails:'));
      expect(RegExp(r'PurchaseParam\([^)]*(amount|price|cents)').hasMatch(iap),
          isFalse,
          reason: 'the app must never hand the sheet an amount');
      // And the amount is nowhere in the app at all, so it cannot leak in
      // from a constant either.
      for (final f in Directory('lib')
          .listSync(recursive: true)
          .whereType<File>()
          .where((f) => f.path.endsWith('.dart'))) {
        final src = f.readAsStringSync();
        // The comment naming the real-world example is the one exception.
        if (f.path.endsWith('store_products_screen.dart')) continue;
        expect(src.contains('1299'), isFalse,
            reason: '${f.path} hardcodes the amount Apple was quoting');
      }
    });

    test('the app re-asks the store instead of trusting the launch answer', () {
      // "I raise the price in App Store Connect and the app still shows the
      // old one." Prices were fetched ONCE at launch — and on iOS the app is
      // resumed far more often than relaunched, so a stale figure could
      // outlive the price change for as long as the process did. Exactly the
      // staleness already fixed here for follow counts.
      final main = File('lib/main.dart').readAsStringSync();
      final resume = main.substring(main.indexOf('AppLifecycleState.resumed'));
      expect(resume, contains('StorePrices.instance.load()'),
          reason: 'a resumed app must re-ask the store its prices');

      // And a way to force it by hand, because Apple's own product metadata
      // can lag its own purchase sheet and no amount of waiting inside the
      // app fixes a cache the app cannot see.
      final store = File('lib/screens/store_screen.dart').readAsStringSync();
      expect(store, contains('RefreshIndicator'));
      // The pull re-asks the store — via _refreshPrices, which also reports
      // what it found (below). Pinning the CALL rather than the callback's
      // name, so wrapping it again does not read as removing it.
      expect(store, contains('onRefresh: _refreshPrices'));
      expect(store, contains('await StorePrices.instance.load()'));
      // Pull-to-refresh needs a list that always scrolls, or a short page
      // has nothing to pull.
      expect(store, contains('AlwaysScrollableScrollPhysics'));
      // And it has to SAY what it found. A pull that silently returns the
      // same figures cannot answer the only question it exists for — did my
      // App Store Connect change land? — so all three outcomes are named,
      // including "Apple answered and nothing moved".
      expect(store, contains('prices updated'));
      expect(store, contains('still reports the same prices'));
      expect(store, contains('did not answer'));
    });

