  group('Contacts sync (phone matching)', () {
    test('phoneCandidates handles international and bare local numbers', () {
      // Already fully qualified (11 digits) → just itself.
      expect(
          ContactsSync.phoneCandidates('+1 (555) 012-3456'), {'15550123456'});
      // Bare 10-digit NANP number → itself and the +1 form.
      expect(ContactsSync.phoneCandidates('555-012-3456'),
          {'5550123456', '15550123456'});
      // Too short to dial → nothing.
      expect(ContactsSync.phoneCandidates('123'), isEmpty);
    });

    test('hashesFor dedupes and hashes every candidate', () {
      final hashes = ContactsSync.hashesFor(['555-012-3456']);
      // Two candidates → two distinct hashes, matching AccountService's hash.
      expect(hashes.toSet().length, 2);
      expect(hashes, contains(AccountService.phoneHashHex('15550123456')));
      expect(hashes, contains(AccountService.phoneHashHex('5550123456')));
      // De-duplication across numbers that normalise to the same thing.
      final dupes = ContactsSync.hashesFor(['15550123456', '+1 555 012 3456']);
      expect(dupes.toSet().length, dupes.length);
    });

    test('phone display formatting touches numbers, never names', () {
      expect(formatPhoneForDisplay('14386386261'), '+1 (438) 638-6261');
      expect(formatPhoneForDisplay('+1 438 638 6261'), '+1 (438) 638-6261');
      expect(formatPhoneForDisplay('4386386261'), '(438) 638-6261');
      expect(formatPhoneForDisplay('+447911123456'), '+447911123456');
      // Real names, usernames, and short fragments pass through untouched.
      expect(formatPhoneForDisplay('Grace Hopper'), 'Grace Hopper');
      expect(formatPhoneForDisplay('555-0123'), '555-0123');
      expect(formatPhoneForDisplay(''), '');
    });

    test('the dial pad groups a number as it is typed, and only when it can',
        () {
      // After every keystroke, not just once the number is complete.
      expect(formatDialedNumber(''), '');
      expect(formatDialedNumber('4'), '4');
      expect(formatDialedNumber('416'), '416');
      expect(formatDialedNumber('4165'), '(416) 5');
      expect(formatDialedNumber('416555'), '(416) 555');
      expect(formatDialedNumber('4165550123'), '(416) 555-0123');
      expect(formatDialedNumber('14165550123'), '1 (416) 555-0123');

      // Everything it cannot name honestly is handed back exactly as typed.
      // Guessing NANP brackets for these would be inventing a shape.
      expect(formatDialedNumber('+447911123456'), '+447911123456',
          reason: 'the caller already said which country this is');
      expect(formatDialedNumber('*67'), '*67', reason: 'a feature code');
      expect(formatDialedNumber('4165550123#'), '4165550123#');
      expect(formatDialedNumber('4915112345678'), '4915112345678',
          reason: 'thirteen digits is a shape this cannot name');
      expect(formatDialedNumber('24165550123'), '24165550123',
          reason: 'eleven digits that do not start with 1 are not +1');
    });

    test('a typed number reaches the SMS provider with its country code', () {
      // THE BUG: the verify-your-number screen prepended a bare '+' to what
      // was typed, so a Toronto number went out as +4167813638 — read as
      // Switzerland (+41) and refused, "sms_send_failed" / Twilio 60200.
      expect(phoneToE164('4167813638', dialCode: '+1'), '+14167813638');
      // Punctuation people actually type.
      expect(phoneToE164('(416) 781-3638', dialCode: '+1'), '+14167813638');
      expect(phoneToE164('416 781 3638', dialCode: '+1'), '+14167813638');
      // Already carries the country code — not doubled.
      expect(phoneToE164('14167813638', dialCode: '+1'), '+14167813638');
      // Idempotent on anything already E.164, which is what lets it sit at
      // the send choke point without touching numbers that were right.
      expect(phoneToE164('+14167813638', dialCode: '+1'), '+14167813638');
      expect(phoneToE164('+1 416 781 3638', dialCode: '+1'), '+14167813638');
      // A national trunk '0' is never part of the international form.
      expect(phoneToE164('07911123456', dialCode: '+44'), '+447911123456');
      expect(phoneToE164('7911123456', dialCode: '+44'), '+447911123456');
      expect(phoneToE164('447911123456', dialCode: '+44'), '+447911123456');
      // Nothing typed stays nothing, rather than becoming a bare '+'.
      expect(phoneToE164('', dialCode: '+1'), '');
      expect(phoneToE164('   ', dialCode: '+1'), '');
    });

    testWidgets('verifying a number picks a country, and never sends a bare +',
        (tester) async {
      await tester
          .pumpWidget(const MaterialApp(home: NumberlessVerifyScreen()));
      await tester.pumpAndSettle();

      // The country is chosen, not inferred — Canada by default, like the
