      await tester.pumpAndSettle();
      expect(find.text('4167813638'), findsOneWidget);

      // Switching country switches the code the number goes out under.
      await tester.tap(find.text('🇨🇦 +1'));
      await tester.pumpAndSettle();
      await tester.tap(find.text('United Kingdom'));
      await tester.pumpAndSettle();
      expect(find.text('🇬🇧 +44'), findsOneWidget);
    });

    test('the provider error is a sentence, not an exception dump', () {
      // What the screen showed: "AuthApiException(message: Error sending
      // confirmation OTP to provider: Invalid parameter `To`: +4167813638
      // More information: https://www.twilio.com/docs/errors/60200,
      // statusCode: 422, code: sms_send_failed)".
      final dump = Exception(
          'AuthApiException(message: Error sending confirmation OTP to '
          'provider: Invalid parameter `To`: +4167813638, code: '
          'sms_send_failed)');
      final shown = NumberlessVerifyScreen.readableError(dump);
      expect(shown, contains('couldn\'t be texted'));
      expect(shown, isNot(contains('AuthApiException')));
      expect(shown, isNot(contains('twilio')));
    });

    test('live-delivery self-test names what is missing before it can run',
        () async {
      // Without a relay (this suite) it must say so and not touch the
      // network — the probe would otherwise throw on an uninitialized
      // Supabase and turn a configuration answer into a crash.
      final report = await RelaySelfTest.run();
      expect(report.faulty, isTrue);
      expect(report.steps.first.state, CheckState.fail);
      expect(report.verdict, contains('relay'));
    });

    test('live broadcast callbacks unwrap the wire envelope', () {
      // realtime_client hands a subscription callback the whole envelope
      // ({event, payload, type}), not the payload the sender broadcast —
      // proven against the live project by tool/probe_realtime.dart. Every
      // handler used to read fields off the envelope, get null, and drop the
      // event: no message, typing, presence, or incoming call ever applied
      // LIVE, and delivery silently degraded to the offline-mailbox sweeps.
      expect(
        RelayService.unwrapBroadcast({
          'event': 'typing',
          'type': 'broadcast',
          'payload': {'from': '+1 555 0100'},
        }),
        {'from': '+1 555 0100'},
      );
      // A payload that is already the sent one passes through untouched, so
      // a future client that starts delivering the inner payload can't
      // re-break delivery. (No app payload nests a map under 'payload'.)
      const sent = {'from': '+1 555 0100', 'kind': 'offer', 'callId': 'c1'};
      expect(RelayService.unwrapBroadcast(Map.of(sent)), sent);
    });

    test('relay wake/resync are safe no-ops before the relay ever starts',
        () async {
      // wake() runs on every return from the background — including on
      // builds with no relay configured and before sign-in — so it must
      // never throw or touch the network when there is nothing to rebuild.
      await RelayService.instance.wake();
      await RelayService.instance.resync();
    });

    test('CallKit uuids are stable per call and version-4 shaped', () {
      addTearDown(CallKitBridge.instance.resetForTest);
      final a = CallKitBridge.instance.uuidFor('call_1');
      expect(CallKitBridge.instance.uuidFor('call_1'), a); // stable
      expect(CallKitBridge.instance.uuidFor('call_2'), isNot(a));
      // DERIVED, not minted: SHA-256(callId) with the version/variant bits
      // stamped in. Swift computes the identical value from a VoIP push
      // (CallKitBridge.uuidFor in AppDelegate.swift), which is how both
      // sides ring ONE system call instead of two. This vector is that
      // contract — if it moves, the Swift twin must move with it.
      expect(a, '74196fe7-2e4c-4c13-9c10-33e05a2e020c');
      expect(
          RegExp(r'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$')
              .hasMatch(a),
          isTrue);
    });

    test('mailbox rows route by event and tolerate junk', () {
      final rows = [
        // Typed rows: messages, receipts, edits all queue offline now.
        {
          'id': 1,
          'payload': {
            'e': 'msg',
            'p': {'id': 'm1', 'from': '+15550100', 'c': 'AAA='}
          }
        },
        {
          'id': 2,
          'payload': {
            'e': 'receipt',
            'p': {'from': '+15550100', 'kind': 'delivered', 'id': 'm1'}
          }
        },
        // A legacy row from before events were queued reads as a message.
        {'id': 3, 'payload': '{"id":"m2","from":"+15550100","c":"BBB="}'},
        {'id': 4, 'payload': 42}, // corrupt — skipped, never wedges the queue
        'not even a map',
      ];
      final entries = RelayService.mailboxEntries(rows);
      expect(entries, hasLength(3));
      expect(entries[0].$1, 'msg');
      expect(entries[0].$2['id'], 'm1');
      expect(entries[1].$1, 'receipt');
      expect(entries[1].$2['kind'], 'delivered');
      expect(entries[2].$1, 'msg');
      expect(entries[2].$2['id'], 'm2');
      // Envelopes stay ciphertext, same as the live broadcast.
      expect(entries[0].$2.containsKey('text'), isFalse);
    });

    test('a scanned QR parses end to end, and the whole chain is wired', () {
      // The QR encoded okaymsg://add from day one, but no scheme was
      // registered, the scene delegate filtered it out, and nothing in Dart
      // knew the shape — three gaps, one dead feature. This test holds all
      // three shut.
      const me = AppUser(
          id: 'x',
          name: 'Iman K',
          avatarColor: '#111111',
          phone: '+1 437 833 6018',
          username: 'iman');
      final url = MyQrScreen.payloadFor(me);
      expect(url.startsWith('okaymsg://add?'), isTrue);
      final t = IncomingLinks.addTarget(url)!;
      expect(t.phone, '+14378336018');
      expect(t.name, 'Iman K');
      expect(t.username, 'iman');
      // A numberless account's QR carries its code — same door.
      const ghost = AppUser(
          id: 'g',
          name: 'Ghost',
          avatarColor: '#222222',
          phone: '001234567890',
          username: 'ghosty');
      expect(IncomingLinks.addTarget(MyQrScreen.payloadFor(ghost))!.phone,
          '001234567890');
      // Anything else is not an add.
      expect(IncomingLinks.addTarget('im:+15550100'), isNull);
      expect(IncomingLinks.addTarget('okaymsg://other?p=15550100'), isNull);
      expect(IncomingLinks.addTarget('okaymsg://add?p=123'), isNull,
          reason: 'too short to be an inbox');
      // The scheme is registered, the scene delegate forwards it, and main
      // actually creates the chat.
      final plist = File('ios/Runner/Info.plist').readAsStringSync();
      expect(plist.contains('<string>okaymsg</string>'), isTrue,
          reason: 'unregistered scheme = the camera offers nothing');
      final scene = File('ios/Runner/SceneDelegate.swift').readAsStringSync();
      expect(scene.contains('"okaymsg"'), isTrue,
          reason: 'the scene delegate must not filter the QR scheme out');
      final mainSrc = File('lib/main.dart').readAsStringSync();
      expect(mainSrc.contains('onAdd:'), isTrue,
          reason: 'parsing without a handler still does nothing');
    });

    test('im: links (default messaging app) parse and open the right chat', () {
      // Phone targets, in every shape iOS sends them.
      expect(IncomingLinks.imPhone('im:+15550123456'), '+15550123456');
      expect(IncomingLinks.imPhone('im://+1-555-012.3456'), '+15550123456');
      expect(IncomingLinks.imPhone('sms:5550123456'), '5550123456');
      expect(IncomingLinks.imPhone('im:%2B15550123456'), '+15550123456');
      // Email, junk, and foreign schemes are not phone targets.
      expect(IncomingLinks.imPhone('im:user@example.com'), isNull);
      expect(IncomingLinks.imPhone('im:123'), isNull);
      expect(IncomingLinks.imPhone('https://okay.chat'), isNull);
      expect(IncomingLinks.isEmailTarget('im:user@example.com'), isTrue);
      expect(IncomingLinks.isEmailTarget('im:+15550123456'), isFalse);

      // Call taps (default calling app) parse the same way from tel: URLs,
      // and the two kinds never cross.
      expect(IncomingLinks.telPhone('tel:+15550123456'), '+15550123456');
      expect(IncomingLinks.telPhone('telprompt://5550123456'), '5550123456');
      expect(IncomingLinks.telPhone('im:+15550123456'), isNull);
      expect(IncomingLinks.imPhone('tel:+15550123456'), isNull);

      // A message tap creates the chat, then reuses (and unarchives) it.
      ChatStore.instance.reset();
      openChatForPhone('+15550123456');
      final created = ChatStore.instance.chatWithContact('+15550123456');
      expect(created, isNotNull);
      expect(created!.contact.phone, '+15550123456');
      ChatStore.instance.setArchived(created.id, true);
      openChatForPhone('+15550123456');
      expect(ChatStore.instance.chatWithContact('+15550123456')!.isArchived,
          isFalse);
      expect(
          ChatStore.instance.allChats
              .where((c) => c.contact.id == '+15550123456'),
          hasLength(1));

      // A call tap resolves to the existing chat's contact (named), and to
      // a bare number identity for strangers.
      expect(contactForPhone('+15550123456').id, '+15550123456');
      expect(contactForPhone('+19998887777').phone, '+19998887777');
    });

