  test('file transfer chunking splits and losslessly reassembles', () {
    final data = Uint8List.fromList(List.generate(40000, (i) => (i * 7) % 256));
    final chunks = FileTransfer.chunk(data);
    // 40000 / 16384 -> 3 chunks (16384, 16384, 7232).
    expect(chunks.length, 3);
    expect(chunks.first.length, FileTransfer.chunkSize);
    expect(FileTransfer.reassemble(chunks), equals(data));

    // Edge: empty input.
    expect(FileTransfer.chunk(Uint8List(0)), isEmpty);
    expect(FileTransfer.reassemble(const []), isEmpty);
  });

  group('ECDH key exchange', () {
    test('two devices derive the same shared secret (P-256 ECDH)', () {
      final alice = SecureKeyExchange.instance;
      alice.resetForTest();
      alice.ensureKeys();
      final alicePub = alice.myPublicKey!;
      final alicePriv = alice.exportPrivate();

      // Bob: a second identity, restored into the same singleton to compute
      // his side, capturing his public key.
      final bob = SecureKeyExchange.instance;
      bob.resetForTest();
      bob.ensureKeys();
      final bobPub = bob.myPublicKey!;
      final bobSecret = bob.sharedSecretWith(alicePub);

      // Back to Alice's identity to compute her side.
      alice.resetForTest();
      alice.ensureKeys(restorePrivateHex: alicePriv);
      final aliceSecret = alice.sharedSecretWith(bobPub);

      expect(aliceSecret, isNotNull);
      expect(bobSecret, isNotNull);
      expect(aliceSecret, equals(bobSecret));
    });

    test('an ECDH secret encrypts/decrypts through AES-256-GCM', () {
      final kx = SecureKeyExchange.instance;
      kx.resetForTest();
      kx.ensureKeys();
      // Round-trip with the device talking to itself (same key both ways).
      final secret = kx.sharedSecretWith(kx.myPublicKey!)!;
      final blob = E2eCrypto.encrypt(secret, 'handshake secured 🔒');
      expect(E2eCrypto.decrypt(secret, blob), 'handshake secured 🔒');
    });

    test('restoring a private key reproduces the same public key', () {
      final kx = SecureKeyExchange.instance;
      kx.resetForTest();
      kx.ensureKeys();
      final pub = kx.myPublicKey;
      final priv = kx.exportPrivate();
      kx.resetForTest();
      kx.ensureKeys(restorePrivateHex: priv);
      expect(kx.myPublicKey, pub);
    });
  });

  group('E2E crypto', () {
    test('encrypt/decrypt round-trips with the derived shared key', () {
      final key = E2eCrypto.keyFor('+1 555 0199', '+1 555 0100');
      final blob = E2eCrypto.encrypt(key, 'hello 🔐 world');
      expect(blob, isNot('hello 🔐 world'));
      expect(E2eCrypto.decrypt(key, blob), 'hello 🔐 world');
    });

    test('both parties derive the same key regardless of order', () {
      expect(
        E2eCrypto.keyFor('+1 555 0199', '+1 (555) 0100'),
        E2eCrypto.keyFor('15550100', '15550199'),
      );
    });

    test('a wrong key fails to decrypt (returns null)', () {
      final key = E2eCrypto.keyFor('+1 555 0199', '+1 555 0100');
      final other = E2eCrypto.keyFor('+1 555 0199', '+1 555 0123');
      final blob = E2eCrypto.encrypt(key, 'top secret');
      expect(E2eCrypto.decrypt(other, blob), isNull);
    });

    test('a tampered ciphertext fails authentication', () {
      final key = E2eCrypto.keyFor('+1 555 0199', '+1 555 0100');
      final blob = E2eCrypto.encrypt(key, 'integrity matters');
      final bytes = base64.decode(blob);
      bytes[20] = bytes[20] ^ 0xFF; // flip a byte in the ciphertext region
      expect(E2eCrypto.decrypt(key, base64.encode(bytes)), isNull);
    });

    test('the safety number fingerprints the KEYS, and fails when it should',
        () {
      // It used to be derived from the two phone numbers — which an
      // interceptor also has, so the codes matched through any attack and
      // the comparison verified nothing. A check that cannot fail is not a
      // check.
      final alice = SecureKeyExchange.freshForTest();
      final bob = SecureKeyExchange.freshForTest();
      final mallory = SecureKeyExchange.freshForTest();
      final a =
          E2eCrypto.safetyNumberForKeys(alice.myPublicKey!, bob.myPublicKey!);
      final b =
          E2eCrypto.safetyNumberForKeys(bob.myPublicKey!, alice.myPublicKey!);
      expect(a, b, reason: 'both sides compute the same code');
      final groups = a.split(' ');
      expect(groups.length, 12);
      expect(groups.every((g) => RegExp(r'^\d{5}$').hasMatch(g)), isTrue);
      // The point of the whole exercise: a middle-man holds different keys,
      // so each victim computes a DIFFERENT code and comparing catches it.
      expect(
          E2eCrypto.safetyNumberForKeys(
              alice.myPublicKey!, mallory.myPublicKey!),
          isNot(a));
      expect(
          E2eCrypto.safetyNumberForKeys(mallory.myPublicKey!, bob.myPublicKey!),
          isNot(a));
    });

    test('a changed identity key is said in the conversation', () async {
      // The crypto layer already handles a key change safely; this is the
      // HUMAN being told it happened — Signal's warning. First learn stays
      // silent (that is every new contact introducing themselves).
      SharedPreferences.setMockInitialValues({});
      // ignore: invalid_use_of_visible_for_testing_member
      addTearDown(SecureKeyExchange.instance.resetForTest);
      addTearDown(() => SecureKeyExchange.instance.onPeerKeyChanged = null);
      await SecureKeyExchange.instance.load();
      SecureKeyExchange.instance.onPeerKeyChanged =
          (digits) => ChatStore.instance.noteIdentityChange(digits);

      final store = ChatStore.instance;
      store.upsert(const Chat(
        id: 'chat_keychg',
        contact: AppUser(
            id: 'kc',
            name: 'Kai',
            avatarColor: '#7A5CFF',
            about: '',
            phone: '+1 555 0171'),
        messages: [],
      ));
      addTearDown(() => store.deleteChat('chat_keychg'));

      final first = SecureKeyExchange.freshForTest();
      final second = SecureKeyExchange.freshForTest();
      SecureKeyExchange.instance
          .rememberPeer('+1 555 0171', first.myPublicKey!);
      expect(store.chatById('chat_keychg')!.messages, isEmpty,
          reason: 'meeting someone is not a warning');
      SecureKeyExchange.instance
          .rememberPeer('+1 555 0171', second.myPublicKey!);
      final msgs = store.chatById('chat_keychg')!.messages;
      expect(msgs.length, 1);
      expect(msgs.single.text, contains('security code changed'));
      expect(msgs.single.text, contains('compare security codes'),
          reason: 'the warning names the action, not just the event');
      // Repeats within a run stay quiet — a two-device pairing alternating
      // keys would otherwise fill the chat with warnings.
      SecureKeyExchange.instance
          .rememberPeer('+1 555 0171', first.myPublicKey!);
      expect(store.chatById('chat_keychg')!.messages.length, 1);
    });
  });

