      expect(publicFeed.contains('offerPublicSpark('), isFalse);
      expect(
          File('lib/screens/feed_screen.dart')
              .readAsStringSync()
              .contains('offerSpark('),
          isFalse);
    });
  });

  group('Account lifecycle', () {
    test('delete account erases THIS account, not the others on the device',
        () async {
      // Per-account deletion: the signed-in account's own slice goes, but the
      // device's settings/PIN and — crucially — any OTHER account parked here
      // must survive, so deleting one identity never wipes a person's other
      // identities off a shared phone.
      SharedPreferences.setMockInitialValues({
        'session_v1': '{}', // the current account's live data…
        'communities_v1': '[{"id":"mine"}]', // …its servers…
        'anything_else': 'x', // …and whatever else it wrote
        'theme': 'dark', // device setting — stays
        'app_lock_hash_v1': 'h', // device PIN — stays
        'last_account_v1': '{}', // welcome-back card — stays
        AccountWipe.ownerKey: '15550001111', // owner marker — stays
        'acct_ns_15550002222': '{"prefs":{},"sec":{}}', // ANOTHER account
      });
      await AccountWipe.eraseCurrentAccount();
      final prefs = await SharedPreferences.getInstance();
      // The current account's slice is gone.
      expect(prefs.containsKey('session_v1'), isFalse);
      expect(prefs.containsKey('communities_v1'), isFalse);
      expect(prefs.containsKey('anything_else'), isFalse);
      // The device and the OTHER account are untouched.
      expect(prefs.getString('theme'), 'dark');
      expect(prefs.getString('app_lock_hash_v1'), 'h');
      expect(prefs.containsKey('acct_ns_15550002222'), isTrue,
          reason: "another account's parked data must survive a delete");
    });

    test(
        'signing out a name-only account with no recovery PIN erases it — '
        'there is nothing to sign back in with', () async {
      SharedPreferences.setMockInitialValues({});
      IdentityRecovery.resetReadyForTest();
      Session.instance.knownAccounts = [];
      addTearDown(() async {
        Session.instance.knownAccounts = [];
        Session.instance.resetForTest();
        IdentityRecovery.resetReadyForTest();
      });
      final code = AccountCode.mint();
      Session.instance.signInForTest(phone: code, name: 'ghost');
      expect(Session.instance.isNumberless, isTrue);

      await Session.instance.signOut();

      expect(Session.instance.user.value, isNull);
      // Erased, not remembered: there is no PIN to bring it back with, so
      // offering it as a one-tap "known account" would be a dead end.
      expect(Session.instance.knownAccounts, isEmpty,
          reason: 'an unrecoverable numberless account must not be '
              'remembered for next time — there is no next time');
      final prefs = await SharedPreferences.getInstance();
      expect(prefs.containsKey('session_v1'), isFalse);
    });

    test(
        'signing out a name-only account WITH a recovery PIN backup is a '
        'normal sign-out — it really can come back', () async {
      SharedPreferences.setMockInitialValues({});
      IdentityRecovery.resetReadyForTest();
      Session.instance.knownAccounts = [];
      addTearDown(() async {
        Session.instance.knownAccounts = [];
        Session.instance.resetForTest();
        IdentityRecovery.resetReadyForTest();
      });
      final code = AccountCode.mint();
      Session.instance.signInForTest(phone: code, name: 'ghost');
      expect(Session.instance.isNumberless, isTrue);
      await IdentityRecovery.markReady(); // a backup really was stored

      await Session.instance.signOut();

      expect(Session.instance.user.value, isNull);
      // Remembered, not erased — the PIN is a real way back in, the same
      // one "Deactivate temporarily" already promises for this exact case.
      expect(Session.instance.knownAccounts.map((a) => a.phone), [code],
          reason: 'a numberless account with a stored recovery backup can '
              'really sign back in, so signing out must not erase it');
    });

    test(
        'every place that signs out a name-only account checks for a '
        'recovery backup before claiming the sign-out is reversible', () {
      // Session.signOut() is the one funnel that decides erase-vs-remember;
      // this pins that the decision is actually wired to the real signal
      // rather than a copy of the old unconditional assumption creeping
      // back into a UI-level check.
      final session = File('lib/state/session.dart').readAsStringSync();
      expect(session, contains('isNumberless && !IdentityRecovery.ready.value'));

      for (final path in [
        'lib/screens/home_screen.dart',
        'lib/screens/settings_screen.dart',
      ]) {
        final src = File(path).readAsStringSync();
        expect(src, contains('IdentityRecovery.ready'),
            reason: '$path signs a numberless account out without checking '
                'whether it can actually come back');
      }
    });

    test('the delete flow is server-first, and deactivation hides the row', () {
      final settings =
          File('lib/screens/settings_screen.dart').readAsStringSync();
      expect(settings, contains('Deactivate temporarily'));
      expect(settings, contains('Type DELETE to confirm'));
      // Server before local: wiping the phone while the server rows live on
      // would only look like deletion.
      final invokeAt = settings.indexOf("invoke('delete-account'");
      final eraseAt = settings.indexOf('eraseCurrentAccount');
      expect(invokeAt, greaterThan(0));
      expect(eraseAt, greaterThan(invokeAt),
          reason: 'the local erase must come after the server said yes');
      expect(settings, contains('setHidden(true)'),
          reason: 'deactivation must reach the directory, not just sign out');

      // Reactivation IS the sign-in.
      final session = File('lib/state/session.dart').readAsStringSync();
      expect(session, contains("'hidden': false"),
          reason: 'signing back in must clear the deactivation flag');

      // The function deletes what the phone owns — each named table — and
      // the auth user last.
      final fn =
          File('supabase/functions/delete-account/index.ts').readAsStringSync();
      for (final table in [
        'usernames',
        'push_tokens',
        'identity_backups',
        'mailbox',
        'payment_settings',
        'identity_verifications',
        'public_posts',
      ]) {
        expect(fn, contains('"$table"'),
            reason: '$table holds rows the account owns');
      }
      expect(fn, contains('deleteUser'));
      expect(fn, isNot(contains('drop("payment_transactions"')),
          reason: 'transfer records are receipts, not preferences — kept');
      // And the paste copy exists, so it can actually be deployed.
      expect(File('docs/edge_functions_paste/delete-account.ts').existsSync(),
          isTrue);
    });

    test('setHidden refuses without a session instead of pretending', () async {
      Session.instance.user.value = null;
      expect(await AccountService.instance.setHidden(true), isFalse);
    });
  });

  group('MFA and parental controls', () {
    test('two-step PIN guessing hits an escalating cooldown', () async {
      final ts = TwoStepVerification.instance;
      ts.resetForTest();
      addTearDown(ts.resetForTest);
      await ts.load();
      await ts.setPin('123456');
      expect(ts.verify('123456'), isTrue, reason: 'the right PIN works');

      // A near-miss run: four wrong guesses cost attempts, not time.
      for (var i = 0; i < 4; i++) {
        expect(ts.verify('000000'), isFalse);
      }
      expect(ts.attemptsLeft, 1);
      expect(ts.lockedFor, Duration.zero);
      expect(ts.verify('123456'), isTrue,
          reason: 'a correct PIN before the lock clears the count');
      expect(ts.attemptsLeft, TwoStepVerification.maxAttempts);

      // Five misses start the cooldown — and the RIGHT PIN is refused
      // during it, or the lock becomes an oracle for the guesser.
      for (var i = 0; i < 5; i++) {
        expect(ts.verify('000000'), isFalse);
      }
      expect(ts.lockedFor, greaterThan(Duration.zero));
      expect(ts.verify('123456'), isFalse,
          reason: 'the cooldown refuses even the correct PIN');

      // The lock survives a relaunch — killing the app is not a way around.
      final again = TwoStepVerification.instance;
      await again.load();
      expect(again.lockedFor, greaterThan(Duration.zero));
      await ts.disable();
      expect(ts.lockedFor, Duration.zero);
    });

    test('parental controls block what they say and only that', () async {
      final pc = ParentalControls.instance;
      pc.resetForTest();
      addTearDown(pc.resetForTest);
      await pc.load();
      expect(pc.blocks(ParentalRestriction.payments), isFalse,
          reason: 'nothing is blocked before a parent sets anything up');

      await pc.setPin('4321');
      await pc.setBlocked(ParentalRestriction.payments, true);
      expect(pc.blocks(ParentalRestriction.payments), isTrue);
      expect(pc.blocks(ParentalRestriction.marketplace), isFalse);

      // The payments block is enforced INSIDE the one send funnel, so a
      // payment surface added later is caught too — and test mode is not
      // exempt, because a simulated send still teaches the gesture.
      PaymentService.instance.testMode.value = true;
      addTearDown(() => PaymentService.instance.testMode.value = false);
      expect(
        () => PaymentService.instance
            .sendMoney(toPhone: '15550002222', amountCents: 100),
        throwsA(isA<PaymentException>()
            .having((e) => e.code, 'code', 'parental_locked')),
      );

      // Wrong-PIN throttling, same shape as two-step.
      for (var i = 0; i < 5; i++) {
        expect(pc.verify('0000'), isFalse);
      }
      expect(pc.lockedFor, greaterThan(Duration.zero));
      expect(pc.verify('4321'), isFalse,
          reason: 'the cooldown refuses even the right PIN');

      // Blocks survive a reload (the child relaunching the app).
      await pc.load();
      expect(pc.blocks(ParentalRestriction.payments), isTrue);

      await pc.disable();
      expect(pc.blocks(ParentalRestriction.payments), isFalse);
    });

    testWidgets('a parental gate stands in front of the wallet',
        (tester) async {
      final pc = ParentalControls.instance;
      pc.resetForTest();
      addTearDown(pc.resetForTest);
      await pc.load();
      await pc.setPin('4321');
      await pc.setBlocked(ParentalRestriction.payments, true);
      await tester.pumpWidget(const MaterialApp(
        home: ParentalGate(
          restriction: ParentalRestriction.payments,
          title: 'Wallet',
          child: Text('the wallet itself'),
        ),
      ));
      await tester.pump();
      expect(find.text('the wallet itself'), findsNothing);
      expect(find.text('Wallet is turned off'), findsOneWidget);
      expect(find.textContaining('Parental controls'), findsOneWidget);
      // No PIN entry on the gate — unlocking where the child is watching
      // would teach the PIN. The way back is Settings.
      expect(find.byType(TextField), findsNothing);

      // Lifting the block restores the screen without a rebuild.
      await pc.setBlocked(ParentalRestriction.payments, false);
      await tester.pump();
      expect(find.text('the wallet itself'), findsOneWidget);
    });

    test('every named surface is actually wrapped', () {
      // The gate exists exactly where the settings screen claims it does; a
      // surface named in the toggles but never wrapped would be a lie a
      // child finds first.
      expect(File('lib/screens/wallet_screen.dart').readAsStringSync(),
          contains('ParentalRestriction.payments'));
      expect(File('lib/screens/marketplace_screen.dart').readAsStringSync(),
          contains('ParentalRestriction.marketplace'));
      expect(File('lib/screens/public_feed_screen.dart').readAsStringSync(),
          contains('ParentalRestriction.publicFeed'));
      expect(File('lib/screens/communities.dart').readAsStringSync(),
          contains('ParentalRestriction.servers'));
      expect(File('lib/payments/payment_service.dart').readAsStringSync(),
          contains('parental_locked'));
    });
  });

  group('Call clarity and voice-channel media', () {
    test(
        'tuneOpus turns on FEC, DTX and the 64k ceiling without wrecking '
        'the SDP', () {
      const sdp = 'v=0\r\n'
          'm=audio 9 UDP/TLS/RTP/SAVPF 111 103\r\n'
          'a=rtpmap:111 opus/48000/2\r\n'
          'a=fmtp:111 minptime=10;useinbandfec=0\r\n'
          'a=rtpmap:103 ISAC/16000\r\n';
      final tuned = CallQuality.tuneOpus(sdp);
      expect(tuned, contains('a=rtpmap:111 opus/48000/2'),
          reason: 'the rtpmap line must survive intact');
      expect(tuned, contains('useinbandfec=1'));
      expect(tuned, contains('usedtx=1'));
      expect(tuned, contains('maxaveragebitrate=64000'));
      expect(tuned, contains('minptime=10'),
          reason: 'params the platform negotiated are kept');
      expect(RegExp('useinbandfec').allMatches(tuned).length, 1,
          reason: 'a stale value is replaced, not stacked');

      // No fmtp line at all: one is added after the rtpmap, whole-line.
      const bare = 'a=rtpmap:96 opus/48000/2\r\na=rtpmap:97 ISAC/16000\r\n';
      final added = CallQuality.tuneOpus(bare);
      expect(added, contains('a=rtpmap:96 opus/48000/2\r\na=fmtp:96 '));
      expect(added, contains('a=rtpmap:97 ISAC/16000'));

      // No Opus: nothing to tune, nothing touched.
      const noOpus = 'a=rtpmap:96 VP8/90000\r\n';
      expect(CallQuality.tuneOpus(noOpus), noOpus);
    });

    test('for any pair exactly one side dials', () {
      expect(RoomMedia.initiates('15550001111', '15550002222'),
          isNot(RoomMedia.initiates('15550002222', '15550001111')),
          reason: 'both devices computing the same rule is what prevents '
              'the two-Alices race');
      expect(RoomMedia.initiates('15550001111', '15550001111'), isFalse);
      // Numberless codes and phone digits compare fine too.
      expect(RoomMedia.initiates('001234567890', '15550001111'),
          isNot(RoomMedia.initiates('15550001111', '001234567890')));
    });

    test('the mesh follows presence: joiners connect, leavers drop', () {
      final diff = RoomMedia.diffPeers({'a', 'b', 'c'}, {'b', 'c', 'd'});
      expect(diff.add, {'d'});
      expect(diff.drop, {'a'});
      final none = RoomMedia.diffPeers({'a'}, {'a'});
      expect(none.add, isEmpty);
      expect(none.drop, isEmpty);
    });

    test('room signaling is sealed, live-only, and actually wired', () {
      final relay = File('lib/relay/relay_service.dart').readAsStringSync();
      // The sender seals like call signaling and never queues: a room offer
      // replayed hours later would dial a room the sender already left.
      final sendBody = relay.substring(
          relay.indexOf('sendRoomSignal'), relay.indexOf('onRoomSignal'));
      expect(sendBody, contains('_sealSignalPair'));
      expect(sendBody, isNot(contains('_mailboxPut')));
      expect(relay, contains("event: 'vrtc'"));
      // The room's screen drives real media, not just presence flags.
      final screens = File('lib/screens/communities.dart').readAsStringSync();
      expect(screens, contains('.joinRoom(widget.communityId'));
      expect(screens, contains('.leaveRoom()'));
      expect(screens, contains('toggleScreenShare'));
      expect(screens, contains('enableCamera'));
      // And startup binds the two together.
      final mainSrc = File('lib/main.dart').readAsStringSync();
      expect(mainSrc, contains('RoomMedia.instance.send'));
      expect(mainSrc, contains('onRoomSignal'));
      expect(mainSrc, contains('RoomMedia.instance.bind()'));
      // The 1:1 call runs the same clarity profile.
      final media = File('lib/state/call_media.dart').readAsStringSync();
      expect(media, contains('CallQuality.micConstraints'));
      expect(media, contains('CallQuality.tuneOpus'));
    });

    test('the adaptive bitrate backs off hard and recovers slowly', () {
      final abr =
          AdaptiveBitrate(floor: 250000, ceiling: 2500000, start: 1200000);
      // Real loss: multiplicative decrease, and the change is reported so
      // the caller re-applies it to the senders.
      expect(abr.sample(0.10), isTrue);
      expect(abr.rate, 840000);
      expect(abr.sample(0.10), isTrue);
      expect(abr.rate, lessThan(840000));
      // It can be beaten down only to the floor.
      for (var i = 0; i < 20; i++) {
        abr.sample(0.5);
      }
      expect(abr.rate, 250000);
      expect(abr.sample(0.5), isFalse,
          reason: 'at the floor there is nothing left to change');
      // Clean windows earn additive raises, capped at the ceiling.
      expect(abr.sample(0.0), isTrue);
      expect(abr.rate, 350000);
      for (var i = 0; i < 100; i++) {
        abr.sample(0.0);
      }
      expect(abr.rate, 2500000);
      // The gray zone between thresholds changes nothing.
      expect(abr.sample(0.03), isFalse);
    });

    test('a relayed call is held to a cheaper video cap', () {
      // A relayed byte is a byte somebody pays for, and video is the whole
      // bill. Congestion control alone would never bring it down: a relayed
      // link is usually perfectly capable of the full rate, so the link is
      // not the thing being answered here — the invoice is.
      final abr =
          AdaptiveBitrate(floor: 250000, ceiling: 2500000, start: 2500000);
      expect(abr.limit, 2500000);

      // Going onto the relay pulls the rate down NOW, and says it did, so
      // the caller re-applies it. Waiting for the next loss sample would
      // mean waiting forever on a clean link.
      expect(abr.setLimit(CallMedia.relayVideoBitrate), isTrue);
      expect(abr.rate, CallMedia.relayVideoBitrate);
      expect(abr.limit, CallMedia.relayVideoBitrate);

      // Clean windows may no longer climb past the cheap cap...
      for (var i = 0; i < 100; i++) {
        abr.sample(0.0);
      }
      expect(abr.rate, CallMedia.relayVideoBitrate,
          reason: 'a clean relayed link must not creep back to the ceiling');

      // ...but the link can still adapt DOWNWARD underneath it, which is why
      // the cap sits well above the floor.
      expect(abr.sample(0.10), isTrue);
      expect(abr.rate, lessThan(CallMedia.relayVideoBitrate));
      expect(abr.rate, greaterThanOrEqualTo(250000));

      // An ICE restart can move a call back off the relay, and the cap has to
      // follow it both ways.
      expect(abr.setLimit(abr.ceiling), isFalse,
          reason: 'raising the cap alone does not raise the rate');
      for (var i = 0; i < 100; i++) {
        abr.sample(0.0);
      }
      expect(abr.rate, 2500000);

      // The cheap cap is a real saving and still a usable picture — above the
      // floor, and well under the normal ceiling.
      expect(CallMedia.relayVideoBitrate, greaterThan(250000));
      expect(CallMedia.relayVideoBitrate, lessThan(2500000 ~/ 3));

      // And it is actually wired to the path the call took, not set once.
      final media = File('lib/state/call_media.dart').readAsStringSync();
      expect(media, contains("mediaPath.value == 'relay'"));
      expect(media, contains('relayVideoBitrate'));
    });

    test('quality bars are the worse of loss and latency', () {
      // Loss alone called a 500 ms link perfect; a phone call at 500 ms is
      // not a good phone call.
      expect(CallMedia.qualityFor(0.0), 3);
      expect(CallMedia.qualityFor(0.0, rttMs: 500), 1);
      expect(CallMedia.qualityFor(0.0, rttMs: 300), 2);
      expect(CallMedia.qualityFor(0.10, rttMs: 50), 1,
          reason: 'good latency cannot buy back heavy loss');
      expect(CallMedia.qualityFor(0.03, rttMs: 300), 2);
    });

    test('a dead link redials itself — on both call shapes', () {
      // 1:1: CallMedia asks, CallService restarts, and only the original
      // caller does — a failure both ends see must not collide offers.
      final media = File('lib/state/call_media.dart').readAsStringSync();
      expect(media, contains('onNeedsIceRestart'));
      expect(media, contains("'iceRestart': true"));
      final service = File('lib/state/call_service.dart').readAsStringSync();
      expect(service, contains('restartIce'));
      expect(service, contains('CallDirection.outgoing'),
          reason: 'exactly one side may redial');
      expect(File('lib/main.dart').readAsStringSync(),
          contains('onNeedsIceRestart'));
      // Mesh: the pair's initiator redials its own dead leg.
      final room = File('lib/state/room_media.dart').readAsStringSync();
      expect(room, contains('_restartPeer'));
      expect(room, contains("'iceRestart': true"));
      // And a TCP TURN path exists for UDP-swallowing networks.
      expect(media, contains('transport=tcp'));
    });

    test('the speaking ring is voice, with a hold against flicker', () {
      expect(CallQuality.audible(0.2), isTrue);
      expect(CallQuality.audible(0.001), isFalse,
          reason: 'noise floor must not light the ring');
      expect(CallQuality.audible(null), isFalse);
      // The room reads real levels when media is live and says so.
      final screens = File('lib/screens/communities.dart').readAsStringSync();
      expect(screens, contains('amSpeaking'));
      expect(screens, contains('isSpeaking(o.digits)'));
      final room = File('lib/state/room_media.dart').readAsStringSync();
      expect(room, contains('audioLevel'));
      expect(room, contains('_speechHold'),
          reason: 'the gap between two words must not flicker the ring');
    });

    test('iOS gets a real call audio session, and rooms play out loud', () {
      // The knob most WebRTC apps forget: Apple's own voice pipeline under
      // WebRTC's, earpiece for voice calls, speaker for video and rooms.
      final quality = File('lib/state/call_quality.dart').readAsStringSync();
      expect(quality, contains('setAppleAudioIOMode'));
      final media = File('lib/state/call_media.dart').readAsStringSync();
      expect(media, contains('configureAudioSession(speaker: video)'),
          reason: 'a voice call belongs on the earpiece, video on speaker');
      expect(media, contains('configureAudioSession(speaker: true)'),
          reason: 'a camera turning on mid-call moves to the speaker');
      final room = File('lib/state/room_media.dart').readAsStringSync();
      expect(room, contains('configureAudioSession(speaker: speaker)'),
          reason: 'the room routes by what it is serving');
      expect(room, contains('speaker: true'),
          reason: 'a voice channel held to the ear is a phone call '
              'pretending — channels are speaker-first');
      // Each mesh leg adapts its own bitrate; the room reports its worst
      // link in words instead of silently degrading.
      expect(room, contains('_abrByPeer'));
      expect(room, contains('roomQuality'));
      expect(File('lib/screens/communities.dart').readAsStringSync(),
          contains('poor connection'));
    });

    test('the call check names the missing path instead of guessing', () {
      (String, bool) v(CallProbe p) =>
          CallSelfTest.verdictFor(supported: true, probe: p, error: null);
      // The everything-works case says so and blames nothing.
      final ok = v(const CallProbe(micOk: true, host: 2, srflx: 1, relay: 2));
      expect(ok.$2, isFalse);
      expect(ok.$1, contains('can connect'));
      // No relay is THE "calls sometimes fail" diagnosis: fine on Wi-Fi,
      // dead between two phones on cellular.
      final noRelay =
          v(const CallProbe(micOk: true, host: 2, srflx: 1, relay: 0));
      expect(noRelay.$2, isTrue);
      expect(noRelay.$1, contains('cellular'));
      expect(noRelay.$1, contains('TURN'));
      // A dead mic outranks the network: a call without one is text.
      final noMic =
          v(const CallProbe(micOk: false, host: 2, srflx: 1, relay: 2));
      expect(noMic.$2, isTrue);
      expect(noMic.$1.toLowerCase(), contains('microphone'));
      // No sockets at all is its own sentence, not a TURN complaint.
      final dead = v(const CallProbe(micOk: true, host: 0, srflx: 0, relay: 0));
      expect(dead.$2, isTrue);
      expect(dead.$1, contains('socket'));

      // And the candidate classifier reads real ICE lines.
      expect(
          CallSelfTest.candidateType(
              'candidate:1 1 udp 2122260223 192.168.1.5 54321 typ host'),
          'host');
      expect(
          CallSelfTest.candidateType(
              'candidate:2 1 udp 1686052607 88.1.2.3 6000 typ srflx '
              'raddr 192.168.1.5 rport 54321'),
          'srflx');
      expect(
          CallSelfTest.candidateType(
              'candidate:3 1 udp 41885439 44.5.6.7 3478 typ relay '
              'raddr 88.1.2.3 rport 6000'),
          'relay');
      expect(CallSelfTest.candidateType(null), isNull);

      // The whole report runs from an injected probe — no network.
      CallSelfTest.debugProbe =
          () async => const CallProbe(micOk: true, host: 1, srflx: 1, relay: 0);
      addTearDown(() => CallSelfTest.debugProbe = null);
      // And the settings screen offers it next to the push check.
      expect(File('lib/screens/settings_screen.dart').readAsStringSync(),
          contains('Check call setup'));
    });

    test('mesh renegotiation cannot glare: only the initiator offers', () {
      final room = File('lib/state/room_media.dart').readAsStringSync();
      // The non-initiator asks for a round instead of offering into a
      // possible head-on collision; one round renegotiates both directions.
      expect(room, contains("kind: 'renegreq'"));
      final reneg = room.substring(room.indexOf('Future<void> _renegotiate'));
      expect(reneg.substring(0, reneg.indexOf('try {')),
          contains('initiates(_myDigits, digits)'),
          reason: 'the role check must come before any offer is created');
      // And a share that moves no frames stops itself in rooms too, with
      // the badge coming back off for everyone.
      expect(room, contains('_verifyShareMovesFrames'));
      expect(File('lib/screens/communities.dart').readAsStringSync(),
          contains('_onShareFailure'));
    });

    test(
        'the mesh has a stated ceiling, and every device picks the same '
        'room', () {
      // Under the cap: everyone connects to everyone.
      expect(RoomMedia.legsFor({'2', '3'}, '1'), {'2', '3'});
      // Over it: the first eight by digit-sort mesh; the rest are presence
      // only — and every member computes the SAME subset, or each phone
      // would connect to a different eight.
      final present = {for (var i = 2; i <= 10; i++) '$i'.padLeft(2, '0')};
      final legs = RoomMedia.legsFor(present, '01');
      expect(legs.length, RoomMedia.maxRoomSize - 1);
      expect(legs, isNot(contains('10')),
          reason: 'the sorted overflow member stays presence-only');
      // A member outside the first eight holds no legs at all rather than
      // half a room.
      expect(RoomMedia.legsFor({for (var i = 1; i <= 9; i++) '0$i'}, '99'),
          isEmpty);
      // And the join path refuses a full room BEFORE presence lists a
      // member nobody can hear.
      final screens = File('lib/screens/communities.dart').readAsStringSync();
      expect(screens, contains('full for voice'));
      final room = File('lib/state/room_media.dart').readAsStringSync();
      expect(room, contains('maxRoomSize'));
    });

