    test('server posts get a durable sealed copy — and chats never do', () {
      final relay = File('lib/relay/relay_service.dart').readAsStringSync();
      // Stored under the community SECRET, not a sender-key chain: chain
      // keys die on use, and a stored listing must open for any member on
      // any day.
      final store = relay.substring(relay.indexOf('_storeCommunityPost('));
      expect(store.substring(0, store.indexOf('sendFeedPost')),
          contains('E2eCrypto.encrypt(secret'));
      // Post → upsert; delete → row dies; fetch feeds the normal arrival
      // path on start AND on pull-to-refresh.
      expect(relay, contains('_storeCommunityPost(community, post)'));
      expect(relay, contains('_deleteCommunityPost(communityId, postId)'));
      expect(relay, contains('fetchCommunityPosts'));
      final del = relay.substring(relay.indexOf('Future<void> sendFeedDelete'));
      expect(del.substring(0, del.indexOf(';')), isNot(contains('mailbox')));
      // The one thing that must never gain a durable server copy: the
      // messages table name does not exist, and the store function only
      // ever takes a FeedPost.
      expect(relay, isNot(contains("'messages'")));
      expect(store, contains('FeedPost post'));
      // And the SQL ships + is exercised by the gate.
      expect(File('docs/community_posts.sql').existsSync(), isTrue);
      expect(File('tool/check_sql.sh').readAsStringSync(),
          contains('community_posts.sql'));
    });

    test('the call screen can say whether the relay is carrying the call', () {
      // The selection order the pure picker must honor: the transport's
      // chosen pair, then a nominated succeeded pair, then any succeeded.
      List<(String, String, Map<dynamic, dynamic>)> reports(
              {String? selectedId}) =>
          [
            ('local-candidate', 'lc_host', {'candidateType': 'host'}),
            ('local-candidate', 'lc_relay', {'candidateType': 'relay'}),
            (
              'candidate-pair',
              'pair_direct',
              {'state': 'succeeded', 'localCandidateId': 'lc_host'}
            ),
            (
              'candidate-pair',
              'pair_relay',
              {
                'state': 'succeeded',
                'nominated': true,
                'localCandidateId': 'lc_relay'
              }
            ),
            if (selectedId != null)
              ('transport', 't1', {'selectedCandidatePairId': selectedId}),
          ];
      expect(CallMedia.selectedLocalType(reports(selectedId: 'pair_direct')),
          'host',
          reason: 'the transport\'s word outranks nomination');
      expect(CallMedia.selectedLocalType(reports()), 'relay',
          reason: 'without a transport report, the nominated pair decides');
      expect(CallMedia.selectedLocalType(const []), isNull);

      // Neither a transport report nor a nomination — the branch real devices
      // actually land in, since both fields are optional. "Any succeeded
      // pair" was a coin toss: a DIRECT call very often has a succeeded relay
      // pair sitting beside the host one, so an arbitrary pick reported
      // "via relay" for a call going straight out. The pair carrying the
      // media is the one that decides.
      List<(String, String, Map<dynamic, dynamic>)> unnominated({
        required int hostBytes,
        required int relayBytes,
      }) =>
          [
            ('local-candidate', 'lc_host', {'candidateType': 'host'}),
            ('local-candidate', 'lc_relay', {'candidateType': 'relay'}),
            (
              'candidate-pair',
              'pair_relay',
              {
                'state': 'succeeded',
                'localCandidateId': 'lc_relay',
                'bytesReceived': relayBytes,
                'bytesSent': 0,
              }
            ),
            (
              'candidate-pair',
              'pair_direct',
              {
                'state': 'succeeded',
                'localCandidateId': 'lc_host',
                'bytesReceived': hostBytes,
                'bytesSent': 0,
              }
            ),
          ];
      expect(
          CallMedia.selectedLocalType(
              unnominated(hostBytes: 90000, relayBytes: 0)),
          'host',
          reason: 'the media is on the direct pair, so it is not "via relay"');
      expect(
          CallMedia.selectedLocalType(
              unnominated(hostBytes: 0, relayBytes: 90000)),
          'relay',
          reason: 'and when the relay really is carrying it, it says so');
      // Nothing moving yet (the first seconds, or a platform with no byte
      // counts) still answers something rather than nothing.
      expect(
          CallMedia.selectedLocalType(unnominated(hostBytes: 0, relayBytes: 0)),
          isNotNull);

      // And the screen says it, in words a person can act on.
      expect(File('lib/screens/call_screen.dart').readAsStringSync(),
          contains('via relay'));
    });

    test('a missed hang-up cannot zombie the call', () {
      final service = File('lib/state/call_service.dart').readAsStringSync();
      // The far side's 'end' is queued to the mailbox; a dead media link
      // fetches it NOW instead of at the next app-open, and a link still
      // dead after the restart window ends the call locally.
      final watchdog = service.substring(service.indexOf('onMediaState'));
      final body = watchdog.substring(0, watchdog.indexOf('restartIce'));
      expect(body, contains('fetchMailbox'));
      expect(body, contains('end();'));
      expect(
          File('lib/main.dart').readAsStringSync(), contains('onMediaState'));
    });

