    test('the unit picker enforces every rule of the stance', () {
      String? unit({
        bool web = false,
        TargetPlatform platform = TargetPlatform.iOS,
        bool release = true,
        String ios = '',
        String android = '',
      }) =>
          AdService.bannerUnitFor(
            isWeb: web,
            platform: platform,
            releaseMode: release,
            configuredIos: ios,
            configuredAndroid: android,
          );
      // Release with no ids: NOTHING — not placeholders, not test ads.
      expect(unit(), isNull);
      // A configured id turns ads on for its platform only.
      expect(unit(ios: 'ca-app-pub-x/1'), 'ca-app-pub-x/1');
      expect(unit(platform: TargetPlatform.android, ios: 'ca-app-pub-x/1'),
          isNull);
      // Debug uses Google's labeled test units, so wiring is verifiable
      // without an account.
      expect(unit(release: false), contains('3940256099942544'));
      // The web build never shows ads, configured or not.
      expect(unit(web: true, ios: 'ca-app-pub-x/1'), isNull);
      // And every request the service makes is non-personalized — the
      // whole privacy story in one flag.
      final src = File('lib/ads/ad_service.dart').readAsStringSync();
      expect(src, contains('nonPersonalizedAds: true'));
      // The iOS side has the SDK's required plist key.
      expect(File('ios/Runner/Info.plist').readAsStringSync(),
          contains('GADApplicationIdentifier'));
      // And the build pipeline can inject the real unit id.
      expect(File('codemagic.yaml').readAsStringSync(),
          contains('ADMOB_BANNER_IOS'));
    });

    test('app-ads.txt rides the web deploy, exactly as AdMob dictated', () {
      // AdMob's crawler compares this line byte-for-byte against the
      // account ("your details don't match" is what a drifted copy looks
      // like). Everything in web/ is copied verbatim into build/web, so
      // the deployed site serves it at /app-ads.txt.
      expect(File('web/app-ads.txt').readAsStringSync().trim(),
          'google.com, pub-9111642557916743, DIRECT, f08c47fec0942fa0');
    });

    test('the native unit picker holds the same line', () {
      String? unit({
        bool web = false,
        TargetPlatform platform = TargetPlatform.iOS,
        bool release = true,
        bool testAds = false,
        String ios = '',
        String android = '',
      }) =>
          AdService.nativeUnitFor(
            isWeb: web,
            platform: platform,
            releaseMode: release,
            testAds: testAds,
            configuredIos: ios,
            configuredAndroid: android,
          );
      expect(unit(), isNull); // release + no id = nothing
      expect(unit(ios: 'ca-app-pub-x/9'), 'ca-app-pub-x/9');
      expect(unit(platform: TargetPlatform.android, ios: 'ca-app-pub-x/9'),
          isNull);
      expect(unit(release: false), contains('3940256099942544'));
      expect(unit(web: true, ios: 'ca-app-pub-x/9'), isNull);
    });

    test('ADMOB_TEST_ADS lets the owner see labeled test ads on TestFlight',
        () {
      // The one hole in "release shows nothing without ids": real fill is
      // impossible until AdMob finishes verifying the account, so the owner
      // could never SEE the placement work on a real phone. The flag is an
      // explicit opt-in, uses only Google's clearly-labeled test units, and
      // a configured real id always beats it.
      expect(
          AdService.bannerUnitFor(
              isWeb: false,
              platform: TargetPlatform.iOS,
              releaseMode: true,
              testAds: true),
          contains('3940256099942544'));
      expect(
          AdService.nativeUnitFor(
              isWeb: false,
              platform: TargetPlatform.iOS,
              releaseMode: true,
              testAds: true),
          contains('3940256099942544'));
      // A real id wins over the flag — forgetting to remove it can't hide
      // real ads once verification lands.
      expect(
          AdService.bannerUnitFor(
              isWeb: false,
              platform: TargetPlatform.iOS,
              releaseMode: true,
              testAds: true,
              configuredIos: 'ca-app-pub-x/1'),
          'ca-app-pub-x/1');
      // Web stays adless even with the flag.
      expect(
          AdService.bannerUnitFor(
              isWeb: true,
              platform: TargetPlatform.iOS,
              releaseMode: true,
              testAds: true),
          isNull);
      // And the pipeline can carry it (default false when unset).
      final yaml = File('codemagic.yaml').readAsStringSync();
      expect(
          RegExp(r'ADMOB_TEST_ADS=\$\{ADMOB_TEST_ADS:-false\}')
              .allMatches(yaml)
              .length,
          3);
    });

    test('native ads are dealt into the timeline, never as filler', () {
      // Ads off: the layout is just the posts.
      expect(AdService.timelineWithAds(5, adsEnabled: false), [0, 1, 2, 3, 4]);
      // One ad after every 8 posts...
      expect(AdService.timelineWithAds(17, adsEnabled: true),
          [0, 1, 2, 3, 4, 5, 6, 7, -1, 8, 9, 10, 11, 12, 13, 14, 15, -2, 16]);
      // ...but never as the trailing element: a feed of exactly 8 posts
      // ends on a post, not an ad.
      expect(AdService.timelineWithAds(8, adsEnabled: true),
          [0, 1, 2, 3, 4, 5, 6, 7]);
      // And a short feed carries no ads at all.
      expect(AdService.timelineWithAds(3, adsEnabled: true), [0, 1, 2]);
      // The feed really uses it, and the card really exists there.
      final feed =
          File('lib/screens/public_feed_screen.dart').readAsStringSync();
      expect(feed, contains('timelineWithAds'));
      expect(feed, contains('NativeAdCard'));
    });

    test('the build pipeline passes native ids and survives a sloppy paste',
        () {
      final yaml = File('codemagic.yaml').readAsStringSync();
      // The native unit reaches all three build workflows.
      expect(
          RegExp(r'ADMOB_NATIVE_IOS=\$ADMOB_NATIVE_IOS')
              .allMatches(yaml)
              .length,
          3);
      // Every UI-sourced value is stripped of whitespace before it becomes
      // a flag — a trailing newline once made flutter read the whole
      // --dart-define as the build target and killed the archive.
      for (final v in [
        'MAPBOX_TOKEN',
        'KLIPY_API_KEY',
        'ADMOB_BANNER_IOS',
        'ADMOB_NATIVE_IOS',
      ]) {
        final strip = '$v="\$(printf \'%s\' "\${$v:-}" | tr -d \'[:space:]\')"';
        expect(RegExp(RegExp.escape(strip)).allMatches(yaml).length, 3,
            reason: '$v must be whitespace-stripped in all three workflows');
      }
    });
  });

