  group('Reviewer demo account and random identities', () {
    tearDown(() {
      Session.instance.resetForTest();
      IdentityVerification.debugGateOverride = null;
      PaymentService.instance.setTestMode(false);
    });

    test('the reviewer account is recognized by its digits alone', () {
      expect(ReviewerMode.active, isFalse, reason: 'nobody signed in');
      Session.instance.signInForTest(phone: '+1 500 555 0006');
      expect(ReviewerMode.active, isTrue);
      Session.instance.signInForTest(phone: '+1 555 0100');
      expect(ReviewerMode.active, isFalse,
          reason: 'a real account must gain nothing from this');
    });

    test('the reviewer passes the ID gate and is pinned to the sandbox', () {
      // The gate is ON (as in a server build) and the account unverified —
      // the exact state an App Review tester arrives in. Reset FIRST: it
      // clears the override it would otherwise erase.
      IdentityVerification.instance.resetForTest();
      IdentityVerification.debugGateOverride = true;
      PaymentService.instance.setTestMode(false); // a clean baseline
      Session.instance.signInForTest(phone: '+1 555 0100');
      expect(IdentityVerification.instance.allowsTrusted, isFalse);
      expect(PaymentService.instance.testMode.value, isFalse);

      Session.instance.signInForTest(phone: '+1 500 555 0006');
      expect(IdentityVerification.instance.allowsTrusted, isTrue,
          reason: 'a reviewer will not photograph a passport for a demo');
      // Test mode reads on, and CANNOT be turned off for this account —
      // exploring every screen must never reach a real charge.
      expect(PaymentService.instance.testMode.value, isTrue);
      PaymentService.instance.setTestMode(false);
      expect(PaymentService.instance.testMode.value, isTrue);

      // And the pin is the reviewer's alone: a real account on the same
      // device reads its own stored setting.
      Session.instance.signInForTest(phone: '+1 555 0100');
      expect(PaymentService.instance.testMode.value, isFalse);
    });

    test('random identities are valid, presentable, and vary', () {
      final u = RandomIdentity.username(math.Random(7));
      expect(AccountService.isValidUsername(u), isTrue,
          reason: 'the mint must pass the same validation typed handles do');
      expect(u, matches(RegExp(r'^[a-z]+[0-9]{2}$')));
      final n = RandomIdentity.displayName(math.Random(7));
      expect(n.trim(), isNotEmpty);
      expect(n.split(' ').length, 2);
      expect(n[0], n[0].toUpperCase());
      // Different randomness, different identity — the point of random.
      expect(RandomIdentity.username(math.Random(1)),
          isNot(RandomIdentity.username(math.Random(2))));
      // And the sign-up paths actually reach for it when fields are blank.
      final login =
          File('lib/screens/auth/phone_login_screen.dart').readAsStringSync();
      expect(RegExp('RandomIdentity').allMatches(login).length,
          greaterThanOrEqualTo(5),
          reason: 'skip-username, claim, local and numberless sign-ups all '
              'mint blanks');
    });

    testWidgets('a different account starts blank — nothing carries over',
        (tester) async {
      Session.instance.lastAccount = const AppUser(
        id: '+1 555 0100',
        name: 'Old Name',
        avatarColor: '#E57373',
        about: 'Available',
        phone: '+1 555 0100',
        username: 'oldhandle',
      );
      addTearDown(() {
        Session.instance.lastAccount = null;
        Session.instance.resetForTest();
      });
      await tester.pumpWidget(const MaterialApp(home: PhoneLoginScreen()));
      await tester.pump();
      // The one-tap way back in exists, prefilled — that part is wanted.
      expect(find.textContaining('Continue as Old'), findsOneWidget);

      await tester.tap(find.text('Use a different account'));
      await tester.pumpAndSettle();
      // The previous person's identity must not dress the next account.
      expect(find.text('Old Name'), findsNothing);
      expect(find.text('oldhandle'), findsNothing);
      expect(find.text('555 0100'), findsNothing);
    });
  });

  group('Remembered profiles and the owner\'s team', () {
    test('every account that signs in is remembered, deduped and capped',
        () async {
      SharedPreferences.setMockInitialValues({});
      Session.instance.knownAccounts = [];
      addTearDown(() {
        Session.instance.knownAccounts = [];
        Session.instance.resetForTest();
      });
      AppUser acc(String phone, String name) => AppUser(
          id: phone,
          name: name,
          avatarColor: '#E57373',
          about: '',
          phone: phone);
      for (var i = 1; i <= 7; i++) {
        await Session.instance.rememberAccount(acc('+1 555 010$i', 'P$i'));
      }
      expect(Session.instance.knownAccounts.length, 5,
          reason: 'capped — a login screen is not an archive');
      expect(Session.instance.knownAccounts.first.name, 'P7',
          reason: 'most recent first');
      // Re-signing an old one moves it up rather than duplicating it.
      await Session.instance.rememberAccount(acc('+1 555 0105', 'P5'));
      expect(Session.instance.knownAccounts.first.name, 'P5');
      expect(Session.instance.knownAccounts.where((a) => a.name == 'P5').length,
          1);
      // And forgetting removes exactly one.
      await Session.instance.forgetAccount('+1 555 0105');
      expect(
          Session.instance.knownAccounts.any((a) => a.name == 'P5'), isFalse);
    });

    test('the profile list survives the account-switch wipe', () {
      expect(AccountWipe.keepKeys, contains('known_accounts_v1'),
          reason: 'remembering who signed in here is device history, like '
              'last_account_v1 — the wipe erases their DATA, not the list');
    });

    testWidgets('the welcome screen offers every profile, one tap each',
        (tester) async {
      const ada = AppUser(
          id: '+1 555 0100',
          name: 'Ada Lovelace',
          avatarColor: '#E57373',
          about: '',
          phone: '+1 555 0100',
          username: 'adal');
      const grace = AppUser(
          id: '+1 555 0200',
          name: 'Grace Hopper',
          avatarColor: '#64B5F6',
          about: '',
          phone: '+1 555 0200',
          username: 'graceh');
      Session.instance.lastAccount = ada;
      Session.instance.knownAccounts = [ada, grace];
      addTearDown(() {
        Session.instance.lastAccount = null;
        Session.instance.knownAccounts = [];
        Session.instance.resetForTest();
      });
      await tester.pumpWidget(const MaterialApp(home: PhoneLoginScreen()));
      await tester.pump();

      expect(find.textContaining('Continue as Ada'), findsOneWidget);
      expect(find.text('Grace Hopper'), findsOneWidget,
          reason: 'the second profile is offered too');

      // Tapping the other profile signs into IT (local mode — the verified
      // build sends its code instead; only the typing is ever saved).
      await tester.tap(find.text('Grace Hopper'));
      await tester.pump();
      await tester.pump(const Duration(milliseconds: 100));
      expect(Session.instance.user.value?.name, 'Grace Hopper');
      expect(Session.instance.user.value?.username, 'graceh');
    });

    test('signing back into the same account keeps the profile', () async {
      // The wipe's promise is 'same account returning keeps everything' —
      // but signIn rebuilt a BARE profile: about back to 'Available', the
      // avatar look, pronouns, link and location gone, on every return.
      SharedPreferences.setMockInitialValues({});
      Session.instance.knownAccounts = [];
      Session.instance.lastAccount = null;
      addTearDown(() {
        Session.instance.knownAccounts = [];
        Session.instance.lastAccount = null;
        Session.instance.resetForTest();
        AppState.resetForTest();
      });
      await Session.instance
          .signIn(phone: '+1 555 0177', name: 'Ada', username: 'ada');
      await Session.instance.updateProfile(
        name: 'Ada',
        about: 'Building',
        emoji: '🦊',
        pronouns: 'she/her',
        link: 'ada.dev',
        avatarColor2: '#64B5F6',
        bannerColor: '#BA68C8',
        location: 'Toronto',
      );
      await Session.instance.signOut();
      await Session.instance
          .signIn(phone: '+1 555 0177', name: '', username: '');
      final me = Session.instance.user.value!;
      expect(me.name, 'Ada');
      expect(me.about, 'Building');
      expect(me.emoji, '🦊');
      expect(me.pronouns, 'she/her');
      expect(me.link, 'ada.dev');
      expect(me.avatarColor2, '#64B5F6');
      expect(me.bannerColor, '#BA68C8');
      expect(me.location, 'Toronto');
      expect(me.username, 'ada',
          reason: 'the handle survives a blank sign-in field too');

      // A DIFFERENT account still starts factory-fresh.
      await Session.instance
          .signIn(phone: '+1 555 0288', name: '', username: '');
      final other = Session.instance.user.value!;
      // A fresh account has no bio at all now — the status line it used to
      // start with was a sentence the app wrote about a stranger.
      expect(other.about, isEmpty);
      expect(other.emoji, '');
      expect(other.location, '');
    });

    test('deleting the account forgets THAT profile, keeps the others',
        () async {
      // signOut re-remembers the leaving account and the erase clears only
      // its data — the remembered list would still offer one-tap entry into
      // the deleted account. So the flow forgets it. But ONLY it: the other
      // accounts on a shared device must stay one-tap signable.
      SharedPreferences.setMockInitialValues({});
      Session.instance.knownAccounts = [];
      addTearDown(() {
        Session.instance.knownAccounts = [];
        Session.instance.resetForTest();
      });
      await Session.instance.rememberAccount(const AppUser(
          id: 'x', name: 'X', avatarColor: '#000000', phone: '+1 555 0100'));
      await Session.instance.rememberAccount(const AppUser(
          id: 'y', name: 'Y', avatarColor: '#000000', phone: '+1 555 0200'));
      expect(Session.instance.knownAccounts.length, 2);
      await Session.instance.forgetAccount('+1 555 0100');
      expect(
          Session.instance.knownAccounts.map((a) => a.phone), ['+1 555 0200'],
          reason: 'only the deleted account is forgotten');
      // And the delete flow actually forgets it, after the erase.
      final src = File('lib/screens/settings_screen.dart').readAsStringSync();
      final erase = src.indexOf('eraseCurrentAccount()');
      expect(erase, greaterThan(-1));
      expect(src.indexOf('forgetAccount(phone)', erase), greaterThan(erase),
          reason: 'the erase clears this account; forgetAccount drops it from '
              'the remembered list, leaving the others');
    });

    test('backing out of a one-tap profile clears the resolved phone', () {
      // Tapping a remembered profile resolves its number into
      // _identifierPhone, and _loginPhone prefers it — so after a failed
      // one-tap, a freshly typed number would have had its code sent to
      // the TAPPED account instead. 'Use a different account' must drop it.
      final src =
          File('lib/screens/auth/phone_login_screen.dart').readAsStringSync();
      final blank = src.indexOf('A different account starts BLANK');
      expect(blank, greaterThan(-1));
      final handler = src.substring(blank, blank + 900);
      expect(handler, contains('_identifierPhone = null'));
      expect(handler, contains("_resolvedName = ''"));
    });

    test('a handle changes once every 30 days; a name changes any time',
        () async {
      SharedPreferences.setMockInitialValues({});
      Session.instance.knownAccounts = [];
      Session.instance.lastAccount = null;
      Session.instance.debugUsernameChangedAt = null;
      addTearDown(() {
        Session.instance.knownAccounts = [];
        Session.instance.lastAccount = null;
        Session.instance.debugUsernameChangedAt = null;
        Session.instance.resetForTest();
        AppState.resetForTest();
      });
      await Session.instance
          .signIn(phone: '+1 555 0166', name: 'Ada', username: 'ada');
      // The FIRST change is free, and starts the clock.
      await Session.instance
          .updateProfile(name: 'Ada', about: 'x', username: 'grace');
      expect(Session.instance.user.value!.username, 'grace');
      expect(Session.instance.usernameCooldownLeft(),
          greaterThan(const Duration(days: 29)));

      // A second change inside the window is refused — including CLEARING,
      // or clear-then-set would dodge the clock — while the name and the
      // rest of the profile stay fully editable.
      await Session.instance
          .updateProfile(name: 'Ada L', about: 'y', username: 'lin');
      expect(Session.instance.user.value!.username, 'grace');
      expect(Session.instance.user.value!.name, 'Ada L');
      expect(Session.instance.user.value!.about, 'y');
      await Session.instance
          .updateProfile(name: 'Ada L', about: 'y', username: '');
      expect(Session.instance.user.value!.username, 'grace');

      // Thirty-one days later the handle is free again.
      Session.instance.debugUsernameChangedAt =
          DateTime.now().subtract(const Duration(days: 31));
      expect(Session.instance.usernameCooldownLeft(), Duration.zero);
      await Session.instance
          .updateProfile(name: 'Ada L', about: 'y', username: 'lin');
      expect(Session.instance.user.value!.username, 'lin');

      // And the edit screen locks the field rather than letting Save
      // quietly refuse.
      final editor =
          File('lib/screens/edit_profile_screen.dart').readAsStringSync();
      expect(editor, contains('usernameCooldownLeft()'));
      expect(editor, contains('enabled: !usernameLocked'));
    });

    test('the owner\'s new powers exist, gated and server-checked', () {
      // Takedown: in the function, with the author outranked; in the app,
      // drawn only for moderators and never on your own post.
      final act =
          File('supabase/functions/moderation-act/index.ts').readAsStringSync();
      expect(act, contains('"takedown"'));
      expect(act, contains('outranked'));
      final feed =
          File('lib/screens/public_feed_screen.dart').readAsStringSync();
      expect(feed, contains('canModerate'));
      expect(feed, contains('takedownPublicPost'));

      // Roles: owner-only in the function — never assignable to 'owner',
      // never self, never another owner.
      final roles =
          File('supabase/functions/roles-set/index.ts').readAsStringSync();
      expect(roles, contains('owner_only'));
      expect(roles, contains('cannot_change_self'));
      expect(roles, contains('cannot_touch_owner'));
      expect(roles, isNot(contains('role !== "owner" &&')),
          reason: 'owner must not be an assignable role');
      // The client refuses to even ask for owner.
      final store =
          File('lib/state/platform_moderation.dart').readAsStringSync();
      expect(store, contains('role == PlatformRole.owner) return false'));
      // And the Team tab is drawn for the owner alone.
      final admin = File('lib/screens/admin_screen.dart').readAsStringSync();
      expect(admin, contains('store.isOwner'));
      expect(admin, contains('_teamList'));
    });
  });

