  group('Custom bubble color', () {
    Color outgoingBubbleColor(WidgetTester tester) {
      final containers = tester.widgetList<Container>(
        find.descendant(
          of: find.byType(MessageBubble),
          matching: find.byType(Container),
        ),
      );
      final bubble = containers.firstWhere(
        (c) =>
            c.decoration is BoxDecoration &&
            (c.decoration as BoxDecoration).color != null,
      );
      return (bubble.decoration as BoxDecoration).color!;
    }

    testWidgets('anyone can pick and reset a bubble color — no paywall',
        (tester) async {
      AppState.setVerified(false); // no longer gated
      await tester.pumpWidget(
        const MaterialApp(home: ChatsSettingsScreen()),
      );
      await tester.pumpAndSettle();

      // The perk is free now: no lock, no upgrade copy.
      expect(find.text('Chat bubble color'), findsOneWidget);
      expect(find.text('An Okay Pro perk'), findsNothing);
      expect(find.byIcon(Icons.lock_outline), findsNothing);

      await tester.tap(find.text('Chat bubble color'));
      await tester.pumpAndSettle();

      // The picker sheet opens.
      expect(find.text('Bubble color'), findsOneWidget);
      // Tap the Pro purple swatch (third in the palette).
      final swatch = find.descendant(
        of: find.byType(BottomSheet),
        matching: find.byType(GestureDetector),
      );
      await tester.tap(swatch.at(2));
      await tester.pumpAndSettle();
      expect(AppState.bubbleColor.value, const Color(0xFF7A5CFF));

      // Reopen and reset to default.
      await tester.tap(find.text('Chat bubble color'));
      await tester.pumpAndSettle();
      await tester.tap(find.text('Reset to default green'));
      await tester.pumpAndSettle();
      expect(AppState.bubbleColor.value, isNull);
    });

    testWidgets('outgoing bubble honors the custom color', (tester) async {
      AppState.bubbleColor.value = const Color(0xFFEB4B7E);
      await tester.pumpWidget(
        MaterialApp(
          home: Scaffold(
            body: MessageBubble(
              message: Message(
                id: 'm1',
                text: 'hello',
                time: DateTime(2020, 1, 1, 10),
                isMe: true,
              ),
            ),
          ),
        ),
      );
      await tester.pumpAndSettle();
      expect(outgoingBubbleColor(tester), const Color(0xFFEB4B7E));
    });

    testWidgets('incoming bubble ignores the custom color', (tester) async {
      AppState.bubbleColor.value = const Color(0xFFEB4B7E);
      await tester.pumpWidget(
        MaterialApp(
          home: Scaffold(
            body: MessageBubble(
              message: Message(
                id: 'm2',
                text: 'hi there',
                time: DateTime(2020, 1, 1, 10),
                isMe: false,
              ),
            ),
          ),
        ),
      );
      await tester.pumpAndSettle();
      expect(outgoingBubbleColor(tester), isNot(const Color(0xFFEB4B7E)));
    });

    testWidgets(
        'reply quote inside a bubble takes the bubble\'s own text color, '
        'not raw theme brightness', (tester) async {
      // A light custom bubble color in a DARK theme is exactly the case a
      // theme-brightness-only color pick gets backwards: the bubble itself
      // renders near-black text (computeLuminance > 0.5), but plain `isDark`
      // would still pick light/white70 text — unreadable on the light
      // bubble underneath. This is the VoiceNoteBubble bug class, in the
      // reply-quote widget instead.
      AppState.bubbleColor.value = const Color(0xFFF5D0C5); // light, warm
      await tester.pumpWidget(
        MaterialApp(
          theme: ThemeData.dark(),
          home: Scaffold(
            body: MessageBubble(
              message: Message(
                id: 'm3',
                text: 'sounds good',
                time: DateTime(2020, 1, 1, 10),
                isMe: true,
                replyTo: const ReplyInfo(
                  senderName: 'Alex',
                  text: 'are we still on for lunch?',
                  isMe: false,
                ),
              ),
            ),
          ),
        ),
      );
      await tester.pumpAndSettle();

      final replyTexts = tester.widgetList<Text>(
        find.descendant(
          of: find.byType(MessageBubble),
          matching: find.text('are we still on for lunch?'),
        ),
      );
      final senderTexts = tester.widgetList<Text>(
        find.descendant(
          of: find.byType(MessageBubble),
          matching: find.text('Alex'),
        ),
      );
      expect(replyTexts.length, 1);
      expect(senderTexts.length, 1);

      const ink = Color(0xFF0F1419);
      // Bubble luminance > 0.5, so the bubble itself picks near-black text —
      // the reply quote must match, never the theme's light-on-dark colors.
      expect((senderTexts.first.style!.color!).toARGB32(), ink.toARGB32());
      final metaColor = replyTexts.first.style!.color!;
      expect(metaColor.toARGB32(), isNot(Colors.white70.toARGB32()));
      expect(metaColor.toARGB32(), isNot(Colors.black54.toARGB32()));
    });
  });

  group('Weighted group polls (Decision Voting)', () {
    Message pollMessage({required Map<String, int> votesBy}) => Message(
          id: 'poll1',
          text: '',
          time: DateTime(2020, 1, 1, 10),
          isMe: false,
          isPoll: true,
          pollQuestion: 'Pizza night?',
          pollOptions: const ['Yes', 'No'],
          pollVotes: const [0, 0], // unweighted fallback — unused when weighted
          pollVotesBy: votesBy,
        );

    testWidgets(
        'a group poll with a weightFor shows the weighted tally and '
        'names the rule, not a plain vote count', (tester) async {
      await tester.pumpWidget(
        MaterialApp(
          home: Scaffold(
            body: MessageBubble(
              message: pollMessage(
                  votesBy: const {'admin': 0, 'alice': 1, 'bob': 1}),
              onPollVote: (_) {},
              pollVoteWeight: (voter) => voter == 'admin' ? 2 : 1,
            ),
          ),
        ),
      );
      await tester.pumpAndSettle();

      // Admin(2) on Yes vs alice+bob(1 each) on No — weighted 2-2, not the
      // 1-2 a plain headcount would show.
      expect(find.text('50%'), findsNWidgets(2));
      expect(find.text('3 people voted · admin\'s vote counts double'),
          findsOneWidget);
      expect(find.textContaining(' votes'), findsNothing);
    });

    testWidgets(
        'no weightFor (a 1:1 chat) tallies every vote as 1, exactly '
        'as before this existed', (tester) async {
      await tester.pumpWidget(
        MaterialApp(
          home: Scaffold(
            body: MessageBubble(
              message: pollMessage(votesBy: const {'alice': 0, 'bob': 1}),
              onPollVote: (_) {},
              // pollVoteWeight omitted — null.
            ),
          ),
        ),
      );
      await tester.pumpAndSettle();

      // Falls back to the raw (all-zero) pollVotes since weightFor is null —
      // unweighted display is untouched by this feature.
      expect(find.text('0 votes'), findsOneWidget);
    });
  });

  group('Chat list filters', () {
    Future<void> pumpTab(WidgetTester tester) async {
      // The chip bar is hidden by default; reveal it for these tests.
      ChatsTab.filtersVisible.value = true;
      await tester.pumpWidget(
        const MaterialApp(home: Scaffold(body: ChatsTab())),
      );
      await tester.pumpAndSettle();
    }

    testWidgets('filter chips are hidden by default', (tester) async {
      await tester.pumpWidget(
        const MaterialApp(home: Scaffold(body: ChatsTab())),
      );
      await tester.pumpAndSettle();
      // No chip row until it's toggled on from the menu.
      expect(find.text('Unread'), findsNothing);
      expect(find.text('Groups'), findsNothing);
      // The chat list is still shown, unfiltered.
