  group('Feed post actions', () {
    testWidgets('the three engagement icons sit small at the bottom left',
        (t) async {
      // 2026-08-14, the owner's call, reversing "evenly spread". Both feeds
      // draw this one widget, so measuring it once covers both.
      t.view.physicalSize = const Size(390, 844);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      await t.pumpWidget(MaterialApp(
        home: Scaffold(
          body: FeedPostActions(
            replyCount: 2,
            repostCount: 3,
            likeCount: 4,
            liked: false,
            reposted: false,
            onReply: () {},
            onRepost: () {},
            onLike: () {},
            onShare: () {},
          ),
        ),
      ));
      await t.pumpAndSettle();

      Rect rectOf(String tip) => t.getRect(find.byTooltip(tip));
      final reply = rectOf('Reply');
      final repost = rectOf('Repost');
      final like = rectOf('Like');
      final share = rectOf('Copy text');

      // Gathered, not spread: the three sit together in the left half.
      expect(like.left, lessThan(20),
          reason: 'the row does not start at the left edge');
      expect(repost.right, lessThan(195),
          reason: 'the three engagement actions are not gathered left');
      // LIKE · COMMENT · REPOST, in that order — the owner's correction to
      // the order they were first gathered in (2026-08-14). Like leads: it
      // is the one people reach for most and the cheapest to give, so it is
      // the one nearest the thumb.
      expect(reply.left, greaterThan(like.left));
      expect(repost.left, greaterThan(reply.left));
      // And touching-close rather than spread across the card.
      expect(repost.left - like.left, lessThan(150),
          reason: 'they are spread out again');

      // Share is the odd one out and keeps the right end: it sends the post
      // somewhere else rather than acting on it.
      expect(share.left, greaterThan(repost.right + 100),
          reason: 'share should stay at the right end');

      // Smaller glyph, and the touchable area NOT taken down with it: the
      // buttons keep Material's padded tap target, which a first cut of this
      // had switched off with `tapTargetSize: shrinkWrap`.
      final icon = t.widget<Icon>(find
          .descendant(of: find.byTooltip('Like'), matching: find.byType(Icon)));
      expect(icon.size, 15);
      final button = t.widget<TextButton>(find.descendant(
          of: find.byTooltip('Like'), matching: find.byType(TextButton)));
      expect(button.style?.tapTargetSize, isNot(MaterialTapTargetSize.shrinkWrap),
          reason: 'the tap target must not shrink with the icon');
      // 40, which is what it was BEFORE the icons shrank: Material's padded
      // 48 less the 8 VisualDensity.compact takes back. With shrinkWrap it
      // measured 24, so this number is the difference between shrinking the
      // look and shrinking the button.
      expect(reply.height, 40);
    });
  });

  group('Undo send', () {
    Message mine(DateTime at) => Message(
        id: 'u1', text: 'oops', time: at, isMe: true,
        status: MessageStatus.sent);

    test('the window is five minutes, yours only, and not a tombstone', () {
      final sent = DateTime(2026, 8, 14, 12, 0);
      expect(mine(sent).canUnsendAt(sent.add(const Duration(seconds: 1))),
          isTrue);
      expect(
          mine(sent).canUnsendAt(sent.add(const Duration(minutes: 4, seconds: 59))),
          isTrue);
      expect(mine(sent).canUnsendAt(sent.add(const Duration(minutes: 5))),
          isFalse, reason: 'the window is closed AT five minutes');

      // Somebody else's message is not yours to take back.
      final theirs = Message(
          id: 'u2', text: 'hi', time: sent, isMe: false);
      expect(theirs.canUnsendAt(sent.add(const Duration(seconds: 1))), isFalse);

      // A tombstone has nothing left to unsend.
      expect(
          mine(sent)
              .copyWith(isDeleted: true)
              .canUnsendAt(sent.add(const Duration(seconds: 1))),
          isFalse);

      // The countdown floors at zero rather than going negative.
      expect(mine(sent).unsendLeftAt(sent.add(const Duration(minutes: 9))),
          Duration.zero);
      expect(mine(sent).unsendLeftAt(sent.add(const Duration(minutes: 1))),
          const Duration(minutes: 4));
    });

    test('unsending removes the message and blocks a mailbox replay', () {
      final store = ChatStore.instance;
      store.reset();
      addTearDown(store.reset);
      store.upsert(const Chat(
          id: 'c_undo',
          contact: AppUser(
              id: '+15550100',
              name: 'Ada',
              avatarColor: '#111111',
              phone: '+15550100'),
          messages: []));
      store.addMessage(
          'c_undo',
          Message(
              id: 'm_undo',
              text: 'oops',
              time: DateTime.now(),
              isMe: true,
              status: MessageStatus.sent));
      expect(store.chatById('c_undo')!.messages.length, 1);

      expect(store.unsendMessage('c_undo', 'm_undo'), isTrue);
      // Gone entirely — no "This message was deleted" bubble, which is the
      // whole difference from delete-for-everyone.
      expect(store.chatById('c_undo')!.messages, isEmpty);
      expect(store.isMessageDeleted('m_undo'), isTrue,
          reason: 'a mailbox replay would otherwise bring it straight back');

      // A second call, or one for an id that was never here, changes nothing
      // and says so.
      expect(store.unsendMessage('c_undo', 'm_undo'), isFalse);
      expect(store.unsendMessage('c_undo', 'nope'), isFalse);
    });

    test('an unsend event arriving from the peer takes the message away', () {
      final store = ChatStore.instance;
      store.reset();
      addTearDown(store.reset);
      store.upsert(const Chat(
          id: 'chat_+15550100',
          contact: AppUser(
              id: '+15550100',
              name: 'Ada',
              avatarColor: '#111111',
              phone: '+15550100'),
          messages: []));
      store.addMessage(
          'chat_+15550100',
          Message(
              id: 'm_in',
              text: 'oops',
              time: DateTime.now(),
              isMe: false));

      final handled = RelayService.applyMessageEvent(
          'unsend', {'from': '+15550100', 'id': 'm_in'},
          myPhone: '+15550199', store: store);
      expect(handled, isTrue);
      expect(store.chatById('chat_+15550100')!.messages, isEmpty);
    });

    test('unsend is registered everywhere a message event has to be', () {
      // The trap this file keeps hitting: applyInboxEvent (the sealed
      // router) and the mailbox-drain switch are two rosters that must stay
      // in step, and 'locstop' was in one and not the other until this round.
      final src = File('lib/relay/relay_service.dart').readAsStringSync();
      expect("'unsend'".allMatches(src).length, greaterThanOrEqualTo(3),
          reason: 'the case, the sealed roster, and the mailbox roster');
      expect(src, contains('sendUnsend'));
      // The gap found and closed while adding this one.
      final mailboxRoster =
          src.substring(src.indexOf('for (final (event, payload) in '));
      expect(mailboxRoster, contains("'locstop'"),
          reason: 'a legacy locstop that waited in the mailbox was dropped');
    });

    testWidgets('the chat offers Undo send inside the window, not after',
        (t) async {
      t.view.physicalSize = const Size(390, 844);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      await t.pumpWidget(const OkayMessagingApp());
      await t.pumpAndSettle();
      await t.tap(find.text('Bob Carter'));
      await t.pumpAndSettle();

      await t.enterText(find.byType(TextField).last, 'wrong chat');
      await t.pumpAndSettle();
      await t.tap(find.byIcon(Icons.send));
      await t.pumpAndSettle();

      await t.longPress(find.text('wrong chat'));
      await t.pumpAndSettle();
      expect(find.text('Undo send'), findsOneWidget);
      await t.tap(find.text('Undo send'));
      await t.pumpAndSettle();

      // Gone, with no tombstone left where it was.
      expect(find.text('wrong chat'), findsNothing);
      expect(find.text('This message was deleted'), findsNothing);
      // And the sheet said plainly that this cannot unsee it.
      expect(find.textContaining('may already have read it'), findsOneWidget);
    });
  });

  group('Chat composition options', () {
    Future<void> openBobsChat(WidgetTester t) async {
      t.view.physicalSize = const Size(390, 844);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      await t.pumpWidget(const OkayMessagingApp());
      await t.pumpAndSettle();
      await t.tap(find.text('Bob Carter'));
      await t.pumpAndSettle();
    }

    testWidgets('the formatting strip wraps the selection in real markers',
        (t) async {
      // Bold has RENDERED since the app shipped — RichMessageText parses
      // *bold* / _italic_ / ~strike~ / `mono`. What never existed was any way
      // to apply it without already knowing the syntax.
      await openBobsChat(t);
      final field = find.byType(TextField).last;
      await t.enterText(field, 'hello world');
      await t.pump();

      // Nothing showing until asked for: the strip is a panel like emoji and
      // attachments, not permanent chrome.
      expect(find.text('B'), findsNothing);
      await t.tap(find.byTooltip('Formatting'));
      await t.pumpAndSettle();
      expect(find.text('B'), findsOneWidget);

      // Select "world" and bold it.
      final controller = t.widget<TextField>(field).controller!;
      controller.selection =
          const TextSelection(baseOffset: 6, extentOffset: 11);
      await t.pump();
      await t.tap(find.text('B'));
      await t.pumpAndSettle();
      expect(controller.text, 'hello *world*');

      // The selection survives, so a second marker stacks on the first
      // rather than landing somewhere else.
      await t.tap(find.text('I'));
      await t.pumpAndSettle();
      expect(controller.text, 'hello _*world*_');
    });

    testWidgets('the subject bar is off until the setting turns it on',
        (t) async {
      final prev = AppState.showSubjectBar.value;
      addTearDown(() => AppState.showSubjectBar.value = prev);

      AppState.showSubjectBar.value = false;
      await openBobsChat(t);
      expect(find.widgetWithText(TextField, 'Subject'), findsNothing);
      // A permanently empty field above every composer is a row of chrome
      // nobody asked for, which is why this is opt-in.
      expect(find.text('Subject'), findsNothing);

      // Flipping it while the chat is open has to reach this composer — the
      // switch lives on another screen.
      AppState.showSubjectBar.value = true;
      await t.pumpAndSettle();
      expect(find.text('Subject'), findsOneWidget);
    });

    testWidgets('the subject line is INSIDE the composer card, not above it',
        (t) async {
      // Reported as "make the subject line blend in even more". It used to be
      // a sibling laid out ABOVE the composer's rounded card, which put it on
      // the BAR's background rather than the card's: a full-width flat strip
      // with its own visible edge, reading as a second control to fill in.
      // A subject is part of the message, so it belongs in the same box.
      final prev = AppState.showSubjectBar.value;
      addTearDown(() => AppState.showSubjectBar.value = prev);
      AppState.showSubjectBar.value = true;
      await openBobsChat(t);

      final subject = find.widgetWithText(TextField, 'Subject');
      final message = find.widgetWithText(TextField, 'Message');
      expect(subject, findsOneWidget);
      expect(message, findsOneWidget);

      // The card is the one thing both fields now share an ancestor in.
      final card = find.ancestor(
          of: message, matching: find.byType(LiquidGlass));
      expect(card, findsWidgets);
      expect(
          find.descendant(of: card.first, matching: subject), findsOneWidget);

      // And it really is the card's first line: above the message, inside it.
      expect(t.getTopLeft(subject).dy, lessThan(t.getTopLeft(message).dy));
      expect(t.getTopLeft(subject).dy,
          greaterThanOrEqualTo(t.getTopLeft(card.first).dy));
    });

    testWidgets('a typed subject rides the message and then clears',
        (t) async {
      final prev = AppState.showSubjectBar.value;
      addTearDown(() => AppState.showSubjectBar.value = prev);
      AppState.showSubjectBar.value = true;
      await openBobsChat(t);

      final fields = find.byType(TextField);
      // Subject sits above the composer, so it is the earlier of the two.
      await t.enterText(fields.at(fields.evaluate().length - 2), 'Flights');
      await t.enterText(fields.last, 'landing at six');
      await t.pumpAndSettle();
      await t.tap(find.byIcon(Icons.send));
      await t.pumpAndSettle();

      final sent = ChatStore.instance
          .chatById('c_bob')!
          .messages
          .lastWhere((m) => m.isMe);
      expect(sent.text, 'landing at six');
      expect(sent.subject, 'Flights');
      // And it draws above the body in the bubble.
      expect(find.text('Flights'), findsOneWidget);

      // Cleared straight after: carrying it over would title the next
      // message with something written for this one. Checked on the FIELD,
      // not the screen — the sent subject is legitimately on screen now, in
      // the bubble.
      final subjectField = t.widgetList<TextField>(find.byType(TextField)).
          firstWhere((f) => f.decoration?.hintText == 'Subject');
      expect(subjectField.controller!.text, '');
    });

    test('a subject survives the json round trip, and an old message has none',
        () {
      final m = Message(
        id: 'm1',
        text: 'body',
        subject: 'Flights',
        time: DateTime(2026, 8, 14),
        isMe: true,
      );
      expect(Message.fromJson(m.toJson()).subject, 'Flights');
      // A message stored before the field existed decodes to no subject
      // rather than throwing.
      final old = m.toJson()..remove('subject');
      expect(Message.fromJson(old).subject, '');
      // And an empty one is not written at all, so nothing grows on the wire
      // for the overwhelming majority of messages that have none.
      expect(m.copyWith(subject: '').toJson().containsKey('subject'), isFalse);
    });

    test('message text scales further than it used to', () {
      // 1.30 was reported as not big enough.
      final src =
          File('lib/screens/chats_settings_screen.dart').readAsStringSync();
      expect(src, contains('max: 1.60'));
      // The clamp on load has to agree, or a saved 1.55 comes back as 1.30.
      final persist = File('lib/state/persistence.dart').readAsStringSync();
      expect(persist, contains('clamp(0.85, 1.60)'));
    });
  });

