      await t.pumpWidget(const MaterialApp(home: DialerScreen()));
      await t.pumpAndSettle();
      for (final d in ['4', '1', '6', '5', '5', '5']) {
        await t.tap(find.text(d).first);
        await t.pump();
      }
      // Grouped as it is typed, rather than read as a run of digits.
