  group('Account email', () {
    setUp(AccountEmail.instance.resetForTest);

    test('an email changes once every 30 days, and removing counts', () async {
      SharedPreferences.setMockInitialValues({});
      final store = AccountEmail.instance;
      // First set is free.
      expect(await store.setEmail('ada@example.com'),
          EmailSaveResult.savedUnverified);
      expect(store.changeCooldownLeft(), Duration.zero,
          reason: 'setting the first address starts no clock');
      // The first CHANGE is allowed, and starts the clock.
      expect(await store.setEmail('ada@newhost.com'),
          EmailSaveResult.savedUnverified);
      expect(store.changeCooldownLeft(), greaterThan(const Duration(days: 29)));
      // A second change inside the window is refused, and so is removal —
      // remove-then-add would dodge the clock.
      expect(
          await store.setEmail('third@example.com'), EmailSaveResult.tooSoon);
      expect(store.email, 'ada@newhost.com');
      expect(await store.clear(), isFalse);
      expect(store.email, 'ada@newhost.com');
      // Re-saving the SAME address is not a change (a resend flow).
      expect(await store.setEmail('ada@newhost.com'),
          EmailSaveResult.savedUnverified);
      // Thirty-one days on, it moves again.
      store.debugChangedAt = DateTime.now().subtract(const Duration(days: 31));
      expect(await store.setEmail('third@example.com'),
          EmailSaveResult.savedUnverified);
      expect(store.email, 'third@example.com');
    });

    test('a password cannot go back to one this account has used', () async {
      SharedPreferences.setMockInitialValues({});
      final h = PasswordHistory.instance;
      // 120k PBKDF2 rounds twice per check is a second of real work; the
      // suite must not pay it, and the rule is the same at any cost.
      PasswordHistory.debugRounds = 1;
      h.reset();
      addTearDown(() {
        PasswordHistory.debugRounds = null;
        h.reset();
      });
      await h.load();

      // Nothing remembered: anything goes.
      expect(await h.problemFor('correct horse battery'), isNull);
      await h.remember('Summer2024!');

      // The same password again, exactly.
      expect(await h.problemFor('Summer2024!'), isNotNull);
      // And "anything similar" — a counter bumped, a symbol swapped in, the
      // case changed. All three reduce to the same skeleton.
      expect(await h.problemFor('summer2025'), isNotNull);
      expect(await h.problemFor('SUMMER2024'), isNotNull);
      expect(await h.problemFor('Summ3r2024#'), isNotNull);
      // Something genuinely different is fine.
      expect(await h.problemFor('correct horse battery'), isNull);

      // Only the last [keep] are held, so a long-lived account is not
      // eventually refused everything.
      for (var i = 0; i < PasswordHistory.keep + 2; i++) {
        await h.remember('unrelated-phrase-$i-xyzzy');
      }
      expect(h.debugCount, PasswordHistory.keep);
      expect(await h.problemFor('Summer2024!'), isNull,
          reason: 'pushed out of the window by newer entries');
    });

    test('the password skeleton is strict enough to be worth comparing', () {
      // Pure, so the rule is checkable without a hash or a store behind it.
      expect(PasswordHistory.skeletonOf('Summer2024!'), 'summer');
      expect(PasswordHistory.skeletonOf('summer2025'), 'summer');
      expect(PasswordHistory.skeletonOf('P@ssw0rd1'), 'password');
      // Leading digits are usually part of the word somebody chose; only the
      // trailing counter comes off.
      expect(PasswordHistory.skeletonOf('2024summer'), '2024summer');
      // Two unrelated passwords must not collide.
      expect(PasswordHistory.skeletonOf('winter2024') ==
          PasswordHistory.skeletonOf('summer2024'), isFalse);
    });

    test('a too-generic skeleton is not compared at all', () async {
      SharedPreferences.setMockInitialValues({});
      final h = PasswordHistory.instance;
      PasswordHistory.debugRounds = 1;
      h.reset();
      addTearDown(() {
        PasswordHistory.debugRounds = null;
        h.reset();
      });
      await h.load();
      // `x1y2` reduces to `xiy` — three letters. Matching on that would refuse
      // half the passwords somebody could pick next, so the skeleton check
      // sits out and only an EXACT repeat is caught.
      expect(PasswordHistory.skeletonOf('x1y2').length,
          lessThan(4));
      await h.remember('x1y2');
      expect(await h.problemFor('x1y2'), isNotNull);
      expect(await h.problemFor('x1y3'), isNull,
          reason: 'the skeleton they share is too generic to refuse on');
    });

    test('no password is stored, and the history is account-scoped', () async {
      SharedPreferences.setMockInitialValues({});
      final h = PasswordHistory.instance;
      PasswordHistory.debugRounds = 1;
      h.reset();
      addTearDown(() {
        PasswordHistory.debugRounds = null;
        h.reset();
      });
      await h.load();
      await h.remember('Summer2024!');
      // What is on disk is slow hashes, not passwords — neither the password
      // nor its skeleton appears anywhere in the stored blob.
      final prefs = await SharedPreferences.getInstance();
      final blob = prefs.getKeys().map((k) => '${prefs.get(k)}').join('|');
      expect(blob.toLowerCase(), isNot(contains('summer')));

      // The wipe forgets it, so the next account on this phone is not refused
      // a password somebody else once had.
      final wipe = File('lib/state/account_wipe.dart').readAsStringSync();
      expect(wipe, contains('PasswordHistory.instance.reset()'));
      expect(wipe, contains('PasswordHistory.instance.load'));
      // Checked BEFORE the round trip, and recorded only once it landed.
      final screen =
          File('lib/screens/account_email_screen.dart').readAsStringSync();
      expect(screen, contains('PasswordHistory.instance.problemFor'));
      expect(screen, contains('PasswordHistory.instance.remember'));
    });

    test('a verified email survives reinstall through the auth user', () {
      // The address lives on the Supabase auth user; a reinstall (or the
      // account switch's wipe) only empties the LOCAL copy. The refresh
      // adopts it back — address and confirmed state — instead of asking
      // somebody to re-verify an email the server already confirmed.
      final src = File('lib/state/account_email.dart').readAsStringSync();
      expect(src, contains('_email.isEmpty && serverEmail.isNotEmpty'));
      expect(src, contains('_verified = user.emailConfirmedAt != null'));
      // And the refusal in the UI names the wait, rather than a bare no.
      final screen =
          File('lib/screens/account_email_screen.dart').readAsStringSync();
      expect(screen, contains('EmailSaveResult.tooSoon'));
      expect(screen, contains('changeCooldownLeft()'));
    });

    test('the confirmation link lands somewhere real, not on localhost', () {
      // With no emailRedirectTo, Supabase falls back to the project's Site
      // URL — `http://localhost:3000` until someone changes it — so the link
      // in the email opened a dead page on the reader's own phone.
      //
      // Driven through the pure builder because a test binary carries no
      // --dart-define, which would make every case the empty one.
      final base = AppPages.baseFor('https://abc.supabase.co', '');
      final url = AppPages.subFor(base, 'email-confirmed');
      expect(url.startsWith('https://'), isTrue);
      expect(url.contains('localhost'), isFalse);
      expect(url.contains('127.0.0.1'), isFalse);

      // And it has to be a page the server will actually answer for. It is
      // served by an Edge Function on the same project rather than a static
      // file, so the check is that the function routes this leaf.
      final leaf = Uri.parse(url).pathSegments.last;
      final fn = File('supabase/functions/pages/index.ts').readAsStringSync();
      expect(fn.contains('case "$leaf":'), isTrue,
          reason: 'the confirmation link points at a page nothing serves');
    });

    test(
        'sendNumberlessEmailCode redirects somewhere real too, not '
        'localhost — the same fix as the phone-account link', () {
      // A thin Supabase wrapper with no seam to call and inspect, so this is
      // a source pin — same shape as other network-wrapper checks in this
      // file. Found live: the numberless "Send code" flow's email used
      // Supabase's default "Confirm signup" template (a LINK, not the
      // {{ .Token }} code this flow needs) with no emailRedirectTo, so the
      // link opened http://localhost:3000 and 404'd.
      final src = File('lib/state/account_service.dart').readAsStringSync();
      expect(src, contains('emailRedirectTo: AppPages.emailConfirmed'));
    });

    test('the confirmation page tells the truth about a failed link', () {
      // Supabase reports an expired or already-used link in the URL FRAGMENT,
      // which never reaches a server — so the page has to correct itself. One
      // hardcoded to say "confirmed" would send someone back to the app
      // believing something that didn't happen.
      final fn = File('supabase/functions/pages/index.ts').readAsStringSync();
      final page = fn.substring(
          fn.indexOf('const EMAIL_CONFIRMED'), fn.indexOf('Deno.serve'));
      expect(page.contains('error_description'), isTrue);
      expect(page.contains(r'Link didn’t work'), isTrue);
    });

    test('validation accepts real addresses and rejects the rest', () {
      expect(AccountEmail.isValid('ada@example.com'), isTrue);
      expect(AccountEmail.isValid('ada.lovelace+okay@mail.co.uk'), isTrue);
      expect(AccountEmail.isValid('  ada@example.com  '), isTrue);
      expect(AccountEmail.isValid('ada@example'), isFalse); // no TLD
      expect(AccountEmail.isValid('ada example.com'), isFalse);
      expect(AccountEmail.isValid('@example.com'), isFalse);
      expect(AccountEmail.isValid('ada@@example.com'), isFalse);
      expect(AccountEmail.isValid(''), isFalse);
    });

    test('masking hides the address without hiding which one it is', () {
      expect(AccountEmail.mask('ada@example.com'), 'a•a@example.com');
      expect(AccountEmail.mask('lovelace@example.com'), 'l••••••e@example.com');
      expect(AccountEmail.mask('ab@example.com'), 'a•@example.com');
      // Not an address — passed through rather than mangled.
      expect(AccountEmail.mask('nonsense'), 'nonsense');
    });

    test('an invalid address is refused and nothing is stored', () async {
      expect(await AccountEmail.instance.setEmail('not-an-email'),
          EmailSaveResult.invalid);
      expect(AccountEmail.instance.isSet, isFalse);
    });

    test('a valid address is stored unverified without a server session',
        () async {
      final result = await AccountEmail.instance.setEmail(' ada@example.com ');
      // No Supabase session in tests, so nothing can be sent to confirm it —
      // it's saved and honestly flagged rather than claimed as verified.
      expect(result, EmailSaveResult.savedUnverified);
      expect(AccountEmail.instance.email, 'ada@example.com');
      expect(AccountEmail.instance.isVerified, isFalse);
      expect(AccountEmail.instance.isSet, isTrue);

      await AccountEmail.instance.clear();
      expect(AccountEmail.instance.isSet, isFalse);
    });

    test('the account email rides the encrypted sync', () async {
      CloudSync.debugServerOverride = {};
      addTearDown(() {
        CloudSync.debugServerOverride = null;
        CloudSync.instance.resetForTest();
        AccountEmail.instance.resetForTest();
      });
      await CloudSync.instance
          .configure(passphrase: 'correct horse battery', on: false);
      await AccountEmail.instance.setEmail('ada@example.com');

      expect(await CloudSync.instance.syncNow(), isNull);
      final blob = CloudSync.debugServerOverride!.values.single;
      // The address is in the backup, but only as ciphertext.
      expect(blob.contains('ada@example.com'), isFalse);

      AccountEmail.instance.resetForTest();
      expect(await CloudSync.instance.restore(), isNull);
      expect(AccountEmail.instance.email, 'ada@example.com');
    });

    testWidgets('the screen adds an address and offers to remove it',
