    testWidgets('voting does not move the poll under the thumb', (t) async {
      // Answering used to shrink a three-option poll by thirty points,
      // because a button and the bar it becomes were different heights — so
      // the timeline jumped under the finger that had just tapped.
      // Relative to the real clock: a fixed date makes "still open" depend on
      // what day the suite happens to run, and a closed poll draws bars.
      final now = DateTime.now();
      PublicFeedStore.debugLoadOverride = () async => [
            PublicPost(
              id: 'open',
              authorUsername: 'ada',
              authorName: 'Ada',
              body: 'Not answered yet',
              createdAt: now,
              pollOptions: const ['Tabs', 'Spaces'],
              pollClosesAt: now.add(const Duration(hours: 5)),
              pollVotes: const [3, 4],
            ),
            PublicPost(
              id: 'voted',
              authorUsername: 'ada',
              authorName: 'Ada',
              body: 'Answered',
              createdAt: now,
              pollOptions: const ['Tabs', 'Spaces'],
              pollClosesAt: now.add(const Duration(hours: 5)),
              pollVotes: const [3, 4],
              myVote: 0,
            ),
          ];
      addTearDown(() => PublicFeedStore.debugLoadOverride = null);

      await t.pumpWidget(const MaterialApp(home: PublicFeedScreen()));
      await t.pumpAndSettle();

      // "Tabs" appears twice: once as a button to press, once as a bar.
      // The gap between one answer and the next IS the answer's height, and
      // it needs no guessing about which box in the tree owns it.
      expect(find.text('Tabs'), findsNWidgets(2));
      expect(find.text('Spaces'), findsNWidgets(2));
      // One poll is still answerable and one is not, or this compares two
      // copies of the same thing and proves nothing.
      expect(find.byType(OutlinedButton), findsNWidgets(2),
          reason: 'exactly one of the two polls should still be buttons');
      double pitch(int poll) =>
          t.getCenter(find.text('Spaces').at(poll)).dy -
          t.getCenter(find.text('Tabs').at(poll)).dy;

      expect(pitch(0), pitch(1),
          reason: 'the answer and the bar it turns into are different heights');
      expect(pitch(0), greaterThan(44),
          reason: 'an answer is a target, and 44 is the floor');
    });

    test('length is validated before the database has to refuse it', () {
      expect(PublicFeedStore.validate(''), isNotNull);
      expect(PublicFeedStore.validate('   '), isNotNull);
      expect(PublicFeedStore.validate('hello'), isNull);
      expect(PublicFeedStore.validate('x' * PublicFeedStore.maxLength), isNull);
      final over =
          PublicFeedStore.validate('x' * (PublicFeedStore.maxLength + 7));
      expect(over, contains('7 characters too long'),
          reason: 'say how much to cut, not just that it is too long');
      // Empty text is fine when something else is attached — which is what
      // the table allows too, via a not-empty constraint across the three.
      expect(PublicFeedStore.validate('', hasImage: true), isNull);
      expect(PublicFeedStore.validate('', isRepost: true), isNull);
      expect(PublicFeedStore.validate('x' * 501, hasImage: true), isNotNull,
          reason: 'the length cap still applies to a captioned photo');
      // The client cap and the table's CHECK have to be the same number, or
      // one of them is a lie.
      final sql = File('docs/public_feed.sql').readAsStringSync();
      expect(sql.contains('char_length(body) <= ${PublicFeedStore.maxLength}'),
          isTrue);
      expect(sql.contains('public_posts_not_empty'), isTrue,
          reason: 'a row with no text, image or repost is nonsense');
    });

    test('ids do not collide', () {
      final ids = {for (var i = 0; i < 500; i++) PublicFeedStore.newId()};
      expect(ids, hasLength(500));
      expect(ids.every((i) => i.startsWith('pp_')), isTrue);
    });

    test('the timeline is top-level posts; replies hang off their parent',
        () async {
      final store = PublicFeedStore.instance;
      PublicFeedStore.debugLoadOverride = () async => [
            mk('a'),
            mk('b'),
            mk('r1', replyTo: 'a'),
            mk('r2', replyTo: 'a'),
          ];
      await store.load();
      expect(store.posts.map((p) => p.id), ['a', 'b'],
          reason: 'a reply is not a timeline entry');
      expect(store.repliesTo('a').map((p) => p.id), ['r2', 'r1']);
      expect(store.repliesTo('b'), isEmpty);
      expect(store.byId('r1')?.replyTo, 'a');
    });

    test('a post appears at once and its parent\'s reply count moves',
        () async {
      final store = PublicFeedStore.instance;
      PublicFeedStore.debugLoadOverride = () async => [mk('a')];
      await store.load();
      final written = <PublicPost>[];
      PublicFeedStore.debugPostOverride = (p) async => written.add(p);

      await store.post('  hello world  ');
      expect(written.single.body, 'hello world', reason: 'trimmed');
      expect(store.posts.first.body, 'hello world',
          reason: 'shown without waiting for a reload');
      expect(store.posts.first.mine, isTrue);

      await store.post('a reply', replyTo: 'a');
      expect(store.byId('a')!.replyCount, 1,
          reason: 'an empty-looking thread after replying is a bug');
      expect(store.posts.any((p) => p.body == 'a reply'), isFalse,
          reason: 'a reply belongs under its parent, not on the timeline');

      // Nothing is written when the text is unusable.
      written.clear();
      await expectLater(store.post('   '), throwsA(isA<PublicFeedError>()));
      expect(written, isEmpty);
    });

    test('a like that the server refuses is put back', () async {
      final store = PublicFeedStore.instance;
      PublicFeedStore.debugLoadOverride = () async => [mk('a', likes: 4)];
      await store.load();

      PublicFeedStore.debugLikeOverride = (_, __) async {};
      await store.toggleLike('a');
      expect(store.byId('a')!.liked, isTrue);
      expect(store.byId('a')!.likeCount, 5);
      await store.toggleLike('a');
      expect(store.byId('a')!.liked, isFalse);
      expect(store.byId('a')!.likeCount, 4);

      // A refusal rolls the optimistic change back, rather than showing a
      // like that never happened — AND says so. It used to end at the
      // roll-back, so the heart flicked on, flicked off, and nothing
      // explained it; that is how "still can't like posts" arrived as a
      // report with nothing to go on.
      PublicFeedStore.debugLikeOverride =
          (_, __) async => throw PublicFeedError('no');
      await expectLater(
          store.toggleLike('a'), throwsA(isA<PublicFeedError>()));
      expect(store.byId('a')!.liked, isFalse, reason: 'rolled back');
      expect(store.byId('a')!.likeCount, 4);
    });

    test('deleting a post takes its replies with it', () async {
      final store = PublicFeedStore.instance;
      PublicFeedStore.debugLoadOverride =
          () async => [mk('a'), mk('r1', replyTo: 'a'), mk('b')];
      await store.load();
      await store.delete('a');
      expect(store.byId('a'), isNull);
      expect(store.byId('r1'), isNull,
          reason: 'the table cascades; the store must match');
      expect(store.byId('b'), isNotNull);
    });

    testWidgets('a profile shows what someone posted, in tabs', (t) async {
      t.view.physicalSize = const Size(500, 2000);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      final store = PublicFeedStore.instance;
      addTearDown(store.resetForTest);

      final now = DateTime.now();
      final mine = [
        PublicPost(
            id: 'a',
            authorUsername: 'sam',
            authorName: 'Sam',
            body: 'a top-level post',
            createdAt: now),
        PublicPost(
            id: 'b',
            authorUsername: 'sam',
            authorName: 'Sam',
            body: 'a reply',
            replyTo: 'z',
            createdAt: now.subtract(const Duration(minutes: 1))),
        PublicPost(
            id: 'c',
            authorUsername: 'sam',
            authorName: 'Sam',
            body: 'with a photo',
            imagePath: 'c.jpg',
            createdAt: now.subtract(const Duration(minutes: 2))),
        // Somebody else's post must never appear on Sam's profile.
        PublicPost(
            id: 'd',
            authorUsername: 'kim',
            authorName: 'Kim',
            body: 'not sam',
            createdAt: now),
      ];
      PublicFeedStore.debugProfileOverride = (_) async => mine;

      await t.pumpWidget(const MaterialApp(
          home: PublicProfileScreen(username: 'sam', name: 'Sam')));
      await t.pumpAndSettle();

      expect(find.text('@sam'), findsWidgets);
      expect(find.text('a top-level post'), findsOneWidget);
      expect(find.text('not sam'), findsNothing,
          reason: 'a profile is one person\'s posts');
      // Three of Sam's four, and the count is the real number the server gave.
      // Capitalised now: it is one stat among the others rather than a
      // sentence fragment, since the two rows of counts became one.
      expect(find.text('3'), findsWidgets);
      expect(find.byTooltip('Posts'), findsWidgets);

      // Followers exist now — the owner's call (2026-08-05): a server
      // graph was BUILT for them (public_follows, phones inside and
      // usernames out), so the number is real rather than invented. What
      // this pin now holds is the honesty rule that replaced the absence:
      // with no server answer in this test, the stat is a dash, never a
      // zero the app cannot know.
      // By tooltip: the stat's label is a glyph since 2026-08-15, and the
      // tooltip is what carries the word (and the semantics name) now.
      expect(find.byTooltip('Followers'), findsOneWidget);
      expect(find.text('—'), findsWidgets);

      await t.tap(find.byTooltip('Replies'));
      await t.pumpAndSettle();
      expect(find.text('a reply'), findsOneWidget);
      expect(find.text('a top-level post'), findsNothing);

      await t.tap(find.byTooltip('Media'));
      await t.pumpAndSettle();
      // A grid of the photos themselves: the caption is not what somebody
      // opened this tab to look at, so it is in the post it belongs to.
      expect(find.byType(SliverGrid), findsOneWidget);
      expect(find.byType(Image), findsWidgets);
      expect(find.text('a reply'), findsNothing);
    });

    test('the profile tabs are a rule, not three queries', () {
      final now = DateTime.now();
      PublicPost p(String id, {String? replyTo, String image = ''}) =>
          PublicPost(
              id: id,
              authorUsername: 'sam',
              authorName: 'Sam',
              body: 'x',
              replyTo: replyTo,
              imagePath: image,
              createdAt: now);
      final all = [
        p('top'),
        p('reply', replyTo: 'other'),
        p('photo', image: 'p.jpg'),
        p('photoReply', replyTo: 'other', image: 'q.jpg'),
      ];
      ids(ProfileTab tab) =>
          [for (final x in PublicFeedStore.profileTab(all, tab)) x.id];

      expect(ids(ProfileTab.posts), ['top', 'photo'],
          reason: 'Posts excludes replies');
      expect(ids(ProfileTab.replies), ['reply', 'photoReply']);
      // Media is about carrying an image, not about being top-level — a reply
      // with a photo in it is still a photo this person posted.
      expect(ids(ProfileTab.media), ['photo', 'photoReply']);

      // A banner colour has to be stable, or somebody's profile looks like a
      // different profile every time it opens.
      const scheme = ColorScheme.light();
      expect(feedHandleSeed('sam', scheme), feedHandleSeed('sam', scheme));
      expect(
          feedHandleSeed('sam', scheme), isNot(feedHandleSeed('kim', scheme)));
    });

    test('a view that predates reposts still gives a timeline', () {
      // The app and the web page deploy the moment they are pushed. The SQL is
      // pasted into a dashboard by hand, whenever somebody gets to it. So there
      // is always a window where the client asks for columns the view has not
      // got — and PostgREST fails the whole request over one missing column, so
      // the feed goes blank with nothing said about why. That happened.
      expect(PublicFeedStore.isMissingColumn('42703'), isTrue);
      expect(PublicFeedStore.isMissingColumn('42501'), isFalse,
          reason: 'a permission refusal is not a stale schema');
      expect(PublicFeedStore.isMissingColumn(null), isFalse);

      // The fallback only works if a row without the new keys still parses.
      final old = PublicPost.fromRow({
        'id': 'p1',
        'author_username': 'sam',
        'author_name': 'Sam',
        'author_verified': false,
        'body': 'hello',
        'reply_to': null,
        'created_at': DateTime.now().toIso8601String(),
        'like_count': 2,
        'reply_count': 0,
      });
      expect(old.body, 'hello');
      expect(old.repostOf, isNull);
      expect(old.imagePath, '');
      expect(old.repostCount, 0);
      expect(old.hasImage, isFalse);
      expect(old.likeCount, 2,
          reason: 'what the old view does have still reads');
    });

    test('a public post carries the author\'s own face for a stranger', () {
      // Reported as "it doesn't show the right profile pictures on my other
      // phone": a second account, with no chats, saw a timeline of letter
      // avatars. Not a rendering fault — FeedAvatar resolves through
      // knownUserFor, which answers only for YOURSELF or a chat CONTACT, and
      // the feed row carried nothing else to draw. A stranger on a public
      // timeline is exactly the person a device cannot know.
      final withFace = PublicPost.fromRow({
        'id': 'p1',
        'author_username': 'sam',
        'author_name': 'Sam',
        'author_verified': true,
        'body': 'hello',
        'created_at': DateTime.now().toIso8601String(),
        'author_avatar_color': '#123456',
        'author_avatar_seed': 'okay-7-2',
      });
      expect(withFace.authorAvatar, isNotNull);
      expect(withFace.authorAvatar!.avatarSeed, 'okay-7-2');
      expect(withFace.authorAvatar!.avatarColor, '#123456');
      expect(withFace.authorAvatar!.username, 'sam');
      // Nothing on a world-readable row carries a number, and the avatar does
      // not need one: the legacy-seed re-salt keys off the handle.
      expect(withFace.authorAvatar!.phone, '');

      // A row from before the migration — or from a project that has not run
      // it — must read as NO avatar, not as a blank one that would override
      // the initial with an empty circle.
      final bare = PublicPost.fromRow({
        'id': 'p2',
        'author_username': 'sam',
        'author_name': 'Sam',
        'body': 'hello',
        'created_at': DateTime.now().toIso8601String(),
      });
      expect(bare.authorAvatar, isNull);

      // The read path steps DOWN a schema generation on 42703, so a project
      // that has not run the migration still gets a timeline.
      expect(PublicFeedStore.debugColumnSets.first, contains('author_avatar_seed'));
      expect(PublicFeedStore.debugColumnSets.length, greaterThan(1));
      expect(PublicFeedStore.debugColumnSets[1],
          isNot(contains('author_avatar_seed')));

      // And the write path does the same rather than refusing to post.
      final src = File('lib/state/public_feed_store.dart').readAsStringSync();
      expect(src, contains("e.code != '42703'"));
    });

    testWidgets('a contact\'s live face beats the one frozen on a post',
        (tester) async {
      // The snapshot is what a STRANGER is drawn with. Somebody this device
      // has really chatted with keeps a live face, so changing your avatar
      // still reaches the people who know you rather than being frozen at
