    test('the columns the app reads are the columns the SQL grants', () {
      // A column added to the table but left off the grant list comes back
      // missing with nothing said about why — the exact shape of bug this
      // file has shipped before.
      final sql = File('docs/public_feed.sql').readAsStringSync();
      final grant =
          RegExp(r'grant select \(([^)]*)\)\s*\n?\s*on public\.public_posts')
              .firstMatch(sql)!
              .group(1)!;
      for (final column in ['gif_url', 'video_path', 'image_path']) {
        expect(grant.contains(column), isTrue,
            reason: '$column is readable by nobody');
        // And the view the feed actually selects from has to carry it too.
        expect(RegExp('p\\.$column').hasMatch(sql), isTrue,
            reason: '$column never reaches the public_feed view');
      }
      // The newest column set the client asks for must not name a column the
      // view lacks: one missing column fails the whole request.
      expect(PublicFeedStore.debugColumnSets.first.contains('gif_url'), isTrue);
      expect(
          PublicFeedStore.debugColumnSets.first.contains('video_path'), isTrue);

      // And the INSERT has to name them as well. debugPostOverride stands in
      // for the whole round trip, so no test above this line ever touches the
      // insert map — a column missing there renders once, locally, and is
      // gone on the next load with nothing said about why.
      final dart = File('lib/state/public_feed_store.dart').readAsStringSync();
      for (final column in ['gif_url', 'video_path', 'image_path']) {
        expect(dart.contains("'$column':"), isTrue,
            reason: 'the insert never writes $column, so it would not survive '
                'a reload');
      }
    });

    test('spark tallies survive the whole public-feed round trip', () {
      // The SQL, the newest column set, and the parser all have to agree —
      // one missing link and the bolt lies or the whole fetch fails.
      final sql = File('docs/public_feed.sql').readAsStringSync();
      for (final piece in [
        'public_post_sparks',
        'spark_count',
        'spark_cents',
        'is_post_author'
      ]) {
        expect(sql.contains(piece), isTrue,
            reason: '$piece missing from the public feed SQL');
      }
      expect(PublicFeedStore.debugColumnSets.first.contains('spark_count'),
          isTrue);
      expect(PublicFeedStore.debugColumnSets.first.contains('spark_cents'),
          isTrue);
      // An unmigrated server steps down to a generation without the bolt.
      // Asserted by SEARCHING rather than by index: adding a generation at
      // the top shifts every index below it, which is exactly how this broke
      // when the author-avatar columns were added.
      final sets = PublicFeedStore.debugColumnSets;
      final firstNoViews = sets.indexWhere((s) => !s.contains('view_count'));
      expect(firstNoViews, greaterThan(0),
          reason: 'the newest generation carries view counts');
      final firstNoSparks = sets.indexWhere((s) => !s.contains('spark_count'));
      expect(firstNoSparks, greaterThan(firstNoViews),
          reason: 'sparks predate views, so they survive one more generation');

      final post = PublicPost.fromRow({
        'id': 'p',
        'body': 'b',
        'created_at': DateTime.now().toIso8601String(),
        'spark_count': 3,
        'spark_cents': 542,
      });
      expect(post.sparkCount, 3);
      expect(post.sparkCents, 542);
      expect(post.copyWith(sparkCount: 4, sparkCents: 563).sparkCents, 563);

      // The intent function resolves the recipient FROM THE POST ID, so the
      // author's number never reaches the sparker — the privacy design that
      // makes a bolt on a world-readable feed possible at all.
      final intent = File('docs/edge_functions_paste/payments-create-intent.ts')
          .readAsStringSync();
      expect(intent.contains('sparkPostId'), isTrue);
      expect(intent.contains('author_phone'), isTrue);
    });

    test('a public spark in test mode never touches the real tally', () async {
      addTearDown(() => PaymentService.instance.testMode.value = false);
      addTearDown(() => PublicFeedStore.debugLoadOverride = null);
      PaymentService.instance.testMode.value = true;
      PublicFeedStore.debugLoadOverride = () async => [
            PublicPost(
                id: 'sp1',
                authorUsername: 'ada',
                body: 'sparkable',
                createdAt: DateTime.now()),
          ];
      await PublicFeedStore.instance.load();
      await PublicFeedStore.instance.recordSpark('sp1', 2100);
      final p = PublicFeedStore.instance.byId('sp1')!;
      expect(p.sparkCount, 1);
      expect(p.sparkCents, 2100);
      expect(PublicFeedStore.instance.sparkedByMe('sp1'), isTrue);
      // The tally survives, and NOTHING can add to it from a post any
      // more: sparking moved off posts entirely (2026-08-09), because money
      // pinned to one piece of content is a payment for digital content —
      // the shape Apple made Damus remove. The eligibility helpers went with
