    testWidgets('the profile header fits, and counts each thing once',
        (t) async {
      t.view.physicalSize = const Size(430, 1600);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      final store = PublicFeedStore.instance;
      addTearDown(store.resetForTest);
      final prevProfile = AppState.profile.value;
      addTearDown(() => AppState.profile.value = prevProfile);
      AppState.profile.value = const AppUser(
          id: 'me', name: 'Iman', avatarColor: '#000000', username: 'iman');

      PublicFeedStore.debugProfileOverride = (username) async => [
            PublicPost(
                id: 'p1',
                authorUsername: 'iman',
                authorName: 'Iman',
                body: 'hello',
                createdAt: DateTime.now()),
          ];
      await t.pumpWidget(const MaterialApp(
          home: Scaffold(
              body: PublicProfileScreen(username: 'iman', embedded: true))));
      await t.pumpAndSettle();

      // THE AVATAR WAS CUT IN HALF. It was pushed up out of the header sliver
      // with Transform.translate, and a sliver clips at its own bounds, so the
      // top of somebody's head disappeared behind the banner. Both are one box
      // now, and the whole avatar has to be inside the screen.
      final avatar = t.getRect(find.byType(CircleAvatar).first);
      expect(avatar.top, greaterThanOrEqualTo(0.0),
          reason: 'the top of the head is on screen');
      expect(avatar.height, greaterThan(50.0),
          reason: 'and it is a whole circle, not a sliver of one');
      // Clipping does not change a widget's rect, so the rect alone cannot see
      // this. What can: the header below has to start BELOW the avatar. When
      // the box holding banner and avatar is too short, the name is drawn over
      // the avatar's lower half — which is what a clipped avatar looks like.
      final handle = t.getRect(find.text('@iman').first);
      expect(handle.top, greaterThanOrEqualTo(avatar.bottom),
          reason: 'the header begins after the avatar, not through it');

      // ONE set of counts. There were two — "1 post 0 following" above a second
      // row repeating Following beside Servers and Okay Score — which invites
      // somebody to check whether the two numbers disagree.
      //
      // Counted by TOOLTIP since 2026-08-15: the labels are glyphs, and the
      // word survives as the tooltip and the semantics name. "Post" (one of
      // them) is the count and "Posts" is the tab, so the stat has to be
      // scoped to `ProfileStat` — the tab strip carries a 'Posts' tooltip of
      // its own, and an unscoped finder would pass on the wrong widget.
      Finder statTip(String label) => find.descendant(
          of: find.byType(ProfileStat), matching: find.byTooltip(label));
      expect(statTip('Following'), findsOneWidget);
      expect(find.text('Following'), findsNothing,
          reason: 'the label is a glyph now, not a word');
      expect(statTip('Post'), findsOneWidget);
      expect(find.byTooltip('Posts'), findsOneWidget,
          reason: 'and the only "Posts" left is the tab');
      expect(find.text('posts'), findsNothing);
      // Okay Score used to be a fourth count in the same row. Four do not fit
      // a 390pt phone, so the row broke three-and-one; it has a row of its own
      // now, with somewhere to go, which is what it was all along.
      expect(find.text('Okay Score'), findsOneWidget);
      final scoreRow = t.getRect(find
          .ancestor(of: find.text('Okay Score'), matching: find.byType(InkWell))
          .first);
      // Against Following, not Posts: with one post the count reads "Post"
      // while the TAB reads "Posts", so measuring from "Posts" measures the
      // tab strip and passes for the wrong reason.
      final followingCount = t.getRect(statTip('Following'));
      expect(scoreRow.top, greaterThan(followingCount.bottom),
          reason: 'it is below the counts, not wrapped off the end of them');
      expect(find.byIcon(Icons.chevron_right), findsWidgets,
          reason: 'and it says it goes somewhere');

      // Everything down the left edge starts at the same margin — the counts
      // card included, which is what keeps it reading as part of the profile
      // rather than as a widget dropped onto it. The score row is INSIDE that
      // card now, so it is indented by the card's own padding rather than
      // sharing the page margin; what must line up is the card.
      final name = t.getRect(find.text('Iman').first);
      // .first, not .last: the outermost Material ancestor is the Scaffold's
      // own, which starts at the screen edge and would pass this for nothing.
      final card = t.getRect(find
          .ancestor(of: find.text('Okay Score'), matching: find.byType(Material))
          .first);
      expect(card.left, closeTo(name.left, 1.0),
          reason: 'the counts card shares the margin everything else uses');
      expect(scoreRow.left, greaterThan(card.left),
          reason: 'and the score row sits inside it');

      // The header has to leave room for the thing the profile is for. This
      // was 520 while the header was packed into 4-to-8-point gaps; opening it
      // out cost about 70 points, which is the change and not a regression.
      //
      // 600 is where it stops being one: the shortest phone still sold is 667
      // tall, so the tabs have to end far enough up that the first lines of a
      // post are under them without a scroll. Tightening this back below 520
      // means taking the air out again.
      final tabs = t.getRect(find.byTooltip('Replies'));
      expect(tabs.bottom, lessThan(600.0),
          reason: 'a post is visible without scrolling on a 667pt phone');

      // Nothing overflows at a real phone width. takeException() CONSUMES the
      // error, so asserting on a bool threw away the one thing that says what
      // broke — the reason carries it now.
      final failure = t.takeException();
      expect(failure, isNull, reason: 'layout error: $failure');
    });

    testWidgets('the counts are equal columns of one card, not loose phrases',
        (t) async {
      // The owner said "too compact" three times, and three passes at the
      // spacing were answered with the same sentence — because the spacing
      // was never the problem. The counts were four small number-beside-label
      // phrases in a `Wrap`, floating in a column of other small phrases, so
      // more air around them read as the same screen with more air. This pins
      // the structural answer: one card, equal columns, number over label.
      t.view.physicalSize = const Size(390, 844);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      SharedPreferences.setMockInitialValues({});
      final store = PublicFeedStore.instance;
      addTearDown(store.resetForTest);
      final prevProfile = AppState.profile.value;
      addTearDown(() => AppState.profile.value = prevProfile);
      AppState.profile.value = const AppUser(
          id: 'me', name: 'Iman', avatarColor: '#2E7D32', username: 'iman');
      PublicFeedStore.debugProfileOverride = (username) async => [];

      await t.pumpWidget(const MaterialApp(
          home: Scaffold(
              body: PublicProfileScreen(username: 'iman', embedded: true))));
      await t.pumpAndSettle();

      // EQUAL columns. A `Wrap` sized every stat to its own contents, so the
      // gaps moved with the numbers and four counts could tip onto a second
      // line the moment anything got wider — which `type_metrics_test.dart`
      // caught twice. Columns cannot reflow, whatever the numbers say.
      // Located by tooltip since the labels became glyphs (2026-08-15) —
      // which is also the check that every stat still HAS its word, since a
      // stat with no tooltip is a number beside an unexplained icon.
      Finder statOf(String label) => find.ancestor(
          of: find.byTooltip(label), matching: find.byType(ProfileStat));
      final widths = <String, double>{
        for (final label in ['Following', 'Followers', 'Posts', 'Servers'])
          label: t.getRect(statOf(label)).width,
      };
      for (final w in widths.values) {
        expect(w, closeTo(widths['Following']!, 1.0),
            reason: 'the columns are the same width: $widths');
      }

      // Number OVER glyph, not beside it — the shape that only becomes safe
      // once each one has a column of its own.
      final stat = statOf('Following');
      final value = t.getRect(
          find.descendant(of: stat, matching: find.byType(Text)).first);
      final glyph = t.getRect(find.descendant(
          of: stat, matching: find.byIcon(Icons.person_add_alt_1_outlined)));
      expect(value.bottom, lessThanOrEqualTo(glyph.top),
          reason: 'the count sits above what it counts');

      // And the Okay Score is INSIDE the card, under a rule, rather than
      // adrift below the counts. Same card: one Material holds both.
      // .first is the innermost Material — the card. .last would be the
      // Scaffold's, which everything on the screen shares.
      Finder cardOf(Finder inner) =>
          find.ancestor(of: inner, matching: find.byType(Material)).first;
      expect(cardOf(find.text('Okay Score')).evaluate().single.widget,
          same(cardOf(statOf('Following')).evaluate().single.widget),
          reason: 'the score is a row of the counts card, not a stray row');
    });

