    testWidgets('the shared strip draws four actions and hides empty counts',
        (t) async {
      var tapped = '';
      await t.pumpWidget(MaterialApp(
        home: Scaffold(
          body: FeedPostActions(
            replyCount: 0,
            repostCount: 2,
            likeCount: 13,
            liked: true,
