  group('Colour that survives both themes', () {
    /// WCAG contrast between two opaque colours.
    double ratio(Color a, Color b) {
      final l1 = a.computeLuminance(), l2 = b.computeLuminance();
      final hi = l1 > l2 ? l1 : l2, lo = l1 > l2 ? l2 : l1;
      return (hi + 0.05) / (lo + 0.05);
    }

    test('nothing in either scheme is a colour nobody chose', () {
      // ColorScheme.fromSeed builds the container tones from a tonal palette
      // and raises the chroma while it does. From a seed that is very nearly
      // black it still handed back #CDE5FF, #D4E4F6 and #EDDCFF in light and
      // #004E5C, #334A50 and #3E4565 in dark — all at full saturation. Every
      // widget that asked for a container colour got one, which is how a
      // greyscale app ended up with a teal card on its first screen, a teal
      // chip on Alerts and a teal panel in Cloud storage.
      for (final (name, scheme) in [
        ('light', AppTheme.light.colorScheme),
        ('dark', AppTheme.dark.colorScheme),
      ]) {
        for (final (label, colour) in [
          ('primaryContainer', scheme.primaryContainer),
          ('secondaryContainer', scheme.secondaryContainer),
          ('tertiaryContainer', scheme.tertiaryContainer),
        ]) {
          expect(HSLColor.fromColor(colour).saturation, lessThan(0.25),
              reason: '$name $label is saturated');
          // And readable, since things get written on them.
          final on = switch (label) {
            'primaryContainer' => scheme.onPrimaryContainer,
            'secondaryContainer' => scheme.onSecondaryContainer,
            _ => scheme.onTertiaryContainer,
          };
          expect(ratio(on, colour), greaterThan(4.5),
              reason: '$name $label cannot be written on');
        }
        // Error keeps its red. That one is saying something.
        expect(HSLColor.fromColor(scheme.errorContainer).saturation,
            greaterThan(0.5),
            reason: '$name lost the one colour that carries meaning');
      }
    });

    test('a selected chip does not look like an unselected one', () {
      // With the container tones neutralised, a selected chip fell through to
      // the same grey as an unselected one and the filter row stopped saying
      // which filter was on.
      for (final (name, theme) in [
        ('light', AppTheme.light),
        ('dark', AppTheme.dark),
      ]) {
        final chip = theme.chipTheme;
        expect(chip.selectedColor, isNotNull, reason: name);
        expect(chip.selectedColor, isNot(chip.backgroundColor), reason: name);
        expect(
            ratio(chip.selectedColor!, chip.backgroundColor!), greaterThan(3.0),
            reason: '$name: selected and unselected are the same to look at');
        // And the label flips with it.
        expect(ratio(chip.secondaryLabelStyle!.color!, chip.selectedColor!),
            greaterThan(4.5),
            reason: '$name: the selected label is unreadable on its own chip');
        expect(ratio(chip.labelStyle!.color!, chip.backgroundColor!),
            greaterThan(4.5),
            reason: '$name: the unselected label is unreadable on its chip');
      }
    });

    testWidgets('an unread chat is the loudest row, not the quietest',
        (t) async {
      // The timestamp and the count on an unread row were painted in a fixed
      // #536471, which is 3.2:1 on the dark background — so the row asking to
      // be read was the dimmest one on the screen. The badge on Alerts was
      // worse: the accent, which flips to near-white in dark, with white
      // written on it.
      for (final (name, theme) in [
        ('light', AppTheme.light),
        ('dark', AppTheme.dark),
      ]) {
        final scheme = theme.colorScheme;
        expect(ratio(scheme.primary, scheme.surface), greaterThan(4.5),
            reason: '$name: an unread row does not stand out');
        expect(ratio(scheme.onPrimary, scheme.primary), greaterThan(4.5),
            reason: '$name: the count on the badge cannot be read');
      }

      // And nothing on the row hard-codes a colour that only works in one of
      // them.
      final src = File('lib/widgets/chat_list_tile.dart').readAsStringSync();
      expect(src.contains('AppColors.lightGreen'), isFalse,
          reason: 'a fixed grey cannot pass both themes');
      final alerts = File('lib/tabs/activity_tab.dart').readAsStringSync();
      expect(alerts.contains('color: Colors.white,\n'), isFalse,
          reason: 'white on the accent is white on white in dark mode');
    });

    testWidgets('no screen in the app is a slab of one colour', (t) async {
      // The sweep, applied to the screens that had a big coloured block on
      // them. Each one shipped as a gradient somebody liked in isolation, and
      // together they were four different loud colours in an app whose whole
      // identity is black and white.
      t.view.physicalSize = const Size(430, 2600);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      SharedPreferences.setMockInitialValues({});
      ScoreStore.instance.resetForTest();
      addTearDown(ScoreStore.instance.resetForTest);
      ScoreStore.instance.award(117);

      for (final (name, screen) in <(String, Widget)>[
        ('Okay Score', const ScoreScreen()),
        ('Settings', const SettingsScreen()),
        ('Cloud storage', const CloudSyncScreen()),
      ]) {
        await t.pumpWidget(MaterialApp(theme: AppTheme.dark, home: screen));
        await t.pumpAndSettle();

        for (final box in t.widgetList<Container>(find.byType(Container))) {
          final decoration = box.decoration;
          if (decoration is! BoxDecoration) continue;
          // A gradient across a whole card is the shape this keeps coming
          // back in.
          expect(decoration.gradient, isNull,
              reason: '$name has a gradient block on it again');
          final colour = decoration.color;
          if (colour == null || colour.a < 0.5) continue;
          final rect = t.getRect(find.byWidget(box));
          // Small things may be as loud as they like — the flame on the score
          // card is the point of it. A block is what this is about.
          if (rect.width < 120 || rect.height < 60) continue;
          expect(HSLColor.fromColor(colour).saturation, lessThan(0.25),
              reason: '$name draws a saturated block '
                  '${rect.width.round()}x${rect.height.round()}');
        }
      }
    });

    test('the tip row is a row, not a billboard', () {
      // A full-bleed violet gradient in the middle of Settings, in an app
      // that is greyscale everywhere else. Now an ordinary InfoTile under a
      // section named what people actually look for; the heart keeps the
      // colour and stays the findable mark.
      final src = File('lib/screens/settings_screen.dart').readAsStringSync();
      expect(src.contains('LinearGradient'), isFalse,
          reason: 'the tip jar is a gradient slab again');
      // The two rows became one Store row (everything purchasable now lives
      // on one screen), but the findability the old section bought must
      // survive: somebody scanning Settings for "subscription" still has to
      // land on it.
      expect(src.contains("settingsSectionLabel(context, 'Store')"), isTrue);
      expect(src.contains('Subscriptions, cloud storage'), isTrue,
          reason: 'the word people search the screen for must still be here');
      final store = File('lib/screens/store_screen.dart').readAsStringSync();
      expect(store.contains('Icons.favorite'), isTrue,
          reason: 'the heart is what makes the tip findable');
      expect(store.contains("'Support the developer'"), isTrue);
      expect(store.contains("'Cloud storage'"), isTrue,
          reason: 'the subscription must be visible AS a subscription');
    });

    test('no fixed grey can pass both themes, which is why subtle exists', () {
      // The measurement the sweep came out of. Each of the two greys the app
      // reached for fails in one theme, and not the same one — so there is no
      // shade to pick, only a theme colour to ask for.
      final light = AppTheme.light.colorScheme;
      final dark = AppTheme.dark.colorScheme;

      expect(ratio(Colors.grey.shade600, dark.surface), lessThan(4.5),
          reason: 'shade600 is the one that fails on dark');
      expect(ratio(Colors.grey.shade500, light.surface), lessThan(4.5),
          reason: 'and shade500 is the one that fails on light');

      // What replaced them, in both.
      for (final (name, scheme) in [('light', light), ('dark', dark)]) {
        expect(ratio(scheme.onSurfaceVariant, scheme.surface),
            greaterThanOrEqualTo(4.5),
            reason: 'secondary text is unreadable on $name');
        // And the ordinary text colour, while we are here.
        expect(
            ratio(scheme.onSurface, scheme.surface), greaterThanOrEqualTo(7.0),
            reason: 'body text should be comfortable on $name, not just legal');
      }
    });

    test('nothing outside the theme picks a colour the theme should pick', () {
      // The whole of lib/, not a list of files that goes stale. There were
      // 300 fixed greys and 67 hard-coded light accents; what is left is
      // named below, with the reason, and nothing else may join them.
      const allowed = {
        // The themes' own definitions. A light-only grey inside AppTheme.light
        // is not a bug — that theme knows which one it is.
        'lib/theme/app_theme.dart',
        // Avatar swatch fallbacks: a colour painted BEHIND initials, judged
        // against the initials rather than against the page.
        'lib/screens/group_info_screen.dart',
        'lib/screens/edit_group_screen.dart',
      };
      final offenders = <String>[];
      for (final f in Directory('lib').listSync(recursive: true)) {
        if (f is! File || !f.path.endsWith('.dart')) continue;
        if (allowed.contains(f.path)) continue;
        final src = f.readAsStringSync();
        for (final banned in [
          'Colors.grey.shade500',
          'Colors.grey.shade600',
          'Colors.grey.shade700',
          // The trap app_theme.dart documents in so many words: "hard-coding
          // it paints a near-black button onto a near-black screen".
          'AppColors.tealGreenDark',
        ]) {
          if (src.contains(banned)) offenders.add('${f.path} → $banned');
        }
      }
      expect(offenders, isEmpty,
          reason: 'these pick a fixed colour where the theme has one:\n'
              '${offenders.join('\n')}');
    });

    testWidgets('the same screen is readable in both themes', (t) async {
      // Measured on what is actually painted, not on the palette. A colour
      // that passes in the abstract is still wrong if the widget draws it on
      // something other than the surface it was checked against.
      t.view.physicalSize = const Size(390, 844);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);

      for (final (name, theme) in [
        ('light', AppTheme.light),
        ('dark', AppTheme.dark),
      ]) {
        await t.pumpWidget(MaterialApp(
          theme: theme,
          home: const Scaffold(
            body: EmptyState(
              icon: Icons.chat_bubble_outline,
              title: 'No chats yet',
              caption: 'Start a private, end-to-end encrypted conversation.',
            ),
          ),
        ));
        await t.pumpAndSettle();

        final surface = theme.colorScheme.surface;
        for (final finder in [
          find.text('No chats yet'),
          find.text('Start a private, end-to-end encrypted conversation.'),
        ]) {
          final colour = t.widget<Text>(finder).style?.color ??
              theme.textTheme.bodyMedium!.color!;
          expect(ratio(colour, surface), greaterThanOrEqualTo(4.5),
              reason: 'an empty state is unreadable on $name');
        }
      }
    });
  });

  group('Getting around', () {
    Future<void> home(WidgetTester t,
        {double width = 390, double height = 844}) async {
      t.view.physicalSize = Size(width, height);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      await t.pumpWidget(const OkayMessagingApp());
      await t.pumpAndSettle();
    }

    /// The pill in the floating bar, named rather than found by icon: the
    /// Servers empty state draws `Icons.groups_outlined` too, so finding the
    /// pill by its glyph can land on the illustration instead.
    Finder navPill(String label) =>
        find.byKey(HomeScreen.debugNavPillKey(label));

    /// Notifications left the bottom bar for the newsfeed's top-right (the
    /// owner's call), so reaching it is two taps now — and the tests use the
    /// real route rather than poking the tab index.
    Future<void> openNotifications(WidgetTester t) async {
      await t.tap(navPill('Newsfeed'));
      await t.pumpAndSettle();
      await t.tap(find.byTooltip('Notifications'));
      await t.pumpAndSettle();
    }

    testWidgets('back leaves the tab you are on before it leaves the app',
        (t) async {
      // Android's back gesture and the browser's back button both closed the
      // app outright from a tab nobody had navigated *to*. The bar is
      // navigation; back has to undo it first.
      await home(t);
      // Any tab proves the point; Calls is one that still has a pill now
      // that Notifications moved to the newsfeed's top-right.
      await t.tap(navPill('Calls'));
      await t.pumpAndSettle();
      expect(find.text('Calls'), findsWidgets);

      final popped = await t.binding.handlePopRoute(); // the system back button
      await t.pumpAndSettle();
      expect(popped, isTrue, reason: 'the app handled it rather than exiting');
      expect(
          find.descendant(
              of: find.byType(AppBar), matching: find.byType(BrandMark)),
          findsOneWidget,
          reason: 'back from a tab lands on Chats, which wears the mark');

      // And from Chats it is a real pop again, so the app can still be left.
      expect(await t.binding.handlePopRoute(), isFalse);
    });

    testWidgets('tapping the tab you are on scrolls it back to the top',
        (t) async {
      // Short enough that the conversation list actually overflows — at
      // 390x844 the sample chats fit, and a list with nowhere to go proves
      // nothing about coming back.
      await home(t, height: 460);
      // The conversation list itself, not whichever Scrollable happens to be
      // first in the tree — a horizontal chip row would answer to that. Held
      // by reference: the row it was found through scrolls out of the tree.
      final list = t.state<ScrollableState>(find
          .ancestor(
              of: find.text('Alice Bennett'), matching: find.byType(Scrollable))
          .first);
      await t.drag(find.text('Alice Bennett'), const Offset(0, -200));
      await t.pumpAndSettle();
      expect(list.position.pixels, greaterThan(0), reason: 'the list moved');

      await t.tap(navPill('Chats')); // already selected
      await t.pumpAndSettle();
      expect(list.position.pixels, 0,
          reason: 'a second tap on the current tab returns to the top');
    });

    testWidgets('a re-tap is safe on a tab that is not a plain list',
        (t) async {
      // The profile tab carries its own tab bar and a grid, so it is the one
