          await openNotifications(t);
        } else {
          await t.tap(navPill(label));
          await t.pumpAndSettle();
        }
      }

      for (final width in [320.0, 390.0]) {
        for (final label in [
          'Chats',
          'Servers',
          'Calls',
          'Notifications',
          'You'
        ]) {
