    testWidgets('a blank screen carries the action it names', (t) async {
      // "Tap the compose button to start a conversation" pointed at an icon in
      // the corner. EmptyState has always taken a button; four screens told
      // people what to do and made them go and find it.
      addTearDown(ChatStore.instance.reset);
      for (final c in [...ChatStore.instance.chats]) {
        ChatStore.instance.deleteChat(c.id);
      }
      await home(t);
      expect(find.text('No chats yet'), findsOneWidget);
      await t.tap(find.widgetWithText(FilledButton, 'Start a chat'));
      await t.pumpAndSettle();
      expect(t.takeException(), isNull);
      expect(find.text('No chats yet'), findsNothing,
          reason: 'the button opens the compose screen');
    });

    testWidgets('every themed text style is drawn in the app\'s own type',
        (t) async {
      // A component theme's textStyle does NOT inherit the textTheme's family,
      // so the app bar title and every filled button were being drawn in
      // whatever the platform picked instead of Roboto. Invisible on iOS,
      // where the fallback happens to look similar; not on the web.
      // Comments stripped first: the explanations for exactly this are long
      // enough to push `fontFamily` out of any fixed window after the match.
      final theme = File('lib/theme/app_theme.dart')
          .readAsStringSync()
          .split('\n')
          .where((l) => !l.trimLeft().startsWith('//'))
          .join('\n');
      final styles =
          RegExp(r'(?:title)?[tT]extStyle:\s*(?:const\s*)?TextStyle\(')
              .allMatches(theme);
      expect(styles.length, greaterThan(3),
          reason: 'the regex stopped matching the component themes');
      for (final m in styles) {
        final body =
            theme.substring(m.end, math.min(m.end + 200, theme.length));
        expect(body.contains("fontFamily: 'Roboto'"), isTrue,
            reason: 'a themed style at offset ${m.start} names no font family');
      }
    });
  });

  group('Suggested replies', () {
    setUp(() => SmartReplies.instance.resetForTest());
    tearDown(() => SmartReplies.instance.resetForTest());

    test('nothing is suggested until the other person has spoken', () {
      DateTime t(int m) => DateTime.now().subtract(Duration(minutes: m));
      Message msg(String id, String text, bool mine) =>
          Message(id: id, text: text, time: t(1), isMe: mine);

      // Answering yourself, or starting the conversation for somebody.
      expect(SmartReplies.worthSuggesting(const []), isFalse);
      expect(SmartReplies.worthSuggesting([msg('a', 'hi', true)]), isFalse);
      expect(SmartReplies.worthSuggesting([msg('a', 'hi', false)]), isTrue);
      expect(
          SmartReplies.worthSuggesting(
              [msg('a', 'hi', false), msg('b', 'hello', true)]),
          isFalse,
          reason: 'you spoke last');
    });

    test('the transcript stays inside the model\'s context window', () {
      // The on-device model has about 4,000 tokens for the prompt AND the
      // answer together. A long conversation must not be able to overrun it —
      // this is the check that the cap is real rather than aspirational.
      final many = [
        for (var i = 0; i < 500; i++)
          Message(
              id: 'm$i',
              text: 'A message of some length, number $i, with words in it.',
              time: DateTime.now().subtract(Duration(minutes: 500 - i)),
              isMe: i.isEven),
      ];
      final transcript = SmartReplies.transcriptFor(many, 'Bob');
      expect(transcript.length, lessThanOrEqualTo(4000));
      expect(transcript.split('\n').length, lessThanOrEqualTo(20));
      // And it keeps the RECENT end — the old end is what may be dropped.
      expect(transcript, contains('number 499'));
      expect(transcript, isNot(contains('number 0,')));
    });

    test('one long message cannot eat the whole budget', () {
      final wall = Message(
          id: 'w', text: 'x' * 20000, time: DateTime.now(), isMe: false);
      final transcript = SmartReplies.transcriptFor([wall], 'Bob');
      expect(transcript.length, lessThan(600),
          reason: 'a pasted wall of text is trimmed, not passed whole');
    });

    test('the transcript says who wrote each line', () {
      final messages = [
        Message(
            id: 'a',
            text: 'are you free tomorrow',
            time: DateTime.now(),
            isMe: false),
      ];
      expect(SmartReplies.transcriptFor(messages, 'Bob'),
          'Bob: are you free tomorrow');
      expect(SmartReplies.transcriptFor(messages, ''),
          'Them: are you free tomorrow',
          reason: 'a nameless contact still needs a label');
    });

    testWidgets('a device that cannot generate suggests nothing at all',
        (t) async {
      // THE RULE THIS PROTECTS. Most iPhones have no Apple Intelligence, and
      // the web build has no channel. On those, the honest answer is silence —
      // a canned suggestion would be invented words attributed to nobody.
      SmartReplies.debugAvailableOverride = false;
      final replies = await SmartReplies.instance.suggest(
        messages: [
          Message(id: 'a', text: 'hi', time: DateTime.now(), isMe: false),
        ],
        contactName: 'Bob',
      );
      expect(replies, isEmpty);
    });

    testWidgets('blank and duplicate suggestions are dropped', (t) async {
      SmartReplies.debugAvailableOverride = true;
      SmartReplies.debugSuggestOverride = (_, __) async => [
            'Sounds good',
            '   ',
            'sounds good',
            'Can we do Friday?',
          ];
      final replies = await SmartReplies.instance.suggest(
        messages: [
          Message(id: 'a', text: 'hi', time: DateTime.now(), isMe: false),
        ],
        contactName: 'Bob',
      );
      expect(replies, ['Sounds good', 'Can we do Friday?'],
          reason: 'the model is asked for three, not promised three distinct');
    });

    testWidgets('a suggestion fills the composer and is not sent',
        (tester) async {
      // Tapping a guess must never put it in somebody else's chat on its own.
      final sent = <String>[];
      await tester.pumpWidget(MaterialApp(
        home: Scaffold(
          body: Column(children: [
            const Spacer(),
            ChatInputBar(
              onSend: sent.add,
              suggestedReplies: const ['Sounds good', 'Can we do Friday?'],
            ),
          ]),
        ),
      ));
      await tester.pumpAndSettle();

      await tester.tap(find.text('Sounds good'));
      await tester.pumpAndSettle();

      expect(sent, isEmpty,
          reason: 'a tapped suggestion is a draft, not a send');
      expect(find.widgetWithText(TextField, 'Sounds good'), findsOneWidget);
      // And once there is text, the alternatives get out of the way.
      expect(find.text('Can we do Friday?'), findsNothing);
    });
  });

  group('A channel is not a one-way street', () {
    // Posting was the only channel action that ever left the device. Deleting,
    // editing, reacting and pinning all stopped at the phone that did them —
    // so "Delete" removed a message for its author and nobody else, and a
    // moderator had no way to remove anyone else's at all.

    /// A server whose creator is the owner, with one text channel holding one
    /// message from somebody else.
    (Community, Channel) seedServer({String name = 'Guild'}) {
      final community = CommunityStore.instance.createCommunity(name);
      final channel = CommunityStore.instance
          .byId(community.id)!
          .channels
          .firstWhere((c) => c.type == ChannelType.text);
      return (CommunityStore.instance.byId(community.id)!, channel);
    }

    setUp(() {
      SharedPreferences.setMockInitialValues({});
      CommunityStore.instance.resetForTest();
    });
    tearDown(CommunityStore.instance.resetForTest);

    test('a toggle reports which way it went, because a relay cannot guess',
        () {
      final (community, channel) = seedServer();
      CommunityStore.instance.postMessage(
          community.id,
          channel.id,
          Message(
              id: 'm1',
              text: 'hello',
              time: DateTime.now(),
              isMe: true,
              status: MessageStatus.sent));

      final store = CommunityStore.instance;
      expect(store.toggleChannelReaction(community.id, channel.id, 'm1', '👍'),
          isTrue,
          reason: 'a reaction that was not there is now on');
      expect(store.toggleChannelReaction(community.id, channel.id, 'm1', '👍'),
          isFalse);
      expect(store.togglePinChannelMessage(community.id, channel.id, 'm1'),
          isTrue);
      expect(store.togglePinChannelMessage(community.id, channel.id, 'm1'),
          isFalse);
    });

    test('setting a reaction is idempotent, so two arrivals are one reaction',
        () {
      final (community, channel) = seedServer();
      final store = CommunityStore.instance;
      store.postMessage(
          community.id,
          channel.id,
          Message(
              id: 'm1',
              text: 'hi',
              time: DateTime.now(),
              isMe: false,
              status: MessageStatus.delivered));

      store.setChannelReaction(community.id, channel.id, 'm1', '🔥', add: true);
      store.setChannelReaction(community.id, channel.id, 'm1', '🔥', add: true);
      expect(store.messageInChannel(community.id, channel.id, 'm1')!.reactions,
          ['🔥'],
          reason: 'a redelivered event must not double the emoji');

      store.setChannelReaction(community.id, channel.id, 'm1', '🔥',
          add: false);
      store.setChannelReaction(community.id, channel.id, 'm1', '🔥',
          add: false);
      expect(store.messageInChannel(community.id, channel.id, 'm1')!.reactions,
          isEmpty);
    });

    test(
        'channel reactions record WHO reacted, so a second member reacting '
        'does not toggle off the first member\'s reaction', () {
      final (community, channel) = seedServer();
      final store = CommunityStore.instance;
      store.postMessage(
          community.id,
          channel.id,
          Message(
              id: 'm1',
              text: 'hi',
              time: DateTime.now(),
              isMe: false,
              status: MessageStatus.delivered));
      Message msg() => store.messageInChannel(community.id, channel.id, 'm1')!;

      // Before per-reactor tracking, the model held one flag per emoji, not
      // one per reactor — so a second member reacting with an already-
      // present emoji would toggle it OFF for everyone. That is exactly what
      // this test would have caught: two named reactors both land, and each
      // clears independently.
      expect(
          store.toggleChannelReaction(
              community.id, channel.id, 'm1', '👍',
              reactor: '15550001111'),
          isTrue);
      expect(
          store.toggleChannelReaction(
              community.id, channel.id, 'm1', '👍',
              reactor: '15550002222'),
          isTrue,
          reason: 'a second reactor must not read as un-reacting the first');
      expect(msg().reactions.contains('👍'), isTrue);
      expect(msg().reactionsBy['👍'], ['15550001111', '15550002222']);

      // The first reactor removes theirs — the emoji stays, the second still
      // holds it.
      expect(
          store.toggleChannelReaction(
              community.id, channel.id, 'm1', '👍',
              reactor: '15550001111'),
          isFalse);
      expect(msg().reactions.contains('👍'), isTrue);
      expect(msg().reactionsBy['👍'], ['15550002222']);

      // The last holder removes theirs — now the emoji clears entirely.
      expect(
          store.toggleChannelReaction(
              community.id, channel.id, 'm1', '👍',
              reactor: '15550002222'),
          isFalse);
      expect(msg().reactions.contains('👍'), isFalse);
      expect(msg().reactionsBy.containsKey('👍'), isFalse);
    });

    test('a relayed edit rewrites somebody else\'s message; a local one cannot',
        () {
      final (community, channel) = seedServer();
      final store = CommunityStore.instance;
      store.postMessage(
          community.id,
          channel.id,
          Message(
              id: 'theirs',
              text: 'original',
              time: DateTime.now(),
              isMe: false,
              status: MessageStatus.delivered,
              senderName: 'Ada'));

      // The local path refuses: nobody rewrites another member's words from
      // their own device.
      store.editChannelMessage(community.id, channel.id, 'theirs', 'tampered');
      expect(store.messageInChannel(community.id, channel.id, 'theirs')!.text,
          'original');

      // The relayed path is the author's own edit arriving here, so it lands.
      store.applyRemoteChannelEdit(
          community.id, channel.id, 'theirs', 'second thoughts');
      final edited =
          store.messageInChannel(community.id, channel.id, 'theirs')!;
      expect(edited.text, 'second thoughts');
      expect(edited.edited, isTrue);
      expect(edited.originalText, 'original');
    });

    test('leaving a server takes the leaver off everyone else\'s roster', () {
      // Leaving used to be PURELY LOCAL: the server vanished from the
      // leaver's phone and nobody else was told. Every remaining device kept
      // them on the roster forever — the member count stayed wrong, a mailbox
      // copy of every message went on being queued for somebody who had gone,
      // and the sender keys were never rotated, because nothing removed them.
      final (community, _) = seedServer();
      final store = CommunityStore.instance;
      final secret = store.byId(community.id)!.secretBytes!;
      store.addMember(
          community.id,
          Member(
              id: CommunityStore.wireId('15550102222'),
              name: 'Bo',
              role: MemberRole.member));
      expect(
          store
              .byId(community.id)!
              .members
              .any((m) => m.id == CommunityStore.wireId('15550102222')),
          isTrue);

      // Rotation is the point of the whole thing, so watch for it rather
      // than trusting that the roster edit implies it.
      var rotated = '';
      store.onMemberRemoved = (id) => rotated = id;
      addTearDown(() => store.onMemberRemoved = null);

      RelayService.instance.debugApplyCommunityEvent(
        'chleave',
        {
          'from': '+15550102222',
          'communityId': community.id,
          'data': E2eCrypto.encrypt(secret, jsonEncode(const {})),
        },
        '+15550101111',
      );

      expect(
          store
              .byId(community.id)!
              .members
              .any((m) => m.id == CommunityStore.wireId('15550102222')),
          isFalse,
          reason: 'the leaver is still on the roster');
      expect(rotated, community.id,
          reason: 'the sender keys were not rotated on departure — a '
              'departed member reads everything sent after they left');
    });

    test('leaving announces itself before the local copy is destroyed', () {
      // Order matters and cannot be checked at runtime here: sealing and the
      // mailbox fan-out both need the secret and the roster, and
      // deleteCommunity takes both away.
      final src =
          File('lib/screens/community_settings_screen.dart').readAsStringSync();
      final announce = src.indexOf('sendServerLeave(communityId)');
      final destroy = src.indexOf('deleteCommunity(communityId)');
      expect(announce, greaterThan(-1), reason: 'leaving tells nobody again');
      expect(announce, lessThan(destroy),
          reason: 'the local copy is destroyed before the leave is sent, so '
              'there is no secret left to seal it with');
    });

    test('a received chdel/chedt/chrxn/chpin actually changes the channel', () {
      // Through the real routing — a switch with no case for an event is
      // exactly the bug this is here to catch.
      final (community, channel) = seedServer();
      final store = CommunityStore.instance;
      final secret = store.byId(community.id)!.secretBytes!;
      store.postMessage(
          community.id,
          channel.id,
          Message(
              id: 'm1',
              text: 'first',
              time: DateTime.now(),
              isMe: false,
              status: MessageStatus.delivered,
              senderName: 'Ada'));

      Map<String, dynamic> sealed(Map<String, dynamic> body) => {
            'from': '+15550102222',
            'communityId': community.id,
            'data': E2eCrypto.encrypt(secret, jsonEncode(body)),
          };
      void deliver(String event, Map<String, dynamic> body) =>
          RelayService.instance
              .debugApplyCommunityEvent(event, sealed(body), '+15550101111');

      deliver('chrxn', {
        'channelId': channel.id,
        'id': 'm1',
        'emoji': '🎉',
        'add': true,
      });
      expect(store.messageInChannel(community.id, channel.id, 'm1')!.reactions,
          ['🎉']);

      deliver('chedt', {
        'channelId': channel.id,
        'id': 'm1',
        'text': 'first, actually',
      });
      expect(store.messageInChannel(community.id, channel.id, 'm1')!.text,
          'first, actually');

      deliver('chpin', {
        'channelId': channel.id,
        'id': 'm1',
        'pinned': true,
      });
      expect(
          store
              .byId(community.id)!
              .channels
              .firstWhere((c) => c.id == channel.id)
              .pinnedMessageIds,
          contains('m1'));

      deliver('chdel', {'channelId': channel.id, 'id': 'm1'});
      expect(store.messageInChannel(community.id, channel.id, 'm1'), isNull);
      expect(
          store
              .byId(community.id)!
              .channels
              .firstWhere((c) => c.id == channel.id)
              .pinnedMessageIds,
          isEmpty,
          reason: 'a deleted message must not stay on the pin banner');
    });

    test('a channel message picks up delivered/read ticks, coarse like a group',
        () {
      final (community, channel) = seedServer();
      final store = CommunityStore.instance;
      store.addMember(
          community.id, const Member(id: 'u_15550103333', name: 'Chen'));
      final secret = store.byId(community.id)!.secretBytes!;
      store.postMessage(
          community.id,
          channel.id,
          Message(
              id: 'm1',
              text: 'anyone around?',
              time: DateTime.now(),
              isMe: true,
              status: MessageStatus.sent));

      Map<String, dynamic> sealed(Map<String, dynamic> body) => {
            'from': '+15550102222',
            'communityId': community.id,
            'data': E2eCrypto.encrypt(secret, jsonEncode(body)),
          };
      void deliver(String event, Map<String, dynamic> body) =>
          RelayService.instance
              .debugApplyCommunityEvent(event, sealed(body), '+15550101111');

      deliver(
          'chack', {'channelId': channel.id, 'kind': 'delivered', 'id': 'm1'});
      expect(store.messageInChannel(community.id, channel.id, 'm1')!.status,
          MessageStatus.delivered,
          reason: 'the first ack upgrades the whole channel, like a group');
      expect(store.messageInChannel(community.id, channel.id, 'm1')!.seenBy,
          isEmpty,
          reason: 'delivered is ticks-only — it does not name who');

      deliver('chack', {'channelId': channel.id, 'kind': 'read', 'id': 'm1'});
      final afterRead = store.messageInChannel(community.id, channel.id, 'm1')!;
      expect(afterRead.status, MessageStatus.read);
      expect(afterRead.seenBy, ['15550102222'],
          reason: 'a read ack records who, unlike delivered');

      // A second read ack from someone else advances "seen by" without
      // downgrading anything, and a stale delivered ack from a third
      // party never regresses an already-read status.
      RelayService.instance.debugApplyCommunityEvent(
          'chack',
          {
            'from': '+15550103333',
            'communityId': community.id,
            'data': E2eCrypto.encrypt(
                secret,
                jsonEncode({
                  'channelId': channel.id,
                  'kind': 'read',
                  'id': 'm1',
                })),
          },
          '+15550101111');
      final afterBoth = store.messageInChannel(community.id, channel.id, 'm1')!;
      expect(afterBoth.seenBy.toSet(), {'15550102222', '15550103333'});
      expect(afterBoth.status, MessageStatus.read,
          reason: 'status never regresses below its high-water mark');
    });

    test(
        'a channel message arriving over the wire keeps its voice, thread '
        'and view-once fields (the fix for a whitelist that used to drop '
        'them)', () {
      final (community, channel) = seedServer();
      final store = CommunityStore.instance;
      final secret = store.byId(community.id)!.secretBytes!;
      store.postMessage(
          community.id,
          channel.id,
          Message(
              id: 'root1',
              text: 'root',
              time: DateTime.now(),
              isMe: true,
              status: MessageStatus.sent));

      final wireMsg = Message(
        id: 'm_voice',
        text: '',
        time: DateTime.now(),
        isMe: true, // the SENDER's own local flag; must not survive receipt
        status: MessageStatus.sent,
        isVoice: true,
        voiceSeconds: 12,
        audioUrl: 'data:audio/mp4;base64,AAA',
        threadRootId: 'root1',
        viewOnce: true,
      );
      RelayService.instance.debugApplyCommunityEvent(
          'chmsg',
          {
            'from': '+15550102222',
            'communityId': community.id,
            'data': E2eCrypto.encrypt(
                secret,
                jsonEncode({
                  'channelId': channel.id,
                  'senderName': 'Chen',
                  'message': wireMsg.toJson(),
                })),
          },
          '+15550101111');

      final received = store.messageInChannel(community.id, channel.id, 'm_voice')!;
      expect(received.isVoice, isTrue);
      expect(received.voiceSeconds, 12);
      expect(received.audioUrl, 'data:audio/mp4;base64,AAA');
      expect(received.threadRootId, 'root1');
      expect(received.viewOnce, isTrue);
      expect(received.viewOnceOpened, isFalse,
          reason: 'never copied — a fresh delivery is always unopened');
      expect(received.isMe, isFalse,
          reason: 'isMe is recomputed fresh on receipt, never trusted off the wire');
    });

