  group('Messages over Bluetooth', () {
    Map<String, dynamic> sealed({String body = 'ciphertext'}) =>
        {'v': 2, 'id': 'm1', 'from': '+15550101111', 'enc': body};

    setUp(() {
      SharedPreferences.setMockInitialValues({});
      MeshService.instance.resetForTest();
    });
    tearDown(() {
      MeshService.instance.resetForTest();
      MeshService.debugAvailableOverride = null;
      MeshService.debugSendOverride = null;
    });

    test('a packet carries only what a router needs, and never opens the rest',
        () {
      final packet =
          MeshPacket(id: 'm1', to: '15550102222', ttl: 5, payload: sealed());
      final wire = jsonDecode(packet.encode()) as Map<String, dynamic>;
      // Addressing and hop count in the clear, because routing needs them.
      expect(wire['to'], '15550102222');
      expect(wire['ttl'], 5);
      // And the body untouched — a relay must not be able to read it, so
      // nothing here may transform, re-encrypt, or inspect it.
      expect(wire['p'], sealed());
      final back = MeshPacket.decode(packet.encode())!;
      expect(back.payload, sealed());
    });

    test('anything off the air that is not exactly right is refused', () {
      String wire(Map<String, dynamic> over) => jsonEncode({
            'v': 1,
            'id': 'm1',
            'to': '1555',
            'ttl': 3,
            'p': sealed(),
            ...over,
          });
      expect(MeshPacket.decode(wire(const {})), isNotNull);
      // Everything here arrived from a device nobody vouched for.
      expect(MeshPacket.decode('not json'), isNull);
      expect(MeshPacket.decode(wire(const {'v': 2})), isNull,
          reason: 'a version this cannot parse is not a packet to guess at');
      expect(MeshPacket.decode(wire(const {'id': ''})), isNull);
      expect(MeshPacket.decode(wire(const {'p': 'a string'})), isNull);
      // A hop count above the ceiling is REFUSED, not clamped — clamping
      // would let one sender hand every phone in range a packet with a
      // lifetime of its choosing.
      expect(MeshPacket.decode(wire({'ttl': MeshPacket.maxTtl + 1})), isNull);
      expect(MeshPacket.decode(wire(const {'ttl': -1})), isNull);
      // And nothing enormous, whatever it claims to be.
      expect(MeshPacket.decode('x' * (MeshPacket.maxBytes + 1)), isNull);
    });

    test('a photo does not go by Bluetooth, and a sentence does', () {
      // A radio that moves a few KB a second is a minute a hop for a photo.
      expect(MeshPacket.fits({'enc': 'x' * 200}), isTrue);
      expect(MeshPacket.fits({'enc': 'x' * 140000}), isFalse,
          reason: 'this app caps a photo at 140k base64 — it must not mesh');
    });

    test('a flood stops', () {
      // The whole safety property: without dedup, three phones in a ring hand
      // the same packet round for as long as they are in range.
      final router = MeshRouter(myDigits: '15550102222');
      final packet =
          MeshPacket(id: 'm1', to: '15550102222', ttl: 3, payload: sealed());
      expect(router.accept(packet), MeshAction.deliverAndRelay);
      expect(router.accept(packet), MeshAction.drop,
          reason: 'the second time round it must stop');
      expect(router.accept(packet.withTtl(2)), MeshAction.drop,
          reason: 'and the same message at a different hop count is the same '
              'message');
    });

    test('a packet dies when it runs out of hops', () {
      final router = MeshRouter(myDigits: '15550109999');
      final far =
          MeshPacket(id: 'm1', to: '15550102222', ttl: 0, payload: sealed());
      expect(router.accept(far), MeshAction.drop);
      expect(router.forwarded(far), isNull);

      // One with hops left is passed on, one hop shorter, and the original is
      // not touched — it may still be needed to deliver.
      final near =
          MeshPacket(id: 'm2', to: '15550102222', ttl: 3, payload: sealed());
      expect(router.accept(near), MeshAction.relay);
      expect(router.forwarded(near)!.ttl, 2);
      expect(near.ttl, 3);
    });

    test('a phone carries a stranger\'s message but does not open it', () {
      final router = MeshRouter(myDigits: '15550109999');
      final theirs =
          MeshPacket(id: 'm1', to: '15550102222', ttl: 3, payload: sealed());
      expect(router.accept(theirs), MeshAction.relay,
          reason: 'not addressed here — carry it, do not deliver it');
    });

    test('your own message coming back is not a message you received', () {
      final router = MeshRouter(myDigits: '15550101111', memory: 4);
      router.noteSent('m1');
      // A neighbour relays it straight back: the seen-set catches that.
      final echo =
          MeshPacket(id: 'm1', to: '15550101111', ttl: 4, payload: sealed());
      expect(router.accept(echo), MeshAction.drop);

      // The case that needs its own record: a busy room pushes the send out
      // of the seen-set, and the echo arrives after that. Without a separate
      // memory of what this phone originated, its own message is delivered
      // back to it as an incoming one.
      for (var i = 0; i < 20; i++) {
        router.accept(MeshPacket(
            id: 'other$i', to: '15550109999', ttl: 2, payload: sealed()));
      }
      expect(router.hasSeen('m1'), isFalse, reason: 'aged out, as designed');
      expect(router.accept(echo), MeshAction.drop,
          reason: 'this phone sent it — it is not a message it received');
    });

    test('a message for you is delivered and still passed on', () {
      // A group message is addressed to each member separately, so the phone
      // behind this one may not have heard its own copy yet.
      final router = MeshRouter(myDigits: '15550102222');
      final mine =
          MeshPacket(id: 'm1', to: '15550102222', ttl: 2, payload: sealed());
      expect(router.accept(mine), MeshAction.deliverAndRelay);

      final last =
          MeshPacket(id: 'm2', to: '15550102222', ttl: 0, payload: sealed());
      expect(router.accept(last), MeshAction.deliver,
          reason: 'nothing left to relay with, but still ours to open');
    });

    test('what it remembers is bounded', () {
      final router = MeshRouter(myDigits: '1', memory: 4);
      for (var i = 0; i < 50; i++) {
        router
            .accept(MeshPacket(id: 'm$i', to: '2', ttl: 2, payload: sealed()));
      }
      expect(router.rememberedCount, lessThanOrEqualTo(4),
          reason: 'a phone left running must not grow a list forever');
      expect(router.hasSeen('m49'), isTrue);
      expect(router.hasSeen('m0'), isFalse, reason: 'oldest out first');
    });

    test('a packet survives being cut up and put back together', () {
      final packet = MeshPacket(
          id: 'm1',
          to: '15550102222',
          ttl: 5,
          payload: sealed(body: 'y' * 900));
      final raw = packet.encode();
      final frames = MeshChunks.split(raw);
      expect(frames.length, greaterThan(1), reason: 'this needs chunking');

      final reassembler = MeshReassembler();
      String? whole;
      for (final f in frames) {
        whole = reassembler.add(f) ?? whole;
      }
      expect(whole, raw);
      expect(MeshPacket.decode(whole!)!.payload, packet.payload);
      expect(reassembler.pendingCount, 0, reason: 'nothing left half-done');
    });

    test('two senders at once do not fill each other\'s buffer', () {
      // Two neighbours mid-packet at the same moment is the ordinary case in
      // a room, not an edge one.
      final a = MeshPacket(
          id: 'a', to: '1', ttl: 5, payload: sealed(body: 'a' * 600));
      final b = MeshPacket(
          id: 'b', to: '2', ttl: 5, payload: sealed(body: 'b' * 600));
      final fa = MeshChunks.split(a.encode());
      final fb = MeshChunks.split(b.encode());
      final reassembler = MeshReassembler();

      final done = <String>[];
      // Interleaved, the way two radios actually arrive.
      for (var i = 0;
          i < (fa.length > fb.length ? fa.length : fb.length);
          i++) {
        if (i < fa.length) {
          final w = reassembler.add(fa[i]);
          if (w != null) done.add(w);
        }
        if (i < fb.length) {
          final w = reassembler.add(fb[i]);
          if (w != null) done.add(w);
        }
      }
      expect(done, containsAll([a.encode(), b.encode()]));
    });

    test('a frame that is nonsense, repeated, or lost breaks nothing', () {
      final packet = MeshPacket(
          id: 'm1', to: '1', ttl: 5, payload: sealed(body: 'z' * 400));
      final frames = MeshChunks.split(packet.encode());
      final reassembler = MeshReassembler();

      for (final junk in ['', 'nocolons', 'a:b:c:d', 'id:99:2:x', 'id:0:0:x']) {
        expect(reassembler.add(junk), isNull, reason: junk);
      }
      // Two packets whose frame ids collide, disagreeing about how long the
      // packet is. The half-filled buffer is no longer trustworthy, so it has
      // to be thrown away rather than partly overwritten — otherwise the
      // pieces of two different messages get joined into one.
      expect(reassembler.add('dup:0:3:aaa'), isNull);
      expect(reassembler.add('dup:0:2:bbb'), isNull, reason: 'length changed');
      expect(reassembler.add('dup:1:2:ccc'), isNull,
          reason: 'the poisoned buffer was dropped, so this starts over');
      expect(reassembler.add('dup:0:2:bbb'), 'bbbccc');
      // A frame arriving twice is not a second packet.
      String? whole;
      for (final f in [...frames, ...frames]) {
        whole = reassembler.add(f) ?? whole;
      }
      expect(whole, packet.encode());

      // And one lost frame means no packet, rather than a broken one.
      final short = MeshReassembler();
      for (final f in frames.take(frames.length - 1)) {
        expect(short.add(f), isNull);
      }
    });

    test('a peer that never finishes cannot grow the buffer forever', () {
      final reassembler = MeshReassembler(maxPending: 3);
      for (var i = 0; i < 12; i++) {
        // First frame of a ten-frame packet that never arrives.
        reassembler.add('id$i:0:10:fragment');
      }
      expect(reassembler.pendingCount, lessThanOrEqualTo(4));
    });

    testWidgets('the toggle is off until asked, and says what it costs',
        (t) async {
      MeshService.debugAvailableOverride = true;
      await t.pumpWidget(const MaterialApp(home: PrivacySettingsScreen()));
      await t.pumpAndSettle();

      await t.scrollUntilVisible(find.text('Message people nearby'), 200);
      final tile = t.widget<SwitchListTile>(find.ancestor(
          of: find.text('Message people nearby'),
          matching: find.byType(SwitchListTile)));
      expect(tile.value, isFalse, reason: 'a radio does not start uninvited');
      // The deal is stated: this phone carries other people's messages.
      expect(find.textContaining('passes on other people'), findsOneWidget);
      expect(find.textContaining('without being able to read them'),
          findsOneWidget);
    });

    testWidgets('a device that cannot mesh is not offered a switch', (t) async {
      // Every browser, for a start — Safari has no Web Bluetooth at all, and
      // no platform gives a page the peripheral role.
      MeshService.debugAvailableOverride = false;
      await t.pumpWidget(const MaterialApp(home: PrivacySettingsScreen()));
      await t.pumpAndSettle();
      // Scroll PAST where the tile would be first. A ListView only builds what
      // it can show, so asserting findsNothing on an unscrolled screen proves
      // nothing at all — it passes just as happily when the tile is there.
      await t.scrollUntilVisible(
          find.text('Only my contacts can message me'), 200);
      expect(find.text('Message people nearby'), findsNothing,
          reason: 'a dead switch is a promise the app cannot keep');
    });

    test('sending puts framed packets on the air and remembers them', () async {
      final sent = <String>[];
      MeshService.debugSendOverride = sent.add;
      final mesh = MeshService.instance;

      expect(await mesh.send('15550102222', sealed(), messageId: 'm1'), isTrue);
      expect(sent, isNotEmpty);
      final rebuilt = MeshReassembler();
      String? whole;
      for (final f in sent) {
        whole = rebuilt.add(f) ?? whole;
      }
      final packet = MeshPacket.decode(whole!)!;
      expect(packet.to, '15550102222');
      expect(packet.ttl, MeshPacket.maxTtl, reason: 'a fresh packet is full');
      // And it knows it sent this, so the echo off a neighbour is not
      // delivered back to the sender as an incoming message.
      expect(mesh.router.accept(packet), MeshAction.drop);
    });

    test('an envelope too big for the radio is refused, not attempted',
        () async {
      MeshService.debugSendOverride = (_) {};
      final ok = await MeshService.instance
          .send('15550102222', {'enc': 'x' * 140000}, messageId: 'big');
      expect(ok, isFalse);
    });
  });

  group('Finding a server in the room', () {
    setUp(() {
      SharedPreferences.setMockInitialValues({});
      CommunityStore.instance.resetForTest();
      MeshService.instance.resetForTest();
      NearbyServers.instance.clear();
      // A phone answering a request needs a number and a key pair — without
      // either it has nothing to seal an invite with, and says nothing.
      Session.instance.signInForTest();
      SecureKeyExchange.instance.ensureKeys();
    });
    tearDown(() {
      CommunityStore.instance.resetForTest();
      MeshService.instance.resetForTest();
      NearbyServers.instance.clear();
      MeshService.debugSendOverride = null;
      MeshService.debugAvailableOverride = null;
    });

    /// Everything one phone put on the air, rebuilt into packets.
    List<MeshPacket> packetsFrom(List<String> frames) {
      final rebuilt = MeshReassembler();
      final out = <MeshPacket>[];
      for (final f in frames) {
        final whole = rebuilt.add(f);
        if (whole == null) continue;
        final packet = MeshPacket.decode(whole);
        if (packet != null) out.add(packet);
      }
      return out;
    }

    test('a server is announced only when its owner said it could be', () {
      final air = <String>[];
      MeshService.debugSendOverride = air.add;
      final store = CommunityStore.instance;
      final quiet = store.createCommunity('Private');
      final open = store.createCommunity('Cafe');

      MeshService.instance.debugBeaconNow();
      expect(packetsFrom(air), isEmpty,
          reason: 'being a member is not consent to advertise');

      store.setDiscoverableNearby(open.id, true);
      air.clear();
      MeshService.instance.debugBeaconNow();
      final beacons = packetsFrom(air);
      expect(beacons.length, 1);
      expect(beacons.single.kind, MeshPacket.kindServer);
      expect(beacons.single.payload['name'], 'Cafe');
      expect(beacons.single.payload['id'], open.id);
      expect(beacons.single.payload['id'], isNot(quiet.id));
      // A beacon is public by design, so it carries a name and nothing else.
      expect(beacons.single.payload.containsKey('secret'), isFalse,
          reason: 'the key must never be in the clear');
      expect(beacons.single.payload.containsKey('members'), isTrue);
      expect(beacons.single.isBroadcast, isTrue);
    });

    test('the way in is sealed to whoever asked, not shouted at the room', () {
      // Two devices. One is in the server; the other wants in; a third is
      // simply within earshot.
      final store = CommunityStore.instance;
      final community = store.createCommunity('Cafe');
      store.setDiscoverableNearby(community.id, true);

      final asker = SecureKeyExchange.freshForTest();
      final bystander = SecureKeyExchange.freshForTest();

      final air = <String>[];
      MeshService.debugSendOverride = air.add;
      // The member answers a request carrying the asker's public key.
      MeshService.instance
          .debugAnswerInvite({'cid': community.id, 'pk': asker.myPublicKey});
      final replies = packetsFrom(air);
      expect(replies.length, 1);
      final reply = replies.single;
      expect(reply.kind, MeshPacket.kindInvite);

      // Nothing readable is on the air.
      final blob = reply.payload['blob'] as String;
      expect(blob.contains('Cafe'), isFalse);
      expect(blob.contains(store.byId(community.id)!.secret), isFalse);

      // The asker can open it.
      final theirs = asker.sharedSecretWith(reply.payload['pk'] as String)!;
      final opened = E2eCrypto.decrypt(theirs, blob);
      expect(opened, isNotNull);
      expect(jsonDecode(opened!)['name'], 'Cafe');

      // Somebody else in range cannot, though they heard every byte.
      final notTheirs =
          bystander.sharedSecretWith(reply.payload['pk'] as String)!;
      expect(E2eCrypto.decrypt(notTheirs, blob), isNull,
          reason: 'a reply everyone can read is a key everyone gets');
    });

    test('a server that was never opened up does not answer', () {
      final store = CommunityStore.instance;
      final community = store.createCommunity('Private');
      final asker = SecureKeyExchange.freshForTest();
      final air = <String>[];
      MeshService.debugSendOverride = air.add;

      MeshService.instance
          .debugAnswerInvite({'cid': community.id, 'pk': asker.myPublicKey});
      expect(air, isEmpty, reason: 'nobody asked for this to be findable');

      // Nor does one this phone is not in at all.
      MeshService.instance
          .debugAnswerInvite({'cid': 'someone-elses', 'pk': asker.myPublicKey});
      expect(air, isEmpty);
    });

    test('a member who may not invite may not hand out the key either', () {
      // The server's own invite policy still applies over Bluetooth — it
      // would be an odd door that admins-only locks on the internet and
      // leaves open in the room.
      final store = CommunityStore.instance;
      final owner =
          store.createCommunity('Cafe', invitePolicy: invitePolicyAdmins);
      store.setDiscoverableNearby(owner.id, true);
      final invite =
          store.exportInvite(owner.id, myDigits: '15550101111', myName: 'Ada')!;
      store.deleteCommunity(owner.id);
      final joined = store.joinFromInvite(Map<String, dynamic>.from(invite),
          myDigits: '15550102222', myName: 'Bob')!;
      store.setDiscoverableNearby(joined.id, true);
      expect(store.canInvite(joined.id), isFalse);

      final air = <String>[];
      MeshService.debugSendOverride = air.add;
      MeshService.instance.debugAnswerInvite({
        'cid': joined.id,
        'pk': SecureKeyExchange.freshForTest().myPublicKey,
      });
      expect(air, isEmpty);
    });

    test('what is nearby stops being nearby', () {
      // A beacon is a claim that lasts about as long as being in the room
      // does. Without expiry, "nearby" becomes "was nearby once", which looks
      // joinable and is not.
      final now = DateTime(2026, 8, 1, 12);
      final directory = NearbyServers.instance;
      directory.heard(NearbyServer(
          id: 'c1',
          name: 'Cafe',
          color: '#fff',
          icon: '',
          members: 3,
          heardAt: now));
      expect(directory.servers.length, 1);

      directory.expire(now.add(const Duration(seconds: 30)));
      expect(directory.servers.length, 1, reason: 'still in the room');

      directory.expire(now.add(NearbyServers.linger * 2));
      expect(directory.servers, isEmpty);
    });

    test('several phones in one server make one row, not three', () {
      final now = DateTime(2026, 8, 1, 12);
      final directory = NearbyServers.instance;
      for (var i = 0; i < 3; i++) {
        directory.heard(NearbyServer(
            id: 'c1',
            name: 'Cafe',
            color: '#fff',
            icon: '',
            members: 3,
            heardAt: now.add(Duration(seconds: i))));
      }
      expect(directory.servers.length, 1);
    });

    test('a beacon off the air is not trusted about anything', () {
      final now = DateTime(2026, 8, 1, 12);
      // Nameless, unnamed, or absurd — all from a device nobody vouched for.
      expect(NearbyServer.fromWire(const {'id': 'c1'}, now), isNull);
      expect(NearbyServer.fromWire(const {'id': 'c1', 'name': '   '}, now),
          isNull);
      expect(NearbyServer.fromWire(const {'name': 'Cafe'}, now), isNull);
      final huge = NearbyServer.fromWire(
          {'id': 'c1', 'name': 'x' * 500, 'members': 99999999}, now)!;
      expect(huge.name.length, lessThanOrEqualTo(60),
          reason: 'this is drawn in a list');
      expect(huge.members, 0, reason: 'a nonsense count is no count');
    });

    testWidgets('a server you are already in is not offered as a stranger',
        (t) async {
      final community = CommunityStore.instance.createCommunity('Cafe');
      MeshService.instance.debugDeliver(MeshPacket(
        id: 'b1',
        to: '',
        ttl: 3,
        kind: MeshPacket.kindServer,
        payload: <String, dynamic>{
          'id': community.id,
          'name': 'Cafe',
          'members': 3,
        },
      ));
      expect(NearbyServers.instance.servers, isEmpty,
          reason: 'that is a server, not a nearby one');
      await t.pump();
    });

    testWidgets('a heard server shows up with a way in', (t) async {
      NearbyServers.instance.heard(NearbyServer(
          id: 'c_far',
          name: 'Conference',
          color: '#7A5CFF',
          icon: '',
          members: 12,
          heardAt: DateTime.now()));

      await t.pumpWidget(
          const MaterialApp(home: Scaffold(body: CommunitiesTab())));
      await t.pumpAndSettle();

      expect(find.text('NEARBY'), findsOneWidget);
      expect(find.text('Conference'), findsOneWidget);
      expect(find.textContaining('12 members'), findsOneWidget);
      expect(find.widgetWithText(FilledButton, 'Join'), findsOneWidget);
    });

    testWidgets('nothing about nearby servers shows when nothing is near',
        (t) async {
      await t.pumpWidget(
          const MaterialApp(home: Scaffold(body: CommunitiesTab())));
      await t.pumpAndSettle();
      expect(find.text('NEARBY'), findsNothing,
          reason: 'an empty section is a section nobody wants');
    });

    test('a server event goes on the air with its name inside it', () async {
      // A Bluetooth broadcast has no per-event channel to arrive on, where
      // the Supabase bus subscribes to one name per event — so the name has
      // to travel in the payload or the far end cannot route it.
      final air = <String>[];
      MeshService.debugSendOverride = air.add;
      final ok = await MeshService.instance.sendCommunity({
        'from': '+15550101111',
        'communityId': 'c1',
        'data': 'sealed',
        'e': 'chmsg'
      }, eventId: 'e1');
      expect(ok, isTrue);
      final packet = packetsFrom(air).single;
      expect(packet.kind, MeshPacket.kindCommunity);
      expect(packet.payload['e'], 'chmsg');
      expect(packet.payload['data'], 'sealed');
      expect(packet.isBroadcast, isTrue,
          reason: 'no phone knows which of its neighbours are members');
    });

    test('a broadcast is opened by everyone and still passed on', () {
      // Nobody is addressed, so the old rule — deliver only what is addressed
      // to me — would have dropped every beacon and every server event.
      final router = MeshRouter(myDigits: '15550101111');
      const beacon = MeshPacket(
          id: 'b1',
          to: '',
          ttl: 3,
          kind: MeshPacket.kindServer,
          payload: {'id': 'c1', 'name': 'Cafe'});
      expect(router.accept(beacon), MeshAction.deliverAndRelay);
      expect(router.forwarded(beacon)!.kind, MeshPacket.kindServer,
          reason: 'a relayed packet keeps what it is');
    });
  });

  group('An account with no phone number', () {
    setUp(() async {
      SharedPreferences.setMockInitialValues({});
      ChatStore.instance.reset();
      // The session is a singleton, and an earlier group may have left one
      // signed in — which is exactly what one of these asserts is not true.
      await Session.instance.signOut();
    });

    test('verifying a number upgrades in place, keeping the account', () async {
      await Session.instance.signInWithoutNumber(
          name: 'Ada',
          username: 'ada',
          code: AccountCode.mint(),
          isSignup: true);
      addTearDown(() async {
        await Session.instance.signOut();
        AppState.resetForTest();
      });
      expect(Session.instance.isNumberless, isTrue);

      // Give the account a bit of profile to prove the upgrade keeps it.
      await Session.instance.updateProfile(name: 'Ada', about: 'trying it out');

      // Verifying a number upgrades IN PLACE — not a new account: numbered now,
      // and the handle and profile are kept (the "keep your account" promise).
      await Session.instance.attachNumberInPlace('+1 555 987 6543');
      final me = Session.instance.user.value!;
      expect(Session.instance.isNumberless, isFalse);
      expect(me.phone, '+1 555 987 6543');
      expect(me.username, 'ada');
      expect(me.about, 'trying it out');

      // Source pins: the gate offers the in-place verify, no forced lock.
      expect(
          File('lib/widgets/phone_gate.dart')
              .readAsStringSync()
              .contains('NumberlessVerifyScreen'),
          isTrue);
      expect(
          File('lib/screens/auth/numberless_verify_screen.dart')
              .readAsStringSync()
              .contains('attachNumberInPlace'),
          isTrue);
    });

    test('the address an account is reached at changes once every 30 days',
        () async {
      Session.instance.debugIdentityChangedAt = null;
      addTearDown(() async {
        Session.instance.debugIdentityChangedAt = null;
        await Session.instance.signOut();
        AppState.resetForTest();
      });
      await Session.instance.signInWithoutNumber(
          name: 'Ada',
          username: 'ada',
          code: AccountCode.mint(),
          isSignup: true);

      // Earning a REAL number is never blocked by the clock: an account with
      // no number has nothing to change FROM, and a number is the strongest
      // identity the app has.
      expect(await Session.instance.attachNumberInPlace('+1 555 987 6543'),
          isTrue);
      expect(Session.instance.user.value!.phone, '+1 555 987 6543');
      expect(Session.instance.identityCooldownLeft(),
          greaterThan(const Duration(days: 29)));

      // A second move inside the window is refused, and the identity does not
      // budge — this is what every contact holds and what a ban is recorded
      // against.
      expect(await Session.instance.attachNumberInPlace('+1 555 222 3333'),
          isFalse);
      expect(Session.instance.user.value!.phone, '+1 555 987 6543');
      expect(Session.instance.identityCooldownMessage(), isNotNull);

      // Re-attaching the SAME identity is not a change — `email-account`
      // answers a re-verification with the code it already stamped, and
      // reporting a cooldown for that would name a lock nobody hit.
      expect(await Session.instance.attachNumberInPlace('+1 555 987 6543'),
          isTrue);

      // Thirty-one days on, the address is free to move again.
      Session.instance.debugIdentityChangedAt =
          DateTime.now().subtract(const Duration(days: 31));
      expect(Session.instance.identityCooldownMessage(), isNull);
      expect(await Session.instance.attachNumberInPlace('+1 555 222 3333'),
          isTrue);
      expect(Session.instance.user.value!.phone, '+1 555 222 3333');
      expect(Session.instance.user.value!.username, 'ada',
          reason: 'a move is still an in-place upgrade, not a new account');
    });

    test('both verify screens report a refused attach instead of closing', () {
      // An attach that silently no-ops and pops reads exactly like one that
      // worked — the silent-failure shape this codebase keeps paying to
      // debug. Both callers of the (now boolean) attach must branch on it.
      for (final path in [
        'lib/screens/auth/numberless_verify_screen.dart',
        'lib/screens/auth/email_verify_screen.dart',
      ]) {
        final src = File(path).readAsStringSync();
        expect(src, contains('identityCooldownMessage()'), reason: path);
      }
      // And the sentence lives in ONE place, so the two screens cannot word
      // the same rule differently.
      expect(File('lib/state/session.dart').readAsStringSync(),
          contains('String? identityCooldownMessage()'));
    });

    test('an unverified account is held to tighter anti-spam limits', () {
      final g = AbuseGuard.instance;
      g.resetForTest();
      addTearDown(g.resetForTest);
      final t0 = DateTime(2026, 6, 1, 12);

      // A verified account may message one person many times; an unverified
      // (name-only) one is capped lower — it can talk, but not blast.
      for (var i = 0; i < 8; i++) {
        g.noteSend('15550001', now: t0.add(Duration(seconds: i * 2)));
      }
      final at = t0.add(const Duration(seconds: 17));
      expect(
          g.messageBlockReason('15550001', now: at, unverified: false), isNull,
          reason: 'a verified account is well under its higher cap');
      expect(g.messageBlockReason('15550001', now: at, unverified: true),
          contains('Verify your number'),
          reason: 'the same volume trips the tighter unverified cap');
    });

    test('a code can never be mistaken for somebody\'s phone number', () {
      // This is the property that matters. Everything downstream addresses by
      // digits — the relay listens on inbox_<digits>, the mesh addresses a
      // packet by them — so a code that collided with a real number would
      // route somebody's messages to a stranger.
      for (var i = 0; i < 200; i++) {
        final code = AccountCode.mint();
        expect(code.length, AccountCode.length);
        expect(AccountCode.isCode(code), isTrue);
        expect(int.tryParse(code), isNotNull, reason: 'digits only');
        expect(code.startsWith('0'), isTrue,
            reason: 'no international number starts with a zero');
      }
      // Real numbers, in the shapes this app sees them.
      for (final number in [
        '+14386386261',
        '14386386261',
        '4386386261',
        '+447700900123',
        '+861380013800',
        '',
      ]) {
        expect(AccountCode.isCode(number), isFalse, reason: number);
      }
    });

    test('a code survives being read off one phone and typed into another', () {
      // Which is the whole point of it, and nobody types twelve digits
      // without putting spaces in.
      const code = '001234567890';
      expect(AccountCode.pretty(code), '0012 3456 7890');
      for (final typed in [
        '001234567890',
        '0012 3456 7890',
        '0012-3456-7890',
        '  0012 3456 7890  ',
      ]) {
        expect(AccountCode.normalize(typed), code, reason: typed);
      }
      // And a number is left well alone, so the caller falls through to
      // treating it as one.
      expect(AccountCode.normalize('+14386386261'), isNull);
      expect(AccountCode.normalize('not a code'), isNull);
      // A '+' means a number was meant, whatever follows it.
      expect(AccountCode.isCode('+001234567890'), isFalse);
    });

    test('two codes minted on two phones do not collide', () {
      final seen = <String>{};
      for (var i = 0; i < 500; i++) {
        seen.add(AccountCode.mint());
      }
      expect(seen.length, 500);
    });

    test('signing in without a number still gives a reachable identity',
        () async {
      await Session.instance.signInWithoutNumber(name: 'Ada', username: 'ada');
      addTearDown(Session.instance.signOut);
      final me = Session.instance.user.value!;
      expect(me.name, 'Ada');
      expect(me.username, 'ada');
      expect(Session.instance.isNumberless, isTrue);
      // Reachable: the relay addresses an inbox by digits, and this has them.
      expect(RelayService.digits(me.phone), me.phone);
      expect(RelayService.inboxChannel(me.phone), 'inbox_${me.phone}');
      // And the mesh can address a packet to it.
