    test('every store that persists is cleared from the live slot on switch',
        () {
      // The switch is a keep-list, and this pins the other half: a store added
      // later that touches SharedPreferences must either appear in
      // account_wipe.dart (so its in-memory copy is reset when a different
      // account arrives) or be named here as deliberately device-scoped —
      // otherwise it leaks the previous account to the next one silently.
      final wipe = File('lib/state/account_wipe.dart').readAsStringSync();
      const deviceScoped = {
        'app_lock.dart', // the device PIN belongs to the phone's owner
        'legal_consent.dart', // the human accepted the terms, not the account
        // The Terms/Privacy text is public policy — identical for every
        // account and carrying no account data — so its cached copy is
        // device-scoped, like legal_consent above.
        'legal_store.dart',
        'onboarding_store.dart', // the human has seen the tour
        'session.dart', // the identity itself — replaced by the sign-in
        'persistence.dart', // app-level settings, reset via AppState
        'account_wipe.dart', // the wiper
        // The parent's rule about the DEVICE, exactly like the app PIN — a
        // child switching accounts must not shed it.
        'parental_controls.dart',
        // The language you read in belongs to the human holding the phone,
        // not the account — like the theme. Switching accounts shouldn't
        // reset it, and it carries no account data to leak.
        'translate_service.dart',
        // Okay AI's chosen personality is a tone preference — how the
        // assistant talks, like the language above — carrying no account
        // data, so it stays with the device across an account switch. (The
        // assistant's per-user MEMORY, which does hold personal facts, is
        // account-scoped and wiped; that's ai_memory.dart, not this.)
        'ai_persona.dart',
        // The abuse history (accounts minted / seen on this device) belongs to
        // the phone, not the account — it must survive a switch, or the
        // spam-signup brake would reset every time someone changed accounts.
        'abuse_guard.dart',
        // The owner's published prices are app-wide config — the same numbers
        // for every account and carrying none of anyone's data — so the
        // cached copy is device-scoped, exactly like legal_store above.
        // Clearing it on a switch would only mean re-fetching what everyone
        // gets anyway.
        'pricing_store.dart',
        // The 14-day clock on a name-only account. Keyed BY ACCOUNT CODE and
        // deliberately device-scoped, for the same reason as abuse_guard
        // above: clearing it on a switch would restart the fortnight every
        // time somebody changed accounts and back, which is how a 14-day
        // limit quietly becomes no limit. Each code keeps its own entry, so
        // one account can never read another's deadline; adding a phone
        // number removes that account's entry outright.
        'numberless_grace.dart',
      };
      for (final f in Directory('lib/state').listSync().whereType<File>()) {
        final name = f.path.split(Platform.pathSeparator).last;
        if (deviceScoped.contains(name)) continue;
        if (!f.readAsStringSync().contains('SharedPreferences')) continue;
        expect(wipe.contains(name), isTrue,
            reason: '$name persists state but account_wipe.dart never '
                'touches it — the next account would inherit it');
      }
    });

    test('a new member is backfilled the listings they could never have seen',
        () {
      // Broadcast has no history: a listing posted before someone joined
      // never existed for them, which read as "marketplace listings don't
      // show up for everyone". The backfill hands a joiner the live
      // listings FIRST, only that server's, capped.
      FeedStore.instance.resetForTest();
      addTearDown(FeedStore.instance.resetForTest);
      FeedPost post(String id, String cid,
              {int? price, bool sold = false, int day = 1}) =>
          FeedPost(
              id: id,
              communityId: cid,
              authorName: 'Ada',
              authorUsername: 'ada',
              time: DateTime(2026, 1, day),
              text: id,
              priceCents: price,
              listingSold: sold);
      FeedStore.instance.addRemote(post('p_old', 'srv', day: 1));
      FeedStore.instance
          .addRemote(post('l_sold', 'srv', price: 100, sold: true, day: 2));
      FeedStore.instance.addRemote(post('l_live', 'srv', price: 500, day: 3));
      FeedStore.instance
          .addRemote(post('l_other', 'other', price: 700, day: 4));

      final fill = FeedStore.instance.backfillFor('srv');
      expect(fill.first.id, 'l_live',
          reason: 'live listings lead the backfill');
      expect(fill.map((p) => p.id), isNot(contains('l_other')),
          reason: 'another server\'s listing must never cross over');
      expect(fill.map((p) => p.id), containsAll(['p_old', 'l_sold']));
    });

