  group('Okay Score, with a shape to it', () {
    setUp(() {
      SharedPreferences.setMockInitialValues({});
      ScoreStore.instance.resetForTest();
    });
    tearDown(ScoreStore.instance.resetForTest);

    test('points are remembered by the day they were earned', () {
      final store = ScoreStore.instance;
      final today = DateTime(2026, 8, 1);
      store.award(10, now: today.subtract(const Duration(days: 3)));
      store.award(5, now: today.subtract(const Duration(days: 3)));
      store.award(7, now: today);

      final days = store.recentDays(now: today);
      expect(days.length, ScoreStore.historyDays);
      expect(days.last, 7, reason: 'today is the last column');
      expect(days[ScoreStore.historyDays - 4], 15, reason: 'summed per day');
      // Zeros for days nothing happened — a chart with the gaps missing lies
      // about how long the gap was.
      expect(days[ScoreStore.historyDays - 2], 0);
      expect(days.fold(0, (a, b) => a + b), 22);
      expect(store.points, 22);
    });

    test('the history does not grow forever', () {
      final store = ScoreStore.instance;
      final today = DateTime(2026, 8, 1);
      for (var i = 0; i < 100; i++) {
        store.award(1, now: today.subtract(Duration(days: i)));
      }
      expect(store.history.length, lessThanOrEqualTo(ScoreStore.historyDays),
          reason: 'a device left running must not carry a year of days');
      // And the total is untouched by forgetting the shape of it.
      expect(store.points, 100);
    });

    test('this week is the last seven days, not everything', () {
      final store = ScoreStore.instance;
      // Relative to the REAL clock, because thisWeek reads today from it — a
      // hardcoded date drifts out of the window as time passes and the -2-day
      // award falls off the edge.
      final today = DateTime.now();
      store.award(50, now: today.subtract(const Duration(days: 10)));
      store.award(3, now: today.subtract(const Duration(days: 2)));
      store.award(4, now: today);
      expect(store.thisWeek, 7);
      expect(store.points, 57);
    });

    test('the new badges exist and are earned by doing the thing', () {
      final store = ScoreStore.instance;
      for (final id in ['nearby', 'relay', 'forwarder']) {
        final badge = ScoreStore.badgeById(id);
        expect(badge, isNotNull, reason: id);
        expect(store.isEarned(id), isFalse, reason: id);
      }
      store.recordFlag('sent_mesh');
      store.recordFlag('relayed_mesh');
      store.recordFlag('forwarded');
      for (final id in ['nearby', 'relay', 'forwarder']) {
        expect(store.isEarned(id), isTrue, reason: id);
      }
    });

    testWidgets('the score screen draws the fortnight', (t) async {
      t.view.physicalSize = const Size(430, 1400);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      await t.pumpWidget(const MaterialApp(home: ScoreScreen()));
      await t.pumpAndSettle();
      expect(find.text('Last two weeks'), findsOneWidget);
      // Nothing yet rather than fourteen empty columns, which look like a
      // chart that failed to load.
      expect(find.text('Nothing yet this fortnight.'), findsOneWidget);

      ScoreStore.instance.award(12);
      await t.pumpAndSettle();
      expect(find.text('Nothing yet this fortnight.'), findsNothing);
      expect(find.textContaining('12 this week'), findsOneWidget);
    });
  });

  group('More to decide about Bluetooth and what leaves with a message', () {
    setUp(() {
      SharedPreferences.setMockInitialValues({});
      MeshService.instance.resetForTest();
      ScoreStore.instance.resetForTest();
    });
    tearDown(() {
      MeshService.instance.resetForTest();
      ScoreStore.instance.resetForTest();
      AppState.resetForTest();
      MeshService.debugSendOverride = null;
      MeshService.debugAvailableOverride = null;
    });

    test('a phone that will not relay still sends and receives', () {
      final sent = <String>[];
      MeshService.debugSendOverride = sent.add;
      final mesh = MeshService.instance;

      // Somebody else's packet, passing through.
      const theirs = MeshPacket(
          id: 'm1', to: '15550109999', ttl: 3, payload: {'enc': 'x'});
      mesh.debugReceive(theirs);
      expect(sent, isNotEmpty, reason: 'relaying is on by default');

      sent.clear();
      mesh.setRelayForOthers(false);
      mesh.router.reset();
      mesh.debugReceive(theirs);
      expect(sent, isEmpty, reason: 'their traffic stops here now');
    });

    test('turning off nearby discovery empties the list and keeps it empty',
        () {
      final mesh = MeshService.instance;
      const beacon = MeshPacket(
          id: 'b1',
          to: '',
          ttl: 3,
          kind: MeshPacket.kindServer,
          payload: {'id': 'c1', 'name': 'Cafe', 'members': 2});
      mesh.debugDeliver(beacon);
      expect(NearbyServers.instance.servers, isNotEmpty);

      mesh.setFindServers(false);
      expect(NearbyServers.instance.servers, isEmpty,
          reason: 'what was listed goes when you say stop listening');
      mesh.router.reset();
      mesh.debugDeliver(beacon);
      expect(NearbyServers.instance.servers, isEmpty);
    });

    test('a withheld score never leaves, rather than being zeroed later',
        () async {
      // Round-tripped rather than grepped: the score travels INSIDE the
      // sealed blob, so looking for it in the JSON on the wire finds nothing
      // whether it was sent or not — which is a test that passes for the
      // wrong reason.
      ChatStore.instance.reset();
      addTearDown(ChatStore.instance.reset);
      ScoreStore.instance.award(90);

      Map<String, dynamic> envelope({required bool share}) =>
          RelayService.encode(
            message: Message(
                id: 'm${share ? 1 : 2}',
                text: 'hi',
                time: DateTime(2026),
                isMe: true,
                status: MessageStatus.sent),
            fromPhone: '+15550101111',
            fromName: 'Ada',
            fromScore: share ? ScoreStore.instance.points : 0,
            toPhone: '+15550102222',
          );

      RelayService.applyIncoming(envelope(share: true),
          myPhone: '+15550102222');
      final shared = ChatStore.instance.chatWithContact('+15550101111');
      expect(shared?.contact.score, 90, reason: 'it arrives when shared');

      ChatStore.instance.reset();
      RelayService.applyIncoming(envelope(share: false),
          myPhone: '+15550102222');
      final withheld = ChatStore.instance.chatWithContact('+15550101111');
      expect(withheld?.contact.score, 0,
          reason: 'the far end never received a number to ignore');
    });

    test('the send path is the one that reads the switch', () {
      // The check has to be at the point the envelope is built, not at the
      // far end — a field that never leaves is one nobody has to be trusted
      // with.
      final src = File('lib/relay/relay_service.dart').readAsStringSync();
      expect(src.contains('AppState.shareScore.value ? ScoreStore'), isTrue);
      expect(src.contains('AppState.shareStreak.value ? streak : 0'), isTrue);
    });

    testWidgets('the Bluetooth switches appear only once it is on', (t) async {
      t.view.physicalSize = const Size(430, 1600);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      MeshService.debugAvailableOverride = true;

      await t.pumpWidget(const MaterialApp(home: PrivacySettingsScreen()));
      await t.pumpAndSettle();
      await t.scrollUntilVisible(find.text('Message people nearby'), 200);
      // Nothing to decide about a radio that is off.
      expect(find.text('Pass on other people\'s messages'), findsNothing);
      expect(find.text('Find servers nearby'), findsNothing);

      // NOT awaited: turning the mesh on talks to a method channel, and a
      // channel reply is delivered by the pump — awaiting it inside
      // testWidgets waits for a message that only pumping can deliver.
      unawaited(MeshService.instance.setEnabled(true));
      // pump, not pumpAndSettle: the mesh beacons on a periodic timer while
      // it is on, and a tree with a repeating timer in it never settles.
      await t.pump();
      await t.pump();
      expect(find.text('Pass on other people\'s messages'), findsOneWidget);
      expect(find.text('Find servers nearby'), findsOneWidget);
      unawaited(MeshService.instance.stop());
      await t.pump();
    });

    testWidgets('signing out closes the screens above it too', (t) async {
      // The auth gate swaps its child the moment the session clears — but
      // Settings is PUSHED on top of that gate, and so is whatever opened
      // it, so the login screen appeared underneath a stack nobody had
      // closed. It looked like sign-out did nothing until the app was killed.
      t.view.physicalSize = const Size(430, 1600);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      await Session.instance.signIn(phone: '+15550101111', name: 'Ada');
      addTearDown(Session.instance.signOut);

      await t.pumpWidget(MaterialApp(
        home: Builder(
          builder: (context) => Scaffold(
            body: Center(
              child: TextButton(
                onPressed: () => Navigator.of(context).push(
                    MaterialPageRoute(builder: (_) => const SettingsScreen())),
                child: const Text('open settings'),
              ),
            ),
          ),
        ),
      ));
      await t.tap(find.text('open settings'));
      await t.pumpAndSettle();
      expect(find.byType(SettingsScreen), findsOneWidget);

      // Two more tiles above it pushed Sign out past the bottom of even this
      // tall surface, so scrolling to it is no longer enough on its own.
      await t.scrollUntilVisible(find.text('Sign out'), 250);
      await t.ensureVisible(find.text('Sign out'));
      await t.pumpAndSettle();
      await t.tap(find.text('Sign out'));
      await t.pumpAndSettle();

      expect(Session.instance.isSignedIn, isFalse);
      expect(find.byType(SettingsScreen), findsNothing,
          reason: 'the pushed screens have to come down with the session');
      expect(find.text('open settings'), findsOneWidget,
          reason: 'back at the root, where the gate can show sign-in');
    });

    testWidgets('what rides along with a message can be turned off', (t) async {
      t.view.physicalSize = const Size(430, 1600);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      await t.pumpWidget(const MaterialApp(home: PrivacySettingsScreen()));
      await t.pumpAndSettle();
      await t.scrollUntilVisible(find.text('Share my Okay Score'), 200);
      expect(find.text('Share our streak'), findsOneWidget);

      await t.tap(find.text('Share my Okay Score'));
      await t.pumpAndSettle();
      expect(AppState.shareScore.value, isFalse);
    });
  });

  group('Both timelines, with more in them', () {
    setUp(() {
      SharedPreferences.setMockInitialValues({});
      FeedDrafts.instance.resetForTest();
      FeedStore.instance.resetForTest();
      PublicFeedStore.instance.resetForTest();
    });
    tearDown(() {
      FeedDrafts.instance.resetForTest();
      FeedStore.instance.resetForTest();
      PublicFeedStore.instance.resetForTest();
      PublicFeedStore.debugLoadOverride = null;
    });

    // --- A long post folds -------------------------------------------------

    testWidgets('a wall of text folds, and opens when asked', (t) async {
      t.view.physicalSize = const Size(390, 900);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      final long =
          List.generate(40, (i) => 'Line $i of a very long post.').join('\n');

      var maxLinesSeen = -1;
      // In a scroll view, as it is in both timelines — opened out, the text
      // is taller than the screen, which is the point of folding it.
      await t.pumpWidget(MaterialApp(
        home: Scaffold(
          body: SingleChildScrollView(
            child: CollapsibleText(
              text: long,
              style: const TextStyle(fontSize: 15),
              builder: (context, maxLines) {
                maxLinesSeen = maxLines ?? -1;
                return Text(long, maxLines: maxLines);
              },
            ),
          ),
        ),
      ));
      await t.pumpAndSettle();

      expect(maxLinesSeen, 10, reason: 'folded to ten lines');
      expect(find.text('Show more'), findsOneWidget);

      await t.tap(find.text('Show more'));
      await t.pumpAndSettle();
      expect(maxLinesSeen, -1, reason: 'all of it now');
      expect(find.text('Show less'), findsOneWidget);
    });

    testWidgets('a short post is not folded, and offers nothing to open',
        (t) async {
      t.view.physicalSize = const Size(390, 900);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      const short = 'Two words.';
      int? seen = 99;
      await t.pumpWidget(MaterialApp(
        home: Scaffold(
          body: CollapsibleText(
            text: short,
            style: const TextStyle(fontSize: 15),
            builder: (context, maxLines) {
              seen = maxLines;
              return const Text(short);
            },
          ),
        ),
      ));
      await t.pumpAndSettle();
      expect(seen, isNull, reason: 'nothing to clip');
      expect(find.text('Show more'), findsNothing,
          reason: 'a button under every short post is noise');
    });

    testWidgets('a recycled row does not inherit the last post\'s state',
        (t) async {
      // A list reuses its widgets. Without resetting, scrolling an opened
      // post off screen leaves the next one that lands in that slot opened
      // too — which reads as the app deciding what you wanted to read.
      t.view.physicalSize = const Size(390, 900);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      final long = List.generate(40, (i) => 'Line $i.').join('\n');
      final other = List.generate(40, (i) => 'Other $i.').join('\n');

      Widget frame(String text) => MaterialApp(
            home: Scaffold(
              body: SingleChildScrollView(
                child: CollapsibleText(
                  key: const ValueKey('same-slot'),
                  text: text,
                  style: const TextStyle(fontSize: 15),
                  builder: (context, maxLines) =>
                      Text(text, maxLines: maxLines),
                ),
              ),
            ),
          );

      await t.pumpWidget(frame(long));
      await t.pumpAndSettle();
      await t.tap(find.text('Show more'));
      await t.pumpAndSettle();
      expect(find.text('Show less'), findsOneWidget);

      await t.pumpWidget(frame(other));
      await t.pumpAndSettle();
      expect(find.text('Show more'), findsOneWidget,
          reason: 'a different post starts folded');
    });

    testWidgets('a body is measured in the font it is drawn in', (t) async {
      // The style handed in carries a size and no family, because the family
      // — and the letter spacing, and the rest — come from the ambient
      // DefaultTextStyle, which is what Text.rich merges against when it
      // draws. Measuring the bare style measured a different typeface from
      // the one on screen, so the SAME body folded on one timeline and not
      // the other: the server feed showed "Show more" under five lines.
      Widget frame(double spacing) => MaterialApp(
            home: Scaffold(
              body: DefaultTextStyle(
                style: TextStyle(fontSize: 15, letterSpacing: spacing),
                child: SizedBox(
                  width: 300,
                  child: CollapsibleText(
                    text: 'One short line of a post, and then a second.',
                    style: const TextStyle(fontSize: 15),
                    maxLines: 4,
                    builder: (context, maxLines) => Text(
                        'One short line of a post, and then a second.',
                        maxLines: maxLines),
                  ),
                ),
              ),
            ),
          );

      await t.pumpWidget(frame(0));
      await t.pumpAndSettle();
      expect(find.text('Show more'), findsNothing,
          reason: 'it fits, so there is nothing to unfold');

      // Same text, same passed style, ambient type that makes it far wider.
      await t.pumpWidget(frame(20));
      await t.pumpAndSettle();
      expect(find.text('Show more'), findsOneWidget,
          reason: 'it no longer fits, and the measurement has to know that');
    });

    test('both feeds fold through the same widget', () {
      // Two feeds that drifted apart is the thing this is here to stop; they
      // render their bodies through different tag-highlighting widgets, so
      // without one shared piece the fold would only ever be on one of them.
      for (final path in [
        'lib/screens/feed_screen.dart',
        'lib/screens/public_feed_screen.dart',
      ]) {
        final src = File(path).readAsStringSync();
        expect(src.contains('FeedBodyText('), isTrue, reason: path);
      }
      expect(
          File('lib/widgets/feed_post_parts.dart')
              .readAsStringSync()
              .contains('CollapsibleText('),
          isTrue);
    });

    // --- A draft survives leaving -----------------------------------------

    test('what you typed and did not post is still there', () {
      final drafts = FeedDrafts.instance;
      expect(drafts.read(FeedDrafts.publicKey), '');

      drafts.write(FeedDrafts.publicKey, 'half a thought');
      expect(drafts.read(FeedDrafts.publicKey), 'half a thought');
      expect(drafts.has(FeedDrafts.publicKey), isTrue);

      // Emptying the box is not a draft to tidy up later.
      drafts.write(FeedDrafts.publicKey, '   ');
      expect(drafts.has(FeedDrafts.publicKey), isFalse);
    });

    test('a reply draft does not turn up in somebody else\'s box', () {
      final drafts = FeedDrafts.instance;
      drafts.write(FeedDrafts.replyKey('p1'), 'to Ada');
      drafts.write(FeedDrafts.replyKey('p2'), 'to Grace');
      drafts.write(FeedDrafts.serverKey('c1'), 'to the server');
      drafts.write(FeedDrafts.publicKey, 'to everyone');

      expect(drafts.read(FeedDrafts.replyKey('p1')), 'to Ada');
      expect(drafts.read(FeedDrafts.replyKey('p2')), 'to Grace');
      expect(drafts.read(FeedDrafts.serverKey('c1')), 'to the server');
      expect(drafts.read(FeedDrafts.publicKey), 'to everyone');
      expect(drafts.read(FeedDrafts.serverKey('c2')), '');
    });

    test('abandoned drafts do not pile up forever', () {
      final drafts = FeedDrafts.instance;
      for (var i = 0; i < FeedDrafts.maxDrafts + 30; i++) {
        drafts.write(FeedDrafts.replyKey('p$i'), 'draft $i');
      }
      expect(drafts.count, FeedDrafts.maxDrafts);
      // Oldest out first: the newest is kept, the first is gone.
      expect(drafts.has(FeedDrafts.replyKey('p0')), isFalse);
      expect(drafts.read(FeedDrafts.replyKey('p${FeedDrafts.maxDrafts + 29}')),
          'draft ${FeedDrafts.maxDrafts + 29}');
    });

    testWidgets('the public composer opens with what you left in it',
        (t) async {
      t.view.physicalSize = const Size(430, 1000);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      PublicFeedStore.debugLoadOverride = () async => [];
      FeedDrafts.instance.write(FeedDrafts.publicKey, 'left half-written');

      await t.pumpWidget(const MaterialApp(home: PublicFeedScreen()));
      await t.pumpAndSettle();
      await t.tap(find.byTooltip('New post'));
      await t.pumpAndSettle();

      expect(find.text('left half-written'), findsOneWidget,
          reason: 'backing out of a composer should not cost you the text');

      // And typing more keeps it.
      await t.enterText(find.byType(TextField).first, 'left half-written more');
      await t.pump();
      expect(FeedDrafts.instance.read(FeedDrafts.publicKey),
          'left half-written more');
    });

    test('both composers keep a draft', () {
      for (final path in [
        'lib/screens/feed_screen.dart',
        'lib/screens/public_feed_screen.dart',
      ]) {
        final src = File(path).readAsStringSync();
        expect(src.contains('FeedDrafts.instance.read('), isTrue,
            reason: '$path opens without what was left in it');
        expect(src.contains('FeedDrafts.instance.clear('), isTrue,
            reason: '$path keeps the draft after posting it');
      }
    });
  });

  group('Handing a photo to somebody in the room', () {
    setUp(() {
      SharedPreferences.setMockInitialValues({});
      MeshService.instance.resetForTest();
      NearbyShare.instance.resetForTest();
      NearbyPeople.instance.clear();
      ChatStore.instance.reset();
      ScoreStore.instance.resetForTest();
      Session.instance.signInForTest();
    });
    tearDown(() {
      MeshService.instance.resetForTest();
      NearbyShare.instance.resetForTest();
      NearbyPeople.instance.clear();
      ScoreStore.instance.resetForTest();
      NearbyShare.debugSendOverride = null;
      MeshService.debugSendOverride = null;
      MeshService.debugAvailableOverride = null;
    });

    NearbyPerson ada() => NearbyPerson(
        digits: '15550102222',
        name: 'Ada',
        avatarColor: '#2E7D32',
        heardAt: DateTime.now());

    /// A stand-in for the radio: records what went out, and lets a test play
    /// the other phone.
    List<(String, String, Map<String, dynamic>)> wireTap() {
      final sent = <(String, String, Map<String, dynamic>)>[];
      NearbyShare.debugSendOverride = (to, kind, payload) async {
        sent.add((to, kind, payload));
        return true;
      };
      return sent;
    }

    MeshPacket asPacket(String kind, Map<String, dynamic> payload) =>
        MeshPacket(
            id: MeshPacket.randomId(),
            to: '15550101111',
            ttl: 0,
            kind: kind,
            payload: payload);

    test('a file is never passed on through anybody else', () {
      // The whole reason this is separate from the message path. A message
      // floods because nobody knows the way; a photo is a hundred kilobytes
      // going to one person who agreed to receive it, and relaying that
      // through every phone in the room would pin four radios.
      final router = MeshRouter(myDigits: '15550109999');
      for (final kind in MeshPacket.directOnly) {
        final notMine = MeshPacket(
            id: 'x$kind',
            to: '15550102222',
            ttl: 5,
            kind: kind,
            payload: const {'id': 't1'});
        expect(router.accept(notMine), MeshAction.drop,
            reason: '$kind was relayed');
      }
      // Addressed here, it is delivered — and still not relayed.
      const mine = MeshPacket(
          id: 'mine',
          to: '15550109999',
          ttl: 5,
          kind: MeshPacket.kindChunk,
          payload: {'id': 't1'});
      expect(router.accept(mine), MeshAction.deliver);
    });

    test('an offer carries who it is from, or it cannot be answered', () async {
      final sent = wireTap();
      await NearbyShare.instance.offer(
          ada(), 'data:image/png;base64,${'A' * 200}',
          fileName: 'Photo');
      final (to, kind, payload) = sent.single;
      expect(to, '15550102222');
      expect(kind, MeshPacket.kindOffer);
      expect(payload['d'], isNotEmpty,
          reason: 'a packet says who it is FOR, not who it is from');
      expect(payload['c'], greaterThan(0), reason: 'how many chunks');
      // And none of the photo itself: an offer is a question.
      expect(jsonEncode(payload).contains('A' * 100), isFalse);
    });

    test('nothing moves until the far end says yes', () async {
      final sent = wireTap();
      final data = 'data:image/png;base64,${'B' * 7000}';
      final t =
          (await NearbyShare.instance.offer(ada(), data, fileName: 'Photo'))!;
      expect(t.state, TransferState.offered);
      expect(sent.where((e) => e.$2 == MeshPacket.kindChunk), isEmpty);

      // They say no.
      NearbyShare.instance
          .handle(asPacket(MeshPacket.kindAnswer, {'id': t.id, 'ok': false}));
      expect(NearbyShare.instance.byId(t.id)!.state, TransferState.declined);
      expect(sent.where((e) => e.$2 == MeshPacket.kindChunk), isEmpty,
          reason: 'not one byte to somebody who refused');
    });

    test('yes sends every chunk, and the far end can rebuild it', () async {
      final sent = wireTap();
      final data = 'data:image/png;base64,${'C' * 7000}';
      final t =
          (await NearbyShare.instance.offer(ada(), data, fileName: 'Photo'))!;
      expect(t.totalChunks, greaterThan(1), reason: 'this needs chunking');

      NearbyShare.instance
          .handle(asPacket(MeshPacket.kindAnswer, {'id': t.id, 'ok': true}));
      await Future<void>.delayed(Duration.zero);

      final chunks = sent.where((e) => e.$2 == MeshPacket.kindChunk).toList();
      expect(chunks.length, t.totalChunks);
      expect(NearbyShare.instance.byId(t.id)!.state, TransferState.done);

      final assembler = TransferAssembler(t.totalChunks);
      for (final c in chunks) {
        assembler.add(c.$3['i'] as int, c.$3['p'] as String);
      }
      expect(assembler.assemble(), data,
          reason: 'what arrives has to be what was sent');
    });

    test('a photo that arrives lands in the chat with whoever sent it',
        () async {
      wireTap();
      const data = 'data:image/png;base64,ABCD';
      NearbyShare.instance.handle(asPacket(MeshPacket.kindOffer, {
        'id': 't1',
        'n': 'Photo',
        'c': 1,
        'k': 'image',
        'd': '15550102222',
        'w': 'Ada',
      }));
      final pending = NearbyShare.instance.pendingIncoming!;
      expect(pending.peerName, 'Ada');

      await NearbyShare.instance.accept('t1');
      NearbyShare.instance.handle(asPacket(
          MeshPacket.kindChunk, {'id': 't1', 'i': 0, 'c': 1, 'p': data}));

      expect(NearbyShare.instance.byId('t1')!.state, TransferState.done);
      final chat = ChatStore.instance.chatWithContact('15550102222');
      expect(chat, isNotNull, reason: 'a photo from somebody is from them');
      expect(chat!.messages.last.isImage, isTrue);
      expect(chat.messages.last.imageUrl, data);
      expect(ScoreStore.instance.isEarned('handoff'), isTrue);
    });

    test('an offer off the air is not trusted about anything', () {
      wireTap();
      for (final bad in <Map<String, dynamic>>[
        {'n': 'Photo', 'c': 1},
        {'id': '', 'n': 'Photo', 'c': 1},
        {'id': 'a', 'n': 'Photo', 'c': 0},
        {'id': 'b', 'n': 'Photo', 'c': -1},
        // More chunks than the ceiling allows, before a buffer is made.
        {'id': 'c', 'n': 'Photo', 'c': 100000},
      ]) {
        NearbyShare.instance.handle(asPacket(MeshPacket.kindOffer, bad));
      }
      expect(NearbyShare.instance.pendingIncoming, isNull);
      expect(NearbyShare.instance.transfers, isEmpty);
    });

    test('chunks for something never accepted are ignored', () {
      wireTap();
      NearbyShare.instance.handle(asPacket(MeshPacket.kindChunk,
          {'id': 'never-offered', 'i': 0, 'c': 1, 'p': 'x'}));
      expect(NearbyShare.instance.transfers, isEmpty,
          reason: 'a chunk cannot conjure a transfer nobody agreed to');
    });

    test('a file too big for this radio is refused at the sender', () async {
      wireTap();
      final huge = 'x' * (TransferChunks.maxLength + 1);
      expect(await NearbyShare.instance.offer(ada(), huge, fileName: 'Big'),
          isNull);
    });

    test('chunks out of order still rebuild the file', () {
      // Packets do not necessarily land in the order they were sent.
      final assembler = TransferAssembler(3);
      expect(assembler.add(2, 'ccc'), isTrue);
      expect(assembler.add(0, 'aaa'), isTrue);
      expect(assembler.assemble(), isNull, reason: 'one still missing');
      expect(assembler.add(1, 'bbb'), isTrue);
      expect(assembler.assemble(), 'aaabbbccc');
      // A retried chunk is not a second copy.
      expect(assembler.add(1, 'zzz'), isFalse);
      expect(assembler.add(9, 'out of range'), isFalse);
    });

    test('who can see you is off until you say otherwise', () async {
      expect(MeshService.instance.findable, Findable.off);
      final sent = <String>[];
      MeshService.debugSendOverride = sent.add;
      MeshService.instance.debugHelloNow();
      expect(sent, isEmpty, reason: 'a name in the air is a decision');

      await MeshService.instance.setFindable(Findable.everyone);
      sent.clear();
      MeshService.instance.debugHelloNow();
      expect(sent, isNotEmpty);
    });

    test('a hello from a stranger is ignored on "people I chat with"',
        () async {
      await MeshService.instance.setFindable(Findable.contacts);
      const stranger = MeshPacket(
          id: 'h1',
          to: '',
          ttl: 3,
          kind: MeshPacket.kindHello,
          payload: {'d': '15550109999', 'n': 'A Stranger'});
      MeshService.instance.debugDeliver(stranger);
      expect(NearbyPeople.instance.people, isEmpty,
          reason: 'enforced here as well as at the sender — a modified app '
              'that announces itself to everyone still cannot make you list '
              'it');

      // Somebody already in a chat is listed.
      ChatStore.instance.upsert(const Chat(
        id: 'chat_15550108888',
        contact: AppUser(
            id: '15550108888',
            name: 'Ada',
            avatarColor: '#2E7D32',
            phone: '15550108888'),
        messages: [],
      ));
      MeshService.instance.debugDeliver(const MeshPacket(
          id: 'h2',
          to: '',
          ttl: 3,
          kind: MeshPacket.kindHello,
          payload: {'d': '15550108888', 'n': 'Ada'}));
      expect(NearbyPeople.instance.people.map((p) => p.name), ['Ada']);
    });

    test('who was nearby stops being nearby', () {
      final now = DateTime(2026, 8, 1, 12);
      NearbyPeople.instance.heard(NearbyPerson(
          digits: '1', name: 'Ada', avatarColor: '#fff', heardAt: now));
      expect(NearbyPeople.instance.people, hasLength(1));
      NearbyPeople.instance.expire(now.add(NearbyPeople.linger * 2));
      expect(NearbyPeople.instance.people, isEmpty);
    });

    testWidgets('nothing lands without being asked about first', (t) async {
      wireTap();
      await t.pumpWidget(const MaterialApp(
          home: NearbyOfferHost(child: Scaffold(body: Text('home')))));
      await t.pumpAndSettle();

      NearbyShare.instance.handle(asPacket(MeshPacket.kindOffer, {
        'id': 't9',
        'n': 'Holiday.jpg',
        'c': 1,
        'k': 'image',
        'b': 240000,
        'd': '15550102222',
        'w': 'Ada',
      }));
      await t.pumpAndSettle();

      expect(
          find.textContaining('Ada wants to send you a photo'), findsOneWidget);
      // What it is and how big, because "a file" is not enough to say yes to.
      expect(find.textContaining('Holiday.jpg · 234 KB'), findsOneWidget);
      await t.tap(find.text('No thanks'));
      await t.pumpAndSettle();
      expect(NearbyShare.instance.byId('t9')!.state, TransferState.declined);
    });
  });

  group('Handing over a file or a video', () {
    setUp(() {
      SharedPreferences.setMockInitialValues({});
      MeshService.instance.resetForTest();
      NearbyShare.instance.resetForTest();
      NearbyFast.instance.resetForTest();
      NearbyPeople.instance.clear();
      ChatStore.instance.reset();
      FileModeration.resetForTest();
      Session.instance.signInForTest();
    });
    tearDown(() {
      NearbyShare.instance.resetForTest();
      NearbyShare.debugSendOverride = null;
      NearbyFast.instance.resetForTest();
      MeshService.instance.resetForTest();
      MeshService.debugSendOverride = null;
      FileModeration.resetForTest();
    });

    NearbyPerson ada() => NearbyPerson(
        digits: '15550102222',
        name: 'Ada',
        avatarColor: '#2E7D32',
        heardAt: DateTime.now());

    MeshPacket asPacket(String kind, Map<String, dynamic> payload) =>
        MeshPacket(
            id: MeshPacket.randomId(),
            to: '15550100',
            ttl: 0,
            kind: kind,
            payload: payload);

    var sentId = '';

    Uint8List mp4() => Uint8List.fromList([
          0, 0, 0, 24, 0x66, 0x74, 0x79, 0x70, // ....ftyp
          0x69, 0x73, 0x6F, 0x6D, // isom — a movie brand, not a HEIC one
          ...List<int>.filled(64, 7),
        ]);

    test('a video may be handed over, and still may not be uploaded', () {
      // The block everywhere else is a statement about what this app is
      // willing to STORE. Nothing is stored here — the bytes cross a link
      // between two devices that both agreed — so the reason for it does not
      // exist on this path.
      final video = mp4();
      expect(FileModeration.sniff(video), 'video');
      expect(FileModeration.inspectImage(video).allowed, isFalse);
      expect(FileModeration.inspectFile(video).allowed, isFalse);
      expect(
          FileModeration.inspectNearby(video, limit: 1 << 20).allowed, isTrue,
          reason: 'a video handed to the phone next to you uploads nothing');

      // What was never about storage still applies.
      final exe = Uint8List.fromList([0x4D, 0x5A, 1, 2, 3, 4, 5, 6]);
      expect(
          FileModeration.inspectNearby(exe, limit: 1 << 20).allowed, isFalse);
      final script = Uint8List.fromList([0x23, 0x21, 0x2F, 0x62, 0x69, 0x6E]);
      expect(FileModeration.inspectNearby(script, limit: 1 << 20).allowed,
          isFalse);
      FileModeration.blockHash(FileModeration.hashOf(video));
      expect(
          FileModeration.inspectNearby(video, limit: 1 << 20).allowed, isFalse,
          reason: 'a blocked hash is blocked on every path');
    });

    testWidgets('a send that could only fail is not offered', (t) async {
      // Two people in the room can be on different links. Choosing a video
      // and tapping Send at the one on Bluetooth alone used to spend a tap
      // to learn that — `offer` returned null and a snackbar explained
      // afterwards. The row says so instead, and the button is dead.
      IdentityVerification.debugGateOverride = false;
      MeshService.debugAvailableOverride = true;
      // NOT awaited: turning the mesh on talks to a method channel, and the
      // reply is delivered by the pump — awaiting it here waits for a message
      // only pumping can deliver.
      unawaited(MeshService.instance.setEnabled(true));
      NearbyPeople.instance.heard(ada());

      // Bigger than Bluetooth carries, well inside the fast link — the same
      // boundary `offer` enforces.
      final big = 'data:video/mp4;base64,${'A' * 400000}';
      await t.pumpWidget(MaterialApp(
          home: NearbyShareScreen(
              dataUri: big, kind: 'video', key: const ValueKey('bt'))));
      await t.pump();

      expect(find.text('Ada'), findsOneWidget);
      expect(find.textContaining('Too big for Bluetooth'), findsOneWidget,
          reason: 'the bubble never said the file cannot cross this link');
      // No send arrow: the bubble stays an initial, visibly not a button.
      expect(find.byIcon(Icons.arrow_upward_rounded), findsNothing,
          reason: 'send was offered for a transfer that cannot happen');
    });

    testWidgets('and is offered once the link that can carry it exists',
        (t) async {
      // The other half of the same fact: nothing about the file changed, only
      // the way it would travel.
      IdentityVerification.debugGateOverride = false;
      MeshService.debugAvailableOverride = true;
      unawaited(MeshService.instance.setEnabled(true));
      NearbyPeople.instance.heard(ada());

      // runAsync, not a bare await: bringing the fast link up crosses a
      // method channel, and inside testWidgets a channel reply only arrives
      // while something is pumping. Awaiting it directly waits forever.
      await t.runAsync(() async {
        NearbyFast.instance.debugMarkRunning();
        await NearbyFast.instance.notePeers(['tok-ada']);
        NearbyFast.instance.noteBody(
            'tok-ada', jsonEncode({'k': 'hi', 'd': '15550102222', 'n': 'Ada'}));
      });
      expect(NearbyFast.instance.hasPeer('15550102222'), isTrue,
          reason: 'the fast link never came up, so the rest proves nothing');

      final big = 'data:video/mp4;base64,${'A' * 400000}';
      await t.pumpWidget(MaterialApp(
          home: NearbyShareScreen(
              dataUri: big, kind: 'video', key: const ValueKey('fast'))));
      await t.pump();

      expect(find.textContaining('Too big'), findsNothing);
      // Sendable: the person's bubble shows the send arrow instead of their
      // initial — the avatar IS the send button now.
      expect(find.byIcon(Icons.arrow_upward_rounded), findsOneWidget,
          reason: 'the fast link can carry this and the bubble should offer '
              'to send');
    });

    testWidgets('opening the screen shows the room, not a photo picker',
        (t) async {
      // It used to fire the system picker from a post-frame callback, so the
      // first thing between you and "has Ada appeared yet" was a full-screen
      // modal to dismiss.
      IdentityVerification.debugGateOverride = false;
      MeshService.debugAvailableOverride = true;
      // NOT awaited: turning the mesh on talks to a method channel, and the
      // reply is delivered by the pump — awaiting it here waits for a message
      // only pumping can deliver.
      unawaited(MeshService.instance.setEnabled(true));
      NearbyPeople.instance.heard(ada());

      var pickerOpened = false;
      // BOTH pickers. The screen's photo path goes through PhotoPrep and its
      // file path through NearbyPick, so hooking one and not the other
      // watches a door the auto-open never used.
      PhotoPrep.debugPickOverride = () async {
        pickerOpened = true;
        return null;
      };
      NearbyPick.debugPickOverride = () async {
        pickerOpened = true;
        return null;
      };
      addTearDown(() {
        PhotoPrep.debugPickOverride = null;
        NearbyPick.debugPickOverride = null;
      });

      await t.pumpWidget(const MaterialApp(home: NearbyShareScreen()));
      await t.pump();
      await t.pump(const Duration(milliseconds: 50));

      expect(pickerOpened, isFalse,
          reason: 'the screen hijacked the first frame with a picker');
      expect(find.text('Ada'), findsOneWidget,
          reason: 'the room should be visible immediately');
      // And with nothing chosen there is nothing to send yet: the bubble
      // shows Ada's initial, not the send arrow.
      expect(find.byIcon(Icons.arrow_upward_rounded), findsNothing);
    });

    test('the ceiling is the transport, not a number somebody picked',
        () async {
      NearbyShare.debugSendOverride = (to, kind, p) async => true;
      // Bigger than Bluetooth will carry, well inside the fast link.
      final big = 'data:video/mp4;base64,${'A' * 400000}';

      expect(await NearbyShare.instance.offer(ada(), big, fileName: 'Clip.mp4'),
          isNull,
          reason: 'a minute a hop is not a transfer, it is a hostage');

      NearbyFast.instance.debugMarkRunning();
      await NearbyFast.instance.notePeers(['tok-ada']);
      NearbyFast.instance.noteBody(
          'tok-ada', jsonEncode({'k': 'hi', 'd': '15550102222', 'n': 'Ada'}));

      final t = await NearbyShare.instance
          .offer(ada(), big, fileName: 'Clip.mp4', kind: 'video');
      expect(t, isNotNull, reason: 'the fast link can carry this');
      expect(t!.fast, isTrue);
      expect(t.kind, 'video');
      // And the count it claims is one the far end will accept.
      expect(t.totalChunks, lessThanOrEqualTo(TransferChunks.maxChunks));
    });

    test('what arrives is handled by what it says it is', () async {
      NearbyShare.debugSendOverride = (to, kind, p) async => true;

      Future<void> receive(
          String id, String kind, String name, String data) async {
        NearbyShare.instance.handle(asPacket(MeshPacket.kindOffer, {
          'id': id,
          'n': name,
          'c': 1,
          'k': kind,
          'd': '15550102222',
          'w': 'Ada',
        }));
        await NearbyShare.instance.accept(id);
        NearbyShare.instance.handle(asPacket(
            MeshPacket.kindChunk, {'id': id, 'i': 0, 'c': 1, 'p': data}));
        // Delivery writes to disk before it puts a line in the chat, so this
        // waits for the event loop rather than one microtask.
        await Future<void>.delayed(const Duration(milliseconds: 50));
      }

      await receive(
          'i1', 'image', 'Holiday.jpg', 'data:image/png;base64,iVBORw0KGgo=');
      await receive(
          'v1', 'video', 'Clip.mp4', NearbyPick.dataUriFor(mp4(), 'video'));

      final chat = ChatStore.instance.chatWithContact('15550102222')!;
      final image = chat.messages.firstWhere((m) => m.id == 'near_i1');
      expect(image.isImage, isTrue, reason: 'a picture is shown as a picture');
      expect(image.imageUrl, startsWith('data:image/'));

      final video = chat.messages.firstWhere((m) => m.id == 'near_v1');
      expect(video.isImage, isFalse,
          reason: 'a 12 MB video inside a message is a chat store nobody '
              'can load twice');
      expect(video.text, contains('Clip.mp4'));
      expect(video.text, contains('🎞'));
    });

    test('a file name off the air cannot become a path', () {
      NearbyShare.debugSendOverride = (to, kind, p) async => true;
      // It gets written to disk under this name.
      NearbyShare.instance.handle(asPacket(MeshPacket.kindOffer, {
        'id': 'p1',
        'n': '../../../Library/Preferences/x.plist',
        'c': 1,
        'k': 'file',
        'd': '15550102222',
      }));
      final name = NearbyShare.instance.byId('p1')!.fileName;
      expect(name.contains('/'), isFalse);
      expect(name.contains('..'), isFalse);

      // And a name of nothing usable still gets one.
      NearbyShare.instance.handle(asPacket(MeshPacket.kindOffer, {
        'id': 'p2',
        'n': '...',
        'c': 1,
        'k': 'video',
        'd': '15550102222',
      }));
      expect(NearbyShare.instance.byId('p2')!.fileName, 'Video');
    });

    test('a kind off the air is a claim, and an unknown one is just a file',
        () {
      NearbyShare.debugSendOverride = (to, kind, p) async => true;
      for (final (id, claimed) in [
        ('k1', 'executable'),
        ('k2', ''),
        ('k3', 42),
      ]) {
        NearbyShare.instance.handle(asPacket(MeshPacket.kindOffer, {
          'id': id,
          'n': 'thing',
          'c': 1,
          'k': claimed,
          'd': '15550102222',
        }));
        expect(NearbyShare.instance.byId(id)!.kind, 'file',
            reason: 'claimed $claimed');
      }
    });

    test('bytes survive the trip through a data URI', () {
      final original = mp4();
      final uri = NearbyPick.dataUriFor(original, 'video');
      expect(uri, startsWith('data:video/mp4;base64,'));
      expect(NearbyShare.bytesOfDataUri(uri), original);

      // And anything that is not one is refused rather than half-decoded.
      for (final bad in [
        'https://example.com/x.mp4',
        'data:video/mp4,not-base64-at-all',
        'data:video/mp4;base64,!!!!',
        '',
      ]) {
        expect(NearbyShare.bytesOfDataUri(bad), isNull, reason: bad);
      }
    });

    test('either end can stop a transfer that is already moving', () async {
      final sent = <(String, String, Map<String, dynamic>)>[];
      NearbyShare.debugSendOverride = (to, kind, p) async {
        sent.add((to, kind, p));
        return true;
      };

      // Receiving: accepted, then thought better of it.
      NearbyShare.instance.handle(asPacket(MeshPacket.kindOffer, {
        'id': 'r1',
        'n': 'Clip.mp4',
        'c': 40,
        'k': 'video',
        'd': '15550102222',
      }));
      await NearbyShare.instance.accept('r1');
      expect(NearbyShare.instance.byId('r1')!.state, TransferState.receiving);
      await NearbyShare.instance.cancel('r1');
      expect(NearbyShare.instance.byId('r1')!.state, TransferState.cancelled);
      // The other end is told, or it keeps pushing at a phone that stopped
      // listening.
      final no = sent.lastWhere((e) => e.$2 == MeshPacket.kindAnswer);
      expect(no.$3['ok'], false);
      // And what had arrived is LET GO OF, not merely ignored — a cancelled
      // 12 MB video whose slices stay in a map is a cancel that freed
      // nothing.
      expect(NearbyShare.instance.heldBuffers, 0);
      NearbyShare.instance.handle(asPacket(
          MeshPacket.kindChunk, {'id': 'r1', 'i': 0, 'c': 40, 'p': 'xxxx'}));
      expect(NearbyShare.instance.byId('r1')!.received, 0);
      expect(NearbyShare.instance.heldBuffers, 0);
    });

    test('a change of mind mid-transfer actually stops the sending', () async {
      final sent = <(String, String, Map<String, dynamic>)>[];
      NearbyShare.debugSendOverride = (to, kind, p) async {
        sent.add((to, kind, p));
        // The receiver says no partway through, exactly as it would arrive.
        if (p['i'] == 2) {
          NearbyShare.instance.handle(
              asPacket(MeshPacket.kindAnswer, {'id': sentId, 'ok': false}));
        }
        return true;
      };
      final data = 'data:image/png;base64,${'Z' * 30000}';
      final t = (await NearbyShare.instance
          .offer(ada(), data, fileName: 'Big.png', kind: 'image'))!;
      sentId = t.id;
      NearbyShare.instance
          .handle(asPacket(MeshPacket.kindAnswer, {'id': t.id, 'ok': true}));
      await Future<void>.delayed(const Duration(milliseconds: 20));

      expect(NearbyShare.instance.byId(t.id)!.state, TransferState.cancelled,
          reason: 'a no arriving mid-transfer used to be ignored entirely');
      final chunks = sent.where((e) => e.$2 == MeshPacket.kindChunk).length;
      expect(chunks, lessThan(t.totalChunks),
          reason: 'it kept sending after they said stop');
    });

    testWidgets('what is moving is visible wherever you are', (t) async {
      // The transfer list lives on the screen you would have SENT from, which
      // is exactly the screen a receiver is not on. Accepting a video used to
      // be the last thing that happened on screen.
      NearbyShare.debugSendOverride = (to, kind, p) async => true;
      await t.pumpWidget(const MaterialApp(
          home: NearbyOfferHost(child: Scaffold(body: Text('home')))));
      // Settle the route transition first — a half-open route absorbs
      // pointers, so a tap on the banner lands on nothing.
      await t.pumpAndSettle();
      expect(find.byType(NearbyTransferBanner), findsOneWidget);
      expect(find.textContaining('Clip.mp4'), findsNothing);

      NearbyShare.instance.handle(asPacket(MeshPacket.kindOffer, {
        'id': 'b1',
        'n': 'Clip.mp4',
        'c': 10,
        'k': 'video',
        'd': '15550102222',
      }));
      await t.pumpAndSettle();
      // Through the dialog, as a person would — its barrier is part of the
      // screen the banner has to appear on.
      await t.tap(find.text('Accept'));
      await t.pumpAndSettle();
      NearbyShare.instance.handle(asPacket(
          MeshPacket.kindChunk, {'id': 'b1', 'i': 0, 'c': 10, 'p': 'aaaa'}));
      await t.pump();

      expect(find.textContaining('Clip.mp4 · Receiving 10%'), findsOneWidget);
      // And a way out of it from right there.
      await t.tap(find.text('Stop'));
      await t.pump();
      expect(NearbyShare.instance.byId('b1')!.state, TransferState.cancelled);
      expect(find.textContaining('Stopped'), findsOneWidget);
    });

    test('what the banner says about a transfer', () {
      NearbyTransfer at(TransferState state, {int received = 0}) =>
          NearbyTransfer(
              id: 'x',
              peerDigits: '1',
              peerName: 'Ada',
              fileName: 'Clip.mp4',
              totalChunks: 4,
              state: state,
              received: received);
      expect(
          NearbyTransferBanner.statusLine(
              at(TransferState.receiving, received: 1)),
          'Receiving 25%');
      expect(NearbyTransferBanner.statusLine(at(TransferState.done)), 'Done');
      expect(NearbyTransferBanner.statusLine(at(TransferState.cancelled)),
          'Stopped');
      // Every state says something — an unhandled one would be a blank pill.
      for (final state in TransferState.values) {
        expect(NearbyTransferBanner.statusLine(at(state)), isNotEmpty,
            reason: '$state');
      }
    });

    test('a picture is still shrunk to fit, so it goes either way', () {
      // The photo path resizes into the relay's budget; the file path does
      // not touch the bytes. Both exist on the screen on purpose — a photo
      // has to survive a Bluetooth-only room.
      final src =
          File('lib/screens/nearby_share_screen.dart').readAsStringSync();
      expect(src.contains('PhotoPrep.pickPhoto()'), isTrue);
      expect(src.contains('NearbyPick.pick(limit: _limit)'), isTrue);
    });
  });

  group('The fast link between two phones', () {
    const channel = MethodChannel('okay/nearbyfast');
    late List<MethodCall> platform;

    setUp(() {
      SharedPreferences.setMockInitialValues({});
      MeshService.instance.resetForTest();
      NearbyShare.instance.resetForTest();
      NearbyFast.instance.resetForTest();
      NearbyPeople.instance.clear();
      ChatStore.instance.reset();
      Session.instance.signInForTest();
      AppState.resetForTest();
      platform = [];
      NearbyFast.debugAvailableOverride = true;
      TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
          .setMockMethodCallHandler(channel, (call) async {
        platform.add(call);
        return call.method == 'send' ? true : null;
      });
    });

    tearDown(() {
      TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
          .setMockMethodCallHandler(channel, null);
      NearbyFast.debugAvailableOverride = null;
      NearbyFast.debugSendOverride = null;
      NearbyFast.instance.resetForTest();
      NearbyShare.instance.resetForTest();
      NearbyShare.debugSendOverride = null;
      MeshService.instance.resetForTest();
      MeshService.debugSendOverride = null;
    });

    /// The digits [Session.signInForTest] signs in as.
    const me = '15550100';

    NearbyPerson ada() => NearbyPerson(
        digits: '15550102222',
        name: 'Ada',
        avatarColor: '#2E7D32',
        heardAt: DateTime.now());

    String hello(String digits, String name) =>
        jsonEncode({'k': 'hi', 'd': digits, 'n': name});

    /// Brings the link up with one peer already connected and named.
    Future<void> linkTo(String token, String digits, String name) async {
      NearbyFast.instance.debugMarkRunning();
      await NearbyFast.instance.notePeers([token]);
      NearbyFast.instance.noteBody(token, hello(digits, name));
    }

    test('nothing about you is in the air before a link exists', () async {
      await NearbyFast.instance.start(advertise: true);
      final start = platform.singleWhere((c) => c.method == 'start');
      final token = (start.arguments as Map)['token'] as String;

      expect(token, matches(RegExp(r'^[0-9a-f]{16}$')));
      expect(token.contains(me), isFalse,
          reason: 'a phone number is not an advertising name');
      expect(jsonEncode(start.arguments).contains('You'), isFalse,
          reason: 'nor is a name');

      // And it is different next time, so it is not a handle that follows
      // somebody between rooms.
      await NearbyFast.instance.stop();
      platform.clear();
      await NearbyFast.instance.start(advertise: true);
      final second = (platform.singleWhere((c) => c.method == 'start').arguments
          as Map)['token'] as String;
      expect(second, isNot(token));
    });

    test('a peer cannot be addressed until it says who it is', () async {
      final sent = <(String, String)>[];
      NearbyFast.debugSendOverride = (to, body) => sent.add((to, body));
      NearbyFast.instance.debugMarkRunning();

      await NearbyFast.instance.notePeers(['tok-ada']);
      expect(NearbyFast.instance.hasPeer('15550102222'), isFalse,
          reason: 'a token is not a person');
      expect(
          await NearbyFast.instance
              .send('15550102222', MeshPacket.kindOffer, const {'id': 'x'}),
          isFalse);

      NearbyFast.instance.noteBody('tok-ada', hello('15550102222', 'Ada'));
      expect(NearbyFast.instance.hasPeer('15550102222'), isTrue);
      expect(NearbyFast.instance.peerDigits, ['15550102222']);
    });

    test('a hello from a token with no link is ignored', () {
      NearbyFast.instance.debugMarkRunning();
      NearbyFast.instance.noteBody('never-linked', hello('15550109999', 'Mal'));
      expect(NearbyFast.instance.hasPeer('15550109999'), isFalse);
    });

    test('a hello has to look like a person, or it is dropped', () async {
      NearbyFast.instance.debugMarkRunning();
      await NearbyFast.instance.notePeers(['tok']);
      for (final body in [
        jsonEncode({'k': 'hi', 'd': '', 'n': 'A'}),
        jsonEncode({'k': 'hi', 'd': 'not-digits', 'n': 'A'}),
        jsonEncode({'k': 'hi', 'd': 12345, 'n': 'A'}),
        jsonEncode({'k': 'hi', 'd': '1' * 60, 'n': 'A'}),
        jsonEncode({'k': 'something-else', 'd': '15550102222'}),
        'not json at all',
      ]) {
        expect(NearbyFast.instance.noteBody('tok', body), isFalse,
            reason: 'accepted $body');
      }
      expect(NearbyFast.instance.peerDigits, isEmpty);
    });

    test('hiding stops the fast link volunteering who you are', () async {
      final sent = <(String, String)>[];
      NearbyFast.debugSendOverride = (to, body) => sent.add((to, body));

      NearbyFast.instance.debugMarkRunning(advertising: false);
      await NearbyFast.instance.notePeers(['tok']);
      expect(sent, isEmpty,
          reason: 'somebody who is not findable is not findable here either');

      NearbyFast.instance.resetForTest();
      NearbyFast.instance.debugMarkRunning(advertising: true);
      await NearbyFast.instance.notePeers(['tok']);
      expect(sent.single.$2.contains(me), isTrue);
    });

    test('a peer leaving takes its route with it', () async {
      await linkTo('tok-ada', '15550102222', 'Ada');
      expect(NearbyFast.instance.hasPeer('15550102222'), isTrue);
      await NearbyFast.instance.notePeers([]);
      expect(NearbyFast.instance.hasPeer('15550102222'), isFalse,
          reason: 'a route to somebody who walked out is a transfer that '
              'hangs');
    });

    test('a packet meant for somebody else is not opened', () async {
      await linkTo('tok-ada', '15550102222', 'Ada');
      NearbyFast.instance.noteBody(
          'tok-ada',
          jsonEncode({
            'k': 'pkt',
            'kind': MeshPacket.kindOffer,
            'to': '15550109999',
            'p': {'id': 't1', 'n': 'Photo', 'c': 1, 'd': '15550102222'},
          }));
      expect(NearbyShare.instance.transfers, isEmpty);
    });

    test('only a transfer may cross the fast link', () async {
      await linkTo('tok-ada', '15550102222', 'Ada');
      for (final kind in [
        MeshPacket.kindMessage,
        MeshPacket.kindCommunity,
        MeshPacket.kindHello,
        MeshPacket.kindServer,
        'made-up',
      ]) {
        expect(
            NearbyFast.instance.noteBody(
                'tok-ada',
                jsonEncode({
                  'k': 'pkt',
                  'kind': kind,
                  'to': me,
                  'p': {'id': 't1', 'n': 'Photo', 'c': 1, 'd': '15550102222'},
                })),
            isFalse,
            reason: '$kind crossed a link that carries files only');
      }
      expect(NearbyShare.instance.transfers, isEmpty,
          reason: 'this carries files, not the message bus');

      // The kinds it is for do get through.
      expect(
          NearbyFast.instance.noteBody(
              'tok-ada',
              jsonEncode({
                'k': 'pkt',
                'kind': MeshPacket.kindOffer,
                'to': me,
                'p': {'id': 't1', 'n': 'Photo', 'c': 1, 'd': '15550102222'},
              })),
          isTrue);
      expect(NearbyShare.instance.pendingIncoming?.id, 't1');
    });

    test('a transfer over the fast link is cut into far bigger pieces',
        () async {
      final data = 'data:image/png;base64,${'D' * 90000}';
      NearbyShare.debugSendOverride = (to, kind, p) async => true;

      final slow =
          (await NearbyShare.instance.offer(ada(), data, fileName: 'Photo'))!;
      expect(slow.fast, isFalse);

      NearbyShare.instance.resetForTest();
      await linkTo('tok-ada', '15550102222', 'Ada');
      final fast =
          (await NearbyShare.instance.offer(ada(), data, fileName: 'Photo'))!;
      expect(fast.fast, isTrue);
      expect(fast.totalChunks, lessThan(slow.totalChunks ~/ 5),
          reason: 'the four-kilobyte ceiling is a Bluetooth ceiling');
    });

    test('a file sent in big pieces still rebuilds exactly', () async {
      final sent = <(String, String, Map<String, dynamic>)>[];
      NearbyShare.debugSendOverride = (to, kind, p) async {
        sent.add((to, kind, p));
        return true;
      };
      await linkTo('tok-ada', '15550102222', 'Ada');
      final data = 'data:image/png;base64,${'E' * 90000}';
      final t =
          (await NearbyShare.instance.offer(ada(), data, fileName: 'Photo'))!;
      NearbyShare.instance.handle(MeshPacket(
          id: 'a1',
          to: me,
          ttl: 0,
          kind: MeshPacket.kindAnswer,
          payload: {'id': t.id, 'ok': true}));
      await Future<void>.delayed(Duration.zero);

      final chunks = sent.where((e) => e.$2 == MeshPacket.kindChunk).toList();
      expect(chunks, hasLength(t.totalChunks));
      final assembler = TransferAssembler(t.totalChunks);
      for (final c in chunks) {
        assembler.add(c.$3['i'] as int, c.$3['p'] as String);
      }
      expect(assembler.assemble(), data);
    });

    test('the fast link is used when it is there, Bluetooth when it is not',
        () async {
      final fast = <(String, String)>[];
      final bluetooth = <String>[];
      NearbyFast.debugSendOverride = (to, body) => fast.add((to, body));
      MeshService.debugSendOverride = bluetooth.add;

      // Nobody linked: it goes over the radio.
      await NearbyShare.instance
          .offer(ada(), 'data:image/png;base64,AAAA', fileName: 'Photo');
      expect(fast, isEmpty);
      expect(bluetooth, isNotEmpty);

      // Linked: it goes over the link, and not over the radio.
      NearbyShare.instance.resetForTest();
      bluetooth.clear();
      await linkTo('tok-ada', '15550102222', 'Ada');
      fast.clear();
      await NearbyShare.instance
          .offer(ada(), 'data:image/png;base64,AAAA', fileName: 'Photo');
      expect(fast, hasLength(1));
      expect(bluetooth, isEmpty);
    });

    test('a link that refuses a packet falls back to Bluetooth', () async {
      final bluetooth = <String>[];
      MeshService.debugSendOverride = bluetooth.add;
      await linkTo('tok-ada', '15550102222', 'Ada');
      // The route is known, but the platform says no — a peer that dropped
      // between the peer list and the send.
      TestDefaultBinaryMessengerBinding.instance.defaultBinaryMessenger
          .setMockMethodCallHandler(channel, (call) async => false);

      await NearbyShare.instance
          .offer(ada(), 'data:image/png;base64,AAAA', fileName: 'Photo');
      expect(bluetooth, isNotEmpty,
          reason: 'a transfer does not fail because the quick way did');
    });

    test('newer iOS APIs are guarded above whatever the floor is now', () {
      // TWICE NOW. CXProviderConfiguration() and then
      // UNNotificationPresentationOptions.banner — both iOS 14, both compile
      // fine to read, both failed the archive on Codemagic minutes after a
      // green suite. There is no Xcode here, so this is the only place the
      // mistake can be caught before a build.
      final pbx =
          File('ios/Runner.xcodeproj/project.pbxproj').readAsStringSync();
      final target = RegExp(r'IPHONEOS_DEPLOYMENT_TARGET = ([0-9.]+);')
          .firstMatch(pbx)!
          .group(1)!;
      final major = int.parse(target.split('.').first);

      // Each symbol with the iOS version it first exists in. Per-symbol,
      // because a single "below the floor?" switch is a trap: raising the
      // target from 13 to 15 would have turned the WHOLE check off, silently
      // taking setBadgeCount (16) and TranslationSession (17.4) — both still
      // above the floor — with it. Not exhaustive; it is the list of ones
      // this codebase has actually reached for.
      const needsAvailable = <String, int>{
        '.banner': 14,
        '.list': 14,
        'CXProviderConfiguration()': 14,
        'setBadgeCount(': 16,
        // Apple's Translation framework — iOS 17.4 for the programmatic API.
        'TranslationSession(': 17,
      };

      for (final file in Directory('ios/Runner')
          .listSync()
          .whereType<File>()
          .where((f) => f.path.endsWith('.swift'))) {
        // Comments talk about these on purpose; only real code counts.
        final lines = [
          for (final line in file.readAsLinesSync())
            line.contains('//') ? line.substring(0, line.indexOf('//')) : line
        ];
        for (var i = 0; i < lines.length; i++) {
          for (final entry in needsAvailable.entries) {
            // Already available everywhere the app runs — a guard would be
            // dead code, not a bug.
            if (entry.value <= major) continue;
            if (!lines[i].contains(entry.key)) continue;
            final from = i - 10 < 0 ? 0 : i - 10;
            // Any #available(iOS …) counts: each symbol is guarded at its
            // own floor, which is not necessarily the app's.
            final guarded = lines
                .sublist(from, i + 1)
                .any((l) => l.contains('#available(iOS 1'));
            expect(guarded, isTrue,
                reason: '${file.path}:${i + 1} uses ${entry.key} (iOS '
                    '${entry.value}+) with no #available(iOS …) above it, '
                    'and the target is $target');
          }
        }
      }
    });

    test('the iOS floor is 15, and every place that declares it agrees', () {
      // Raised from 13 on 2026-08-09: App Store Connect warns that 13 stops
      // being accepted in Spring 2027. Three files say it and a disagreement
      // is the "building for iOS 15 but linking a dylib built for iOS 13"
      // archive warning — so they are checked together, not one at a time.
      final pbx =
          File('ios/Runner.xcodeproj/project.pbxproj').readAsStringSync();
      final targets = RegExp(r'IPHONEOS_DEPLOYMENT_TARGET = ([0-9.]+);')
          .allMatches(pbx)
          .map((m) => m.group(1))
          .toSet();
      expect(targets, {'15.0'},
          reason: 'every build configuration must name the same floor');

      final podfile = File('ios/Podfile').readAsStringSync();
      expect(podfile, contains("platform :ios, '15.0'"));
      expect(podfile, contains("'IPHONEOS_DEPLOYMENT_TARGET'] = '15.0'"),
          reason: 'pods left below the app target warn, then fail');
    });

    test('the Bonjour service the app browses is the one it declares', () {
      // iOS 14 and later refuses to browse a service that is not listed in
      // NSBonjourServices, silently — the peer list just stays empty.
      final swift = File('ios/Runner/NearbyFast.swift').readAsStringSync();
      final type =
          RegExp(r'serviceType = "([a-z0-9-]+)"').firstMatch(swift)!.group(1)!;
      final plist = File('ios/Runner/Info.plist').readAsStringSync();
      for (final proto in ['tcp', 'udp']) {
        expect(plist.contains('<string>_$type._$proto</string>'), isTrue,
            reason: 'Info.plist does not declare _$type._$proto');
      }
      expect(plist.contains('NSLocalNetworkUsageDescription'), isTrue,
          reason: 'iOS shows this before the first browse, and refuses '
              'without it');
    });
  });
  group('push self-test', () {
    // A push that never arrives has six different causes and one appearance.
    // These lock down that the report names which one, because the whole
    // reason it exists is that a dashboard cannot tell anybody.

    PushCheck check({
      bool p8 = true,
      bool keyId = true,
      bool teamId = true,
      String bundleId = 'com.okaymessaging',
      bool sandbox = false,
      String keyError = '',
      String prodReason = 'BadDeviceToken',
      String sandboxReason = 'BadDeviceToken',
      bool registered = true,
    }) =>
        PushCheck.fromJson({
          'secrets': {
            'p8': p8,
            'keyId': keyId,
            'teamId': teamId,
            'bundleId': bundleId,
            'sandbox': sandbox,
          },
          'keyError': keyError,
          'production': {
            'host': 'api.push.apple.com',
            'status': 400,
            'reason': prodReason,
          },
          'sandbox': {
            'host': 'api.sandbox.push.apple.com',
            'status': 400,
            'reason': sandboxReason,
          },
          'device': {'registered': registered},
        })!;

    (String, bool) verdict(PushCheck? c,
            {bool releaseBuild = true,
            bool pushable = true,
            String? error,
            bool signedIn = true}) =>
        PushSelfTest.verdictFor(
          relayEnabled: true,
          signedIn: signedIn,
          releaseBuild: releaseBuild,
          pushablePlatform: pushable,
          check: c,
          error: error,
        );

    test('Apple accepting the made-up token is the pass', () {
      // BadDeviceToken is the *good* answer: Apple validates the provider
      // token, then the topic, then the device token, so rejecting only the
      // last one means it approved the key, the team and the app.
      final (text, faulty) = verdict(check());
      expect(faulty, isFalse);
      expect(text, contains('set up correctly'));
    });

    test('a rejected signing key names the three secrets that make it', () {
      final (text, faulty) = verdict(check(prodReason: 'InvalidProviderToken'));
      expect(faulty, isTrue);
      expect(text, contains('APNS_KEY_ID'));
      expect(text, contains('APNS_TEAM_ID'));
      expect(text, contains('APNS_P8'));
      // And must not send somebody after the bundle id, which Apple never
      // got as far as reading.
      expect(text, isNot(contains('APNS_BUNDLE_ID')));
    });

    test('a disallowed topic blames the bundle id and nothing else', () {
      final (text, faulty) = verdict(
          check(bundleId: 'com.wrong.app', prodReason: 'TopicDisallowed'));
      expect(faulty, isTrue);
      expect(text, contains('APNS_BUNDLE_ID'));
      expect(text, contains('com.wrong.app'));
      expect(text, isNot(contains('APNS_P8')));
    });

    test('a p8 that is set but unreadable is not reported as missing', () {
      // "Not set" would send somebody back to Apple for a key they already
      // have, when the fault is how it was pasted.
      final (text, _) = verdict(check(keyError: 'Invalid keyData'));
      expect(text, contains('cannot be read'));
      expect(text, contains('BEGIN'));
      expect(text, isNot(contains('is not set')));
    });

    test('missing secrets are named individually', () {
      expect(verdict(check(p8: false)).$1, contains('APNS_P8 is not set'));
      expect(verdict(check(keyId: false)).$1,
          allOf(contains('APNS_KEY_ID'), isNot(contains('APNS_TEAM_ID'))));
      expect(verdict(check(teamId: false)).$1,
          allOf(contains('APNS_TEAM_ID'), isNot(contains('APNS_KEY_ID'))));
    });

    test('an expired sign-in is named, not dumped as an exception', () {
      // The report used to say "Signed in ✓ This device has a session" one
      // line above "unauthorized ✗" — both true, together a contradiction
      // that dumped a raw FunctionException at whoever opened the screen.
      // A local session the server refuses is an EXPIRED sign-in, and the
      // fix worth saying is sign out, sign back in.
      final (text, faulty) = verdict(null, error: PushSelfTest.kSessionExpired);
      expect(faulty, isTrue);
      expect(text, contains('expired'));
      expect(text.toLowerCase(), contains('sign out'));
      expect(text, isNot(contains('FunctionException')));

      final steps = PushSelfTest.stepsFor(
        relayEnabled: true,
        signedIn: true,
        releaseBuild: true,
        pushablePlatform: true,
        check: null,
        error: PushSelfTest.kSessionExpired,
      );
      final signedIn = steps.firstWhere((s) => s.title == 'Signed in');
      expect(signedIn.state, CheckState.fail,
          reason: 'a session the server refuses is not a green tick');
      expect(signedIn.detail, contains('expired'));

      // And the mapping recognises what the client actually throws.
      expect(PushSelfTest.isAuthFailure(StateError('the server answered 401')),
          isTrue);
      expect(PushSelfTest.isAuthFailure(StateError('the server answered 500')),
          isFalse);
    });

    test('sandbox is judged against the build that is asking', () {
      // The failure this exists for: every secret correct, APNS_SANDBOX left
      // on, and a TestFlight build receiving nothing for ever.
      final release = verdict(check(sandbox: true), releaseBuild: true);
      expect(release.$2, isTrue);
      expect(release.$1, contains('APNS_SANDBOX'));
      expect(release.$1, contains('production'));

      // The same setting is correct for a build installed from Xcode, so it
      // must not be reported as a fault there.
      expect(verdict(check(sandbox: true), releaseBuild: false).$2, isFalse);

      // And the mirror image: a debug build against production APNs is worth
      // saying, but it is not somebody's setup being wrong.
      final debugOnProd = verdict(check(), releaseBuild: false);
      expect(debugOnProd.$2, isFalse);
      expect(debugOnProd.$1, contains('Xcode'));
    });

    test('the sandbox flag decides which of Apple\'s answers counts', () {
      // Both hosts are asked, but only the one the server actually sends to
      // can decide the verdict.
      expect(
          check(sandbox: true, sandboxReason: 'InvalidProviderToken')
              .active
              .reason,
          'InvalidProviderToken');
      expect(
          verdict(
                  check(
                      sandbox: true,
                      prodReason: 'BadDeviceToken',
                      sandboxReason: 'InvalidProviderToken'),
                  releaseBuild: false)
              .$2,
          isTrue);
    });

    test('a phone that never registered is separated from a bad secret', () {
      final (text, faulty) = verdict(check(registered: false));
      expect(faulty, isTrue);
      expect(text, contains('never uploaded'));
      // The secrets are fine, and saying otherwise would send somebody to
      // the wrong dashboard.
      expect(text, contains('secret is right'));

      // On a build that cannot receive one at all, that is not a fault.
      final web = verdict(check(registered: false), pushable: false);
      expect(web.$2, isFalse);
    });

    test('iOS refusing a token is told apart from permission never asked', () {
      (String, bool) v({String? regError, bool token = false, String? up}) =>
          PushSelfTest.verdictFor(
            relayEnabled: true,
            signedIn: true,
            releaseBuild: true,
            pushablePlatform: true,
            check: check(registered: false),
            error: null,
            tokenReceived: token,
            registrationError: regError,
            uploadError: up,
          );

      // The entitlement failure has exactly one fix and it is not on the
      // phone: the build was signed without push. Sending somebody to iOS
      // Settings for it wastes their toggle and their trust.
      final entitlement = v(
          regError: 'no valid \'aps-environment\' entitlement string found '
              'for application');
      expect(entitlement.$2, isTrue);
      expect(entitlement.$1, contains('entitlement'));
      expect(entitlement.$1.toLowerCase(), contains('build'));
      expect(entitlement.$1, isNot(contains('Allow notifications')),
          reason: 'Settings cannot fix a binary signed without push');

      // Any other refusal at least shows its reason instead of guessing.
      expect(v(regError: 'simulator').$1, contains('simulator'));

      // A token that arrived but never stuck server-side is an upload
      // fault, and the reason it failed is the whole diagnosis.
      final upload = v(token: true, up: 'row-level security');
      expect(upload.$2, isTrue);
      expect(upload.$1, contains('uploading'));
      expect(upload.$1, contains('row-level security'));

      // And the steps say the same thing the verdict does.
      List<DiagnosticStep> steps(
              {String? regError, bool token = false, String? up}) =>
          PushSelfTest.stepsFor(
            relayEnabled: true,
            signedIn: true,
            releaseBuild: true,
            pushablePlatform: true,
            check: check(registered: false),
            error: null,
            tokenReceived: token,
            registrationError: regError,
            uploadError: up,
          );
      DiagnosticStep tokenStep(List<DiagnosticStep> s) =>
          s.firstWhere((x) => x.title == 'This device\'s token');
      expect(tokenStep(steps(regError: 'aps-environment ...')).detail,
          contains('new build'));
      expect(tokenStep(steps(token: true, up: 'denied')).detail,
          contains('denied'));
      expect(tokenStep(steps()).detail, contains('Allow notifications'));

      // The native side reports the refusal at all — the failure used to be
      // swallowed, which left this screen guessing about permissions.
      final swift = File('ios/Runner/AppDelegate.swift').readAsStringSync();
      expect(
          swift, contains('didFailToRegisterForRemoteNotificationsWithError'));
      expect(swift, contains('"tokenError"'));
      final dart = File('lib/state/push_service.dart').readAsStringSync();
      expect(dart, contains('tokenError'));
    });

    test('an old deployment is told apart from a broken one', () {
      // push-send before this change answers { sent: false } — a valid reply
      // that is not a self-test. Reading it as "no secrets set" would be a
      // confident wrong answer.
      expect(PushCheck.fromJson({'sent': false}), isNull);
      expect(PushCheck.fromJson(null), isNull);
      final (text, faulty) = verdict(null, error: 'old-deployment');
      expect(faulty, isTrue);
      expect(text, contains('push-send'));
      expect(text, contains('docs/edge_functions_paste/push-send.ts'));
    });

    test('the steps never carry a secret\'s value', () {
      // The report is written to be pasted into a message, so the server may
      // only ever say whether a secret is set — never what it is.
      final src =
          File('supabase/functions/push-send/index.ts').readAsStringSync();
      final body = src.substring(
          src.indexOf('async function checkSetup'), src.indexOf('Deno.serve'));
      for (final name in ['APNS_P8', 'APNS_KEY_ID', 'APNS_TEAM_ID']) {
        expect(body.contains('present("$name")'), isTrue,
            reason: '$name must be reported as a boolean');
        expect(RegExp('Deno\\.env\\.get\\("$name"\\)').hasMatch(body), isFalse,
            reason: '$name must never reach the response');
      }
      // And it must not deliver anything while checking: the device token is
      // one nobody owns.
      expect(body.contains('"0".repeat(64)'), isTrue);
    });

    testWidgets('the report says which link is broken', (t) async {
      addTearDown(() => PushSelfTest.debugCheckProbe = null);
      // Tall enough that the verdict below seven steps is built at all — a
      // ListView does not build what is off screen, and a finder cannot see
      // what was never built.
      t.view.physicalSize = const Size(1000, 2400);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.reset);
      PushSelfTest.debugCheckProbe = () async => {
            'secrets': {
              'p8': true,
              'keyId': true,
              'teamId': true,
              'bundleId': 'com.okaymessaging',
              'sandbox': false,
            },
            'keyError': '',
            'production': {
              'host': 'api.push.apple.com',
              'status': 403,
              'reason': 'InvalidProviderToken',
            },
            'sandbox': {
              'host': 'api.sandbox.push.apple.com',
              'status': 403,
              'reason': 'InvalidProviderToken',
            },
            'device': {'registered': true},
          };

      final steps = PushSelfTest.stepsFor(
        relayEnabled: true,
        signedIn: true,
        releaseBuild: true,
        pushablePlatform: true,
        check: PushCheck.fromJson(await PushSelfTest.debugCheckProbe!()),
        error: null,
      );
      await t.pumpWidget(MaterialApp(
        home: SelfTestScreen(
          title: 'Check push setup',
          run: () async => SelfTestReport(
            title: 'Push self-test',
            steps: steps,
            verdict: PushSelfTest.verdictFor(
              relayEnabled: true,
              signedIn: true,
              releaseBuild: true,
              pushablePlatform: true,
              check: PushCheck.fromJson(await PushSelfTest.debugCheckProbe!()),
              error: null,
            ).$1,
            faulty: true,
          ),
        ),
      ));
      await t.pumpAndSettle();

      expect(find.text('What to change'), findsOneWidget);
      expect(find.text('Apple'), findsOneWidget);
      expect(find.textContaining('Rejected the signing key'), findsOneWidget);
      // The steps that are fine must still say so, or the one that is not
      // does not stand out.
      expect(find.textContaining('Set, and it signs.'), findsOneWidget);
    });

    test('a pasted report names the test it came from', () {
      const r = SelfTestReport(
          title: 'Push self-test',
          steps: [DiagnosticStep('Apple', 'accepted', CheckState.pass)],
          verdict: 'fine',
          faulty: false);
      expect(r.report.split('\n').first, 'Push self-test');
      expect(r.report, contains('[ok]   Apple: accepted'));
    });

    testWidgets('the plumbing checks exist for admins and for nobody else',
        (t) async {
      // The verdicts name Supabase secrets, APNs keys and TURN config —
      // operator vocabulary. A tester or user never sees the rows; the
      // same server-driven role that opens the moderation console (one
      // rank stricter) is what reveals them.
      PlatformModeration.instance.debugSet(role: PlatformRole.admin);
      addTearDown(PlatformModeration.instance.resetForTest);
      await t.pumpWidget(const MaterialApp(home: SettingsScreen()));
      await t.pump(const Duration(milliseconds: 100));
      await t.scrollUntilVisible(find.text('Check push setup'), 240,
          scrollable: find.byType(Scrollable).first);
      expect(find.text('Check push setup'), findsOneWidget);
      expect(find.text('Check call setup'), findsOneWidget);
      expect(find.text('Check live delivery'), findsOneWidget);
      expect(find.text('Check notification preview'), findsOneWidget);

      // And the gate really is the admin one: the four rows live inside
      // the canAdminister branch, after the plain notification tiles.
      final src = File('lib/screens/settings_screen.dart').readAsStringSync();
      final gate = src.indexOf('canAdminister');
      expect(gate, greaterThan(-1));
      for (final title in [
        "'Check call setup'",
        "'Check push setup'",
        "'Check live delivery'",
        "'Check notification preview'",
      ]) {
        expect(src.indexOf(title), greaterThan(gate),
            reason: '$title must sit behind the admin gate');
      }
    });
  });

  group('notification preview self-test', () {
    // A locked screen still saying "New message" has (at least) three
    // separate causes — an old build, a stale server deployment, a
    // keychain the extension can't reach — and one appearance. This tests
    // the one thing this self-test can actually observe from the main app
    // process: whether the shared keychain write succeeds, and whether the
    // real test push was accepted by the server.

    (String, bool) verdict({
      bool relayEnabled = true,
      bool signedIn = true,
      bool hasIdentityKeys = true,
      String? keychainError,
      bool attempted = true,
      bool sent = true,
      String? sendError,
      bool retried = false,
      bool tokenReceived = true,
    }) =>
        NotificationPreviewSelfTest.verdictFor(
          relayEnabled: relayEnabled,
          signedIn: signedIn,
          hasIdentityKeys: hasIdentityKeys,
          keychainError: keychainError,
          attempted: attempted,
          sent: sent,
          sendError: sendError,
          retried: retried,
          tokenReceived: tokenReceived,
        );

    test('everything passing names the test sentence and is not faulty', () {
      final (text, faulty) = verdict();
      expect(faulty, isFalse);
      expect(text, contains(NotificationPreviewSelfTest.testSentence));
      expect(text, contains('lock screen'));
    });

    test(
        'a keychain write failure is named as a provisioning fault, not a '
        'setting', () {
      final (text, faulty) = verdict(keychainError: 'errSecMissingEntitlement');
      expect(faulty, isTrue);
      expect(text, contains('errSecMissingEntitlement'));
      expect(text, contains('CLAUDE.md'));
      expect(text, contains('provisioning fault'));
    });

    test(
        'no relay configured is the first thing named, before anything '
        'else is checked', () {
      final (text, faulty) = verdict(relayEnabled: false);
      expect(faulty, isTrue);
      expect(text, contains('no server'));
    });

    test('not signed in is named before identity keys or the keychain', () {
      final (text, faulty) = verdict(signedIn: false);
      expect(faulty, isTrue);
      expect(text, contains('Sign in first'));
    });

    test(
        'missing identity keys names the fix (open a chat) rather than a '
        'raw state', () {
      final (text, faulty) = verdict(hasIdentityKeys: false);
      expect(faulty, isTrue);
      expect(text, contains('identity keys'));
      expect(text, contains('Open any chat'));
    });

    test('a send failure names the underlying error', () {
      final (text, faulty) = verdict(
          attempted: true, sent: false, sendError: 'the server answered 500');
      expect(faulty, isTrue);
      expect(text, contains('the server answered 500'));
    });

    test(
        'a "not confirmed" failure with no push token yet this launch is '
        'named as the common, self-resolving startup race — not a '
        'settings problem', () {
      // Reported live: "sometimes the test push is red and when I restart
      // the app it's green again." PushService re-registers its APNs
      // token on every launch (an async round trip), which this self-test
      // can outrun; sent:false with no thrown error and no token yet this
      // process is exactly that race, not a real fault.
      final (text, faulty) = verdict(sent: false, tokenReceived: false);
      expect(faulty, isTrue);
      expect(text, contains('has not confirmed a push token'));
      expect(text, contains('self-resolving'));
      expect(text, isNot(contains('the server answered')));
    });

    test(
        'the same failure is worded differently once a token IS confirmed '
        '— that is a real fault, not the startup race', () {
      final (text, faulty) = verdict(sent: false, tokenReceived: true);
      expect(faulty, isTrue);
      expect(text, isNot(contains('has not confirmed a push token')));
      expect(text, contains('Check push setup first'));
    });

    test('a retried send says so, whichever way it ended', () {
      final (failText, _) =
          verdict(sent: false, tokenReceived: true, retried: true);
      expect(failText, contains('retried once'));
    });

    test(
        'stepsFor: Test push passing on the retry explains why the first '
        'try found nothing, rather than just silently succeeding', () {
      final steps = NotificationPreviewSelfTest.stepsFor(
        relayEnabled: true,
        signedIn: true,
        hasIdentityKeys: true,
        keychainError: null,
        attempted: true,
        sent: true,
        retried: true,
      );
      final pushStep = steps.firstWhere((s) => s.title == 'Test push');
      expect(pushStep.state, CheckState.pass);
      expect(pushStep.detail, contains('normal race'));
    });

    test(
        'stepsFor: Test push failing with no confirmed token names that '
        'as the likely reason', () {
      final steps = NotificationPreviewSelfTest.stepsFor(
        relayEnabled: true,
        signedIn: true,
        hasIdentityKeys: true,
        keychainError: null,
        attempted: true,
        sent: false,
        retried: true,
        tokenReceived: false,
      );
      final pushStep = steps.firstWhere((s) => s.title == 'Test push');
      expect(pushStep.state, CheckState.fail);
      expect(pushStep.detail, contains('has not confirmed a push token'));
      expect(pushStep.detail, contains('after a retry'));
    });

    test('stepsFor stops after Server/Signed in when either is missing', () {
      final steps = NotificationPreviewSelfTest.stepsFor(
        relayEnabled: true,
        signedIn: false,
        hasIdentityKeys: false,
        keychainError: null,
        attempted: false,
        sent: false,
      );
      expect(steps.map((s) => s.title), ['Server', 'Signed in']);
      expect(steps.last.state, CheckState.fail);
    });

    test(
        'stepsFor checks the keychain independently of identity keys, and '
        'reports the test push as not yet sent', () {
      final steps = NotificationPreviewSelfTest.stepsFor(
        relayEnabled: true,
        signedIn: true,
        hasIdentityKeys: false,
        keychainError: null,
        attempted: false,
        sent: false,
      );
      expect(steps.map((s) => s.title), [
        'Server',
        'Signed in',
        'Identity keys',
        'Shared keychain',
        'Test push',
      ]);
      expect(steps[2].state, CheckState.fail);
      expect(steps[3].state, CheckState.pass);
      expect(steps.last.state, CheckState.unknown);
    });

    test('stepsFor reports a keychain failure as its own failed step', () {
      final steps = NotificationPreviewSelfTest.stepsFor(
        relayEnabled: true,
        signedIn: true,
        hasIdentityKeys: true,
        keychainError: 'boom',
        attempted: true,
        sent: true,
      );
      final keychainStep =
          steps.firstWhere((s) => s.title == 'Shared keychain');
      expect(keychainStep.state, CheckState.fail);
      expect(keychainStep.detail, contains('boom'));
      // A test push can still be sent even when the keychain write failed —
      // the two are reported independently, since a stale build could still
      // be the reason the banner stays generic even with a healthy keychain.
      final pushStep = steps.firstWhere((s) => s.title == 'Test push');
      expect(pushStep.state, CheckState.pass);
    });

    test('a pasted report names the test it came from', () {
      const r = SelfTestReport(
          title: 'Notification preview self-test',
          steps: [
            DiagnosticStep('Shared keychain', 'writable', CheckState.pass)
          ],
          verdict: 'fine',
          faulty: false);
      expect(r.report.split('\n').first, 'Notification preview self-test');
    });

    test('PreviewKeyStore.testWrite defers to the debug hook when installed',
        () async {
      PreviewKeyStore.debugTestWrite = () async => 'simulated failure';
      addTearDown(() => PreviewKeyStore.debugTestWrite = null);
      expect(await PreviewKeyStore.instance.testWrite(), 'simulated failure');

      PreviewKeyStore.debugTestWrite = () async => null;
      expect(await PreviewKeyStore.instance.testWrite(), isNull);
    });

    test(
        'run() actually retries a "sent:false" answer once before giving '
        'up, reading PushService.instance.tokenReceived for context', () {
      // debugSendProbe/retryDelay exist specifically so this race is
      // provable without a real 3-second wait or a real device — pinned
      // here as a source check since assembling a full signed-in run()
      // (Session + SecureKeyExchange + RelayConfig) duplicates what the
      // pure stepsFor/verdictFor tests above already cover for the actual
      // decision logic.
      final src = File('lib/state/notification_preview_diagnostics.dart')
          .readAsStringSync();
      final start = src.indexOf('static Future<SelfTestReport> run()');
      final body = src.substring(
          start, src.indexOf('\n  }\n\n  static Future<Map', start));
      expect(body, contains('if (!sent) {'));
      expect(body, contains('retried = true'));
      expect(body, contains('await Future.delayed(retryDelay)'));
      expect(body, contains('PushService.instance.tokenReceived'));
    });

    test(
        'run() waits for a real push token BEFORE the first attempt too, '
        'bounded rather than open-ended', () {
      // A blind first attempt followed by one fixed retry still fires the
      // first attempt at exactly the wrong moment when a token genuinely
      // isn't ready yet — waiting for the actual precondition first (up to
      // tokenWaitTimeout, polling every tokenPollInterval) means the send
      // only happens once there is something to send it against, or the
      // wait has genuinely timed out. Both bounds are test seams for the
      // same reason retryDelay is.
      final src = File('lib/state/notification_preview_diagnostics.dart')
          .readAsStringSync();
      final start = src.indexOf('static Future<SelfTestReport> run()');
      final body = src.substring(
          start, src.indexOf('\n  }\n\n  static Future<Map', start));
      expect(body, contains('if (!PushService.instance.tokenReceived) {'));
      expect(body, contains('tokenWaitTimeout'));
      expect(body, contains('tokenPollInterval'));
      // The wait happens BEFORE the try/send block, not after — pin the
      // ordering so a future edit can't silently turn this into "wait,
      // then also blind-retry on top of a already-token-aware first try".
      expect(body.indexOf('tokenWaitTimeout'), lessThan(body.indexOf('try {')));
    });
  });
  group('the ID check does not depend on a page of ours', () {
    // What this is about: identity.html is a static file on GitHub Pages, and
    // GitHub's own branch build republishes the repository's README over the
    // app for minutes after every push. A check started in that window showed
    // GitHub's "File not found" page under the words "Verify your identity",
    // with no way forward. Stripe hosts the same check itself, so the app
    // stopped needing a page of its own.

    test('by default nothing of ours is in the path at all', () {
      // No secret means the screen loads Stripe's hosted flow. Asserted
      // against the shipped constant rather than a literal, so turning the
      // default around would fail here rather than silently reinstate the
      // dependency.
      expect(preferHostedIdentity, isTrue);
      expect(
          IdentityVerification.secretFor(
              secret: 'vs_secret',
              hostedUrl: 'https://verify.stripe.com/x',
              pageServed: true,
              preferHosted: preferHostedIdentity),
          isEmpty,
          reason: 'even a page that IS being served is not used by default');
    });

    test('a missing page falls back to Stripe\'s hosted flow', () {
      // The opt-in embedded path still checks. Dropping the secret is the
      // fallback: the screen runs Stripe.js only when it has one.
      expect(
          IdentityVerification.secretFor(
              secret: 'vs_secret',
              hostedUrl: 'https://verify.stripe.com/x',
              pageServed: false,
              preferHosted: false),
          isEmpty);
      expect(
          IdentityVerification.secretFor(
              secret: 'vs_secret',
              hostedUrl: 'https://verify.stripe.com/x',
              pageServed: true,
              preferHosted: false),
          'vs_secret',
          reason: 'opted in, and the page is there — run the themed flow');
    });

    test('with nothing to fall back to, the secret is kept', () {
      // Stripe returned no hosted URL. Dropping the secret here would turn a
      // check that works into no check at all, which is worse than an
      // unthemed one — so this outranks even preferring the hosted flow.
      for (final prefer in [true, false]) {
        expect(
            IdentityVerification.secretFor(
                secret: 'vs_secret',
                hostedUrl: '',
                pageServed: false,
                preferHosted: prefer),
            'vs_secret');
      }
    });

    test('the page probe decides, and an unanswered probe fails closed',
        () async {
      addTearDown(() => IdentityVerification.debugPageProbe = null);
      var asked = '';
      IdentityVerification.debugPageProbe = (url) async {
        asked = url;
        return true;
      };
      expect(await IdentityVerification.pageIsServed(), isTrue);
      expect(asked, IdentityVerification.pageUrl,
          reason: 'it must probe the page it is deciding about');

      // Unreachable is not "fine": the cost of being wrong the other way is a
      // dead end inside the check.
      IdentityVerification.debugPageProbe = (_) async => false;
      expect(await IdentityVerification.pageIsServed(), isFalse);
    });

    test('there is no page of ours to point at by default', () {
      // The embedded page is a web-build artifact: it only exists wherever
      // that build is deployed, and defaulting to one particular deployment
      // is how the GitHub dependency got here in the first place. A build
      // that wants it has to say where its own copy is served from.
      expect(IdentityVerification.pageUrl, isEmpty);

      // And with no page named, the probe cannot report one as available —
      // so opting in without supplying a URL still lands on Stripe's flow
      // rather than on an empty address.
      expect(
          IdentityVerification.secretFor(
              secret: 'vs_secret',
              hostedUrl: 'https://verify.stripe.com/x',
              pageServed: IdentityVerification.pageUrl.isNotEmpty,
              preferHosted: false),
          isEmpty);
    });
  });
  group('the app does not depend on GitHub', () {
    // The site those URLs pointed at republishes the repository README over
    // the app for minutes after every push, and one of them — the email
    // confirmation link — is opened in a browser on somebody else's device,
    // where the app cannot intervene at all. Everything now comes off the
    // Supabase project the app already cannot work without.

    test('nothing in the app or its functions names GitHub', () {
      // A regression test with teeth: this is the whole ask, and a single
      // pasted URL would quietly undo it.
      final offenders = <String>[];
      for (final dir in [Directory('lib'), Directory('supabase/functions')]) {
        for (final f in dir.listSync(recursive: true).whereType<File>()) {
          if (!f.path.endsWith('.dart') && !f.path.endsWith('.ts')) continue;
          if (f.readAsStringSync().contains('github.io')) {
            offenders.add(f.path);
          }
        }
      }
      expect(offenders, isEmpty,
          reason: 'these still point at GitHub Pages: $offenders');
    });

    test('the pages come off whichever Supabase project the build uses', () {
      // Derived rather than configured, so a build pointed at a different
      // project gets that project's pages without a second flag to forget.
      const project = 'https://abc.supabase.co';
      expect(AppPages.baseFor(project, ''),
          'https://abc.supabase.co/functions/v1/pages');
      expect(AppPages.subFor(AppPages.baseFor(project, ''), 'done'),
          'https://abc.supabase.co/functions/v1/pages/done');

      // A trailing slash on either side must not produce a double slash: the
      // function routes on the last path segment, and '' is not 'done'.
      expect(AppPages.baseFor('$project/', ''),
          'https://abc.supabase.co/functions/v1/pages');
      expect(AppPages.baseFor(project, 'https://okay.example/'),
          'https://okay.example');
    });

    test('SITE_URL wins, so a real domain can replace all of it', () {
      expect(
          AppPages.baseFor('https://abc.supabase.co', 'https://okay.example'),
          'https://okay.example');
    });

    test('with no backend there is no URL, and callers must cope', () {
      // Every test binary is this case, and so is a fully local build. An
      // empty string here is load-bearing: an empty completion prefix never
      // matches, and the share text drops the link rather than trailing off
      // after a colon.
      expect(AppPages.baseFor('', ''), isEmpty);
      expect(AppPages.subFor('', 'done'), isEmpty);
      expect(PaymentService.returnUrl, isEmpty);
      expect(IdentityVerification.returnUrl, isEmpty);
      expect(ConnectWebView.isCompletion('https://anything/', ''), isFalse,
          reason: 'an empty prefix must never swallow a navigation');
    });

    test('the server defaults to the same page the client watches for', () {
      // These are two codebases agreeing on a string. If they drift, Stripe's
      // hosted flow ends by navigating somewhere the WebView does not
      // recognise, and the user is left on a web page inside the app.
      const leaf = '/functions/v1/pages/done';
      for (final f in ['identity-start', 'payments-onboard']) {
        final src = File('supabase/functions/$f/index.ts').readAsStringSync();
        expect(src.contains(leaf), isTrue,
            reason: '$f no longer returns to the page the app watches for');
      }
      expect(
          AppPages.subFor(
                  AppPages.baseFor('https://abc.supabase.co', ''), 'done')
              .endsWith(leaf),
          isTrue);
    });

    test('the pages function needs no session, because a browser has none', () {
      final src = File('supabase/functions/pages/index.ts').readAsStringSync();
      expect(src.contains('verify_jwt = false'), isTrue,
          reason: 'a confirmation link carries no Supabase JWT');
      // It must also read nothing and write nothing: it is the one function
      // anybody on the internet can call.
      expect(src.contains('createClient'), isFalse);
      expect(src.contains('SERVICE_ROLE'), isFalse);
    });
  });
