      void answer(String who, List<String> a) =>
          ChatStore.instance.applyFormResponse('c', 'f1',
              FormResponse(from: who, answers: a, at: DateTime(2026, 1, 2)));

      answer('Ada', ['Ada', 'S', '']);
      answer('Bo', ['Bo', 'M', '']);
      answer('Ada', ['Ada Lovelace', 'M', 'changed my mind']);

