    test('a number question can be given a range, and it is enforced once',
        () {
      // Enforced in formatProblem — the ONE funnel the fill screen's live
      // error and the send button's completeness check both already read.
      const age = FormFieldSpec(
          label: 'How many?', kind: FormFieldKind.number, min: 1, max: 8);
      expect(FormResponse.formatProblem(age, '4'), isNull);
      expect(FormResponse.formatProblem(age, '0'),
          'Enter a number between 1 and 8.');
      expect(FormResponse.formatProblem(age, '9'),
          'Enter a number between 1 and 8.');
      // Blank is "not answered", which is the required check's business.
      expect(FormResponse.formatProblem(age, ''), isNull);
      // A value that will not parse is left alone: the keyboard is numeric
      // and "that is not a number" is not worth saying to somebody looking
      // at what they typed.
      expect(FormResponse.formatProblem(age, 'lots'), isNull);
      // One end only.
      const atLeast =
          FormFieldSpec(label: 'n', kind: FormFieldKind.number, min: 2);
      expect(FormResponse.formatProblem(atLeast, '1'), 'Enter 2 or more.');
      expect(FormResponse.formatProblem(atLeast, '99'), isNull);
      // And the send button agrees, because it reads the same function.
      expect(FormResponse.isComplete([age], ['9']), isFalse);
      expect(FormResponse.isComplete([age], ['5']), isTrue);
    });

    test('the new question options are additive on the wire', () {
      // A form built before these existed must encode exactly as it did, and
      // an older build reading a newer form just never sees the new keys.
      const plain = FormFieldSpec(label: 'Name');
      expect(plain.toJson().containsKey('placeholder'), isFalse);
      expect(plain.toJson().containsKey('min'), isFalse);
      expect(plain.toJson().containsKey('max'), isFalse);

      const rich = FormFieldSpec(
          label: 'How many?',
          kind: FormFieldKind.number,
          placeholder: 'e.g. 4',
          min: 1,
          max: 8);
      final back = FormFieldSpec.fromJson(rich.toJson());
      expect(back.placeholder, 'e.g. 4');
      expect(back.min, 1);
      expect(back.max, 8);
      expect(back.rangeLabel, 'Between 1 and 8');

      // Clearing a range needs its own flag: null is a real value for an end,
      // so it cannot double as copyWith's "leave alone".
      expect(rich.copyWith(clearRange: true).min, isNull);
      expect(rich.copyWith(clearRange: true, max: 8).min, isNull);
      expect(rich.copyWith(clearRange: true, max: 8).max, 8);

      // Only the kinds that can show them offer them.
      expect(rich.takesRange, isTrue);
      expect(rich.takesPlaceholder, isTrue);
      const stars = FormFieldSpec(label: 'How was it?',
          kind: FormFieldKind.rating);
      expect(stars.takesRange, isFalse);
      expect(stars.takesPlaceholder, isFalse);
      expect(stars.rangeLabel, isNull);
    });

    test('an anonymous form sends no name, and never dedupes on the blank',
        () async {
      SharedPreferences.setMockInitialValues({});
      ChatStore.instance.reset();
      final store = ChatStore.instance;
      const contact =
          AppUser(id: 'c_anon', name: 'Fam', phone: '15550001212',
              avatarColor: '#888888');
      store.upsert(const Chat(
          id: 'c_anon', contact: contact, messages: []));
      store.addMessage(
        'c_anon',
        Message(
          id: 'f1',
          text: '',
          time: DateTime(2026, 8, 14),
          isMe: true,
          isForm: true,
          formTitle: 'How is it going?',
          formFields: const [FormFieldSpec(label: 'Honestly?')],
          formAnonymous: true,
        ),
      );

      // Two different people answer, both unnamed. Deduping on '' would let
      // the second overwrite the first and a form of forty would hold one.
      for (final a in ['fine', 'not great']) {
        store.applyFormResponse('c_anon', 'f1',
            FormResponse(from: '', answers: [a], at: DateTime(2026, 8, 14)));
      }
      final form = store.chats
          .firstWhere((c) => c.contact.id == 'c_anon')
          .messages
          .firstWhere((m) => m.id == 'f1');
      expect(form.formResponses.length, 2);
      expect(form.formAnonymous, isTrue);
      // A NAMED form still corrects rather than duplicating.
      expect(form.toJson()['formAnonymous'], true);
      expect(Message.fromJson(form.toJson()).formAnonymous, isTrue);

      // The responder's app is what leaves the name off, so the sender has
      // to actually pass the flag through.
      final relay = File('lib/relay/relay_service.dart').readAsStringSync();
      expect(relay.contains("'name': anonymous ? '' : me.name"), isTrue);
      expect(relay.contains("'from': anonymous ? '' : me.phone"), isTrue);
      final chat = File('lib/screens/chat_screen.dart').readAsStringSync();
      expect(chat.contains('anonymous: message.formAnonymous'), isTrue);
    });

    test('a signature is strokes, small, and survives a bad string', () {
      // Stored as strokes rather than an image: a form answer is a String in
      // a list riding the ordinary encrypted message path, so it has to be
      // small — and normalised points redraw crisply at any size.
      const ink = SignatureInk([
        [Offset(0, 0), Offset(0.5, 0.25)],
        [Offset(1, 1)],
      ]);
      final encoded = ink.encode();
      expect(encoded, '0.000,0.000 0.500,0.250;1.000,1.000');
      final back = SignatureInk.decode(encoded);
      expect(back.strokes.length, 2);
      expect(back.strokes.first.length, 2);
      expect(back.strokes.last.single, const Offset(1, 1));
      expect(back.isEmpty, isFalse);

      // It parses a string that arrived from ANOTHER device, so nothing
      // malformed may take a screen down — it comes back empty instead.
      for (final junk in ['', '   ', 'not ink', 'a,b;c', ';;;', '1,2,3']) {
        expect(() => SignatureInk.decode(junk), returnsNormally,
            reason: junk);
      }
      expect(SignatureInk.decode('not ink').isEmpty, isTrue);
      // A point that ran off the edge is clamped, not dropped: losing it
      // would put a gap in the middle of somebody's name.
      final off = SignatureInk.decode('-0.5,2.0 0.5,0.5');
      expect(off.strokes.single.first, const Offset(0, 1));
      expect(off.strokes.single.last, const Offset(0.5, 0.5));
      expect(SignatureInk.empty.isEmpty, isTrue);
    });

    testWidgets('the signature pad draws, clears, and never claims to prove '
        'anything', (t) async {
      var value = '';
      await t.pumpWidget(MaterialApp(
        home: Scaffold(
          body: StatefulBuilder(
            builder: (context, setState) => SignaturePad(
              value: value,
              onChanged: (v) => setState(() => value = v),
            ),
          ),
        ),
      ));
      await t.pumpAndSettle();
      expect(find.text('Sign here'), findsOneWidget);

      // The sentence that must not be edited out. It is shown to the signer
      // AND to whoever reads the answer back — this app has real signatures
      // (every server broadcast is signed) and conflating the two would be
      // the most misleading thing it could say.
      expect(find.text('A drawn mark, not proof of who drew it.'),
          findsOneWidget);

      // Inside the PAD's box, not the widget's centre — the widget is a
      // column of pad, caption and Clear, and its centre is the caption.
      await t.dragFrom(
          t.getTopLeft(find.byType(SignaturePad)) + const Offset(40, 40),
          const Offset(60, 20));
      await t.pumpAndSettle();
      expect(value, isNotEmpty);
      expect(SignatureInk.decode(value).isEmpty, isFalse);
      expect(find.text('Sign here'), findsNothing);

      await t.tap(find.text('Clear'));
      await t.pumpAndSettle();
      expect(value, isEmpty);
      expect(find.text('Sign here'), findsOneWidget);
    });

    test('a payment question with no amount is refused at build time', () {
      // The same rule a choice with one option follows: finding out at the
      // far end is too late.
      const noAmount =
          FormFieldSpec(label: 'Deposit', kind: FormFieldKind.payment);
      expect(noAmount.isUsable, isFalse);
      const priced = FormFieldSpec(
          label: 'Deposit', kind: FormFieldKind.payment, amountCents: 2500);
      expect(priced.isUsable, isTrue);
      // Additive on the wire like every other new option.
      expect(noAmount.toJson().containsKey('amountCents'), isFalse);
      expect(FormFieldSpec.fromJson(priced.toJson()).amountCents, 2500);
      // Neither new kind can gate a later question or take options: there is
      // no closed set of values to match against.
      expect(priced.canGate, isFalse);
      expect(priced.takesOptions, isFalse);
      const sig =
          FormFieldSpec(label: 'Sign', kind: FormFieldKind.signature);
      expect(sig.canGate, isFalse);
      expect(sig.isUsable, isTrue);
      // Both round-trip by NAME, so an older build reading a newer form gets
      // a plain text question rather than the wrong one.
      expect(FormFieldSpec.fromJson({'label': 'x', 'kind': 'signature'}).kind,
          FormFieldKind.signature);
      expect(FormFieldSpec.fromJson({'label': 'x', 'kind': 'payment'}).kind,
          FormFieldKind.payment);
      expect(FormFieldSpec.fromJson({'label': 'x', 'kind': 'whatever'}).kind,
          FormFieldKind.text);
    });

    testWidgets('a payment question says who it pays, or that it cannot',
        (t) async {
      // With nobody to pay — your own copy of a form you sent — it says so
      // rather than drawing a button that leads nowhere.
      await t.pumpWidget(const MaterialApp(
        home: FormFillScreen(
          key: ValueKey('nobody'),
          title: 'Trip',
          fields: [
            FormFieldSpec(
                label: 'Deposit',
                kind: FormFieldKind.payment,
                amountCents: 2500),
          ],
        ),
      ));
      await t.pumpAndSettle();
      expect(find.textContaining('Asks for \$25.00'), findsOneWidget);
      expect(find.widgetWithText(FilledButton, 'Pay \$25.00'), findsNothing);

      // With somebody to pay, the button names the exact amount — a form is
      // filled in quickly and money must never leave on a vague tap.
      await t.pumpWidget(const MaterialApp(
        home: FormFillScreen(
          key: ValueKey('unpaid'),
          title: 'Trip',
          fields: [
            FormFieldSpec(
                label: 'Deposit',
                kind: FormFieldKind.payment,
                amountCents: 2500),
          ],
          payTo: '15550001234',
          payToName: 'Sam',
        ),
      ));
      await t.pumpAndSettle();
      expect(find.widgetWithText(FilledButton, 'Pay \$25.00'), findsOneWidget);

      // Once paid it is a plain line — there is no "unpay", because the money
      // is gone and a control offering to take it back would be a lie.
      await t.pumpWidget(const MaterialApp(
        home: FormFillScreen(
          key: ValueKey('paid'),
          title: 'Trip',
          fields: [
            FormFieldSpec(
                label: 'Deposit',
                kind: FormFieldKind.payment,
                amountCents: 2500),
          ],
          initial: ['Paid'],
          payTo: '15550001234',
          payToName: 'Sam',
        ),
      ));
      await t.pumpAndSettle();
      expect(find.text('Paid \$25.00'), findsOneWidget);
      expect(find.widgetWithText(FilledButton, 'Pay \$25.00'), findsNothing);
    });

    test('the payment question reuses the money path, it does not rebuild it',
        () {
      final sheet = File('lib/widgets/spark_sheet.dart').readAsStringSync();
      final i = sheet.indexOf('Future<bool> payFormRequest');
      expect(i, greaterThan(-1));
      final body = sheet.substring(i, i + 2400);
      // Every guard offerTipTo runs, for the same reasons — above all the
      // cannot-receive screen, the check almost every real transfer dies on.
      expect(body.contains('allowsTrusted'), isTrue);
      expect(body.contains('showCannotReceiveSheet'), isTrue);
      expect(body.contains('svc.sendMoney('), isTrue);
      // And it does NOT ask for an amount: a form names one, and letting the
      // payer change it would answer a different question.
      expect(body.contains('showTipSheet'), isFalse);

      // The answer is recorded from the TRANSFER, not the tap.
      final fill =
          File('lib/screens/form_fill_screen.dart').readAsStringSync();
      expect(fill.contains('if (ok) onPaid();'), isTrue);
    });

    test('nothing about a form reaches a server in the clear', () {
      // The rule this feature is most able to break: forms collect exactly
      // the kind of answer worth protecting, so they ride the encrypted
      // message path and never a table.
      final src = File('lib/state/chat_store.dart').readAsStringSync();
      expect(src.contains('applyFormResponse'), isTrue);
      for (final path in [
        'lib/models/form_spec.dart',
        'lib/screens/form_builder_screen.dart',
        'lib/screens/form_fill_screen.dart',
      ]) {
        final text = File(path).readAsStringSync();
        expect(text.contains('supabase'), isFalse, reason: path);
        expect(text.contains('http'), isFalse, reason: path);
      }
    });
  });
  group('Split a bill', () {
    test('an equal split hands out every cent, none lost or invented', () {
      // $10.00 three ways is 3.34 / 3.33 / 3.33 — the extra cent goes to the
      // first, and the parts sum to exactly the total.
      final parts = BillSplit.equalCents(1000, 3);
      expect(parts, [334, 333, 333]);
      expect(parts.fold(0, (a, b) => a + b), 1000);
      // A clean division stays clean.
      expect(BillSplit.equalCents(1200, 4), [300, 300, 300, 300]);
      expect(BillSplit.equalCents(0, 3), [0, 0, 0]);
      expect(BillSplit.equalCents(500, 0), isEmpty);
    });

    test('the bill tracks who owes, who has paid, and when it is settled', () {
      const bill = BillSplit(
        title: 'Dinner',
        totalCents: 3000,
        createdByPhone: '+1 555 0100',
        shares: [
          BillShare(name: 'You', phone: '+1 555 0100', cents: 1000, paid: true),
          BillShare(name: 'Bob', phone: '+1 555 0200', cents: 1000),
          BillShare(name: 'Cara', phone: '+1 555 0300', cents: 1000),
        ],
      );
      // The creator's own share never counts as owed or collected.
      expect(bill.outstandingCents, 2000);
      expect(bill.collectedCents, 0);
      expect(bill.settled, isFalse);

      final afterBob = bill.markPaid('+15550200');
      expect(afterBob.collectedCents, 1000);
      expect(afterBob.outstandingCents, 1000);
      expect(afterBob.settled, isFalse);

      final afterAll = afterBob.markPaid('+1 555 0300');
      expect(afterAll.settled, isTrue);
      expect(afterAll.outstandingCents, 0);

      // Round-trips through JSON unchanged.
      final again = BillSplit.fromJson(afterAll.toJson());
      expect(again.collectedCents, 2000);
      expect(again.shareFor('+15550300')!.paid, isTrue);
    });

    test('a bill rides on a message through toJson/fromJson', () {
      final msg = Message(
        id: 'bill_1',
        text: '',
        time: DateTime(2026, 1, 1),
        isMe: true,
        billSplit: const BillSplit(
          title: 'Taxi',
          totalCents: 1600,
          createdByPhone: '+1 555 0100',
          shares: [
            BillShare(
                name: 'You', phone: '+1 555 0100', cents: 800, paid: true),
            BillShare(name: 'Bob', phone: '+1 555 0200', cents: 800),
          ],
        ),
      );
      final back = Message.fromJson(msg.toJson());
      expect(back.isBillSplit, isTrue);
      expect(back.billSplit!.title, 'Taxi');
      expect(back.billSplit!.shareFor('+15550200')!.cents, 800);
    });

    test('a paid update marks the right share, locally and over the relay', () {
      final store = ChatStore.instance;
      store.hydrate(const {'chats': []});
      addTearDown(() => store.hydrate(const {'chats': []}));
      store.upsert(Chat(
        id: 'chat_bob',
        contact: const AppUser(
            id: '+15550200',
            name: 'Bob',
            avatarColor: '#111',
            phone: '+15550200'),
        messages: [
          Message(
            id: 'bill_x',
            text: '',
            time: DateTime(2026, 1, 1),
            isMe: true,
            billSplit: const BillSplit(
              title: 'Lunch',
              totalCents: 2000,
              createdByPhone: '+15550100',
              shares: [
                BillShare(
                    name: 'You', phone: '+15550100', cents: 1000, paid: true),
                BillShare(name: 'Bob', phone: '+15550200', cents: 1000),
              ],
            ),
          ),
        ],
      ));

      // A remote 'billpaid' event from Bob flips his share to paid.
      RelayService.applyMessageEvent(
        'billpaid',
        {'from': '+15550200', 'id': 'bill_x', 'payer': '+15550200'},
        myPhone: '+15550100',
        store: store,
      );
      final bill = store.chatById('chat_bob')!.messages.first.billSplit!;
      expect(bill.shareFor('+15550200')!.paid, isTrue);
      expect(bill.settled, isTrue);
    });

    test('nothing about a split bill reaches a server in the clear', () {
      // Bill splits collect who owes whom — worth protecting — so like forms
      // and polls the whole thing rides the E2E message, never a table.
      final text = File('lib/models/bill_split.dart').readAsStringSync();
      expect(text.contains('supabase'), isFalse);
      expect(text.contains('http'), isFalse);
      expect(text.contains('functions.invoke'), isFalse);
    });
  });

  group('quick replies', () {
    setUp(() {
      QuickReplies.instance.resetForTest();
      SharedPreferences.setMockInitialValues({});
    });
    tearDown(QuickReplies.instance.resetForTest);

    final store = QuickReplies.instance;

    test('newest first, and the same sentence is never saved twice', () async {
      expect(await store.add('On my way'), isTrue);
      expect(await store.add('Thanks'), isTrue);
      expect(store.all, ['Thanks', 'On my way'],
          reason: 'the one just saved is the one about to be used');

      // Duplicates make the picker longer without making it more useful, and
      // case is not a difference somebody means.
      expect(await store.add('thanks'), isFalse);
      expect(await store.add('  Thanks  '), isFalse);
      expect(store.all.length, 2);

      // Nothing is not a reply.
      expect(await store.add('   '), isFalse);
      expect(store.all.length, 2);
    });

    test('editing to nothing removes it rather than leaving a blank row',
        () async {
      await store.add('Thanks');
      await store.edit(0, '   ');
      expect(store.all, isEmpty,
          reason: 'a blank quick reply is a row that inserts nothing');
    });

    test('out-of-range edits and removes change nothing', () async {
      await store.add('Thanks');
      await store.edit(9, 'x');
      await store.removeAt(-1);
      await store.reorder(5, 0);
      // The destination is bounded too — a drop past the end would otherwise
      // throw out of insert() rather than being ignored.
      await store.reorder(0, 9);
      expect(store.all, ['Thanks']);
    });

    test('reordering puts the ones actually used at the top', () async {
      for (final r in ['third', 'second', 'first']) {
        await store.add(r);
      }
      expect(store.all, ['first', 'second', 'third']);
      // onReorderItem hands over the index AFTER the item is lifted out, so
      // there is no off-by-one to compensate for — doing it anyway swaps the
      // wrong pair and looks like the list ignoring the drag.
      await store.reorder(0, 2);
      expect(store.all, ['second', 'third', 'first']);
      await store.reorder(2, 0);
      expect(store.all, ['first', 'second', 'third']);
    });

    test('the list is capped, and says so before it is full', () async {
      for (var i = 0; i < QuickReplies.max; i++) {
        expect(await store.add('reply $i'), isTrue);
      }
      expect(store.isFull, isTrue);
      expect(await store.add('one more'), isFalse);
      expect(store.all.length, QuickReplies.max);
    });

    test('matching narrows on what has been typed', () async {
      await store.add('On my way');
      await store.add('Running late, sorry');
      expect(store.matching('').length, 2, reason: 'empty offers everything');
      expect(store.matching('LATE'), ['Running late, sorry']);
      expect(store.matching('nothing like this'), isEmpty);
    });

    test('they survive a restart, and blanks do not come back', () async {
      SharedPreferences.setMockInitialValues({
        'quick_replies_v1': ['Thanks', '   ', 'On my way'],
      });
      await store.load();
      expect(store.all, ['Thanks', 'On my way']);
    });

    test('nothing about them leaves the device', () {
      // The list of sentences somebody uses most is a fair description of
      // their life. It is not in the backup and not on a server.
      final src = File('lib/state/quick_replies.dart').readAsStringSync();
      expect(src.contains('supabase'), isFalse);
      expect(src.contains('RelayService'), isFalse);
      expect(
          File('lib/state/cloud_sync.dart')
              .readAsStringSync()
              .contains('quick_replies'),
          isFalse,
          reason: 'they rode the cloud sync, which is not where they belong');
    });

    test('the suggestions are offered, never seeded', () {
      // Writing them in would be inventing content in somebody's own words,
      // which is the no-fake-data rule.
      expect(QuickReplies.suggestions, isNotEmpty);
      expect(store.all, isEmpty);
      final src =
          File('lib/screens/quick_replies_screen.dart').readAsStringSync();
      expect(
          src.contains('onPressed: () => QuickReplies.instance.add(s)'), isTrue,
          reason: 'a suggestion has to be tapped to become a reply');
    });

    testWidgets('a saved reply is inserted, never sent', (t) async {
      // A canned reply that sends itself is a message nobody read before it
      // left.
      final src = File('lib/screens/chat_screen.dart').readAsStringSync();
      final fn = src.substring(src.indexOf('Future<void> _handleQuickReply()'),
          src.indexOf('/// Builds a form and sends it as a message.'));
      expect(fn.contains('_store.setDraft'), isTrue);
      expect(fn.contains('_deliver('), isFalse,
          reason: 'the picker sent the message instead of typing it');
      // And it appends rather than replacing what is already typed.
      expect(fn.contains("existing.isEmpty ? reply : '\$existing \$reply'"),
          isTrue);
    });
  });

  group('UI polish', () {
    testWidgets('sending a message taps back', (tester) async {
      var sent = '';
      await tester.pumpWidget(MaterialApp(
        home: Scaffold(
          body: Column(
            children: [
              const Spacer(),
              ChatInputBar(onSend: (t) => sent = t),
            ],
          ),
        ),
      ));
      await tester.pump();
      final before = Haptics.debugCount;
      await tester.enterText(find.byType(TextField), 'hello');
      await tester.pump();
      await tester.tap(find.byIcon(Icons.send));
      await tester.pump();
      expect(sent, 'hello');
      expect(Haptics.debugCount, greaterThan(before),
          reason: 'a send should land under the thumb as well as on screen');
    });

    testWidgets('a like taps back; opening a reply stays silent',
        (tester) async {
      var liked = false;
      var replied = false;
      await tester.pumpWidget(MaterialApp(
        home: Scaffold(
          body: FeedPostActions(
            replyCount: 0,
            repostCount: 0,
            likeCount: 0,
            liked: false,
            reposted: false,
            onReply: () => replied = true,
            onRepost: () {},
            onLike: () => liked = true,
            onShare: () {},
          ),
        ),
      ));
      final before = Haptics.debugCount;
      await tester.tap(find.byIcon(Icons.favorite_border));
      await tester.pump();
      expect(liked, isTrue);
      expect(Haptics.debugCount, before + 1);
      // Reply only opens UI — nothing happened yet, so nothing to feel.
      await tester.tap(find.byIcon(Icons.chat_bubble_outline));
      await tester.pump();
      expect(replied, isTrue);
      expect(Haptics.debugCount, before + 1);
    });

    test('the held-finger and completed moments each fire, once, in one place',
        () {
      // Every entry is (file, enclosing anchor, expected call): the haptic
      // lives at the single funnel each gesture already passes through, so a
      // path added later inherits it rather than needing to remember it.
      final pins = <(String, String, String)>[
        (
          'lib/screens/chat_screen.dart',
          'void _showMessageActions',
          'Haptics.press();'
        ),
        ('lib/screens/chat_screen.dart', 'void _react(', 'Haptics.tap();'),
        (
          'lib/tabs/chats_tab.dart',
          'void _showChatActions',
          'Haptics.press();'
        ),
        (
          'lib/widgets/chat_input_bar.dart',
          'Future<void> _startRecording',
          'Haptics.press();'
        ),
        (
          'lib/widgets/chat_input_bar.dart',
          'Future<void> _finishRecording',
          'Haptics.tap();'
        ),
        (
          'lib/widgets/pull_to_refresh.dart',
          'static Future<void> refreshApp',
          'Haptics.tap();'
        ),
        (
          'lib/screens/home_screen.dart',
          'void _onSelectTab',
          'Haptics.select();'
        ),
      ];
      for (final (file, anchor, call) in pins) {
        final src = File(file).readAsStringSync();
        final at = src.indexOf(anchor);
        expect(at, greaterThanOrEqualTo(0), reason: '$anchor missing in $file');
        final body = src.substring(at, src.indexOf('\n  }', at));
        expect(body.contains(call), isTrue,
            reason: '$anchor in $file lost its $call');
      }
    });

    test('blank screens use the one empty-state look', () {
      // Each of these had its own hand-rolled icon-and-grey-text column —
      // including greys that fail contrast in one theme (see AppColors.subtle).
      for (final file in [
        'lib/screens/archived_chats_screen.dart',
        'lib/screens/message_requests_screen.dart',
        'lib/screens/status_screen.dart',
        'lib/screens/people_screen.dart',
      ]) {
        final src = File(file).readAsStringSync();
        expect(src.contains('EmptyState('), isTrue,
            reason: '$file should draw its blank state with EmptyState');
        expect(src.contains('Colors.grey.shade400'), isFalse,
            reason: '$file kept a fixed grey that fails in one theme');
      }
    });
  });

  group('Marketplace saved searches', () {
    FeedPost listing(String id, String text,
            {String category = 'Electronics',
            int price = 1000,
            bool sold = false,
            DateTime? time}) =>
        FeedPost(
          id: id,
          communityId: 'c1',
          authorName: 'x',
          authorUsername: 'seller',
          time: time ?? DateTime(2026, 1, 10),
          text: text,
          priceCents: price,
          listingCategory: category,
          listingSold: sold,
        );

    test('a kept search matches like a typed one, and skips the sold', () {
      final s = SavedSearch(
          id: 's1',
          query: 'bike',
          category: 'Sports',
          maxCents: 20000,
          lastSeenAt: DateTime(2026, 1, 5));
      final all = [
        listing('l1', 'City bike, tuned', category: 'Sports', price: 12000),
        listing('l2', 'Racing bike', category: 'Sports', price: 30000),
        listing('l3', 'City bike', category: 'Sports', sold: true),
        listing('l4', 'Espresso machine', category: 'Sports'),
        listing('l5', 'Mountain bike', category: 'Home', price: 9000),
      ];
      expect(savedSearchMatches(s, all).map((l) => l.id), ['l1'],
          reason: 'over budget, sold, wrong words and wrong category are out');
    });

    test('the badge counts only what arrived since the last look', () {
      final s = SavedSearch(
          id: 's2', query: 'bike', lastSeenAt: DateTime(2026, 1, 5));
      final all = [
        listing('old', 'Old bike', time: DateTime(2026, 1, 1)),
        listing('new1', 'New bike', time: DateTime(2026, 1, 6)),
        listing('new2', 'Newer bike', time: DateTime(2026, 1, 7)),
      ];
      expect(savedSearchNewCount(s, all), 2);
    });

    test('the store refuses empty, dedupes, caps, and touches', () {
      final store = FeedStore.instance;
      store.resetForTest();
      addTearDown(store.resetForTest);
      // Empty would match everything — "new" would mean "any listing".
      expect(store.addSavedSearch(), isNull);
      expect(store.savedSearches, isEmpty);

      store.addSavedSearch(query: 'bike');
      store.addSavedSearch(query: 'lamp');
      // The same search again moves to the front instead of duplicating —
      // case-insensitively, since the words match that way too.
      store.addSavedSearch(query: 'BIKE');
      expect(store.savedSearches.length, 2);
      expect(store.savedSearches.first.query, 'bike');

      for (var i = 0; i < 10; i++) {
        store.addSavedSearch(query: 'q$i');
      }
      expect(store.savedSearches.length, FeedStore.maxSavedSearches);

      final kept = store.savedSearches.last;
      final before = kept.lastSeenAt;
      store.touchSavedSearch(kept.id);
      final after =
          store.savedSearches.firstWhere((s) => s.id == kept.id).lastSeenAt;
      expect(after.isAfter(before), isTrue,
          reason: 'touching restarts the badge clock');

      store.removeSavedSearch(kept.id);
      expect(store.savedSearches.any((s) => s.id == kept.id), isFalse);
    });

    test('a search survives the json round trip, and labels itself', () {
      final s = SavedSearch(
          id: 's3',
          query: '',
          category: '',
          minCents: 500,
          maxCents: 1250,
          lastSeenAt: DateTime(2026, 1, 5));
      final back = SavedSearch.fromJson(
          Map<String, dynamic>.from(jsonDecode(jsonEncode(s.toJson())) as Map));
      expect(back.minCents, 500);
      expect(back.maxCents, 1250);
      expect(back.lastSeenAt, DateTime(2026, 1, 5));
      // The chip says the words if any, else the category, else the bounds.
      expect(back.label, r'from $5 to $12.50');
      expect(
          SavedSearch(id: 'a', query: 'bike', lastSeenAt: DateTime(2026)).label,
          'bike');
      expect(
          SavedSearch(id: 'b', category: 'Sports', lastSeenAt: DateTime(2026))
              .label,
          'Sports');
    });

    test('the screen offers the save, shows the shelf, restarts the clock', () {
      final src =
          File('lib/screens/marketplace_screen.dart').readAsStringSync();
      // Saveable = words, category or price — views and sorts are not
      // searches, so Your-listings/Saved/sort alone never offer a save.
      expect(src, contains('bool get _saveableSearch'));
      expect(
          src.contains('_mineOnly') && src.contains('_saveableSearch'), isTrue);
      final saveable = src.substring(src.indexOf('bool get _saveableSearch'),
          src.indexOf('void _saveCurrentSearch'));
      expect(saveable.contains('_mineOnly'), isFalse,
          reason: '"new matches for your own listings" means nothing');
      // Applying a kept search marks it looked-at, so the badge restarts.
      final apply = src.substring(src.indexOf('void _applySavedSearch'),
          src.indexOf('Widget _guarded'));
      expect(apply, contains('touchSavedSearch'));
      // The shelf rides the clean browse, like the other shelves.
      expect(src, contains('FeedStore.instance.savedSearches.isNotEmpty'));
    });
  });

  group('Marketplace sold handshake and bumps', () {
    FeedPost own(String id, {bool sold = false, DateTime? time, int rev = 0}) =>
        FeedPost(
          id: id,
          communityId: 'c1',
          authorName: 'You',
          authorUsername: 'you',
          time: time ?? DateTime(2026, 1, 1),
          text: 'City bike\nFreshly tuned',
          priceCents: 12000,
          listingCategory: 'Sports',
          listingSold: sold,
          listingRev: rev,
        );

    test('a bump needs yours, unsold, and 48 hours of sitting', () {
      final store = FeedStore.instance;
      store.resetForTest();
      addTearDown(store.resetForTest);
      addTearDown(AppState.resetForTest);

      // Old and yours: bumpable. Time becomes now, revision climbs.
      store.addRemote(
          own('b1', time: DateTime.now().subtract(const Duration(days: 3))));
      expect(store.canBumpListing('b1'), isTrue);
      expect(store.bumpListing('b1'), isTrue);
      final bumped = store.postById('b1')!;
      expect(DateTime.now().difference(bumped.time).inMinutes, 0,
          reason: 'the bump is the new posting time');
      expect(bumped.listingRev, 1);

      // Immediately after, the same listing has to sit again.
      expect(store.canBumpListing('b1'), isFalse,
          reason: 'the age check IS the rate limit');

      // Sold: never bumpable — a re-topped sold listing sells nothing.
      store.addRemote(own('b2',
          sold: true, time: DateTime.now().subtract(const Duration(days: 3))));
      expect(store.canBumpListing('b2'), isFalse);

      // Somebody else's: never bumpable.
      final theirs = FeedPost(
        id: 'b3',
        communityId: 'c1',
        authorName: 'Ada',
        authorUsername: 'ada',
        time: DateTime(2025, 1, 1),
        text: 'Lamp',
        priceCents: 500,
      );
      store.addRemote(theirs);
      expect(store.canBumpListing('b3'), isFalse);
    });

    test('a stale replay can never un-bump', () {
      final store = FeedStore.instance;
      store.resetForTest();
      addTearDown(store.resetForTest);
      addTearDown(AppState.resetForTest);
      store.addRemote(
          own('b4', time: DateTime.now().subtract(const Duration(days: 3))));
      expect(store.bumpListing('b4'), isTrue);
      final bumpedTime = store.postById('b4')!.time;
      // The mailbox replays the pre-bump copy (rev 0): it must bounce off.
      store.addRemote(own('b4', time: DateTime(2025, 6, 1)));
      expect(store.postById('b4')!.time, bumpedTime);
    });

    test('the thank-you draft names the listing and invites the rating', () {
      final draft = soldThanksDraft(own('b5'));
      expect(draft, contains('"City bike"'));
      expect(draft, contains('rate the sale'));
      expect(draft.contains('Freshly tuned'), isFalse,
          reason: 'the first line is the title; the rest is not the name');
    });

    test('marking sold asks, backing out changes nothing, drafts never send',
        () {
      final src =
          File('lib/screens/marketplace_screen.dart').readAsStringSync();
      // The unsold path routes through the sheet; un-selling stays direct.
      expect(src, contains('markListingSold(context, listing)'));
      final fn = src.substring(src.indexOf('Future<void> markListingSold'),
          src.indexOf('/// The unsold listings [s] matches'));
      // A dismissed sheet returns before anything is marked. (The FIRST
      // setListingSold is the no-contacts fast path, above the sheet.)
      expect(
          fn.indexOf('if (choice == null) return;') <
              fn.lastIndexOf('setListingSold'),
          isTrue,
          reason: 'backing out of the sheet must change nothing');
      // The thank-you is a DRAFT in the composer, never an auto-send.
      expect(fn, contains('setDraft'));
      expect(fn.contains('_deliver('), isFalse);
      // And the bump button only exists when the store says it may.
      expect(src, contains('FeedStore.instance.canBumpListing(listing.id)'));
    });
  });

  group('Marketplace typical prices and the free filter', () {
    FeedPost priced(String id, int cents,
            {String category = 'Sports', bool sold = false}) =>
        FeedPost(
          id: id,
          communityId: 'c1',
          authorName: 'x',
          authorUsername: 'seller',
          time: DateTime(2026, 1, 1),
          text: 'Item $id',
          priceCents: cents,
          listingCategory: category,
          listingSold: sold,
        );

    test('the going rate is a median over unsold, non-free, same-category', () {
      final all = [
        priced('p1', 1000),
        priced('p2', 2000),
        priced('p3', 9000),
        priced('p4', 100000, sold: true), // sold: out
        priced('p5', 0), // free: out
        priced('p6', 500, category: 'Home'), // other category: out
      ];
      expect(typicalPriceCents(all, 'Sports'), 2000);
      // An even count averages the middle two.
      expect(typicalPriceCents([...all, priced('p7', 3000)], 'Sports'), 2500);
      // Fewer than three data points is a coin toss, not a statistic.
      expect(typicalPriceCents(all, 'Home'), isNull);
      expect(typicalPriceCents(all, ''), isNull);
      // A listing's own price stays out of its own benchmark.
      expect(typicalPriceCents(all, 'Sports', excludeId: 'p3'), isNull,
          reason: 'excluding one of three drops it under the threshold');
    });

    test('below-typical is 70% of the median, never for free or sold', () {
      final all = [
        priced('q1', 10000),
        priced('q2', 10000),
        priced('q3', 10000),
        priced('deal', 7000),
        priced('near', 7100),
        priced('freebie', 0),
        priced('solddeal', 1000, sold: true),
      ];
      expect(isBelowTypical(all.firstWhere((l) => l.id == 'deal'), all), isTrue,
          reason: 'exactly at 70% counts');
      expect(
          isBelowTypical(all.firstWhere((l) => l.id == 'near'), all), isFalse);
      expect(isBelowTypical(all.firstWhere((l) => l.id == 'freebie'), all),
          isFalse);
      expect(isBelowTypical(all.firstWhere((l) => l.id == 'solddeal'), all),
          isFalse);
    });

    test('the free filter is its own flag, because 0 cannot be typed', () {
      final src =
          File('lib/screens/marketplace_screen.dart').readAsStringSync();
      // The price boxes read a typed 0 as "no bound" (blank means free
      // there), so free stuff needs a flag of its own to be findable.
      expect(src, contains('bool _freeOnly = false;'));
      expect(src, contains("(l.priceCents ?? 0) == 0"));
      expect(src, contains("'Free only'"));
      // And it clears from the active-filters row like every other filter.
      expect(src, contains('_freeOnly = false'));
    });

    test('the sell form quotes the rate; the card wears the tag honestly', () {
      final src =
          File('lib/screens/marketplace_screen.dart').readAsStringSync();
      // The hint excludes the listing being edited from its own benchmark.
      expect(src, contains("excludeId: widget.existing?.id ?? ''"));
      expect(src, contains('listings here ask about'));
      // One price story per card: the strikethrough drop wins over the
      // below-typical tag, never both.
      final card = src.substring(src.indexOf('class _ListingCard'),
          src.indexOf('/// One listing, full screen'));
      expect(card.contains('else if (isBelowTypical'), isTrue);
    });
  });

