            title: 'City bike',
            description: '',
            price: '120',
            wasPrice: '',
            brand: 'Trek',
            category: 'Sports',
            condition: '',
            delivery: '',
            quantity: '',
            offers: false,
            place: '',
            communityId: '',
          ));
      await tester.pumpWidget(const MaterialApp(home: SellScreen()));
      await tester.pumpAndSettle();
