      // No 'K', no 'M' — the owner asked for nothing compact, and a whole
      // number is also the honest one.
      expect(thousands(0), '0');
      expect(thousands(999), '999');
      expect(thousands(1000), '1,000');
      expect(thousands(1234), '1,234');
      expect(thousands(45000), '45,000');
      expect(thousands(999999), '999,999');
      expect(thousands(1234567), '1,234,567');
    });

    testWidgets('opening a post counts one view, once per run', (tester) async {
      final store = PublicFeedStore.instance;
      addTearDown(store.resetForTest);
      final reported = <String>[];
      PublicFeedStore.debugViewedOverride = reported.add;
      PublicFeedStore.debugLoadOverride = () async => [
            PublicPost(
              id: 'v1',
              authorUsername: 'ada',
              body: 'watched',
              viewCount: 1234,
              createdAt: DateTime(2026, 1, 1),
            )
          ];
      await store.load();
      await tester.pumpWidget(
          const MaterialApp(home: PublicThreadScreen(postId: 'v1')));
      await tester.pumpAndSettle();
      expect(reported, ['v1']);
      // The count shows in full, in its own block with its word under it.
      expect(find.text('1,234'), findsOneWidget);
      expect(find.text('Views'), findsOneWidget);
      // A second open in the same run does not double-count.
      store.notePostViewed('v1');
      expect(reported, ['v1'],
          reason: 'one reader is one view, not one per rebuild');
    });

    test(
        'views dedupe per viewer, and only the author can see who, in Postgres',
        () {
      // 2026-08-07, the owner's call: a view is now deduped per viewer (so the
      // same reader can't inflate a count by re-opening) and the author can see
      // WHO looked. That means a per-viewer table exists now — but its phone
      // column is never client-readable, and the ONLY window is the
      // public_post_viewers directory join, exactly like who-liked.
      final sql = File('docs/public_feed.sql').readAsStringSync();
      expect(sql, contains('add column if not exists view_count'));
      expect(sql,
          contains('create or replace function public.public_post_viewed'));
      expect(sql, contains('created_at, view_count)'));
      // The per-viewer table and the who-viewed window both exist.
      expect(sql,
          contains('create table if not exists public.public_post_views ('));
      expect(sql,
          contains('create or replace function public.public_post_viewers'));
      // And the table is locked to clients — no column of it is ever granted,
      // so a viewer_phone can never be read next to a reading habit.
      expect(
          sql,
          contains(
              'revoke select on table public.public_post_views from anon, authenticated'));
      final check = File('tool/check_sql.sh').readAsStringSync();
      expect(check, contains('a view adds exactly one to the tally'));
      expect(check, contains('the view tally cannot be written directly'));
      expect(
          check, contains('a second view from the same reader adds nothing'));
      expect(check, contains('who-viewed answers usernames'));
      expect(check, contains('the views table itself is unreadable'));
    });
  });

  group('Views on the server feed', () {
    setUp(() => SharedPreferences.setMockInitialValues({}));

    test('opening a post counts once ever, and the guard survives a restart',
        () async {
      final store = FeedStore.instance;
      store.resetForTest();
      final post = store.add('c1', 'watched');
      store.recordPostView(post.id);
      expect(store.postById(post.id)!.views, 1);
      // Opening it again tomorrow is still the same reader.
      store.recordPostView(post.id);
      expect(store.postById(post.id)!.views, 1);
      await Future<void>.delayed(const Duration(milliseconds: 50));

      // Restart: memory cleared, state reloaded from disk. Both the count
      // and the once-ever guard have to come back.
      store.resetForTest();
      await store.load();
      expect(store.postById(post.id)!.views, 1);
      store.recordPostView(post.id);
      expect(store.postById(post.id)!.views, 1,
          reason: 'the once-ever guard must survive the restart');
    });

    test('remote views tally unique viewers and shrug off replays', () {
      final store = FeedStore.instance;
      store.resetForTest();
      final post = store.add('c1', 'seen around');
      store.applyRemoteView(post.id, viewerUsername: 'grace');
      store.applyRemoteView(post.id, viewerUsername: 'ada');
      expect(store.postById(post.id)!.views, 2);
      // The same mailbox row coming back adds nothing.
      store.applyRemoteView(post.id, viewerUsername: 'grace');
      expect(store.postById(post.id)!.views, 2);
      // A nameless event has no dedup key, so it cannot be counted.
      store.applyRemoteView(post.id, viewerUsername: '');
      expect(store.postById(post.id)!.views, 2);
    });

    testWidgets('opening a server post counts the view and wears the band',
        (tester) async {
      final store = FeedStore.instance;
      store.resetForTest();
      final post = store.add('c1', 'a post worth opening');
      await tester
          .pumpWidget(MaterialApp(home: FeedPostScreen(postId: post.id)));
      await tester.pumpAndSettle();
      expect(store.postById(post.id)!.views, 1);
      expect(find.text('View'), findsOneWidget);
    });

    test('the view event rides everywhere a like does, in the shared block',
        () {
      final relay = File('lib/relay/relay_service.dart').readAsStringSync();
      // Live broadcast, the sealed handler, and the offline mailbox replay
      // — miss any one and some member's open is silently dropped.
      expect(relay, contains("event: 'fview'"));
      expect(relay, contains("case 'fview':"));
      expect(relay, contains("'fview' ||"),
          reason: 'the mailbox replay allowlist must carry fview');
      // Both thread screens draw the same block, at the slimmed size —
      // "ui to big" was the complaint, so the size is the pin.
      final parts = File('lib/widgets/feed_post_parts.dart').readAsStringSync();
      expect(parts, contains('class FeedStatBlock'));
      expect(parts, contains('fontSize: 15.5'));
      for (final f in [
        'lib/screens/feed_screen.dart',
        'lib/screens/public_feed_screen.dart'
      ]) {
        expect(File(f).readAsStringSync(), contains('FeedStatBlock('),
            reason: '$f must use the shared block');
      }
    });
  });

  group('Earnings', () {
    setUp(() => SharedPreferences.setMockInitialValues({}));

    test('money labels drop the cents only when there are none', () {
      expect(moneyLabel(0), '\$0');
      expect(moneyLabel(500), '\$5');
      expect(moneyLabel(1250), '\$12.50');
      expect(moneyLabel(120000), '\$1200');
    });

    test('the tally counts only money that honestly came in', () {
      FeedPost server({
        required String id,
        required String author,
        int sparkCents = 0,
        int sparks = 0,
        int? priceCents,
        bool sold = false,
      }) =>
          FeedPost(
            id: id,
            communityId: 'c1',
            authorName: author,
            authorUsername: author,
            time: DateTime(2026, 1, 1),
            text: 'p',
            sparkCents: sparkCents,
            sparks: sparks,
            priceCents: priceCents,
            listingSold: sold,
          );
      PaymentRecord pay({
        bool sent = false,
        String status = 'succeeded',
        String kind = 'transfer',
        String note = '',
        int cents = 1000,
      }) =>
          PaymentRecord(
            id: 'r',
            sent: sent,
            otherPhone: '1',
            amountCents: cents,
            feeCents: 0,
            currency: 'CAD',
            status: status,
            kind: kind,
            note: note,
          );

      final e = computeEarnings(
        myUsername: 'me',
        serverPosts: [
          server(id: 'a', author: 'you', sparkCents: 300, sparks: 2),
          server(id: 'b', author: 'ME', sparkCents: 200, sparks: 1),
          // Somebody else's sparks are their earnings, not mine.
          server(id: 'c', author: 'grace', sparkCents: 900, sparks: 3),
          server(id: 'd', author: 'me', priceCents: 2000, sold: true),
          // Unsold asks nothing has been earned from; free is free.
          server(id: 'e', author: 'me', priceCents: 5000),
          server(id: 'f', author: 'me', priceCents: 0, sold: true),
          server(id: 'g', author: 'grace', priceCents: 700, sold: true),
        ],
        publicPosts: [
          PublicPost(
              id: 'p1',
              authorUsername: 'me',
              body: 'x',
              createdAt: DateTime(2026, 1, 1),
              sparkCount: 1,
              sparkCents: 150),
          PublicPost(
              id: 'p2',
              authorUsername: 'grace',
              body: 'x',
              createdAt: DateTime(2026, 1, 1),
              sparkCents: 400),
        ],
        history: [
          pay(cents: 1500),
          pay(cents: 800, sent: true), // money out, not in
          pay(cents: 600, status: 'pending'), // hasn't moved yet
          // A spark rides a transfer — already counted on the post, so the
          // payments line must leave it out or the dollar counts twice.
          pay(cents: 300, note: 'Spark for your post'),
          pay(cents: 2500, kind: 'payout'), // my own money moving to my bank
        ],
      );

      expect(e.paymentsIncluded, isTrue);
      expect(e.lines, hasLength(3));
      final sparks = e.lines[0], sales = e.lines[1], payments = e.lines[2];
      expect(sparks.cents, 300 + 200 + 150);
      expect(sparks.count, 2 + 1 + 1);
      expect(sales.cents, 2000);
      expect(sales.count, 1);
      expect(payments.cents, 1500);
      expect(payments.count, 1);
      expect(e.totalCents, 650 + 2000 + 1500);

      // No wallet answer: the payments line is ABSENT, not a zero that
      // reads as "nobody ever paid you".
      final offline = computeEarnings(
          myUsername: 'me', serverPosts: const [], publicPosts: const []);
      expect(offline.paymentsIncluded, isFalse);
      expect(offline.lines, hasLength(2));
    });

