      store.upsert(Chat(
        id: 'group_forms',
        contact: const AppUser(
            id: 'group_forms',
            name: 'Planning',
            avatarColor: '#111111',
            isGroup: true),
        members: const [
          AppUser(
              id: '+15550174',
              name: 'Riley',
              avatarColor: '#222222',
              phone: '+15550174'),
        ],
        messages: [
          Message(
              id: 'form_g1',
              text: '',
              time: DateTime(2026, 8, 1),
              isMe: true,
              status: MessageStatus.sent,
              isForm: true,
              formTitle: 'Potluck',
              formFields: const [
                FormFieldSpec(label: 'Bringing?', kind: FormFieldKind.text)
              ]),
        ],
      ));
      RelayService.applyMessageEvent(
          'form',
          {
            'from': '+1 555 0174',
            'id': 'form_g1',
            'name': 'Riley',
            'answers': ['salad'],
          },
          myPhone: '+1 555 0100',
