  group('Presence: in the chat, online, or away', () {
    setUp(() => SharedPreferences.setMockInitialValues({}));

    testWidgets('the header climbs its three rungs and climbs back down',
        (tester) async {
      final store = ChatStore.instance;
      store.hydrate(const {'chats': []});
      addTearDown(store.reset);
      // id == phone, or _isRealPeer refuses the whole presence apparatus.
      const contact = AppUser(
          id: '+15550185',
          name: 'Pia Presence',
          avatarColor: '#111111',
          phone: '+15550185');
      const chat = Chat(id: 'chat_+15550185', contact: contact, messages: []);
      store.upsert(chat);
      final relay = RelayService.instance;
      addTearDown(() {
        relay.presenceFromDigits = null;
        relay.presenceWhere = 'chat';
      });

      await tester.pumpWidget(const MaterialApp(home: ChatScreen(chat: chat)));
      await tester.pumpAndSettle();
      expect(find.text('last seen recently'), findsOneWidget,
          reason: 'nothing fresh has been heard — claim nothing more');

      // Their ping says they are looking at THIS conversation.
      relay.presenceFromDigits = '15550185';
      relay.presenceWhere = 'chat';
      relay.presencePing.value++;
      await tester.pump();
      expect(find.text('in this chat'), findsOneWidget);

      // The app-open pong: online, but somewhere else in the app.
      relay.presenceWhere = 'app';
      relay.presencePing.value++;
      await tester.pump();
      expect(find.text('online'), findsOneWidget);
      expect(find.text('in this chat'), findsNothing);

      // Quiet long enough and the claim is withdrawn, not left stale.
      await tester.pump(const Duration(seconds: 36));
      expect(find.text('last seen recently'), findsOneWidget);
    });

    test('the app answers a chat ping with an app pong — only when safe', () {
      final store = ChatStore.instance;
      store.hydrate(const {'chats': []});
      addTearDown(store.reset);
      final sent = <(String, String)>[];
      RelayService.debugPresenceSendOverride =
          (phone, where) => sent.add((phone, where));
      RelayService.debugForegroundOverride = () => true;
      addTearDown(() {
        RelayService.debugPresenceSendOverride = null;
        RelayService.debugForegroundOverride = null;
        RelayService.instance.openChatDigits = '';
        AppState.shareLastSeen.value = true;
      });
      Chat mk(String last4, {bool isRequest = false}) => Chat(
          id: 'chat_+1555018$last4',
          contact: AppUser(
              id: '+1555018$last4',
              name: 'P$last4',
              avatarColor: '#111111',
              phone: '+1555018$last4'),
          messages: const [],
          isRequest: isRequest);

      store.upsert(mk('6'));
      RelayService.instance.maybeAnswerPresence('15550186');
      expect(sent, [('+15550186', 'app')],
          reason: 'a known contact opening your chat learns the app is open');

      // Rate-limited: their next ping seconds later earns no second pong.
      RelayService.instance.maybeAnswerPresence('15550186');
      expect(sent.length, 1);

      // A stranger's unaccepted request learns nothing…
      store.upsert(mk('7', isRequest: true));
      RelayService.instance.maybeAnswerPresence('15550187');
      expect(sent.length, 1);
      // …nor does a number with no conversation at all…
      RelayService.instance.maybeAnswerPresence('15550188');
      expect(sent.length, 1);
      // …nor is a pong sent while THIS device is already in their chat —
      // the periodic chat ping is saying something stronger.
      store.upsert(mk('9'));
      RelayService.instance.openChatDigits = '15550189';
      RelayService.instance.maybeAnswerPresence('15550189');
      expect(sent.length, 1);
      RelayService.instance.openChatDigits = '';
      // …nor with last-seen hidden…
      AppState.shareLastSeen.value = false;
      RelayService.instance.maybeAnswerPresence('15550189');
      expect(sent.length, 1);
      AppState.shareLastSeen.value = true;
      // …nor from the background.
      RelayService.debugForegroundOverride = () => false;
      RelayService.instance.maybeAnswerPresence('15550189');
      expect(sent.length, 1);
    });

    test('the wire stays honest about what a ping means', () {
      final relay = File('lib/relay/relay_service.dart').readAsStringSync();
      // An older build only ever pings from inside the conversation, so
      // 'chat' is what a where-less ping honestly decodes to.
      expect(relay, contains("payload['where'] as String? ?? 'chat'"));
      // Only a 'chat' ping is answered — pong answering pong would loop.
      expect(
          relay, contains("if (presenceWhere == 'chat') maybeAnswerPresence"));
      // ChatScreen tells the answerer which chat is on screen, both ways.
      final cs = File('lib/screens/chat_screen.dart').readAsStringSync();
      expect(cs, contains('RelayService.instance.openChatDigits ='));
      // A chat buried under another route must not claim "in this chat":
      // the ping pauses while covered, and resuming self-heals the
      // open-chat marker the covering chat's dispose cleared.
      expect(
          cs, contains("!(ModalRoute.of(context)?.isCurrent ?? true)) return;"),
          reason: 'the presence broadcast must check route currency');
    });
  });

  group('Poke', () {
    setUp(() => SharedPreferences.setMockInitialValues({}));

    test('a poke is a real message: json, preview, and the funnel stamps', () {
      final poke = Message(
          id: 'pk1',
          text: '👉 Poke',
          time: DateTime(2026, 1, 1),
          isMe: true,
          status: MessageStatus.sent,
          isPoke: true);
      // Round trip — a restart must not turn a poke into a text.
      expect(Message.fromJson(poke.toJson()).isPoke, isTrue);
      // The delivery funnel copyWiths every outgoing message (protected,
      // thread) — the poke has to survive that or it dies on send.
      expect(poke.copyWith(protected: true).isPoke, isTrue);
      // The chat list says what it is, not the emoji-text fallback.
      final chat = Chat(
          id: 'c',
          contact: const AppUser(
              id: 'x', name: 'X', avatarColor: '#111111', phone: 'x'),
          messages: [poke]);
      expect(chat.preview, '👉 Poke');
      // And it rides the sealed wire both directions.
      final relay = File('lib/relay/relay_service.dart').readAsStringSync();
      expect(relay, contains("if (message.isPoke) 'isPoke': true"));
      expect(relay, contains("isPoke: content['isPoke'] as bool? ?? false"));
    });

    test('one poke per chat per half-minute', () {
      final store = ChatStore.instance;
      store.hydrate(const {'chats': []});
      addTearDown(store.reset);
      expect(store.pokeCooldownLeft('c1'), Duration.zero);
      store.notePoked('c1');
      expect(store.pokeCooldownLeft('c1') > Duration.zero, isTrue);
      // Another conversation is not on this one's clock.
      expect(store.pokeCooldownLeft('c2'), Duration.zero);
      store.reset();
      expect(store.pokeCooldownLeft('c1'), Duration.zero);
    });

    test('pokeChat is the one funnel: it mints a poke and the cooldown answers',
        () {
      final store = ChatStore.instance;
      store.hydrate(const {'chats': []});
      addTearDown(store.reset);
      ScoreStore.instance.resetForTest();
      addTearDown(ScoreStore.instance.resetForTest);
      const contact = AppUser(
          id: '+15550111',
          name: 'Pat',
          avatarColor: '#111111',
          phone: '+15550111');
      store.upsert(
          const Chat(id: 'chat_+15550111', contact: contact, messages: []));

      expect(pokeChat('chat_+15550111'), 0);
      expect(
          store
              .chatById('chat_+15550111')!
              .messages
              .where((m) => m.isPoke && m.isMe)
              .length,
          1);
      expect(ScoreStore.instance.flags, contains('poked'));

      // Straight away again: the cooldown declines with seconds to wait.
      expect(pokeChat('chat_+15550111'), greaterThan(0));
      expect(
          store
              .chatById('chat_+15550111')!
              .messages
              .where((m) => m.isPoke && m.isMe)
              .length,
          1,
          reason: 'a poke that can be spammed is a harassment button');
    });

    testWidgets('an app-wide banner offers a one-tap poke back',
        (tester) async {
      final store = ChatStore.instance;
      store.hydrate(const {'chats': []});
      addTearDown(store.reset);
      const contact = AppUser(
          id: '+15550122',
          name: 'Robin',
          avatarColor: '#111111',
          phone: '+15550122');
      store.upsert(
          const Chat(id: 'chat_+15550122', contact: contact, messages: []));

      await tester.pumpWidget(
          const MaterialApp(home: Scaffold(body: PokeBackBanner())));
      await tester.pumpAndSettle();
      // Nothing until a poke lands.
      expect(find.textContaining('poked you'), findsNothing);

      // A poke arrives in that chat, from anywhere in the app.
      store.addMessage(
          'chat_+15550122',
          Message(
              id: 'pk_in2',
              text: '👉 Poke',
              time: DateTime.now(),
              isMe: false,
              status: MessageStatus.delivered,
              isPoke: true));
      await tester.pumpAndSettle();
      expect(find.text('👉 Robin poked you'), findsOneWidget);

      // One tap sends the poke back, without opening the conversation.
      await tester.tap(find.text('Poke back'));
      await tester.pumpAndSettle();
      expect(
          store
              .chatById('chat_+15550122')!
              .messages
              .where((m) => m.isPoke && m.isMe)
              .length,
          1,
          reason: 'poke back sends a poke');
      expect(find.text('Poke back'), findsNothing,
          reason: 'the banner clears once you answer');
    });

    testWidgets(
        'an incoming poke buzzes, offers poke back, and the brake '
        'holds', (tester) async {
      final store = ChatStore.instance;
      store.hydrate(const {'chats': []});
      addTearDown(store.reset);
      const contact = AppUser(
          id: '+15550195',
          name: 'Poker Pia',
          avatarColor: '#111111',
          phone: '+15550195');
      final chat = Chat(id: 'chat_+15550195', contact: contact, messages: [
        Message(
            id: 'pk_in',
            text: '👉 Poke',
            time: DateTime(2026, 1, 1),
            isMe: false,
            status: MessageStatus.delivered,
            isPoke: true),
      ]);
      store.upsert(chat);
      await tester.pumpWidget(MaterialApp(home: ChatScreen(chat: chat)));
      await tester.pumpAndSettle();
      expect(find.text('Poked you'), findsOneWidget);
      expect(find.text('Tap to poke back'), findsOneWidget);

      final buzzesBefore = Haptics.debugCount;
      await tester.tap(find.text('Poked you'));
      await tester.pumpAndSettle();
      final mine =
          store.chatById(chat.id)!.messages.where((m) => m.isPoke && m.isMe);
      expect(mine.length, 1, reason: 'poke back sends a poke');
      expect(find.text('You poked them'), findsOneWidget);
      expect(Haptics.debugCount, greaterThan(buzzesBefore));

      // Straight away again: the cooldown answers, no second poke goes.
      await tester.tap(find.text('You poked them'));
      await tester.pump();
      await tester.tap(find.text('Poked you'));
      await tester.pumpAndSettle();
      expect(
          store
              .chatById(chat.id)!
              .messages
              .where((m) => m.isPoke && m.isMe)
              .length,
          1,
          reason: 'a poke that can be spammed is a harassment button');
      expect(find.textContaining('give it'), findsOneWidget);
    });
  });

  group('Live location', () {
    setUp(() async {
      SharedPreferences.setMockInitialValues({});
      LiveShareStore.instance.resetForTest();
      await LiveShareStore.instance.load();
      LiveLocationStore.instance.resetForTest();
      LiveShareBroadcaster.instance.resetForTest();
    });
    tearDown(() {
      LiveShareStore.instance.resetForTest();
      LiveShareBroadcaster.instance.resetForTest();
      debugGeolocationOverride = null;
    });

    test('a live-location message round-trips, and the relay carries it', () {
      final until = DateTime(2026, 1, 1, 12);
      final m = Message(
        id: 'l1',
        text: '📍 Live location',
        time: DateTime(2026, 1, 1, 11),
        isMe: true,
        status: MessageStatus.sent,
        isLocation: true,
        isLiveLocation: true,
        liveUntil: until,
        locationLat: 1.0,
        locationLng: 2.0,
      );
      final back = Message.fromJson(m.toJson());
      expect(back.isLiveLocation, isTrue);
      expect(back.liveUntil, until);
      expect(back.copyWith(protected: true).isLiveLocation, isTrue);
      // The chat list names it.
      final chat = Chat(
          id: 'c',
          contact: const AppUser(
              id: 'x', name: 'X', avatarColor: '#111111', phone: 'x'),
          messages: [m]);
      expect(chat.preview, '📍 Live location');
      // And it rides the sealed wire both directions.
      final relay = File('lib/relay/relay_service.dart').readAsStringSync();
      expect(relay,
          contains("if (message.isLiveLocation) 'isLiveLocation': true"));
      expect(
          relay,
          contains(
              "isLiveLocation: content['isLiveLocation'] as bool? ?? false"));
    });

    test('LiveShareStore starts, persists, expires and stops', () async {
      final store = LiveShareStore.instance;
      final until = DateTime.now().add(const Duration(minutes: 15));
      await store.start(
          'chat_+15550170', '+15550170', until, 1.0, 2.0, 'live1');
      final d = LiveShareStore.digitsOf('+15550170');
      expect(store.isSharingTo(d), isTrue);
      expect(store.remaining(d) > Duration.zero, isTrue);

      // Persisted: a one-hour share survives closing the app.
      store.resetForTest();
      await store.load();
      expect(store.isSharingTo(d), isTrue);

      // Expired shares are pruned.
      final gone =
          await store.pruneExpired(now: until.add(const Duration(minutes: 1)));
      expect(gone, contains(d));
      expect(store.isSharingTo(d), isFalse);

      // Stop ends it outright.
      await store.start('c', '+15550170',
          DateTime.now().add(const Duration(minutes: 5)), 1.0, 2.0, 'live2');
      await store.stop(d);
      expect(store.isSharingTo(d), isFalse);
    });

    test('the broadcaster pushes to active shares and skips expired', () async {
      debugGeolocationOverride = () async => (lat: 40.0, lng: -73.0);
      final sent = <String>[];
      LiveShareBroadcaster.debugSendOverride =
          (phone, lat, lng) => sent.add(phone);
      final store = LiveShareStore.instance;
      await store.start('c1', '+15550171',
          DateTime.now().add(const Duration(minutes: 15)), 0, 0, 'live3');
      // Already past its window — the broadcaster prunes and skips it.
      await store.start('c2', '+15550172',
          DateTime.now().subtract(const Duration(minutes: 1)), 0, 0, 'live4');

      final n = await LiveShareBroadcaster.instance.broadcastOnce();
      expect(n, 1);
      expect(sent, ['+15550171']);
      // The sender's own last-sent position is kept for its bubble map.
      expect(store.shareFor(LiveShareStore.digitsOf('+15550171'))!.lat, 40.0);
    });

    testWidgets('a live bubble shows the countdown and stops on tap',
        (tester) async {
      final store = LiveShareStore.instance;
      final until = DateTime.now().add(const Duration(minutes: 15));
      await store.start('c', '+15550180', until, 40.0, -73.0, 'lb');
      var stopped = false;
      final msg = Message(
        id: 'lb',
        text: '📍 Live location',
        time: DateTime.now(),
        isMe: true,
        status: MessageStatus.sent,
