    test('a sale code confirms a purchase; a wrong one stays an opinion', () {
      final feed = FeedStore.instance;
      feed.resetForTest();
      addTearDown(feed.resetForTest);
      final listing = feed.addListing('c1',
          title: 'Trek bike', priceCents: 12000, category: 'Sports');
      // Somebody else's listing mints nothing — the code is the seller's
      // to hand over.
      feed.addRemote(FeedPost(
          id: 'their_l',
          communityId: 'c1',
          authorName: 'Grace',
          authorUsername: 'grace',
          time: DateTime(2026, 1, 1),
          text: 'Grace couch',
          priceCents: 9000));
      expect(feed.mintSaleCode('their_l'), isNull);

      final code = feed.mintSaleCode(listing.id)!;
      expect(code, hasLength(6));
      expect(int.tryParse(code), isNotNull);
      // The listing broadcast carries the HASH and never the code.
      final carried = feed.postById(listing.id)!;
      expect(carried.saleCodeHash, isNotEmpty);
      expect(carried.saleCodeHash.contains(code), isFalse);
      expect(carried.toJson()['saleCodeHash'], carried.saleCodeHash);
      expect(feed.saleCodeMatches(listing.id, code), isTrue);
      expect(feed.saleCodeMatches(listing.id, '000000'), isFalse);

      // The buyer types it with their review — but reviews are for OTHER
      // people's listings, so stage one of Grace's with a code this
      // device knows.
      final hash = FeedStore.saleCodeHashOf('424242');
      feed.addRemote(FeedPost(
          id: 'their_l2',
          communityId: 'c1',
          authorName: 'Grace',
          authorUsername: 'grace',
          time: DateTime(2026, 1, 1),
          text: 'Grace lamp',
          priceCents: 1500,
          saleCodeHash: hash));
      feed.addReview('their_l2', rating: 5, saleCode: '424242');
      expect(feed.reviewsFor('their_l2').single.confirmedPurchase, isTrue);
      // A wrong code still posts, without the chip — an opinion is allowed.
      feed.addReview('their_l2', rating: 2, saleCode: '111111');
      expect(feed.reviewsFor('their_l2').single.confirmedPurchase, isFalse);
      // And the flag survives the wire's json round trip.
      final review = feed.reviewsFor('their_l2').single;
      expect(FeedPost.fromJson(review.toJson()).confirmedPurchase,
          review.confirmedPurchase);
    });

    test('a buyer-bound code confirms only that buyer, not whoever has it', () {
      final feed = FeedStore.instance;
      feed.resetForTest();
      addTearDown(feed.resetForTest);

      // A seller minted a code for buyer "alice" — only the bound hash rides,
      // the buyer's handle never does.
      final boundHash = FeedStore.saleCodeHashOf('654321', buyer: 'alice');
      expect(boundHash, isNot(FeedStore.saleCodeHashOf('654321')),
          reason: 'binding to a buyer changes the hash');
      feed.addRemote(FeedPost(
          id: 'lst_bound',
          communityId: 'c1',
          authorName: 'Seller',
          authorUsername: 'seller',
          time: DateTime(2026, 1, 1),
          text: 'Bike',
          priceCents: 5000,
          saleCodeHash: boundHash));

      // The right buyer, typing the code under their own handle, matches.
      expect(feed.saleCodeMatches('lst_bound', '654321', buyerHandle: 'alice'),
          isTrue);
      // Anyone else with the same code does NOT — a leaked or shared code
      // confirms nobody but the buyer it was minted for.
      expect(
          feed.saleCodeMatches('lst_bound', '654321', buyerHandle: 'mallory'),
          isFalse);
      expect(feed.saleCodeMatches('lst_bound', '654321'), isFalse,
          reason: 'no handle cannot claim a bound sale');
      // The wrong code never matches, bound or not.
      expect(feed.saleCodeMatches('lst_bound', '000000', buyerHandle: 'alice'),
          isFalse);

      // Source pins: the sold flow binds to the buyer, and addReview binds to
      // the reviewer's own handle.
      final market =
          File('lib/screens/marketplace_screen.dart').readAsStringSync();
      expect(market.contains('buyerHandle: buyer.username'), isTrue);
      final fs = File('lib/state/feed_store.dart').readAsStringSync();
      expect(fs.contains('buyerHandle: myUsername'), isTrue);
    });

