    test('a follow toggle records the edge, and old follows push up once',
        () async {
      final follows = FollowStore.instance;
      follows.resetForTest();
      addTearDown(follows.resetForTest);
      addTearDown(PublicFeedStore.instance.resetForTest);
      final sent = <(String, bool)>[];
      PublicFeedStore.debugFollowOverride = (u, f) async => sent.add((u, f));

      follows.toggle('Grace'); // cleaned to lowercase on the way
      follows.toggle('grace');
      expect(sent, [('grace', true), ('grace', false)]);

      // The follows made before the graph existed go up once per run.
      sent.clear();
      follows.toggle('ada');
      follows.toggle('sam');
      sent.clear();
      await PublicFeedStore.instance.pushLocalFollows(follows.following);
      expect(sent.map((e) => e.$1).toSet(), {'ada', 'sam'});
      await PublicFeedStore.instance.pushLocalFollows(follows.following);
      expect(sent.length, 2, reason: 'the push is once per run, not a loop');
    });

    test(
        'a sealed envelope opens only for its recipient, and never names '
        'the sender', () {
      final alice = SecureKeyExchange.freshForTest();
      final bob = SecureKeyExchange.freshForTest();
      final inner = {
        'e': 'msg',
        'p': {'from': '+1 555 0177', 'id': 'ss1', 'text': 'sealed hello'},
      };
      final env = SealedSender.seal(bob.myPublicKey!, inner)!;
      // The wire shape: version, ephemeral key, ciphertext — and nothing
      // else. No 'from' is the entire point.
      expect(env.keys.toSet(), {'v', 'epk', 'sc'});
      expect(jsonEncode(env).contains('5550177'), isFalse,
          reason: 'the sender must not be readable anywhere outside');
      expect(SealedSender.isSealed(env), isTrue);

      // Bob opens it; Alice — any other key — cannot.
      expect(SealedSender.unseal(env, kx: bob), inner);
      expect(SealedSender.unseal(env, kx: alice), isNull);
      // Tampering dies on the GCM tag; junk keys die quietly.
      final bent = Map<String, dynamic>.from(env);
      bent['sc'] = 'AAAA${(bent['sc'] as String).substring(4)}';
      expect(SealedSender.unseal(bent, kx: bob), isNull);
      expect(
          SealedSender.unseal({'v': 1, 'epk': 'garbage', 'sc': env['sc']},
              kx: bob),
          isNull);
      expect(SealedSender.seal('not-a-key', inner), isNull,
          reason: 'a malformed recipient key means "send legacy"');
    });

    test('a push preview seals, opens, and refuses the wrong key', () {
      // The banner said "New message" because the push passes through the
      // relay and Apple, and neither may read it. So the words ride sealed
      // and the recipient's extension opens them after delivery.
      final key = NotificationPreview.keyFor(List<int>.generate(32, (i) => i));
      final blob = NotificationPreview.seal(key, 'see you at 6');
      expect(blob, isNotEmpty);
      expect(blob.contains('see you'), isFalse,
          reason: 'the preview went out in the clear');
      expect(NotificationPreview.open(key, blob), 'see you at 6');

      // A different peer's key opens nothing. This is what guarantees a
      // failure can never become a WRONG banner: the extension gets null and
      // leaves the content-free fallback body standing.
      final other =
          NotificationPreview.keyFor(List<int>.generate(32, (i) => i + 1));
      expect(NotificationPreview.open(other, blob), isNull);
      expect(NotificationPreview.open(key, 'not base64 %%%'), isNull);
      expect(NotificationPreview.open(key, ''), isNull);
    });

    test('the preview key is NOT the message key', () {
      // Domain separation, and the reason it matters here more than usual:
      // this key is long-lived where the ratchet is forward-secret, so it is
      // the weaker of the two. If it were the same output, leaking the weak
      // one would open messages sealed under the strong one.
      final secret = List<int>.generate(32, (i) => i * 3 % 251);
      expect(NotificationPreview.keyFor(secret),
          isNot(equals(E2eCrypto.deriveAesKey(secret))));
      // Same secret, same key, on both devices independently — that is what
      // lets there be no exchange, no distribution and nothing to go stale.
      expect(NotificationPreview.keyFor(secret),
          equals(NotificationPreview.keyFor(secret)));
    });

    test('a sealed preview is exactly CryptoKit\'s combined layout', () {
      // nonce(12) ‖ ciphertext ‖ tag(16) is what AES.GCM.SealedBox(combined:)
      // takes, so the extension opens it in two lines with no framing code to
      // get wrong in a language nothing here can compile.
      final key = NotificationPreview.keyFor(List<int>.filled(32, 7));
      final raw = base64.decode(NotificationPreview.seal(key, 'abcde'));
      expect(raw.length, 12 + 5 + 16);

      // Long text is clipped rather than dropped — a lock screen truncates
      // anyway, and an oversized payload is one APNs refuses outright.
      final long = NotificationPreview.seal(key, 'x' * 500);
      expect(NotificationPreview.open(key, long)!.length,
          NotificationPreview.maxChars);
      // Nothing to say, nothing attached: the push keeps today's fallback.
      expect(NotificationPreview.seal(key, '   '), '');
    });

    test(
        'the relay seals text previews only, and never for a peer it '
        'holds no key for', () {
      final kx = SecureKeyExchange.instance;
      kx.resetForTest();
      kx.ensureKeys();
      addTearDown(kx.resetForTest);

      final src = File('lib/relay/relay_service.dart').readAsStringSync();
      // A caption on a photo is the part of a media message somebody may
      // have assumed was private in a different way, so only a plain text
      // message is previewed — media keeps its content-free type label.
      expect(src, contains('if (message.typeLabel.isNotEmpty) return \'\''));
      // No key for this peer means no preview, never a cleartext one.
      expect(src, contains('if (peerPub == null) return \'\''));
      expect(src, contains('preview: _sealedPreviewFor('));

      // The push function relays it without being able to read it, and drops
      // it entirely for a recipient who asked for private notifications —
      // their lock screen is meant to say nothing, and an extension that
      // filled it in anyway would overrule them.
      final fn =
          File('supabase/functions/push-send/index.ts').readAsStringSync();
      expect(fn, contains('!wantsPrivate'));
      expect(fn, contains('mutable-content'));
      // Beside `aps`, never inside it — Apple owns that dictionary.
      expect(fn, contains('...(sealedPreview ? { p: sealedPreview } : {})'));
    });

    test('the extension and the app agree on where the key lives', () async {
      // Four strings have to match across two languages, and every mismatch
      // fails the SAME silent way: the extension's keychain lookup finds
      // nothing and every banner quietly keeps its fallback body. That is
      // indistinguishable from the feature not being built, so it is pinned
      // here rather than discovered on a device.
      final swift = File('ios/NotificationService/NotificationService.swift')
          .readAsStringSync();
      expect(swift, contains(PreviewKeyStore.accessGroup));
      expect(swift, contains(PreviewKeyStore.keyPrefix));

      // Both targets must declare the shared group or they get separate
      // keychains and never see each other's items.
      for (final f in const [
        'ios/Runner/Runner.entitlements',
        'ios/NotificationService/NotificationService.entitlements',
      ]) {
        final ents = File(f).readAsStringSync();
        expect(ents, contains('keychain-access-groups'), reason: f);
        expect(ents, contains(PreviewKeyStore.accessGroup), reason: f);
      }

      // And the payload keys the sender writes are the ones Swift reads.
      expect(swift, contains('info["p"]'));
      expect(swift, contains('info["from"]'));
    });

    test(
        'neither side names an explicit kSecAttrAccessGroup — confirmed '
        'live 2026-08-12 as the actual cause of every preview failing', () {
      // $(AppIdentifierPrefix) is an Xcode BUILD-SETTING substitution: it is
      // expanded only when Xcode processes an .entitlements/.plist file,
      // never inside compiled Dart or Swift. A device running the old code
      // hit errSecMissingEntitlement (-34018) on the write side because
      // PreviewKeyStore passed the bare group name (missing the team-id
      // prefix Xcode actually signs with) as `groupId`. Both entitlements
      // files declare exactly ONE keychain-access-groups entry, so Apple's
      // documented default — the sole entry is used automatically whenever
      // kSecAttrAccessGroup is left unset — is what has to carry this,
      // rather than either side trying to reconstruct the resolved string.
      final dart = File('lib/state/preview_key_store.dart').readAsStringSync();
      expect(dart, isNot(contains('groupId: accessGroup')));
      expect(dart, isNot(contains('groupId: PreviewKeyStore.accessGroup')));

      // The doc comment above the query legitimately names the API to
      // explain why it isn't used — only the query dictionary literal
      // itself must stay clear of it.
      final swift = File('ios/NotificationService/NotificationService.swift')
          .readAsStringSync();
      expect(swift, isNot(contains('kSecAttrAccessGroup as String:')));
    });

    test('the key the app stores is the key the sender sealed with', () async {
      final kx = SecureKeyExchange.instance;
      kx.resetForTest();
      kx.ensureKeys();
      addTearDown(kx.resetForTest);
      final writes = <String, String>{};
      PreviewKeyStore.debugWrites = writes;
      addTearDown(() => PreviewKeyStore.debugWrites = null);

      // Sealing to our own public key gives both halves of the round trip in
      // one process — the extension is Swift and cannot be run here, so this
      // is the closest thing to proving the two ends line up.
      final myPub = kx.myPublicKey!;
      await PreviewKeyStore.instance.remember('15550100', myPub);
      final stored = writes['${PreviewKeyStore.keyPrefix}15550100'];
      expect(stored, isNotNull);

      final key = Uint8List.fromList(base64.decode(stored!));
      expect(key.length, 32,
          reason: 'the Swift side requires exactly 32 bytes once it has '
              'base64-decoded what was actually stored');
      final sealed = NotificationPreview.seal(
          NotificationPreview.keyFor(kx.sharedSecretWith(myPub)!), 'on my way');
      expect(NotificationPreview.open(key, sealed), 'on my way');

      // An identity-key change buries the old key rather than leaving a stale
      // entry in a SHARED keychain to fail every future open.
      await PreviewKeyStore.instance.forget('15550100');
      expect(
          writes.containsKey('${PreviewKeyStore.keyPrefix}15550100'), isFalse);
    });

    test(
        'the Swift side base64-decodes what it reads back, rather than '
        'treating the raw keychain bytes as the key — confirmed live '
        '2026-08-12 as a second, independent fault', () {
      // debugWrites (used above) is an in-memory Dart map: `stored` there is
      // whatever string PreviewKeyStore.remember() wrote, decoded straight
      // with base64.decode in THIS TEST — it never touches the real native
      // storage layer, so it could never have caught this. The real bug: on
      // a device, PreviewKeyStore writes a base64 STRING through
      // flutter_secure_storage, whose Swift implementation stores that
      // string's UTF-8 BYTES verbatim (`value.data(using: .utf8)`) — so what
      // actually sits in the keychain is the base64 TEXT (44 bytes for a
      // 32-byte key), never the 32 raw bytes. The extension's query used to
      // check `count == 32` on that raw retrieved Data directly, which was
      // always false, so previewKey() always returned nil — silently, for
      // EVERY sender, independent of the keychain-access-group fault fixed
      // alongside it. A real device confirmed the self-test's "Shared
      // keychain" step passing while the notification still showed the
      // fallback text, which is what this bug alone produces.
      final swift = File('ios/NotificationService/NotificationService.swift')
          .readAsStringSync();
      expect(swift, contains('String(data: raw, encoding: .utf8)'));
      expect(swift, contains('Data(base64Encoded: text)'));
    });

    test('the notification extension is a real, embedded target', () {
      // Hand-written, because there is no Xcode on the box that produced it —
      // so the things Xcode would have guaranteed are asserted instead. A
      // target that exists but is never embedded builds cleanly and simply
      // never runs, which is the worst of the failure modes: silent.
      final pbx =
          File('ios/Runner.xcodeproj/project.pbxproj').readAsStringSync();
      expect(pbx, contains('com.apple.product-type.app-extension'));
      expect(pbx, contains('Embed App Extensions'));
      // dstSubfolderSpec 13 IS "PlugIns"; any other value copies the
      // extension somewhere iOS will not look for it.
      expect(pbx, contains('dstSubfolderSpec = 13;'));
      expect(pbx, contains('NotificationService/Info.plist'));
      expect(pbx,
          contains('NotificationService/NotificationService.entitlements'));
      expect(pbx, contains('com.okaymessaging.NotificationService'),
          reason: 'an extension must be a child bundle id of the app');

      final plist =
          File('ios/NotificationService/Info.plist').readAsStringSync();
      expect(plist, contains('com.apple.usernotifications.service'));

      // And CI must fetch signing files for it. An extension is its own
      // bundle with its own App ID and profile; the app's does not cover it.
      // Missing this failed a real archive with 'Signing for
      // "NotificationService" requires a development team' — which reads as
      // a missing setting and is really a missing profile, because
      // use-profiles had nothing to apply to that target.
      final ci = File('codemagic.yaml').readAsStringSync();
      expect(ci, contains('"\$BUNDLE_ID.NotificationService"'));

      // ORDER MATTERS, and getting it wrong failed a real archive with
      // "Cycle inside Runner". Flutter's "Thin Binary" script reads
      // Runner.app/Info.plist, while embedding the extension WRITES into
      // Runner.app — so with the embed placed after it, each phase waited on
      // the other. The embed must come first.
      final embed = pbx.indexOf('DEEDDEED0000000000000015 /* Embed App '
          'Extensions */,\n\t\t\t\t3B06AD1E1E4923F5004D2608 /* Thin Binary */,');
      expect(embed, greaterThan(-1),
          reason: 'Embed App Extensions must sit immediately before Thin '
              'Binary or the build cycles');
    });

    test('the extension never invents notification text', () {
      // The rule that makes a decryption failure harmless: every guard falls
      // through to the alert as it arrived. A wrong banner is worse than a
      // vague one, and this is the only file that could produce one.
      final swift = File('ios/NotificationService/NotificationService.swift')
          .readAsStringSync();
      // Exactly one place assigns the body, and it is behind the guard that
      // produced real plaintext.
      expect('content.body ='.allMatches(swift).length, 1);
      expect(swift, contains('serviceExtensionTimeWillExpire'),
          reason: 'iOS kills an extension that overruns; hand back the '
              'original rather than losing the notification entirely');
    });

    test(
        'the handshake: advertised on legacy traffic, relied on only '
        'after the peer says it back', () {
      final kx = SecureKeyExchange.instance;
      kx.resetForTest();
      kx.ensureKeys();
      addTearDown(kx.resetForTest);
      final store = ChatStore.instance;
      store.hydrate(const {'chats': []});
      addTearDown(store.reset);

      // Outgoing legacy messages carry the advertisement.
      final payload = RelayService.encode(
          message: Message(
              id: 'sv1',
              text: 'hi',
              time: DateTime(2026, 8, 5),
              isMe: true,
              status: MessageStatus.sent),
          fromPhone: '+1 555 0100',
          fromName: 'Me',
          toPhone: '+1 555 0177');
      expect(payload['sv'], 1);

      // Not sealable yet: no capability heard, no key held.
      expect(
          RelayService.instance
              .sealedEnvelopeFor('+1 555 0177', 'msg', payload),
          isNull);
      // An incoming legacy message with the flag records the capability…
      RelayService.applyIncoming({
        'from': '+1 555 0177',
        'id': 'in1',
        'text': 'hello back',
        'sv': 1,
      }, myPhone: '+1 555 0100', store: store);
      expect(kx.sealedCapable('+1 555 0177'), isTrue);
      // …but capability without their key still refuses to seal —
      // an unopenable envelope is a lost message.
      expect(
          RelayService.instance
              .sealedEnvelopeFor('+1 555 0177', 'msg', payload),
          isNull);
      // With both, the envelope seals and says nothing about the sender.
      kx.rememberPeer(
          '+1 555 0177', SecureKeyExchange.freshForTest().myPublicKey!);
      final env = RelayService.instance
          .sealedEnvelopeFor('+1 555 0177', 'msg', payload)!;
      expect(env.keys.toSet(), {'v', 'epk', 'sc'});
    });

    test('a sealed message walks the whole road: unseal, apply, arrive', () {
      final kx = SecureKeyExchange.instance;
      kx.resetForTest();
      kx.ensureKeys();
      addTearDown(kx.resetForTest);
      final store = ChatStore.instance;
      store.hydrate(const {'chats': []});
      addTearDown(store.reset);

      final legacy = {
        'from': '+1 555 0177',
        'id': 'ss_msg1',
        'text': 'came in sealed',
      };
      final env =
          SealedSender.seal(kx.myPublicKey!, {'e': 'msg', 'p': legacy})!;
      RelayService.instance
          .applySealedEnvelope(env, myPhone: '+1 555 0100', store: store);
      final chat = store.chatWithContact('+1 555 0177');
      expect(chat, isNotNull);
      expect(chat!.messages.single.text, 'came in sealed');

      // A ping seals too — the event NAME on the channel is metadata.
      final typing = SealedSender.seal(kx.myPublicKey!, {
        'e': 'typing',
        'p': {'from': '+1 555 0177'},
      })!;
      final pingsBefore = RelayService.instance.typingPing.value;
      RelayService.instance.applySealedEnvelope(typing, myPhone: '+1 555 0100');
      expect(RelayService.instance.typingFromDigits, '15550177');
      expect(RelayService.instance.typingPing.value, pingsBefore + 1);

      // Somebody else's envelope is not ours to open: silently nothing.
      final other = SecureKeyExchange.freshForTest();
      final notMine =
          SealedSender.seal(other.myPublicKey!, {'e': 'msg', 'p': legacy})!;
      RelayService.instance
          .applySealedEnvelope(notMine, myPhone: '+1 555 0100', store: store);
      expect(store.chatWithContact('+1 555 0177')!.messages.length, 1,
          reason: 'an unopenable envelope must do nothing at all');
    });

    test(
        'every inbox event type has a sealed road, and both receive '
        'paths route it', () {
      final src = File('lib/relay/relay_service.dart').readAsStringSync();
      // The dispatcher's roster: an event missing here arrives sealed and
      // is silently dropped.
      final at = src.indexOf('void applyInboxEvent');
      expect(at, isNonNegative);
      final dispatcher = src.substring(at, src.indexOf('/// Pure:', at));
      for (final event in [
        'msg', 'receipt', 'edit', 'delete', 'reaction', 'poll', 'payst',
        'form', 'vopen', 'locstop', 'gupd', 'callmiss', 'call', 'skdm', 'skreq',
        'fbreq', 'key', 'typing', 'presence', 'gpres', 'shot', 'cap',
        'gshot', //
        'status', 'billpaid', 'prof',
      ]) {
        expect(dispatcher.contains("'$event'"), isTrue,
            reason: 'sealed $event would be silently dropped');
      }
      // Live subscription and mailbox drain both open sealed envelopes.
      expect(src, contains("event: 'sealed'"));
      expect(src, contains("case 'sealed':"));
      // And all three send funnels can seal: messages, inbox events, pings.
      expect(RegExp('sealedEnvelopeFor\\(').allMatches(src).length,
          greaterThanOrEqualTo(5),
          reason: 'send funnels: msg, inbox events, pings, and both '
              'call-signaling sites');
    });

    test('a friend\'s story arrives over the relay and lands in the store', () {
      StatusStore.instance.resetForTest();
      addTearDown(StatusStore.instance.resetForTest);

      // A fresh story from a peer folds into the store as an "other" thread,
      // keyed by the sender's digits so the map can light its ring.
      RelayService.instance.applyStatus({
        'from': '+1 555 0177',
        'id': 'st_peer_1',
        'name': 'Alice Bennett',
        'ac': '#E57373',
        'text': 'On the ferry ⛴️',
        'bg': '#0BA5EC',
        't': DateTime.now().toIso8601String(),
      }, myPhone: '+1 555 0100');
      final threads = StatusStore.instance.otherThreads();
      final mine = threads.where((t) => t.authorId == '15550177');
      expect(mine, hasLength(1));
      expect(mine.first.updates.single.text, 'On the ferry ⛴️');

      // My own echo is dropped, and so is one already past its 24h window.
      RelayService.instance.applyStatus({
        'from': '+1 555 0100',
        'id': 'st_self',
        'text': 'my own',
        't': DateTime.now().toIso8601String(),
      }, myPhone: '+1 555 0100');
      RelayService.instance.applyStatus({
        'from': '+1 555 0177',
        'id': 'st_old',
        'text': 'yesterday',
        't': DateTime.now()
            .subtract(const Duration(hours: 25))
            .toIso8601String(),
      }, myPhone: '+1 555 0100');
      final after = StatusStore.instance.otherThreads();
      expect(after.expand((t) => t.updates).map((u) => u.id),
          isNot(contains('st_self')));
      expect(after.expand((t) => t.updates).map((u) => u.id),
          isNot(contains('st_old')));
    });

