        () {
      // Smart replies read PRIVATE conversations, so they run on the device
      // and nowhere else — no network import may ever appear here. This is
      // the pin that stops "swap the AI provider" from quietly meaning
      // "decrypt everyone's chats to a cloud API".
      final replies = File('lib/state/smart_replies.dart').readAsStringSync();
      expect(replies.contains('http'), isFalse,
          reason: 'smart replies must have no network path');
      expect(replies.contains('openrouter'), isFalse);
      expect(replies.contains('supabase'), isFalse);
      // The public-feed screen is the one surface allowed a hosted model
      // (world-readable posts), and it now rides OpenRouter — inert without
      // the key, fail-open on every error path.
      final screen = File('supabase/functions/moderation-screen/index.ts')
          .readAsStringSync();
      expect(screen, contains('OPENROUTER_API_KEY'));
      expect(screen, contains('openrouter.ai/api/v1/chat/completions'));
      expect(screen.contains('api.openai.com'), isFalse);
      expect(screen, contains('parseClassifier'));
      // The paste copy is what actually gets deployed — it must match.
      final paste = File('docs/edge_functions_paste/moderation-screen.ts')
          .readAsStringSync();
      expect(paste, contains('OPENROUTER_API_KEY'));
      expect(paste.contains('api.openai.com'), isFalse);
    });
  });

  group('A name-only account lives 14 days', () {
    setUp(() {
      SharedPreferences.setMockInitialValues({});
      NumberlessGrace.instance.resetForTest();
    });
    tearDown(NumberlessGrace.instance.resetForTest);

    test('the clock starts once and does not restart on relaunch', () async {
      // The failure that would quietly turn a 14-day limit into no limit at
      // all: start() runs on every launch, so a clock that reset each time
      // would never reach the deadline.
      var now = DateTime(2026, 8, 1, 9);
      NumberlessGrace.debugNow = () => now;
      final g = NumberlessGrace.instance;

      await g.start('OKAY-1234');
      final first = g.startedAt;
      expect(first, DateTime(2026, 8, 1, 9));

      now = DateTime(2026, 8, 9, 9); // eight days later, app relaunched
      await g.start('OKAY-1234');
      expect(g.startedAt, first, reason: 'the clock must not restart');
      expect(g.daysLeft, 6);
      expect(g.expired, isFalse);
    });

    test('it expires at 14 days, not before', () async {
      var now = DateTime(2026, 8, 1);
      NumberlessGrace.debugNow = () => now;
      final g = NumberlessGrace.instance;
      await g.start('OKAY-1234');

      // An hour short is not expired — the account still works.
      now = DateTime(2026, 8, 15).subtract(const Duration(hours: 1));
      expect(g.expired, isFalse);
      expect(g.daysLeft, 1, reason: 'rounded UP, so the last day reads as 1');

      now = DateTime(2026, 8, 15);
      expect(g.expired, isTrue);
      expect(g.daysLeft, 0);
      // Past the deadline it stays expired rather than going negative.
      now = DateTime(2026, 9, 1);
      expect(g.expired, isTrue);
      expect(g.remaining, Duration.zero);
    });

    test('each account gets its own fortnight', () async {
      // Two name-only accounts on one phone. The second must not inherit the
      // first's nearly-expired clock.
      var now = DateTime(2026, 8, 1);
      NumberlessGrace.debugNow = () => now;
      final g = NumberlessGrace.instance;
      await g.start('OKAY-AAAA');

      now = DateTime(2026, 8, 13);
      await g.start('OKAY-BBBB');
      expect(g.daysLeft, NumberlessGrace.graceDays);
      expect(g.expired, isFalse);

      // And the first one's clock is still where it was.
      await g.load('OKAY-AAAA');
      expect(g.daysLeft, 2);
    });

    test('adding a number stops the clock for good', () async {
      var now = DateTime(2026, 8, 1);
      NumberlessGrace.debugNow = () => now;
      final g = NumberlessGrace.instance;
      await g.start('OKAY-1234');
      expect(g.running, isTrue);

      await g.clear('OKAY-1234');
      expect(g.running, isFalse);
      expect(g.expired, isFalse);

      // And it stays cleared — load must not resurrect a deadline for an
      // account that now has a number.
      now = DateTime(2026, 9, 1);
      await g.load('OKAY-1234');
      expect(g.running, isFalse);
      expect(g.expired, isFalse);
    });

    test('load never invents a clock for an account that has none', () async {
      final g = NumberlessGrace.instance;
      await g.load('OKAY-NEVER');
      expect(g.running, isFalse);
      await g.load('');
      expect(g.running, isFalse);
    });

    test('the reminder always names the consequence, and sharpens', () async {
      var now = DateTime(2026, 8, 1);
      NumberlessGrace.debugNow = () => now;
      final g = NumberlessGrace.instance;
      await g.start('OKAY-1234');

      // "3 days left" alone never says left until WHAT, so every state names
      // the deletion.
      expect(g.bannerText, contains('deleted'));
      expect(g.urgent, isFalse);

      now = DateTime(2026, 8, 12); // three days to go
      expect(g.urgent, isTrue,
          reason: 'the last stretch is when somebody has to act, not intend');
      expect(g.bannerText, contains('deleted'));

      now = DateTime(2026, 8, 14, 12); // final hours
      expect(g.bannerText, contains('Last day'));
      expect(g.bannerText, contains('deleted'));
    });

    test('an account that pre-dates the rule gets a week from being TOLD',
        () async {
      // Backdating to whenever they signed up would delete the data of
      // people who were never warned — the one thing this feature exists to
      // avoid. So the week starts on the launch that tells them, and someone
      // who does not open the app for a month simply starts their week then.
      var now = DateTime(2026, 8, 11);
      NumberlessGrace.debugNow = () => now;
      final g = NumberlessGrace.instance;

      await g.load('OKAY-OLD');
      expect(g.running, isFalse, reason: 'no clock until it is adopted');

      await g.adoptExisting('OKAY-OLD');
      expect(g.daysLeft, NumberlessGrace.existingAccountDays);
      expect(g.adopted, isTrue);
      expect(g.expired, isFalse);

      // Granted ONCE. Relaunching must not renew the week.
      now = DateTime(2026, 8, 16);
      await g.adoptExisting('OKAY-OLD');
      expect(g.daysLeft, 2);

      now = DateTime(2026, 8, 18);
      expect(g.expired, isTrue);

      // And the shorter window survives a reload — a 7-day account must not
      // come back as a 14-day one.
      now = DateTime(2026, 8, 16);
      await g.load('OKAY-OLD');
      expect(g.days, NumberlessGrace.existingAccountDays);
      expect(g.daysLeft, 2);
    });

    test('a new account still gets the full fortnight', () async {
      var now = DateTime(2026, 8, 11);
      NumberlessGrace.debugNow = () => now;
      final g = NumberlessGrace.instance;
      await g.start('OKAY-NEW');
      expect(g.daysLeft, NumberlessGrace.graceDays);
      expect(g.adopted, isFalse);
    });

    test('the notice goes out once, not on every launch', () async {
      final g = NumberlessGrace.instance;
      expect(await g.markTold('OKAY-OLD', 'adopted'), isTrue);
      expect(await g.markTold('OKAY-OLD', 'adopted'), isFalse,
          reason: 'a notice re-sent every launch is one people turn off');
      // A different milestone is its own notice.
      expect(await g.markTold('OKAY-OLD', 'lastday'), isTrue);
      // And a different account has not been told anything.
      expect(await g.markTold('OKAY-OTHER', 'adopted'), isTrue);

      // The notice has to say all three things, like every other surface.
      expect(
          g.noticeBody,
          contains('${NumberlessGrace.existingAccountDays} '
              'days from today'));
      expect(g.noticeBody, contains('phone number'));
      expect(g.noticeBody, contains('username'));
    });

    test('the notice is local, because there is nobody to push it', () {
      // A name-only account has no Supabase session and therefore no push
      // token — no server can reach it. A local notification is the only
      // honest mechanism, and enough: the account can only be deleted while
      // the app is open anyway.
      final main = File('lib/main.dart').readAsStringSync();
      final fn =
          main.substring(main.indexOf('Future<bool> enforceNumberlessGrace'));
      expect(fn, contains('PushService.instance.localNotify'));
      expect(fn, contains('adoptExisting'));
      expect(fn, contains("markTold(me.phone, 'adopted')"));
      expect(fn, contains("markTold(me.phone, 'lastday')"));
    });

    test('every place this is explained says all three things', () {
      // What happens, when, and what stops it — including that a number lets
      // them pick their own username, which is the reason to bother.
      for (final text in [
        NumberlessGrace.promise,
        File('lib/widgets/numberless_grace_banner.dart').readAsStringSync(),
      ]) {
        expect(text, contains('username'));
      }

      // The sign-up confirmation must say it BEFORE the account exists.
      final login =
          File('lib/screens/auth/phone_login_screen.dart').readAsStringSync();
      expect(login, contains('is deleted in '));
      expect(login, contains('NumberlessGrace.graceDays'));
      // Pinned on a phrase the source does not wrap mid-way — the sentence
      // itself is split across string literals, which has broken a pin in
      // this file before.
      expect(login, contains('your own username'));
      // And the login screen explains a deletion that already happened,
      // rather than dropping somebody at a sign-in form with no word for it.
      expect(login, contains('numberlessAccountExpired'));

      // The banner cannot be dismissed: the one somebody swipes away on day
      // two is the one they needed on day thirteen.
      final banner =
          File('lib/widgets/numberless_grace_banner.dart').readAsStringSync();
      expect(banner.contains('onDismiss'), isFalse);
      expect(banner.contains('Dismiss'), isFalse);
    });

    test('expiry erases the account AND signs out', () {
      // Either half alone is worse than neither: erasing without signing out
      // leaves somebody inside an empty account, and signing out without
      // erasing leaves their chats on disk for whoever has the phone next.
      final main = File('lib/main.dart').readAsStringSync();
      final fn =
          main.substring(main.indexOf('Future<bool> enforceNumberlessGrace'));
      expect(fn, contains('AccountWipe.eraseCurrentAccount()'));
      expect(fn, contains('session.signOut()'));
      expect(fn, contains('numberlessAccountExpired.value = true'));
      // A real account must never be touched by this.
      expect(fn, contains('!session.isNumberless'));
      // Checked on resume too — on iOS the process outlives many days, so a
      // deadline crossed in the background must still be honoured.
      expect('enforceNumberlessGrace()'.allMatches(main).length,
          greaterThanOrEqualTo(3));
    });
  });

  group('Forum comment threads (Reddit-shaped)', () {
    PublicForumComment c(String id,
            {String? parent, int score = 0, int day = 1}) =>
        PublicForumComment(
          id: id,
          postId: 'p1',
          authorUsername: 'u',
          authorName: 'U',
          body: id,
          parentId: parent,
          score: score,
          createdAt: DateTime(2026, 8, day),
        );

    test('replies nest to any depth, not just one', () {
      // The forum shipped with a single level: a reply to a reply rendered as
      // a SIBLING of the comment it answered, so an argument three deep read
      // as several people talking past each other.
      final t = ForumThread.build([
        c('a'),
        c('a1', parent: 'a'),
        c('a1x', parent: 'a1'),
        c('a1xy', parent: 'a1x'),
        c('b'),
      ], sort: ForumCommentSort.oldest);

      expect(
          [for (final x in t) x.comment.id], ['a', 'a1', 'a1x', 'a1xy', 'b']);
      expect([for (final x in t) x.depth], [0, 1, 2, 3, 0]);
      // A parent knows its WHOLE subtree, not just its children — that is the
      // number a collapsed comment shows.
      expect(t.first.descendants, 3);
    });

    test('a thread deeper than the indent keeps its comments', () {
      final chain = <PublicForumComment>[c('r')];
      for (var i = 0; i < ForumThread.maxDepth + 4; i++) {
        chain.add(c('n$i', parent: i == 0 ? 'r' : 'n${i - 1}'));
      }
      final t = ForumThread.build(chain, sort: ForumCommentSort.oldest);
      // Nothing is dropped...
      expect(t.length, chain.length);
      // ...but the indent stops, or a deep argument has no room for words.
      expect(t.map((x) => x.depth).reduce((a, b) => a > b ? a : b),
          ForumThread.maxDepth);
    });

    test('an orphaned reply becomes a root instead of vanishing', () {
      // A parent can disappear from the ROWS without being deleted — the read
      // policy hides a banned author's comments. Everyone who answered them
      // must still be visible.
      final t = ForumThread.build([
        c('kept'),
        c('answer', parent: 'gone'),
      ]);
      expect(t.length, 2);
      expect(t.map((x) => x.depth), everyElement(0));
    });

    test('a cycle renders once and does not hang', () {
      // Two comments each claiming the other as parent should never be
      // possible, but a walk that trusted the data would recurse forever and
      // take the isolate with it.
      final t = ForumThread.build([
        c('x', parent: 'y'),
        c('y', parent: 'x'),
      ]);
      expect(t.length, lessThanOrEqualTo(2));
      expect(t.map((x) => x.comment.id).toSet().length, t.length,
          reason: 'a comment must not render twice');
    });

    test('collapsing hides the subtree but keeps the count', () {
      final all = [
        c('a'),
        c('a1', parent: 'a'),
        c('a1x', parent: 'a1'),
        c('b'),
      ];
      final open = ForumThread.build(all, sort: ForumCommentSort.oldest);
      expect(open.length, 4);

      final folded = ForumThread.build(all,
          sort: ForumCommentSort.oldest, collapsed: {'a'});
      expect([for (final x in folded) x.comment.id], ['a', 'b']);
      expect(folded.first.collapsed, isTrue);
      expect(folded.first.descendants, 2,
          reason: 'the fold has to say how much it is hiding');
    });

    test('sort orders every level, not just the top', () {
      final all = [
        c('low', score: 1, day: 1),
        c('high', score: 9, day: 2),
        c('lowreply', parent: 'high', score: 0, day: 3),
        c('highreply', parent: 'high', score: 5, day: 4),
      ];
      expect([for (final x in ForumThread.build(all)) x.comment.id],
          ['high', 'highreply', 'lowreply', 'low']);
      expect(
          [
            for (final x
                in ForumThread.build(all, sort: ForumCommentSort.newest))
              x.comment.id
          ].first,
          'high',
          reason: 'newest root first');
      expect(
          [
            for (final x
                in ForumThread.build(all, sort: ForumCommentSort.oldest))
              x.comment.id
          ].first,
          'low');
    });

    test('a comment vote is a toggle, and needs a number', () async {
      PublicForumStore.instance.resetForTest();
      addTearDown(PublicForumStore.instance.resetForTest);
      final sent = <(String, int)>[];
      PublicForumStore.debugCommentVoteOverride =
          (id, dir) async => sent.add((id, dir));

      await PublicForumStore.instance.voteComment('c1', 1);
      await PublicForumStore.instance.voteComment('c1', 0);
      expect(sent, [('c1', 1), ('c1', 0)]);

      // Taking a vote back is a DELETE, not a stored zero — the schema has a
      // check constraint that only allows 1 and -1.
      final sql =
          File('docs/public_forum_comment_votes.sql').readAsStringSync();
      expect(sql, contains("dir in (-1, 1)"));
      // Who voted is nobody's business: no cross-user read, and the tally is
      // a definer function so a score can exist without exposing casters.
      expect(sql, contains('security definer'));
      expect(
          sql,
          contains('revoke select on table '
              'public.public_forum_comment_votes\n  from anon, authenticated;'));
      // The comments view must stay phone-free, like every other public read.
      // Pinned on the SELECTED column (the view qualifies every column with
      // `c.`), not the bare word — which appears in the prose above it
      // explaining that it is withheld.
      expect(sql.contains('c.author_phone'), isFalse);
      // Supabase grants EXECUTE on new functions to anon/authenticated by
      // default and revoking PUBLIC does not undo it, so the grant is named.
      expect(
          sql,
          contains('grant execute on function '
              'public.public_forum_comment_score(text)'));
    });

    test('the client survives the migration not being run', () {
      // The score lives on a view this migration adds. Asking the plain table
      // for it would 42703 and leave the post with NO comments at all, which
      // is far worse than comments without scores.
      final src = File('lib/state/public_forum_store.dart').readAsStringSync();
      expect(src, contains('public_forum_comments_v'));
      expect(src, contains("from('public_forum_comments')"),
          reason: 'the fallback path must remain');
    });
  });

  group('The public forum, outside any server', () {
    setUp(() {
      SharedPreferences.setMockInitialValues({});
      PublicForumStore.instance.resetForTest();
      // The forum reuses the public feed's moderation speed bump; make it a
      // pass-through so a post isn't refused by an offline screener in a test.
      PublicFeedStore.debugScreenOverride = (_) async => null;
      Session.instance.signInForTest(username: 'alice', name: 'Alice');
    });
    tearDown(() {
      PublicForumStore.instance.resetForTest();
      PublicFeedStore.debugScreenOverride = null;
      Session.instance.resetForTest();
      AppState.resetForTest();
    });

    test('a new post rides the store, lands on top, upvoted by its author',
        () async {
      PublicForumPost? sent;
      PublicForumStore.debugPostOverride = (p) async => sent = p;
      final post = await PublicForumStore.instance
          .post(title: 'Best pizza in town?', body: 'Go.', tag: 'Question');
      expect(sent, isNotNull);
      expect(post.title, 'Best pizza in town?');
      expect(post.tag, 'Question');
      // Reddit-style: a fresh post reads as +1, the author's own vote.
      expect(post.score, 1);
      expect(post.myVote, 1);
      expect(post.mine, isTrue);
      expect(PublicForumStore.instance.posts.first.id, post.id);
    });

    test('a title is required', () async {
      PublicForumStore.debugPostOverride = (_) async {};
      expect(
        () => PublicForumStore.instance.post(title: '   '),
        throwsA(isA<PublicForumError>()),
      );
    });

    test('voting moves the score, and pressing it again takes it back',
        () async {
      final now = DateTime.now();
      PublicForumStore.instance.debugSetPosts([
        PublicForumPost(
            id: 'fp_x',
            authorUsername: 'bob',
            authorName: 'Bob',
            title: 'A thing',
            createdAt: now,
            score: 5,
            myVote: 0),
      ]);
      final votes = <(String, int)>[];
      PublicForumStore.debugVoteOverride =
          (id, dir) async => votes.add((id, dir));

      await PublicForumStore.instance.vote('fp_x', 1);
      var p = PublicForumStore.instance.posts.first;
      expect(p.score, 6);
      expect(p.myVote, 1);

      // Taking it back: the screen sends 0, the score returns.
      await PublicForumStore.instance.vote('fp_x', 0);
      p = PublicForumStore.instance.posts.first;
      expect(p.score, 5);
      expect(p.myVote, 0);
      expect(votes, [('fp_x', 1), ('fp_x', 0)]);
    });

    PublicForumPost seedOne() {
      final p = PublicForumPost(
          id: 'fp_x',
          authorUsername: 'bob',
          authorName: 'Bob',
          title: 'A thing',
          createdAt: DateTime.now(),
          score: 5);
      PublicForumStore.instance.debugSetPosts([p]);
      return p;
    }

    test('a lapsed server session says so, and never asks for a retry',
        () async {
      // Every forum write is granted `to authenticated`, so a device whose
      // Supabase session has gone reaches Postgres as `anon` and is told
      // "permission denied for table" before RLS is even consulted. That
      // used to surface as "Couldn't reach the forum. Try again." — the
      // network named, and a retry that could never work. READS keep working
      // the whole time (they are served to anon by design), which is why the
      // board looks perfectly healthy around the failure.
      addTearDown(PublicForumStore.instance.resetForTest);
      seedOne();
      var sent = false;
      PublicForumStore.debugVoteOverride = (_, __) async => sent = true;
      PublicForumStore.debugPostOverride = (_) async => sent = true;
      PublicForumStore.debugCommentOverride = (_, __) async => sent = true;
      PublicForumStore.debugSignedOutOverride = true;

      for (final call in <Future<void> Function()>[
        () => PublicForumStore.instance.vote('fp_x', 1),
        () async {
          await PublicForumStore.instance.post(title: 'Hi');
        },
        () async {
          await PublicForumStore.instance.comment('fp_x', 'Hi');
        },
      ]) {
        await expectLater(
            call(),
            throwsA(isA<PublicForumError>()
                .having((e) => e.message, 'message', contains('signed out'))));
      }
      expect(sent, isFalse, reason: 'a doomed write still went to the server');
      // And the optimistic vote is not left applied to a write that never
      // happened.
      expect(PublicForumStore.instance.posts.first.myVote, 0);
      expect(PublicForumStore.instance.posts.first.score, 5);
    });

    test('the forum names the fault instead of blaming the network', () async {
      addTearDown(PublicForumStore.instance.resetForTest);
      seedOne();
      // Signed in — so nothing below is the signed-out branch.
      PublicForumStore.debugSignedOutOverride = false;

      Future<void> expectMessage(String thrown, Matcher says) async {
        PublicForumStore.debugVoteOverride =
            (_, __) async => throw Exception(thrown);
        await expectLater(
            PublicForumStore.instance.vote('fp_x', 1),
            throwsA(
                isA<PublicForumError>().having((e) => e.message, 'msg', says)));
      }

      await expectMessage(
          'PostgrestException(message: relation "public.public_forum_votes" '
          'does not exist, code: 42P01)',
          contains('isn\'t set up on the server yet'));
      // A missing GRANT is not the account's fault, and this test used to say
      // it was. Down-votes proved it: `on conflict (post_id, voter_phone)`
      // needs SELECT on the conflict target, that column was deliberately
      // withheld, and every downvote came back "permission denied" — which
      // the app reported as "your account can't post right now", sending you
      // to look at your own standing for a schema bug.
      await expectMessage('permission denied for table public_forum_votes',
          contains('isn\'t set up correctly on the server'));
      await expectMessage(
          'new row violates row-level security policy for table '
          '"public_forum_votes"',
          contains('can\'t post right now'));
      // Only a real transport failure keeps the sentence that asks for one.
      await expectMessage(
          'ClientException: Connection closed before full header was received',
          contains('Try again'));
    });

    test('a comment goes through the store and bumps the post count', () async {
      PublicForumStore.instance.debugSetPosts([
        PublicForumPost(
            id: 'fp_c',
            authorUsername: 'bob',
            authorName: 'Bob',
            title: 'Talk to me',
            createdAt: DateTime.now(),
            commentCount: 0),
      ]);
      PublicForumComment? sent;
      PublicForumStore.debugCommentOverride = (_, c) async => sent = c;
      final c = await PublicForumStore.instance.comment('fp_c', 'well said');
      expect(sent, isNotNull);
      expect(c.body, 'well said');
      expect(c.mine, isTrue);
      expect(PublicForumStore.instance.posts.first.commentCount, 1);
    });

    test('a name-only account is refused — posting the forum needs a number',
        () async {
      Session.instance
          .signInForTest(phone: AccountCode.mint(), username: 'nameonly');
      expect(Session.instance.isNumberless, isTrue);
      PublicForumStore.debugPostOverride = (_) async {};
      await expectLater(
        () => PublicForumStore.instance.post(title: 'hello'),
        throwsA(isA<PublicForumError>()),
      );
    });

    testWidgets('the forum screen offers a top-right composer, like the feed',
        (tester) async {
      PublicForumStore.instance.debugSetPosts([
        PublicForumPost(
            id: 'fp_ui',
            authorUsername: 'bob',
            authorName: 'Bob',
            title: 'A public forum post',
            body: 'Body here',
            createdAt: DateTime.now(),
            score: 3),
      ]);
      await tester.pumpWidget(const MaterialApp(home: PublicForumScreen()));
      await tester.pump();
      expect(find.text('Forum'), findsOneWidget);
      expect(find.text('A public forum post'), findsOneWidget);
      // Compose lives top-right — the edit pencil, no FAB, matching the feeds.
      expect(find.byTooltip('New post'), findsOneWidget);
      expect(find.byType(FloatingActionButton), findsNothing);
    });

    test('the forum is a public surface — it does not seal or ride crypto', () {
      final src = File('lib/state/public_forum_store.dart').readAsStringSync();
      // A public board is plaintext by definition (see the SQL header); it must
      // not pretend otherwise by pulling in the pairwise/community crypto.
      expect(src.contains('double_ratchet'), isFalse);
      expect(src.contains('sender_key'), isFalse);
      expect(src.contains('sealContent'), isFalse);
    });

    testWidgets('sort is top-right and the old chip row is gone',
