  group('Chat folders, Telegram-style', () {
    setUp(() {
      SharedPreferences.setMockInitialValues({});
      ChatFolders.instance.resetForTest();
    });
    tearDown(ChatFolders.instance.resetForTest);

    test('a folder holds the chats you put in it, and nothing else', () async {
      final f = ChatFolders.instance;
      await f.load();
      expect(f.isEmpty, isTrue);

      expect(await f.create('Work'), isTrue);
      expect(await f.create('Family'), isTrue);
      // Order is creation order, which is the tab order.
      expect(f.folders, ['Work', 'Family']);
      // A duplicate name would make two identical tabs.
      expect(await f.create('Work'), isFalse);
      // As would an empty one.
      expect(await f.create('   '), isFalse);

      await f.setInFolder('Work', 'chat_a', true);
      await f.setInFolder('Work', 'chat_b', true);
      await f.setInFolder('Family', 'chat_b', true);
      expect(f.idsIn('Work'), ['chat_a', 'chat_b']);
      // A chat can sit in more than one folder — they are views, not boxes.
      expect(f.foldersFor('chat_b'), ['Work', 'Family']);
      expect(f.foldersFor('chat_a'), ['Work']);

      await f.setInFolder('Work', 'chat_a', false);
      expect(f.contains('Work', 'chat_a'), isFalse);
    });

    test('renaming keeps the tab where it was', () async {
      final f = ChatFolders.instance;
      await f.load();
      await f.create('A');
      await f.create('B');
      await f.create('C');
      await f.setInFolder('B', 'chat_1', true);

      expect(await f.rename('B', 'Beta'), isTrue);
      // Position preserved: a remove-and-re-add would send it to the end,
      // so fixing a typo would move somebody's tab.
      expect(f.folders, ['A', 'Beta', 'C']);
      expect(f.idsIn('Beta'), ['chat_1']);
      // Onto a name already taken is refused rather than merging two folders.
      expect(await f.rename('Beta', 'A'), isFalse);
      expect(f.folders, ['A', 'Beta', 'C']);
    });

    test('reorder takes the index after the lift', () async {
      final f = ChatFolders.instance;
      await f.load();
      for (final n in ['A', 'B', 'C']) {
        await f.create(n);
      }
      await f.reorder(0, 2);
      expect(f.folders, ['B', 'C', 'A']);
      // Out of range moves nothing rather than throwing.
      await f.reorder(9, 0);
      expect(f.folders, ['B', 'C', 'A']);
    });

    test('deleting a folder keeps the chats; deleting a chat empties the tab',
        () async {
      final f = ChatFolders.instance;
      await f.load();
      await f.create('Work');
      await f.setInFolder('Work', 'chat_a', true);

      await f.delete('Work');
      expect(f.folders, isEmpty);

      // And the other direction: a conversation that is gone must stop being
      // counted, or a tab shows a number nothing can open.
      await f.create('Work');
      await f.setInFolder('Work', 'chat_a', true);
      await f.setInFolder('Work', 'chat_b', true);
      await f.forget('chat_a');
      expect(f.idsIn('Work'), ['chat_b']);
    });

    test('folders survive a reload, and there is a ceiling', () async {
      final f = ChatFolders.instance;
      await f.load();
      await f.create('Work');
      await f.setInFolder('Work', 'chat_a', true);

      // A fresh load reads the same folders back off disk.
      ChatFolders.instance.resetForTest();
      await f.load();
      expect(f.folders, ['Work']);
      expect(f.idsIn('Work'), ['chat_a']);

      while (!f.isFull) {
        expect(await f.create('f${f.folders.length}'), isTrue);
      }
      expect(f.folders.length, ChatFolders.maxFolders);
      // Past the ceiling the strip stops being a strip.
      expect(await f.create('one more'), isFalse);
    });

    test('folders are account data, so a switch must not carry them over', () {
      // The chats a folder names belong to ONE account; leaving the tabs in
      // place for the next one would point them at conversations that
      // account cannot see.
      final wipe = File('lib/state/account_wipe.dart').readAsStringSync();
      expect(wipe, contains('chat_folders.dart'));
      expect(wipe, contains('ChatFolders.instance.resetForTest()'));
      expect(wipe, contains('ChatFolders.instance.load'));
      // And they are local: no table, no column, no upload.
      final src = File('lib/state/chat_folders.dart').readAsStringSync();
      for (final banned in [
        'supabase',
        'Supabase',
        'http',
        'functions.invoke'
      ]) {
        expect(src.contains(banned), isFalse,
            reason: 'which conversations somebody groups is theirs alone');
      }
    });

    group('Saving photos and videos', () {
      tearDown(() => MediaSaver.debugSaveOverride = null);

      test('each outcome gets its own sentence', () {
        // One "Couldn't save" for every failure sends somebody to the wrong
        // place: refused is a Settings trip, no-library is a download, and
        // still-loading is worth waiting out.
        expect(MediaSaver.message(MediaSaveResult.saved, video: false),
            contains('library'));
        expect(MediaSaver.message(MediaSaveResult.saved, video: true),
            startsWith('Video'));
        expect(MediaSaver.message(MediaSaveResult.downloaded, video: false),
            contains('downloaded'));
        expect(MediaSaver.message(MediaSaveResult.denied, video: false),
            contains('Settings'));
        expect(MediaSaver.message(MediaSaveResult.empty, video: false),
            contains('loading'));
        expect(MediaSaver.message(MediaSaveResult.failed, video: true),
            contains("Couldn't"));
      });

      test('the saver never decides WHETHER something may be saved', () {
        // Deliberate: the two refusals are the callers' business, so a
        // surface added later has to make the choice itself rather than
        // inheriting a permissive default from here.
        final src = File('lib/util/media_saver.dart').readAsStringSync();
        expect(src.contains('viewOnce'), isFalse);
        expect(src.contains('protected'), isFalse);
        // And every call site of the viewer states its answer out loud.
        for (final f in [
          'lib/screens/chat_screen.dart',
          'lib/screens/media_gallery_screen.dart',
          'lib/screens/communities.dart',
        ]) {
          expect(File(f).readAsStringSync().contains('canSave:'), isTrue,
              reason: '$f opens the viewer and must say whether Save applies');
        }
      });

      testWidgets('a view-once photo and a protected chat offer no Save',
          (t) async {
        // A Save that appears and then apologises is a worse promise than one
        // that was never offered, so the button is not drawn at all.
        for (final message in [
          Message(
              id: 'v1',
              text: '',
              time: DateTime(2026, 8, 14),
              isMe: false,
              imageUrl: 'https://example.test/a.jpg',
              viewOnce: true),
          Message(
              id: 'p1',
              text: '',
              time: DateTime(2026, 8, 14),
              isMe: false,
              imageUrl: 'https://example.test/a.jpg',
              protected: true),
        ]) {
          await t.pumpWidget(MaterialApp(
            home: ImageViewScreen(
              message: message,
              senderName: 'Sam',
              // The chat decides; these mirror what chat_screen passes.
              canSave: !message.viewOnce && !message.protected,
              onToggleLike: () {},
            ),
          ));
          await t.pumpAndSettle();
          expect(find.text('Save'), findsNothing, reason: message.id);
        }
      });

      testWidgets('an ordinary photo saves, and says where it went', (t) async {
        var asked = 0;
        MediaSaver.debugSaveOverride = (bytes, name) async {
          asked++;
          return MediaSaveResult.saved;
        };
        await t.pumpWidget(MaterialApp(
          home: ImageViewScreen(
            message: Message(
              id: 'ok1',
              text: '',
              time: DateTime(2026, 8, 14),
              isMe: false,
              // A data URI, so nothing is fetched over the network in a test.
              imageUrl:
                  'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==',
            ),
            senderName: 'Sam',
            canSave: true,
            onToggleLike: () {},
          ),
        ));
        await t.pumpAndSettle();
        expect(find.text('Save'), findsOneWidget);
        await t.tap(find.text('Save'));
        await t.pumpAndSettle();
        expect(asked, 1);
        expect(find.textContaining('saved to your library'), findsOneWidget);
      });
    });

    testWidgets('every home tab can be scrolled past the floating bar',
        (t) async {
      // Reported on the You tab: "can't scroll any further down to view the
      // last post". The bar FLOATS (home sets extendBody), so a tab that does
      // not pad itself by HomeNavBar.clearance ends its last row underneath
      // the glass with nothing left to scroll — the debt the floating bar
      // came with. Three tabs were fixed when it started floating; the You
      // tab is a profile screen shared with a pushed route, so it was not on
      // that list, and the newsfeed still carried a hardcoded 96 that is
      // SHORT of the bar on a home-indicator iPhone.
      //
      // Asserted as the SOURCE reading the measured clearance rather than by
      // scrolling each tab, because the failure is "the last pixel is under
      // the glass" — which a widget test at an arbitrary viewport cannot see,
      // and which a wrong constant passes just as happily as a right one.
      for (final (file, what) in [
        ('lib/tabs/chats_tab.dart', 'Chats'),
        ('lib/tabs/calls_tab.dart', 'Calls'),
        ('lib/tabs/activity_tab.dart', 'Notifications'),
        ('lib/screens/public_feed_screen.dart', 'Newsfeed and You'),
        ('lib/screens/communities.dart', 'Servers'),
        ('lib/screens/ai_chat_screen.dart', 'Okay AI'),
      ]) {
        final src = File(file).readAsStringSync();
        expect(
            src.contains('HomeNavBar.clearance(context)') ||
                src.contains('AppBottomNavBar.overlayHeightFor(context)'),
            isTrue,
            reason: '$what must clear the floating bar by measuring it');
        // And not by guessing: the constants that used to stand in for it
        // were all short of the real height.
        expect(src.contains('bottom: 96)'), isFalse,
            reason: '$what still guesses the bar height');
      }

      // The You tab needs its own pin: it shares a file with the newsfeed,
      // so a blanket "this file mentions clearance" would pass on the
      // newsfeed's line alone while the profile stayed broken — which is
      // exactly the state this was reported in.
      final profile =
          File('lib/screens/public_feed_screen.dart').readAsStringSync();
      expect(
          profile.contains(
              'widget.embedded\n                        ? HomeNavBar.clearance(context)'),
          isTrue,
          reason: "the You tab's own tail must clear the bar, and only when "
              'embedded — pushed there is no bar to clear');
    });

    testWidgets('a chat row swipes both ways: right reads, left archives',
        (tester) async {
      // The shape every messaging app has. It used to swipe one way only,
      // and only to archive.
      final store = ChatStore.instance;
      final chat = store.chats.first;
      final name = chat.contact.name;
      store.markUnread(chat.id);
      expect(store.chats.first.unreadCount, greaterThan(0));

      await tester
          .pumpWidget(const MaterialApp(home: Scaffold(body: ChatsTab())));
      await tester.pumpAndSettle();

      // RIGHT marks it read — and the row STAYS, because the chat did not
      // leave the list. A dismissing animation here would say otherwise.
      await tester.drag(find.text(name).first, const Offset(320, 0));
      await tester.pumpAndSettle();
      expect(store.chats.firstWhere((c) => c.id == chat.id).unreadCount, 0);
      expect(find.text(name), findsWidgets, reason: 'a read chat is still here');

      // Swiping right again puts it back to unread: the label and the action
      // follow the row's own state rather than being fixed to the side.
      await tester.drag(find.text(name).first, const Offset(320, 0));
      await tester.pumpAndSettle();
      expect(store.chats.firstWhere((c) => c.id == chat.id).unreadCount,
          greaterThan(0));

      // LEFT archives, and the row really does leave.
      await tester.drag(find.text(name).first, const Offset(-500, 0));
      await tester.pumpAndSettle();
      expect(store.archivedChats.map((c) => c.id), contains(chat.id));
      expect(store.chats.map((c) => c.id), isNot(contains(chat.id)));
      // With an undo, because a swipe is easy to make by accident.
      expect(find.text('Undo'), findsOneWidget);
    });

    testWidgets('the archive swipes back the way it was swiped in',
        (tester) async {
      // The gap this closed: a chat could be archived with a swipe and only
      // UNarchived through a long-press menu.
      final store = ChatStore.instance;
      final chat = store.chats.first;
      final name = chat.contact.name;
      store.setArchived(chat.id, true);

      await tester
          .pumpWidget(const MaterialApp(home: ArchivedChatsScreen()));
      await tester.pumpAndSettle();
      expect(find.text(name), findsWidgets);

      await tester.drag(find.text(name).first, const Offset(500, 0));
      await tester.pumpAndSettle();
      expect(store.archivedChats.map((c) => c.id), isNot(contains(chat.id)));
      expect(store.chats.map((c) => c.id), contains(chat.id));
      expect(find.text('Undo'), findsOneWidget);
    });

    test('a reversible swipe is easier to reach than a destructive one', () {
      // Snapping back costs a mistaken swipe one tap to undo; letting a row
      // fly out of the list on a half-gesture is the thing people complain
      // about. So the thresholds are deliberately different, and this pins
      // the ORDER rather than the two numbers.
      expect(SwipeActions.actThreshold,
          lessThan(SwipeActions.dismissThreshold));
    });

    testWidgets('a row with no actions is not wrapped in a dead gesture',
        (tester) async {
      await tester.pumpWidget(const MaterialApp(
        home: Scaffold(
          body: SwipeActions(
              itemKey: ValueKey('none'), child: Text('plain row')),
        ),
      ));
      await tester.pumpAndSettle();
      // A gesture that starts and goes nowhere is worse than no gesture.
      expect(find.byType(Dismissible), findsNothing);
      expect(find.text('plain row'), findsOneWidget);
    });

    testWidgets('the folder tab filters the chat list', (tester) async {
      final f = ChatFolders.instance;
      await f.load();
      await f.create('Work');

      final store = ChatStore.instance;
      final ids = store.chats.map((c) => c.id).toList();
      expect(ids.length, greaterThan(1),
          reason: 'the seeded list needs at least two chats to filter');
      await f.setInFolder('Work', ids.first, true);
      final kept = store.chats.first.contact.name;
      final dropped = store.chats[1].contact.name;

      await tester
          .pumpWidget(const MaterialApp(home: Scaffold(body: ChatsTab())));
      await tester.pumpAndSettle();
      // Both chats are there under All.
      expect(find.text(kept), findsWidgets);
      expect(find.text(dropped), findsWidgets);

      await tester.tap(find.widgetWithText(ChoiceChip, 'Work'));
      await tester.pumpAndSettle();
      expect(find.text(kept), findsWidgets);
      expect(find.text(dropped), findsNothing,
          reason: 'a folder tab shows only what was filed in it');
    });
  });

  group('Message sounds (default + per-chat)', () {
    setUp(() {
      SharedPreferences.setMockInitialValues({});
      MessageSoundStore.instance.resetForTest();
    });
    tearDown(() {
      MessageSoundStore.instance.resetForTest();
      MessageSoundStore.debugPlayOverride = null;
    });

    test('a chat with no override follows the app-wide default', () async {
      final store = MessageSoundStore.instance;
      await store.load();
      expect(store.defaultSound, MessageSound.chirp);
      expect(store.soundFor('chat_a'), MessageSound.chirp);
      expect(store.overrideFor('chat_a'), isNull);

      await store.setDefault(MessageSound.ringBackBeat);
      expect(store.soundFor('chat_a'), MessageSound.ringBackBeat,
          reason: 'a chat with no override moves with the default');
    });

    test('a per-chat override survives a reload and beats the default',
        () async {
      final store = MessageSoundStore.instance;
      await store.load();
      await store.setDefault(MessageSound.vibrate);
      await store.setForChat('chat_a', MessageSound.silent);
      expect(store.soundFor('chat_a'), MessageSound.silent);
      expect(store.soundFor('chat_b'), MessageSound.vibrate,
          reason: 'the override is per-chat, not global');

      // A fresh load (a relaunch, or an account switch's reload) must read
      // both back from disk, not just remember them in memory.
      store.resetForTest();
      await store.load();
      expect(store.defaultSound, MessageSound.vibrate);
      expect(store.soundFor('chat_a'), MessageSound.silent);
      expect(store.soundFor('chat_b'), MessageSound.vibrate);
    });

    test('clearing an override falls back to the default again', () async {
      final store = MessageSoundStore.instance;
      await store.load();
      await store.setForChat('chat_a', MessageSound.ringBackBeat);
      expect(store.overrideFor('chat_a'), MessageSound.ringBackBeat);
      await store.setForChat('chat_a', null);
      expect(store.overrideFor('chat_a'), isNull);
      expect(store.soundFor('chat_a'), store.defaultSound);
    });

    test('forget drops an orphaned override, deleteChat calls it', () async {
      final store = MessageSoundStore.instance;
      await store.load();
      await store.setForChat('chat_a', MessageSound.silent);
      ChatStore.instance.hydrate(const {'chats': []});
      addTearDown(ChatStore.instance.reset);
      ChatStore.instance.upsert(const Chat(
        id: 'chat_a',
        contact: AppUser(
            id: '+1 555 0111',
            name: 'Gone',
            avatarColor: '#111111',
            phone: '+1 555 0111'),
        messages: [],
      ));
      ChatStore.instance.deleteChat('chat_a');
      expect(store.overrideFor('chat_a'), isNull);
    });

    test('the silent choice never reaches the native side', () async {
      var played = false;
      MessageSoundStore.debugPlayOverride = (_) => played = true;
      await MessageSoundStore.instance.previewSound(MessageSound.silent);
      expect(played, isFalse);
      await MessageSoundStore.instance.previewSound(MessageSound.chirp);
      expect(played, isTrue);
    });

    testWidgets(
        'an incoming message sounds once while the chat is open, and only '
        'for messages that arrive during the visit', (tester) async {
      SharedPreferences.setMockInitialValues({});
      ChatStore.instance.reset();
      Session.instance.signInForTest();
      MessageSoundStore.instance.resetForTest();
      await MessageSoundStore.instance.load();
      final played = <MessageSound>[];
      MessageSoundStore.debugPlayOverride = played.add;
      addTearDown(() => MessageSoundStore.debugPlayOverride = null);

      const contact = AppUser(
          id: '+1 555 0177',
          name: 'Sound Test',
          avatarColor: '#64B5F6',
          phone: '+1 555 0177');
      final t = DateTime(2024, 1, 1);
      ChatStore.instance.upsert(Chat(
        id: 'chat_snd',
        contact: contact,
        // Pre-existing history must not sound on open — only what arrives
        // during the visit.
        messages: [
          Message(id: 'old1', text: 'already here', time: t, isMe: false)
        ],
      ));
      await tester.pumpWidget(MaterialApp(
          home: ChatScreen(chat: ChatStore.instance.chatById('chat_snd')!)));
      await tester.pumpAndSettle();
      expect(played, isEmpty,
          reason: 'opening a chat with unread history sounds nothing yet');

      ChatStore.instance.addMessage(
          'chat_snd', Message(id: 'new1', text: 'hi', time: t, isMe: false));
      await tester.pump();
      expect(played, [MessageSound.chirp]);

      // A second message plays once more, not twice for the same arrival.
      ChatStore.instance.addMessage('chat_snd',
          Message(id: 'new2', text: 'hi again', time: t, isMe: false));
      await tester.pump();
      expect(played, [MessageSound.chirp, MessageSound.chirp]);

      // Our OWN reply must never sound.
      ChatStore.instance.addMessage(
          'chat_snd', Message(id: 'mine1', text: 'ok', time: t, isMe: true));
      await tester.pump();
      expect(played.length, 2, reason: 'an outgoing message never sounds');
    });

    testWidgets('a picked wallpaper is visibly picked, on a PALE tile in dark '
        'mode', (tester) async {
      // Reported as "I change the wallpaper, it changes, but I have no visual
      // feedback of it being changed". It really was invisible: both marks —
      // the tick and the 3-point selection border — were drawn in
      // AppColors.accentOn, a colour chosen against the app BACKGROUND, which
      // is near-white in dark mode. Half the wallpapers on offer are pale, so
      // picking one drew a white tick on a cream tile and a white border
      // INSIDE that same cream tile. Third instance of the "a bubble's
      // contents take the BUBBLE's colours" rule.
      SharedPreferences.setMockInitialValues({});
      ChatStore.instance.reset();
      await tester.pumpWidget(MaterialApp(
        theme: ThemeData.dark(),
        home: const WallpaperScreen(chatId: 'chat_wp'),
      ));
      await tester.pumpAndSettle();

      // The palest wallpaper on offer — the exact case that was invisible.
      const pale = Color(0xFFEFEAE2);
      ChatStore.instance.setWallpaper('chat_wp', pale);
      await tester.pumpAndSettle();

      final tick = find.byIcon(Icons.check);
      expect(tick, findsOneWidget);
      // Drawn against the SWATCH, not the app: on a pale tile the mark has to
      // be dark. A near-white one is the bug.
      final disc = tester.widget<Container>(find
          .ancestor(of: tick, matching: find.byType(Container))
          .first);
      final discColour = (disc.decoration as BoxDecoration).color!;
      expect(discColour.computeLuminance(), lessThan(0.5),
          reason: 'the mark on a pale swatch must be dark, not the app accent');
    });

    testWidgets("a chat's Default tile paints the app-wide wallpaper, not "
        'black', (tester) async {
      // The other half of the same report — "it still shows the black is the
      // wallpaper when it's not". In ONE chat, "Default" does not mean the
      // theme background, it means "follow the app-wide wallpaper"; the tile
      // painted scaffoldBackgroundColor regardless, so somebody who had
      // already set a wallpaper was told their default was black.
      SharedPreferences.setMockInitialValues({});
      ChatStore.instance.reset();
      const global = Color(0xFF14342B);
      final prev = AppState.chatWallpaper.value;
      addTearDown(() => AppState.chatWallpaper.value = prev);
      AppState.chatWallpaper.value = global;

      await tester.pumpWidget(MaterialApp(
        theme: ThemeData.dark(),
        home: const WallpaperScreen(chatId: 'chat_wp2'),
      ));
      await tester.pumpAndSettle();

      final label = find.text('Default');
      expect(label, findsOneWidget);
      final tile = tester.widget<Container>(
          find.ancestor(of: label, matching: find.byType(Container)).first);
      expect((tile.decoration as BoxDecoration).color, global);

      // And it is said in words too, since a tick is easy to miss.
      expect(find.text('Following the app-wide wallpaper.'), findsOneWidget);
    });

    testWidgets('the wallpaper screen picks and previews a chat sound',
        (tester) async {
      SharedPreferences.setMockInitialValues({});
      MessageSoundStore.instance.resetForTest();
      await MessageSoundStore.instance.load();
      var previewed = 0;
      MessageSoundStore.debugPlayOverride = (_) => previewed++;
      addTearDown(() => MessageSoundStore.debugPlayOverride = null);

      await tester.pumpWidget(
          const MaterialApp(home: WallpaperScreen(chatId: 'chat_x')));
      await tester.pumpAndSettle();
      // The sound section sits below the wallpaper grid — a ListView only
      // builds what's in or near the viewport, so it isn't in the tree yet.
      final defaultRow = find.textContaining('Default (');
      await tester.scrollUntilVisible(defaultRow, 250,
          scrollable: find.byType(Scrollable).first);
      await tester.pumpAndSettle();
      // The per-chat screen offers a way back to following the default.
      expect(defaultRow, findsOneWidget);

      final preview = find.byIcon(Icons.play_arrow).first;
      await tester.scrollUntilVisible(preview, 250,
          scrollable: find.byType(Scrollable).first);
      await tester.tap(preview);
      await tester.pump();
      expect(previewed, 1);

      final silentRow = find.text(MessageSound.silent.label);
      await tester.scrollUntilVisible(silentRow, 250,
          scrollable: find.byType(Scrollable).first);
      await tester.tap(silentRow);
      await tester.pumpAndSettle();
      expect(MessageSoundStore.instance.overrideFor('chat_x'),
          MessageSound.silent);
