      expect(wallet, contains('GetPaidScreen('));
      // Reachable from BOTH wallet states: the onboard card, and after Stripe
      // is finished — bank set up is not every rail set up.
      expect(wallet, contains('Other ways to get paid'));
      expect(wallet, contains('cashReady: true'));

      // A tip jar the app never touches: no purchase, no custody, no cut.
      final src = File('lib/screens/get_paid_screen.dart').readAsStringSync();
      for (final banned in const ['StorePurchases', 'AppleIap']) {
        expect(src.contains(banned), isFalse,
            reason: 'a spark is not an in-app purchase');
      }
      expect(src, contains('takes no cut'));
      // And the limit that follows from not holding the money.
      expect(src, contains('cannot tell you when one arrives'));
    });
  });

  group('A throwaway inbox is not a verification', () {
    test('the domain is read off the address, however it is written', () {
      expect(DisposableEmails.domainOf('a@Mailinator.COM'), 'mailinator.com');
      // A trailing dot is a legal fully-qualified host and must not slip past
      // a set lookup on the bare domain.
      expect(DisposableEmails.domainOf('a@mailinator.com.'), 'mailinator.com');
      expect(DisposableEmails.domainOf('  a@example.org '), 'example.org');
      // An address with a '@' in the local part resolves on the LAST one.
      expect(DisposableEmails.domainOf('a@b@guerrillamail.com'),
          'guerrillamail.com');
      expect(DisposableEmails.domainOf('no-at-sign'), '');
      expect(DisposableEmails.domainOf('trailing@'), '');
    });

    test('known throwaway services are refused, subdomains included', () {
      for (final bad in const [
        'spammer@mailinator.com',
        'x@guerrillamail.com',
        'x@sharklasers.com',
        'x@10minutemail.com',
        'x@temp-mail.org',
        'x@yopmail.com',
        'x@trashmail.com',
        'x@getnada.com',
        'x@maildrop.cc',
        'x@dayrep.com',
      ]) {
        expect(DisposableEmails.isDisposable(bad), isTrue,
            reason: 'let "$bad" through');
        expect(DisposableEmails.reason(bad), isNotNull);
      }
      // Several of these hand out unlimited subdomains, so an exact-match
      // set lookup would be trivially sidestepped.
      expect(
          DisposableEmails.isDisposable('x@anything.mailinator.com'), isTrue);
      expect(DisposableEmails.isDisposable('x@a.b.mailinator.com'), isTrue);
      // But a domain that merely ENDS with the letters is a different domain.
      expect(DisposableEmails.isDisposable('x@notmailinator.example.com'),
          isFalse);
      expect(DisposableEmails.isDisposable('x@mymailinator.com'), isFalse);
    });

    test('privacy forwarding aliases are deliberately allowed', () {
      // The line is ephemeral-public-inbox vs forwarding alias. These are
      // durable, belong to one identifiable person, are revocable by them,
      // and reach a real human — and blocking the first would break Sign in
      // with Apple. A privacy-first app must not punish somebody for
      // withholding their real address.
      for (final ok in const [
        'abc123@privaterelay.appleid.com',
        'someone@simplelogin.io',
        'someone@addy.io',
        'someone@anonaddy.me',
        'someone@duck.com',
        'someone@mozmail.com',
        'ada@gmail.com',
        'ada@outlook.com',
        'ada@proton.me',
        'ada@company.co.uk',
      ]) {
        expect(DisposableEmails.isDisposable(ok), isFalse,
            reason: 'refused "$ok", which is a real address');
        expect(DisposableEmails.reason(ok), isNull);
      }
    });

    test('the list carries no real mail provider by accident', () {
      // One bad entry locks somebody out of their own recovery address, which
      // is worse than letting a throwaway through.
      for (final real in const [
        'gmail.com',
        'googlemail.com',
        'outlook.com',
        'hotmail.com',
        'live.com',
        'msn.com',
        'yahoo.com',
        'ymail.com',
        'aol.com',
        'icloud.com',
        'me.com',
        'mac.com',
        'proton.me',
        'protonmail.com',
        'pm.me',
        'tutanota.com',
        'zoho.com',
        'fastmail.com',
        'gmx.com',
        'gmx.de',
        'web.de',
        'mail.com',
        'yandex.com',
        'qq.com',
        'privaterelay.appleid.com',
        'simplelogin.io',
        'addy.io',
        'anonaddy.me',
        'duck.com',
        'mozmail.com',
        'relay.firefox.com',
      ]) {
        expect(DisposableEmails.domains.contains(real), isFalse,
            reason: '$real is a real provider and must never be blocked');
      }
      // Entries are bare, lowercase hostnames — no '@', no scheme, no spaces.
      for (final d in DisposableEmails.domains) {
        expect(d, equals(d.toLowerCase()), reason: '$d is not lowercased');
        expect(d.contains('@'), isFalse, reason: '$d looks like an address');
        expect(d.contains('.'), isTrue, reason: '$d has no dot');
        expect(d.trim(), equals(d), reason: '$d has stray whitespace');
      }
    });

    test('a refused recovery email is not silently swallowed', () {
      // Six of the eight outcomes are refusals. two_step's setup used to
      // discard the answer, so a rejected address vanished behind "Two-step
      // verification turned on" and somebody walked away believing they had a
      // way back into their account.
      expect(EmailSaveResult.verificationSent.saved, isTrue);
      expect(EmailSaveResult.savedUnverified.saved, isTrue);
      expect(EmailSaveResult.verificationSent.shortRefusal, isNull);
      expect(EmailSaveResult.savedUnverified.shortRefusal, isNull);
      for (final refused in const [
        EmailSaveResult.invalid,
        EmailSaveResult.tooSoon,
        EmailSaveResult.banned,
        EmailSaveResult.disposable,
        EmailSaveResult.taken,
      ]) {
        expect(refused.saved, isFalse, reason: '$refused reads as saved');
        expect(refused.shortRefusal, isNotNull,
            reason: '$refused has nothing to tell the person');
      }

      // The answer is bound and reported, not discarded — the bug was a bare
      // `await ...setEmail(...)` statement whose result went nowhere.
      final src = File('lib/screens/two_step_screen.dart').readAsStringSync();
      expect(src, contains('await AccountEmail.instance.setEmail('));
      expect(src, contains('shortRefusal'));
      expect(
          src.contains('      await AccountEmail.instance.setEmail('), isFalse,
          reason: 'the result is thrown away again');
    });

    test('the refusal sits in the one funnel every email save passes', () {
      // Both the email screen and the two-step screen call setEmail, so the
      // check belongs there rather than beside either field.
      final src = File('lib/state/account_email.dart').readAsStringSync();
      expect(src, contains('DisposableEmails.isDisposable(email)'));
      expect(src, contains('EmailSaveResult.disposable'));
      // Refused locally, BEFORE the address is claimed or mailed — a
      // throwaway must not reach the point of being sent a confirmation.
      final atCheck = src.indexOf('DisposableEmails.isDisposable(email)');
      expect(atCheck, greaterThan(0));
      for (final later in const ['claimEmail(', '_requestVerification(']) {
        expect(src.indexOf(later), greaterThan(atCheck),
            reason: '$later runs before the disposable check');
      }
      expect(File('lib/screens/two_step_screen.dart').readAsStringSync(),
          contains('AccountEmail.instance.setEmail('));
      // And the person is told which of the refusals they hit.
      expect(File('lib/screens/account_email_screen.dart').readAsStringSync(),
          contains('EmailSaveResult.disposable'));
    });
  });

  group('One inbox, one account', () {
    test('plus tags and Gmail dots fold to the same mailbox', () {
      // Every one of these really arrives, so every one can be VERIFIED —
      // which is how a single Gmail account minted an unlimited supply of
      // "verified emails" and defeated the email leg of full verification.
      for (final alias in const [
        'you+1@gmail.com',
        'you+2@gmail.com',
        'you+anything.at.all@gmail.com',
        'y.o.u@gmail.com',
        'YOU@Gmail.com',
        '  you@gmail.com  ',
        'you@googlemail.com',
        'y.o.u+7@googlemail.com',
      ]) {
        expect(EmailIdentity.canonical(alias), 'you@gmail.com',
            reason: '"$alias" did not fold');
        expect(EmailIdentity.sameMailbox(alias, 'you@gmail.com'), isTrue);
      }
      // Other sub-addressing providers fold the tag but keep their dots:
      // outside Google, j.smith and jsmith are two different people.
      expect(
          EmailIdentity.canonical('ada+news@outlook.com'), 'ada@outlook.com');
      expect(EmailIdentity.canonical('ada+news@proton.me'), 'ada@proton.me');
      expect(EmailIdentity.canonical('a.b@outlook.com'), 'a.b@outlook.com');
      expect(EmailIdentity.canonical('a.b@proton.me'), 'a.b@proton.me');
    });

    test('an unknown domain is left exactly as written', () {
      // Sub-addressing is a convention, not a rule. Folding on a domain that
      // treats '+' as an ordinary character would collapse two DIFFERENT
      // people onto one address and lock the second out of their own
      // recovery route — worse than letting an alias through.
      expect(EmailIdentity.canonical('a+b@smallcompany.co.uk'),
          'a+b@smallcompany.co.uk');
      expect(EmailIdentity.canonical('j.smith@smallcompany.co.uk'),
          'j.smith@smallcompany.co.uk');
      expect(EmailIdentity.sameMailbox('a+b@example.org', 'a@example.org'),
          isFalse);
      // Yahoo is deliberately off the list — it does not do '+'
      // sub-addressing, so folding would canonicalize an undeliverable
      // address onto a real person's.
      expect(EmailIdentity.canonical('ada+x@yahoo.com'), 'ada+x@yahoo.com');
    });

    test('malformed input is returned, never guessed at', () {
      for (final odd in const ['', 'no-at-sign', 'trailing@', '@leading']) {
        expect(EmailIdentity.canonical(odd), odd.trim().toLowerCase(),
            reason: 'invented something for "$odd"');
      }
      // A local part that is ONLY a tag has no mailbox to work out.
      expect(EmailIdentity.canonical('+tag@gmail.com'), '+tag@gmail.com');
      // A trailing dot on the host is still the same host.
      expect(EmailIdentity.canonical('you+1@gmail.com.'), 'you@gmail.com');
    });

    test('the claim is written under the mailbox, and read under both', () {
      // Claiming the address AS WRITTEN is what let the same inbox be
      // claimed again tomorrow under a different tag.
      expect(AccountService.canonicalEmailHash('you+1@gmail.com'),
          AccountService.canonicalEmailHash('you@gmail.com'));
      expect(AccountService.canonicalEmailHash('you+1@gmail.com'),
          isNot(AccountService.emailHash('you+1@gmail.com')));
      // An address with nothing to fold hashes the same either way, which is
      // what lets the taken-check skip its second round trip.
      expect(AccountService.canonicalEmailHash('ada@example.org'),
          AccountService.emailHash('ada@example.org'));

      final src = File('lib/state/account_service.dart').readAsStringSync();
      expect(
          src,
          contains(
              "rpc('claim_email', params: {'h': canonicalEmailHash(email)})"));
      // Reads check BOTH: a claim written before canonicalization existed is
      // stored under the raw hash and would otherwise look free.
      expect(src, contains('if (raw != canonical) _emailHashTaken(raw)'));
    });
  });

  group('The directory stops handing out phone numbers', () {
    test('a browsing result is a person without a number', () {
      // find_people answers a PREFIX with handles and names and no phone
      // (docs/directory_phone_privacy.sql). This used to return null for
      // every such row, which would have emptied the search screen.
      final browsing = AccountService.debugRowToUser({
        'phone': '',
        'username': 'ada_l',
        'name': 'Ada',
        'verified': true,
      });
      expect(browsing, isNotNull);
      expect(browsing!.username, 'ada_l');
      expect(browsing.name, 'Ada');
      expect(browsing.verified, isTrue);
      // Keyed on the handle, which is unmistakably not a number — and is the
      // thing to resolve with when somebody actually opens the conversation.
      expect(browsing.id, '@ada_l');
      expect(browsing.phone, isEmpty);
      expect(browsing.avatarColor, isNotEmpty);

      // An exact handle still comes back with a number, because opening a
      // chat and signing in by username both need one.
      final exact = AccountService.debugRowToUser({
        'phone': '+15550100',
        'username': 'ada_l',
        'name': 'Ada',
      });
      expect(exact!.phone, '+15550100');
      expect(exact.id, '+15550100');

      // Neither a phone nor a handle is nothing to show or address.
      expect(
          AccountService.debugRowToUser(
              {'phone': '', 'username': '', 'name': 'Nobody'}),
          isNull);
    });

    test('nothing reads another account row straight off the table', () {
      final src = File('lib/state/account_service.dart').readAsStringSync();
      // Every cross-account question now goes through a definer function.
      for (final rpc in const [
        "rpc('username_status'",
        "rpc('find_people_by_hashes'",
        "rpc('is_on_app'",
        "rpc('username_for_phone'",
      ]) {
        expect(src, contains(rpc), reason: 'missing $rpc');
      }
      // The table fallbacks are GONE, not merely unused: a select on the
      // directory now answers only your own row, so a fallback would have
      // silently returned nobody rather than erroring.
      expect(src.contains('_directoryRows'), isFalse,
          reason: 'the multi-row table reader is back');
      expect(src.contains(".select('phone, username')"), isFalse);
      expect(src.contains(".select('phone, name')"), isFalse);
      expect(src.contains(".inFilter('phone_hash'"), isFalse);
      // What is left touching the table is own-row only.
      expect(src, contains("rpc('find_people'"));
    });

    test('picking somebody is what asks for their number', () {
      // A screen that LISTS people must not resolve every row — that is the
      // harvest the server-side change exists to stop, and doing it client
      // side would walk straight back into it.
      final service = File('lib/state/account_service.dart').readAsStringSync();
      expect(service, contains('Future<AppUser?> resolvePerson('));

      for (final f in const [
        'lib/screens/find_people_screen.dart',
        'lib/screens/admin_screen.dart',
      ]) {
        expect(File(f).readAsStringSync(), contains('resolvePerson('),
            reason: '$f acts on a search result without resolving it');
      }
      // The marketplace already asked by EXACT handle, so its existing call
      // comes back with a number and needs no second trip.
      expect(File('lib/screens/marketplace_screen.dart').readAsStringSync(),
          contains('searchByUsername(username)'));
    });

    test('the migration carries forward every filter before it', () {
      // find_people is defined three times across the migrations. Replacing
      // it without copying the earlier `and`s quietly reactivates everybody
      // who deactivated — check_sql.sh caught exactly that here once.
      final sql = File('docs/directory_phone_privacy.sql').readAsStringSync();
      expect(sql, contains('coalesce(u.find_by_username, true)'));
      expect(sql, contains('not coalesce(u.hidden, false)'));
      expect(sql, contains('not public.is_locked_out(u.phone)'));
      // The fix itself, and the narrowed table policy behind it.
      expect(sql,
          contains("case when lower(u.username) = q then u.phone else '' end"));
      expect(sql, contains("using (phone = (auth.jwt() ->> 'phone'))"));
      // And the harness applies it, or none of the above is checked.
      expect(File('tool/check_sql.sh').readAsStringSync(),
          contains('docs/directory_phone_privacy.sql'));
    });
  });

  group('A Store price is the App Store price or a spinner', () {
    tearDown(StorePrices.instance.resetForTest);

    Future<void> pumpLabel(WidgetTester tester,
        {required String id, int cents = 999, String suffix = ''}) async {
      await tester.pumpWidget(MaterialApp(
        home: Scaffold(
          body: StorePriceLabel(cents: cents, productId: id, suffix: suffix),
        ),
      ));
      await tester.pump();
    }

    testWidgets('a spinner while the store has not answered', (tester) async {
      // The state that only exists on a phone, and therefore the one nothing
      // covered: hasRealStore is false under `flutter test`.
      StorePrices.instance.resetForTest();
      StorePrices.debugAwaitingStore = true;
      await pumpLabel(tester, id: 'com.okaymessaging.okayai.pro.monthly');

      expect(find.byType(CircularProgressIndicator), findsOneWidget);
      // Emphatically NOT a figure computed from the cents, and not the dash
      // that means "asked and got nothing" either.
      expect(find.textContaining(r'$'), findsNothing);
      expect(find.text(StorePrices.unknownLabel), findsNothing);
    });

    testWidgets('the store price replaces it, suffix and all', (tester) async {
      StorePrices.instance.resetForTest();
      StorePrices.debugAwaitingStore = true;
      StorePrices.instance.debugSet(
        {'p1': r'$12.99'},
        answered: true,
        currencies: {'p1': 'CAD'},
      );
      await pumpLabel(tester, id: 'p1', suffix: '/mo');

      // Apple's own localized string, VERBATIM. Nothing is appended — the
      // purchase sheet prints no currency code either, and a card that does
      // cannot look like the same number even when it is one.
      expect(find.text(r'$12.99/mo'), findsOneWidget);
      expect(find.textContaining('CAD'), findsNothing);
      expect(find.byType(CircularProgressIndicator), findsNothing);
    });

    testWidgets('a product the store never heard of says so, with no /mo',
        (tester) async {
      StorePrices.instance.resetForTest();
      StorePrices.instance.debugSet({'other': r'$1.99'}, answered: true);
      await pumpLabel(tester, id: 'p1', suffix: '/mo');

      expect(find.text(StorePrices.unavailableLabel), findsOneWidget);
      // '/mo' after a placeholder reads as a price of nothing per month.
      expect(find.textContaining('/mo'), findsNothing);
    });

    testWidgets('where nothing is purchasable, no figure at all',
        (tester) async {
      // The web build. There is no store to ask and nothing to buy, so every
      // number on a Store card was invented — the AI pass rendered "$0.00"
      // (its cents are 0, because its price was only ever meant to come from
      // Apple) and storage and tips rendered plain USD nobody would be
      // charged. Proven by probe before this was written.
      StorePrices.instance.resetForTest();
      addTearDown(() => StorePurchases.debugNoStoreOverride = null);
      StorePurchases.debugNoStoreOverride = true;

      await tester.pumpWidget(const MaterialApp(
        home: Scaffold(
          body: StorePriceLabel(cents: 999, productId: 'p1', suffix: '/mo'),
        ),
      ));
      await tester.pump();

      expect(find.textContaining(r'$'), findsNothing);
      expect(find.textContaining('0.00'), findsNothing);
      expect(find.byType(CircularProgressIndicator), findsNothing);
    });

    test('off a phone there is nothing to wait for', () {
      // Web, payments-test mode and the whole suite keep their plain figure —
      // there is no store to be contradicted by, so a spinner would never end.
      StorePrices.instance.resetForTest();
      expect(StorePrices.instance.awaitingStore, isFalse);
      expect(StorePrices.instance.money(999), r'$9.99');
    });

    test('the currency is named in a sentence, never beside a figure', () {
      // The bug this closes is not a wrong number — it is a right one that
      // cannot be read. The US and Canadian stores BOTH format as a bare '$',
      // so a Canadian buyer quoted CA$9.99 sees "$9.99" and reads it as US
      // dollars, and a US buyer quoted US$9.99 sees exactly the same string.
      // Appending the code to the PRICE was tried and was worse (Apple's
      // sheet prints none, so the card stopped looking like the same number),
      // so the code is stated once, away from any amount.
      StorePrices.instance.resetForTest();
      expect(StorePrices.instance.quotedCurrency, '');

      StorePrices.instance.debugSet(
        {'p1': r'$9.99', 'p2': r'$12.99'},
        answered: true,
        currencies: {'p1': 'CAD', 'p2': 'CAD'},
      );
      expect(StorePrices.instance.quotedCurrency, 'CAD');
      // Still verbatim — the sentence carries the code, the price never does.
      expect(StorePrices.instance.money(0, productId: 'p1'), r'$9.99');

      // A store answering in two currencies at once is not a fact to state as
      // one, so the line says nothing rather than picking a side.
      StorePrices.instance.debugSet(
        {'p1': r'$9.99', 'p2': r'$12.99'},
        answered: true,
        currencies: {'p1': 'USD', 'p2': 'CAD'},
      );
      expect(StorePrices.instance.quotedCurrency, '');
      StorePrices.instance.resetForTest();
    });

    test('the diagnostic screen carries the per-product currency code', () {
      // The Store cards deliberately cannot say which dollars they are, so
      // the products check is the one place that must — per row, because a
      // storefront quoting two currencies is exactly the case a single line
      // at the top would hide.
      final src =
          File('lib/screens/store_products_screen.dart').readAsStringSync();
      expect(src, contains('currencies[p.id]'));
      expect(src, contains('currency!.toUpperCase()'));

      // And the Store screen names it once, in prose.
      final store = File('lib/screens/store_screen.dart').readAsStringSync();
      expect(store, contains('quotedCurrency'));

      // The storefront line must not promise the figure IS the charge.
      // TestFlight reports USA and prices from the US store whatever country
      // the account is in (Apple's bug), while billing the real account in
      // its own currency — so that promise was one the app could not keep,
      // and it is Apple's sheet that confirms the amount.
      expect(store.contains('what it will charge'), isFalse,
          reason: 'the storefront line promises the charge again');
      expect(src, contains('IN TESTFLIGHT'),
          reason: 'the diagnostic no longer explains the TestFlight storefront '
              'bug, which is the cause every real report of this has had');
    });

    test('no Store surface can be handed a price string', () {
      // The card used to take `price:` as text, so a caller could pass
      // anything — including a figure the store had never agreed to.
      final store = File('lib/screens/store_screen.dart').readAsStringSync();
      expect(store, contains('priceProductId'));
      expect(store.contains('final String price;'), isFalse,
          reason: 'the card takes a price string again');
      expect(store, contains('StorePriceLabel('));

      // Every purchase surface goes through the one widget or, where a widget
      // cannot go (a button label), says it is loading rather than guessing.
      for (final f in const [
        'lib/screens/cloud_sync_screen.dart',
        'lib/screens/okay_pro_screen.dart',
      ]) {
        final src = File(f).readAsStringSync();
        expect(src, contains('awaitingStore'),
            reason: '$f prints something while the store is still answering');
      }
      expect(File('lib/screens/cloud_sync_screen.dart').readAsStringSync(),
          contains('StorePriceLabel('));
    });
  });

