  group('The floating bar and what has to stay clear of it', () {
    testWidgets('the compose button is not hidden under the bottom bar',
        (t) async {
      // It FLOATS over the tab (home sets extendBody), so the tab's own
      // Scaffold laid its FAB out as if nothing was there — half the button
      // sat behind the glass and half off the bottom-right corner.
      t.view.physicalSize = const Size(390, 844);
      t.view.devicePixelRatio = 1.0;
      addTearDown(t.view.resetPhysicalSize);
      await t.pumpWidget(const OkayMessagingApp());
      await t.pumpAndSettle();
      await t.tap(find.byKey(HomeScreen.debugNavPillKey('Newsfeed')));
      await t.pumpAndSettle();

      final fab = t.getRect(find.byType(FloatingActionButton));
      final bar = t.getRect(find.byType(AppBottomNavBar));
      expect(fab.bottom, lessThanOrEqualTo(bar.top),
          reason: 'the compose button is under the bar again');
      expect(fab.bottom, lessThanOrEqualTo(844),
          reason: 'the compose button runs off the bottom of the screen');
      // Clear of it, not merely above it: 8pt of gap still read as a slab
      // stuck to the bar, corner overlapping the last two pills.
      expect(bar.top - fab.bottom,
          greaterThanOrEqualTo(AppBottomNavBar.floatingGap),
          reason: 'the compose button is crowding the bar');
      // Round, so its corners cannot crowd the bar's own rounded end.
      expect(
          t
              .widget<FloatingActionButton>(find.byType(FloatingActionButton))
              .shape,
          isA<CircleBorder>());
    });

    test('the bar knows how much room it takes', () {
      // Measured, not guessed: 66 is the pills plus their padding, and the
      // FAB clearance is computed from it. If a redesign grows the bar this
      // constant has to grow with it or the button goes back under the glass.
      expect(AppBottomNavBar.contentHeight, 66);
    });

    testWidgets('the bar clears the home indicator without parking above it',
        (t) async {
      // The margin used to be the WHOLE safe-area inset — 34pt on a
      // home-indicator iPhone — which left an empty band under the bar and
      // made it read as floating loose rather than as chrome anchored to the
      // bottom of the screen. The indicator occupies roughly the bottom
      // 21pt, so the bar can come down to 20 and still clear it.
      late double margin;
      late double overlay;
      late double bare;
      await t.pumpWidget(MediaQuery(
        data: const MediaQueryData(viewPadding: EdgeInsets.only(bottom: 34)),
        child: Builder(builder: (inset) {
          margin = AppBottomNavBar.bottomMarginFor(inset);
          overlay = AppBottomNavBar.overlayHeightFor(inset);
          return MediaQuery(
            data: const MediaQueryData(),
            child: Builder(builder: (flat) {
              bare = AppBottomNavBar.bottomMarginFor(flat);
              return const SizedBox();
            }),
          );
        }),
      ));
      expect(margin, lessThan(34),
          reason: 'the bar is parked above an empty band again');
      expect(margin, greaterThanOrEqualTo(20),
          reason: 'the bar is down in the home indicator');
      expect(bare, 10, reason: 'a phone with no inset still needs a margin');
      // The one number every list, FAB and composer clears itself by. If it
      // stops tracking the margin they all go back under the glass.
      expect(overlay, AppBottomNavBar.contentHeight + margin);
    });

