    test('the published legal pages still match what the app shows', () {
      // The App Store needs a reachable Privacy Policy URL, and App Review
      // reads it against what the app says. So the hosted copies are
      // GENERATED from the same constants the in-app screens render — there
      // is no second copy of the text to fall behind. If this fails, run:
      //   dart tool/build_legal_pages.dart
      final privacy = File('web/privacy.html');
      final terms = File('web/terms.html');
      final served = File('supabase/functions/_shared/legal_pages.ts');
      for (final f in [privacy, terms, served]) {
        expect(f.existsSync(), isTrue,
            reason: 'run: dart tool/build_legal_pages.dart');
      }
      final privacyHtml = privacy.readAsStringSync();
      final termsHtml = terms.readAsStringSync();
      final servedTs = served.readAsStringSync();

      // Every section title, in both the static page and the served copy.
      for (final s in privacyPolicy) {
        expect(privacyHtml, contains(s.title),
            reason: '"${s.title}" is missing from the published policy');
        expect(servedTs, contains(s.title));
      }
      for (final s in termsOfService) {
        expect(termsHtml, contains(s.title));
        expect(servedTs, contains(s.title));
      }
      // And the version, so a bumped document cannot ship a stale page.
      expect(privacyHtml, contains('version $legalVersion'));
      expect(termsHtml, contains('version $legalVersion'));
      expect(privacyHtml, contains(legalLastUpdated));

      // The URL that goes to Apple must not name a code host: the owner's
      // repository is not something a submitted link should advertise.
      final fn = File('supabase/functions/pages/index.ts').readAsStringSync();
      expect(fn, contains('case "privacy":'));
      expect(fn, contains('case "terms":'));
      for (final src in [fn, servedTs, privacyHtml, termsHtml]) {
        expect(src.contains('github.io'), isFalse);
        expect(src.contains('github.com'), isFalse);
      }
    });

    group('store images come out the exact size Apple asks for', () {
      img.Image shot(int w, int h, {bool alpha = false}) {
        final i = img.Image(width: w, height: h, numChannels: alpha ? 4 : 3);
        img.fill(i,
            color: alpha
                ? img.ColorRgba8(0, 0, 0, 0)
                : img.ColorRgb8(0x16, 0x18, 0x1C));
        return i;
      }

      test('the sizes App Store Connect accepts are the ones offered', () {
        // Named by pixels, not by inches: Apple moves which device an inch
        // label means, and the upload checks the pixel count.
        expect(kSizes['1290x2796'], (1290, 2796));
        expect(kSizes['1320x2868'], (1320, 2868));
        expect(kSizes['1260x2736'], (1260, 2736));
        // The In-App Purchase promotional image.
        expect(kSizes['1024x1024'], (1024, 1024));
        expect(kDefault, '1290x2796');
      });

      test('a phone-shaped screenshot is resized, never letterboxed', () {
        // 1179x2556 into 1290x2796 is 0.02% out of shape, and 1170x2532 is
        // 0.16% — both invisible, so padding them would add bars for nothing.
        for (final (w, h) in const [(1179, 2556), (1170, 2532)]) {
          final (out, how) = fitForStore(shot(w, h), 1290, 2796, cover: false);
          expect(how, 'resized', reason: '${w}x$h should not need padding');
          expect((out.width, out.height), (1290, 2796));
        }
      });

      test('a shape that really differs is padded, not stretched', () {
        final (out, how) =
            fitForStore(shot(1179, 2556), 1024, 1024, cover: false);
        expect(how, 'padded');
        expect((out.width, out.height), (1024, 1024));
        // Nothing cropped: the phone shot fits inside, so the sides are the
        // fill colour rather than a squashed picture.
        expect(out.getPixel(2, 512).r, out.getPixel(1021, 512).r);
      });

      test('--cover crops to fill instead, for the square promo image', () {
        final (out, how) =
            fitForStore(shot(1179, 2556), 1024, 1024, cover: true);
        expect(how, 'cropped');
        expect((out.width, out.height), (1024, 1024));
      });

      test('every output is flattened — Apple says so for the promo image', () {
        // A PNG saved from an image that still carries an alpha channel is
        // not "flattened", even when every pixel in it happens to be opaque.
        for (final cover in const [true, false]) {
          final (out, _) = fitForStore(shot(800, 800, alpha: true), 1024, 1024,
              cover: cover);
          expect(out.hasAlpha, isFalse);
          expect(out.numChannels, 3);
        }
      });
    });

    group('the demo seed fills the app without inventing anything shared', () {
      final src = File('lib/state/demo_seed.dart').readAsStringSync();

      test('everything it seeds, it can take back', () {
        // clear() promises to undo exactly what populate() did. A demo post
        // added without being listed for removal is litter on the owner's own
        // phone, and the kind nobody notices until it is in a screenshot.
        // The two const lists clear() walks. An id may be USED by index off
        // one of them (which is better than repeating the literal), so what
        // matters is membership, not how many times it is typed.
        final listed = <String>{};
        for (final name in const ['_postIds', '_noteIds']) {
          final block =
              RegExp('$name = \\[(.*?)\\];', dotAll: true).firstMatch(src);
          expect(block, isNotNull, reason: '$name is gone');
          listed.addAll(RegExp(r"'(demo_[a-z0-9_]+)'")
              .allMatches(block!.group(1)!)
              .map((m) => m.group(1)!));
        }
        final used = RegExp(r"'(demo_[plqn][0-9]+)'")
            .allMatches(src)
            .map((m) => m.group(1)!)
            .toSet();
        expect(used, isNotEmpty, reason: 'the id scan found nothing');
        expect(used.difference(listed), isEmpty,
            reason: 'seeded but never listed for clear()');
      });

      test('it never writes to a surface that is not this device\'s', () {
        // The public feed and forum live in real shared tables: content
        // invented here would be invented for everyone, which is the
        // no-fake-data rule at its sharpest.
        for (final forbidden in const [
          'PublicFeedStore',
          'PublicForumStore',
          'publishMarketListing',
          'sendFeedPost',
          'RelayService',
        ]) {
          expect(src.contains(forbidden), isFalse,
              reason: 'the demo seed reaches for $forbidden');
        }
        // And not the score: award() only adds, so seeded points could never
        // be taken back and clear() would be lying.
        expect(src.contains('ScoreStore'), isFalse);
      });

      test('both gates still hold', () {
        // The compile flag hides it from a normal build; the runtime check is
        // the backstop, and populate() re-checks rather than trusting callers.
        expect(src, contains("bool.fromEnvironment('DEMO_SEED'"));
        expect(src, contains('PlatformModeration.instance.canAdminister'));
        expect(
            src.contains(
                'if (!PlatformModeration.instance.canAdminister) return;'),
            isTrue,
            reason: 'populate() stopped checking for itself');
      });
    });

    test('the glass blurs enough to soften and not enough to erase', () {
      // At 24 the backdrop came through as an even wash — transparent in
      // principle, indistinguishable from a flat tint on screen, which is
      // the whole complaint about frosted plastic. The material needs
      // something recognisable behind it to be glass over.
