  group('Liquid Glass: the two things that float over content', () {
    test('both bars wear the SAME material, not two imitations of it', () {
      // Two hand-tuned copies of one material is exactly how they drift.
      for (final f in [
        'lib/screens/home_screen.dart',
        'lib/widgets/chat_input_bar.dart',
      ]) {
        expect(File(f).readAsStringSync(), contains('LiquidGlass('),
            reason: '$f rolls its own glass');
      }
    });

    testWidgets('the pane really blurs its backdrop and lets it through',
        (t) async {
      await t.pumpWidget(const MaterialApp(
        home: Scaffold(body: LiquidGlass(child: SizedBox(height: 60))),
      ));
      await t.pumpAndSettle();
      // Frosting without a blur is just a tint.
      expect(find.byType(BackdropFilter), findsOneWidget);
      // The first attempt sat at 0.44/0.52, which is a slab you cannot see
      // through — a white gradient over a slab is a slab with a gradient on
      // it, which is exactly how it looked. Glass shows the backdrop.
      // Light mode carries a little more than dark: a pale tint on a white
      // screen has to work harder to be there at all (see the raised-panel
      // test), and it is still two thirds backdrop.
      expect(LiquidGlass.tintAlpha(true), lessThan(0.25));
      expect(LiquidGlass.tintAlpha(false), lessThanOrEqualTo(0.30));
      // The web stand-in goes nearly opaque instead, because a live backdrop
      // blur makes CanvasKit re-blur the whole scene every frame.
      expect(LiquidGlass.flatAlpha(true), greaterThan(0.9));
    });

    test('the panel reads as RAISED, never as a hole cut in the screen', () {
      // The bug a real phone showed. The dark tint was #0E1116 — DARKER than
      // the app's #16181C scaffold — so over an empty screen the panel
      // landed at luminance 22.9 against a background of 23.9 and only its
      // hairline was visible. Elevated glass catches light; it never
      // subtracts it.
      double lum(Color c) =>
          0.2126 * (c.r * 255) + 0.7152 * (c.g * 255) + 0.0722 * (c.b * 255);

      const darkScaffold = AppColors.darkSurface;
      final darkPanel = LiquidGlass.over(darkScaffold, isDark: true);
      expect(lum(darkPanel), greaterThan(lum(darkScaffold) + 10),
          reason: 'the bar disappears into the dark background');

      // Light mode is the mirror: a white tint on a white screen vanishes
      // just as completely, so it steps slightly DOWN instead.
      const lightScaffold = AppColors.lightSurface;
      final lightPanel = LiquidGlass.over(lightScaffold, isDark: false);
      expect(lum(lightPanel), lessThan(lum(lightScaffold)),
          reason: 'the bar disappears into the white background');

      // And it is still glass: most of what is behind it survives.
      expect(LiquidGlass.tintAlpha(true), lessThan(0.25));
      expect(LiquidGlass.tintAlpha(false), lessThan(0.35));
    });

    test('the backdrop is made MORE vivid, not greyer', () {
      // A blur alone desaturates, and desaturated-behind-a-panel is what
      // makes frosted plastic look like frosted plastic. Apple's materials
      // push saturation up.
      expect(LiquidGlass.saturation, greaterThan(1.0));
      // The matrix has to be a real saturation matrix: a fully saturated
      // grey input must stay grey, and each row must sum to 1 over RGB or
      // the panel tints everything behind it.
      expect(LiquidGlass.vibrance(isDark: true).toString(),
          contains('ColorFilter.matrix'));
      const s = LiquidGlass.saturation;
      const lr = 0.2126, lg = 0.7152, lb = 0.0722;
      const rowSum = ((1 - s) * lr + s) + ((1 - s) * lg) + ((1 - s) * lb);
      expect(rowSum, closeTo(1.0, 1e-9),
          reason: 'the vibrance matrix shifts hue instead of saturating');
    });

    test('the lens shader ships, and is the thing a gradient cannot fake', () {
      // An edge that only blurs has no thickness. Bending what is behind it
      // is the signature of the material, and it needs a real shader.
      final frag = File('assets/shaders/liquid_glass.frag');
      expect(frag.existsSync(), isTrue);
      final src = frag.readAsStringSync();
      // The uniform ORDER is the engine's contract: the first vec2 is the
      // bound texture size, written by the engine, and the first sampler2D
      // is the filter input.
      expect(src.indexOf('uniform vec2 uSize'), greaterThan(-1));
      expect(src.indexOf('uniform vec2 uSize'),
          lessThan(src.indexOf('uniform sampler2D')));
      expect(src, contains('roundedBoxSdf'));
      // And it must be registered, or fromAsset finds nothing and the panel
      // silently falls back to a blur nobody notices is missing.
      final pubspec = File('pubspec.yaml').readAsStringSync();
      expect(pubspec, contains('shaders:'));
      expect(pubspec, contains('assets/shaders/liquid_glass.frag'));
    });

    test('the size uniform is left to the engine', () {
      // Indices 0 and 1 are uSize, which the engine writes. Setting them
      // would overwrite the one thing the shader can trust — and asking the
      // widget for its size does not work anyway, because a
      // bottomNavigationBar is laid out with an unbounded height.
      final src = File('lib/widgets/liquid_glass.dart').readAsStringSync();
      expect(src, isNot(contains('setFloat(0,')));
      expect(src, isNot(contains('setFloat(1,')));
      expect(src, contains('setFloat(2,'));
    });

    testWidgets('no shader, no breakage — it degrades to blur', (t) async {
      // Impeller off (web, an older engine) throws outright from
      // ImageFilter.shader. That must cost the refraction and nothing else.
      LiquidGlass.resetShaderForTest();
      addTearDown(LiquidGlass.resetShaderForTest);
      await t.pumpWidget(const MaterialApp(
        home: Scaffold(body: LiquidGlass(child: SizedBox(height: 60))),
      ));
      await t.pumpAndSettle();
      expect(t.takeException(), isNull);
      expect(find.byType(BackdropFilter), findsOneWidget);
    });

    testWidgets('the bar floats over a pushed screen, not in a slot below it',
        (t) async {
      await t.pumpWidget(const MaterialApp(home: SportsScreen()));
      await t.pumpAndSettle();
      final scaffold = t.widget<Scaffold>(find.byType(Scaffold).first);
      expect(scaffold.extendBody, isTrue);
    });

    test('every floating-bar screen extends its body under the glass', () {
      // extendBody without the padding leaves the last row unreachable
      // beneath the bar, so the two go together or neither does.
      for (final f in [
        'lib/screens/weather_screen.dart',
        'lib/screens/sports_screen.dart',
        'lib/screens/store_screen.dart',
        'lib/screens/settings_screen.dart',
        'lib/screens/wallet_screen.dart',
        'lib/screens/public_forum_screen.dart',
      ]) {
        final src = File(f).readAsStringSync();
        expect(src, contains('extendBody: true'), reason: '$f does not float');
        expect(src, contains('HomeNavBar.clearance(context)'),
            reason: '$f floats the bar over content it never padded for');
      }
    });
  });

  group('The forum card leads with the title', () {
    test('the vote pill is not a column pinned to the left any more', () {
      // Old-Reddit-on-desktop: it cost the title about a third of the card
      // on a phone, and pushed the byline and the headline both inward.
      final src =
          File('lib/screens/public_forum_screen.dart').readAsStringSync();
      final card = src.substring(src.indexOf('class _ForumPostCard'),
          src.indexOf('class _ForumAction'));
      // The byline comes first, then the title, then the actions.
      final byline = card.indexOf('FeedPostHeader');
      final title = card.indexOf('Text(post.title');
      final votes = card.indexOf('ForumVotePill');
      expect(byline, lessThan(title));
      expect(title, lessThan(votes),
          reason: 'the title must lead, with the votes in the action row');
    });

    test('a pasted essay cannot push every other title off the screen', () {
      // A card is a preview, and a board is a list of titles.
      expect(forumCardBodyLines, lessThanOrEqualTo(6));
    });

    test('both boards cap through the SAME shared body widget', () {
      // A private copy of the preview was written first, and it quietly cost
      // the public card its tappable mentions, hashtags and links, plus the
      // "Show more" every other surface has — while leaving the in-server
      // board on a different cap. One widget, one constant, four surfaces.
      for (final f in [
        'lib/screens/public_forum_screen.dart',
        'lib/screens/forum_screen.dart',
      ]) {
        final src = File(f).readAsStringSync();
        expect(src, contains('maxLines: forumCardBodyLines'),
            reason: '$f does not share the board cap');
      }
      // And the copy is gone rather than merely unused.
      expect(File('lib/screens/public_forum_screen.dart').readAsStringSync(),
          isNot(contains('_BodyPreview')));
    });
  });

  group('The newsfeed wears the mark, not the icon tile', () {
    // The tile is a home-screen icon: a white bubble on a near-black square.
    // In an app bar that square is a sticker — neither bar is that colour.
    // BrandMark uses the PNG as a luminance mask instead, so what is left is
    // the bubble in the bar's own ink. Checked against the REAL asset's own
    // pixels, because the arithmetic IS the result here and no screenshot can
    // be taken from this box.
    late img.Image icon;

    setUpAll(() {
      icon = img.decodePng(File('assets/icon/icon.png').readAsBytesSync())!;
    });

    double alphaAt(int x, int y) {
      final p = icon.getPixel(x, y);
      return BrandMark.alphaFor(p.r.round(), p.g.round(), p.b.round());
    }

    test('the tile is erased outright, not merely faded', () {
      // Every corner is tile. Plain luminance would leave these near 8% — a
      // grey ghost of the square, which is the whole thing being removed.
      for (final (x, y) in [
        (2, 2),
        (icon.width - 3, 2),
        (2, icon.height - 3),
        (icon.width - 3, icon.height - 3),
      ]) {
        expect(alphaAt(x, y), lessThanOrEqualTo(0),
            reason: 'tile pixel at $x,$y survives as a ghost square');
      }
    });

    test('the bubble survives at full strength', () {
      // Well inside the bubble and clear of the three dots.
      expect(alphaAt(icon.width ~/ 2, (icon.height * 0.28).round()),
          greaterThanOrEqualTo(255));
    });

    test('the three dots stay holes, so it reads as a bubble', () {
      // They are painted in the tile colour, so the same mask that drops the
      // square drops them — which is what keeps the mark from filling in to a
      // featureless blob.
      expect(alphaAt((icon.width * 0.5).round(), (icon.height * 0.45).round()),
          lessThanOrEqualTo(0));
    });

    test('the newsfeed draws it bigger, and no longer draws the tile', () {
      final src =
          File('lib/screens/public_feed_screen.dart').readAsStringSync();
      expect(src.contains('BrandMark(size: 34'), isTrue);
      // The raw asset (and the rounded-corner clip that tried to soften it)
      // are gone from the screen — one way to draw the mark, one place to
      // change it.
      expect(src.contains("Image.asset('assets/icon/icon.png'"), isFalse);
    });
  });

  group('a message says which key protected it', () {
    test('the wire rungs map to the four pairwise answers', () {
      expect(EncryptionLabel.fromWire(3), EncryptionKind.ratchet);
      expect(EncryptionLabel.fromWire(2), EncryptionKind.keyExchange);
      expect(EncryptionLabel.fromWire(1), EncryptionKind.basic);
      expect(EncryptionLabel.fromWire(0), EncryptionKind.none);
      // The wire has carried these as strings and, on the oldest builds, as
      // `true` for the floor rung. openContent reads both; so must this, or
      // the same message would render "not encrypted" in the info dialog
      // while decrypting perfectly.
      expect(EncryptionLabel.fromWire('3'), EncryptionKind.ratchet);
      expect(EncryptionLabel.fromWire(true), EncryptionKind.basic);
    });

    test('a payload cannot claim a community rung', () {
      // 4 and 5 are local bookkeeping for the server bus, which carries no
      // `enc` field at all. A payload naming one is not a stronger message,
      // it is a payload lying — so it reads as no record rather than as the
      // signed sender-key chain it is pretending to be.
      expect(EncryptionLabel.fromWire(4), EncryptionKind.unknown);
      expect(EncryptionLabel.fromWire(5), EncryptionKind.unknown);
      expect(EncryptionLabel.fromWire(99), EncryptionKind.unknown);
      expect(EncryptionLabel.fromWire(-1), EncryptionKind.unknown);
    });

    test('a payload with no enc at all is the plaintext wire, not a mystery',
        () {
      // The oldest format carried its fields at the top level in the clear.
      // Saying "not recorded" about it would hide the one case worth seeing.
      expect(EncryptionLabel.fromWire(null), EncryptionKind.none);
    });

    test('only the two honest failures read as unencrypted', () {
      for (final k in EncryptionKind.values) {
        final encrypted = EncryptionLabel.isEncrypted(k);
        expect(
            encrypted, k != EncryptionKind.none && k != EncryptionKind.unknown,
            reason: '$k');
        // An open padlock is reserved for exactly those two.
        expect(EncryptionNote.iconFor(k),
            encrypted ? Icons.lock_outline : Icons.lock_open);
      }
    });

    test('every rung has words, and codes round-trip', () {
      for (final k in EncryptionKind.values) {
        expect(EncryptionLabel.title(k), isNotEmpty, reason: '$k');
        expect(EncryptionLabel.detail(k).length, greaterThan(30), reason: '$k');
        expect(EncryptionLabel.fromCode(EncryptionLabel.codeOf(k)), k);
      }
      // Nothing unreadable reads as a rung.
      expect(EncryptionLabel.fromCode(null), EncryptionKind.unknown);
      expect(EncryptionLabel.fromCode(42), EncryptionKind.unknown);
    });

    test('the copy names the two things that are worse than the headline', () {
      // A shared server key and no key at all are both weaker than "end-to-end
      // encrypted", and the whole point of showing this is that they say so.
      expect(EncryptionLabel.title(EncryptionKind.none), 'Not encrypted');
      expect(EncryptionLabel.detail(EncryptionKind.none),
          contains('the relay could read it'));
      expect(EncryptionLabel.detail(EncryptionKind.serverSecret),
          contains('every member of this server holds'));
      // ...and the strongest one claims only what it earns.
      expect(EncryptionLabel.detail(EncryptionKind.ratchet),
          contains('a key stolen later cannot unlock it'));
    });

    test('an incoming message records the rung it really arrived under', () {
      final store = ChatStore.instance;
      store.hydrate(const {'chats': []});
      addTearDown(store.reset);
      final body = jsonEncode({'text': 'sealed hello'});
      RelayService.applyIncoming({
        'from': '+1 555 0188',
        'id': 'enc_1',
        'ts': DateTime.now().toIso8601String(),
        'c': E2eCrypto.encrypt(E2eCrypto.keyFor('15550188', '15550100'), body),
        'enc': 1,
      }, myPhone: '+1 555 0100', store: store);
      final msg = store.allChats
          .expand((c) => c.messages)
          .firstWhere((m) => m.id == 'enc_1');
      expect(msg.encryptionKind, EncryptionKind.basic);

      // A legacy top-level payload was never sealed, and says so rather than
      // borrowing the rung of the message before it.
      RelayService.applyIncoming({
        'from': '+1 555 0188',
        'id': 'enc_2',
        'ts': DateTime.now().toIso8601String(),
        'text': 'in the clear',
      }, myPhone: '+1 555 0100', store: store);
      final legacy = store.allChats
          .expand((c) => c.messages)
          .firstWhere((m) => m.id == 'enc_2');
      expect(legacy.encryptionKind, EncryptionKind.none);
    });

    test('the recorded rung only ever lowers', () {
      // A group send seals once per member and members are not all on the
      // same rung. Recording the last one would let one strong delivery
      // vouch for a message that also went out under the floor key.
      final store = ChatStore.instance;
      store.hydrate(const {'chats': []});
      addTearDown(store.reset);
      const chat = Chat(
        id: 'chat_enc',
        contact: AppUser(
            id: 'u', name: 'Ada', avatarColor: '#111111', phone: '+15550199'),
        messages: [],
      );
      store.upsert(chat);
      store.addMessage('chat_enc',
          Message(id: 'm1', text: 'hi', time: DateTime.now(), isMe: true));

      store.noteMessageEnc('chat_enc', 'm1', EncryptionLabel.codeRatchet);
      expect(store.chatById('chat_enc')!.messages.single.encryptionKind,
          EncryptionKind.ratchet);
      store.noteMessageEnc('chat_enc', 'm1', EncryptionLabel.codeBasic);
      expect(store.chatById('chat_enc')!.messages.single.encryptionKind,
          EncryptionKind.basic,
          reason: 'the weakest delivery is the honest answer');
      store.noteMessageEnc('chat_enc', 'm1', EncryptionLabel.codeRatchet);
      expect(store.chatById('chat_enc')!.messages.single.encryptionKind,
          EncryptionKind.basic,
          reason: 'a later strong recipient must not raise it back');
    });

    test('a channel message records the server-bus key, not the chat ladder',
        () {
      CommunityStore.instance.resetForTest();
      final store = CommunityStore.instance;
      final c = store.createCommunity('Crew');
      final chan = store.byId(c.id)!.channels.first;
      store.postMessage(c.id, chan.id,
          Message(id: 'cm1', text: 'hi', time: DateTime.now(), isMe: true));
      // Nothing sealed it yet — an unsent message must not claim a key.
      expect(store.byId(c.id)!.channels.first.messages.single.encryptionKind,
          EncryptionKind.unknown);

      store.noteChannelMessageEnc(
          c.id, chan.id, 'cm1', EncryptionLabel.codeSenderKey);
      expect(store.byId(c.id)!.channels.first.messages.single.encryptionKind,
          EncryptionKind.senderKey);
    });

    test('both message-info surfaces read from the one vocabulary', () {
      // Chat and channels ride different ladders; if either wrote its own
      // sentence, one of them would end up describing encryption the message
      // never had.
      final chat = File('lib/screens/chat_screen.dart').readAsStringSync();
      expect(chat.contains('EncryptionNote.of(message)'), isTrue);
      final channels = File('lib/screens/communities.dart').readAsStringSync();
      expect(channels.contains('showChannelMessageInfo(context, message)'),
          isTrue);
      // Neither may hand-roll the words.
      for (final src in [chat, channels]) {
        expect(src.contains('Double Ratchet'), isFalse,
            reason: 'the rung copy lives in encryption_label.dart only');
      }
    });

    testWidgets('the info dialog shows the key, in plain words',
        (tester) async {
      await tester.pumpWidget(MaterialApp(
        home: Builder(
          builder: (context) => Scaffold(
            body: TextButton(
              onPressed: () => showChannelMessageInfo(
                  context,
                  Message(
                      id: 'x',
                      text: 'hi',
                      time: DateTime(2026, 8, 11, 9, 30),
                      isMe: false,
                      enc: EncryptionLabel.codeSenderKey)),
              child: const Text('open'),
            ),
          ),
        ),
      ));
      await tester.tap(find.text('open'));
      await tester.pumpAndSettle();
      expect(find.text('Message info'), findsOneWidget);
      expect(find.text(EncryptionLabel.title(EncryptionKind.senderKey)),
          findsOneWidget);
      expect(find.textContaining('signed so no other member'), findsOneWidget);
    });
  });

  group('public composers say they are not encrypted', () {
    test('all three public surfaces carry the note', () {
      // These are the only places in the app where somebody types into
      // something the server can read. Every other composer is sealed before
      // it leaves the device, which is exactly why this needs saying.
      for (final f in const [
        'lib/screens/public_feed_screen.dart',
        'lib/screens/public_forum_screen.dart',
        'lib/screens/marketplace_screen.dart',
      ]) {
        expect(File(f).readAsStringSync().contains('PublicContentNote'), isTrue,
            reason: '$f composes public content and must say so');
      }
    });

    test('a SEALED surface never claims to be public', () {
      // A server's own feed and its forum board really are sealed under the
      // community bus. The same line there would be a lie, and the worse
      // direction of lie than the one this feature exists to stop.
      for (final f in const [
        'lib/screens/feed_screen.dart',
        'lib/screens/forum_screen.dart',
        'lib/screens/communities.dart',
        'lib/screens/chat_screen.dart',
      ]) {
        expect(
            File(f).readAsStringSync().contains('PublicContentNote'), isFalse,
            reason: '$f is sealed — it must not warn about a leak it has not');
      }
    });

    testWidgets('the line names who can read it, and that it is not sealed',
        (tester) async {
      await tester.pumpWidget(const MaterialApp(
          home: Scaffold(body: PublicContentNote(what: 'listing'))));
      expect(find.text('Anyone can read this listing — it is not encrypted.'),
          findsOneWidget);
      // The open padlock, the same glyph the message-info line uses for the
      // two answers that are not sealed.
      expect(tester.widget<Icon>(find.byType(Icon)).icon, Icons.lock_open);
    });

    testWidgets('a paid post narrows WHO, not whether', (tester) async {
      // The paywall is access control — the server still reads the body to
      // screen it, which is the documented reason paid posts are not sealed.
      await tester.pumpWidget(const MaterialApp(
          home: Scaffold(body: PublicContentNote(who: 'Your subscribers'))));
      expect(
          find.text('Your subscribers can read this post — it is not '
              'encrypted.'),
          findsOneWidget);
    });
  });

  group('On-device drafting, and the hosted fallback', () {
    setUp(() => OnDeviceDraft.instance.resetForTest());
    tearDown(() => OnDeviceDraft.instance.resetForTest());

    test('a device that cannot generate drafts nothing at all', () async {
      // Same rule as SmartReplies: most iPhones have no Apple Intelligence
      // and the web build has no channel. Silence here is what tells
      // AiAssistant.draft() to fall back to the hosted function rather than
      // surface a made-up draft.
      OnDeviceDraft.debugAvailableOverride = false;
      final draft = await OnDeviceDraft.instance.draft('ask to reschedule');
      expect(draft, isNull);
    });

    test('a blank instruction never reaches the channel', () async {
      OnDeviceDraft.debugAvailableOverride = true;
      var called = false;
      OnDeviceDraft.debugDraftOverride = (_) async {
        called = true;
        return 'x';
      };
      expect(await OnDeviceDraft.instance.draft('   '), isNull);
      expect(called, isFalse);
    });

    test('a blank or null channel answer reads as no draft', () async {
      OnDeviceDraft.debugAvailableOverride = true;
      OnDeviceDraft.debugDraftOverride = (_) async => null;
      expect(await OnDeviceDraft.instance.draft('say hi'), isNull);
      OnDeviceDraft.debugDraftOverride = (_) async => '   ';
      expect(await OnDeviceDraft.instance.draft('say hi'), isNull);
    });

    test('a real draft is trimmed and returned', () async {
      OnDeviceDraft.debugAvailableOverride = true;
      OnDeviceDraft.debugDraftOverride =
          (i) async => '  Sounds good, see you then!  ';
      expect(await OnDeviceDraft.instance.draft('confirm the plan'),
          'Sounds good, see you then!');
    });

    test('AiAssistant.draft() tries the device before the network', () async {
      // The whole point: when the on-device model answers, the hosted
      // function must never be called — that is what makes it free.
      OnDeviceDraft.debugAvailableOverride = true;
      OnDeviceDraft.debugDraftOverride = (i) async => 'On-device: $i';
      var hostedCalled = false;
      AiAssistant.debugReplyOverride = (_) async {
        hostedCalled = true;
        return 'hosted answer';
      };
      final draft = await AiAssistant.instance.draft('ask to reschedule');
      expect(draft, 'On-device: ask to reschedule');
      expect(hostedCalled, isFalse);
    });

    test(
        'AiAssistant.draft() falls back to the hosted function when the '
        'device declines', () async {
      OnDeviceDraft.debugAvailableOverride = false;
      AiAssistant.debugReplyOverride = (_) async => 'hosted answer';
      final draft = await AiAssistant.instance.draft('ask to reschedule');
      expect(draft, 'hosted answer');
    });

    test('the on-device path is still a one-shot instruction, nothing more',
        () {
      // The channel file itself must never be able to see a conversation —
      // the same wall ai_assistant.dart is held to, checked on its own file
      // so nothing widens the interface later without this failing.
      final src = File('lib/state/on_device_draft.dart').readAsStringSync();
      for (final banned in [
        'ChatStore',
        'RelayService',
        'double_ratchet',
        'sealed_sender',
        'http.',
        'Supabase',
      ]) {
        expect(src.contains(banned), isFalse,
            reason: 'on_device_draft.dart must stay a one-shot channel; '
                'found "$banned"');
      }
    });

    test('the Swift side takes only the instruction, never a transcript', () {
      final src = File('ios/Runner/AiDraft.swift').readAsStringSync();
      expect(src.contains('"instruction"'), isTrue);
      // SmartReplies.swift's channel is the one that takes a transcript —
      // this file must not grow that argument too.
      expect(src.contains('"transcript"'), isFalse);
      // Same two-guard shape as SmartReplies.swift: compile-time AND runtime.
      expect(src.contains('#if canImport(FoundationModels)'), isTrue);
      expect(src.contains('#available(iOS 26.0'), isTrue);
    });
  });

  group('store payment disclosures are accurate, not just present', () {
    testWidgets(
        'PassBillingNote states the one fact all four sellers of a '
        '30-day pass depend on', (tester) async {
      await tester.pumpWidget(
          const MaterialApp(home: Scaffold(body: PassBillingNote())));
      // The two claims that matter: charged ONCE (not recurring), and
      // NOTHING appears in Settings → Subscriptions for it. A reader who
      // goes looking there to "cancel" a pass would find nothing — this is
      // the sentence that stops them expecting to.
      expect(find.textContaining('NOT a'), findsOneWidget);
      expect(find.textContaining('nothing appears in Settings → Subscriptions'),
          findsOneWidget);
    });

    test(
        'the three 30-day passes really are consumables, not '
        'auto-renewing subscriptions — the fact PassBillingNote asserts', () {
      // If any of these ever flipped to `consumable: false` (or storage
      // flipped to true), PassBillingNote's promise ("does not renew on its
      // own") would become false for a real charge. Pinning the mechanism
      // next to the copy is what keeps the two from drifting apart.
      final src = File('lib/payments/store_purchases.dart').readAsStringSync();
      // buyCreatorSub, buyCommunitySub, buyAiPass, tip — all consumable.
      expect('consumable: true'.allMatches(src).length, 4);
      // buyStorage — the one real auto-renewing subscription.
      expect('consumable: false'.allMatches(src).length, 1);
    });

    test(
        'Store screen: no single sentence claims every product here can be '
        'cancelled in Settings → Subscriptions', () {
      final src = File('lib/screens/store_screen.dart').readAsStringSync();
      // The old blanket line was true only for storage and wrong for the
      // AI pass, tips, creator subs and paid servers — none of which ever
      // appears in Settings → Subscriptions.
      expect(
          src.contains(
              'Billed by the App Store. Cancel in Settings → your name → '
              'Subscriptions.'),
          isFalse);
      expect(src, contains('Cloud storage renews automatically'));
      expect(src, contains('does not renew on its own'));
      // The AI Pro card carries its own billing note rather than leaving the
      // reader to infer it from the page footer.
      expect(src, contains('extra: const PassBillingNote()'));
    });

    test('the AI upgrade sheet shows a real price before it charges one', () {
      // It used to say "Subscribe to Okay AI" with no amount anywhere on the
      // sheet — the App Store's own confirmation was the first place a price
      // appeared at all.
      final src = File('lib/screens/ai_chat_screen.dart').readAsStringSync();
      expect(src, contains('StorePriceLabel('));
      expect(src, contains('productId: StorePurchases.aiPassProductId'));
      expect(src, contains('const PassBillingNote()'));
      expect(src.contains("const Text('Subscribe to Okay AI')"), isFalse);
    });

    // A rendered price suffix, not a stray substring match: a digit (the
    // last digit of a price, e.g. "12.99") immediately followed by "/mo"
    // and a closing quote. A blunt `contains('/mo')` also matches
    // "models/user.dart" in every import block and any explanatory comment
    // that names the string being removed — this pattern matches neither.
    bool endsPriceStringWithMo(String src) =>
        RegExp('\\d/mo[\'"]').hasMatch(src);

    test(
        'creator-sub and paid-server sheets carry the billing note and no '
        'longer say "/mo" for a pass that does not auto-renew', () {
      for (final f in const [
        'lib/widgets/subscribe_sheet.dart',
        'lib/widgets/message_bubble.dart',
      ]) {
        final src = File(f).readAsStringSync();
        expect(src.contains('PassBillingNote()'), isTrue, reason: f);
        expect(endsPriceStringWithMo(src), isFalse,
            reason: '$f still shows "/mo", which reads as auto-renewing');
      }
    });

    test('every non-storage price label says "30 days", not "/mo"', () {
      // A sweep, not a single site: the creator-sub price is echoed on the
      // subscribe sheet, the profile button, the paid-post lock badge, the
      // composer's paywall chip, the marketplace seller card and the
      // creator's own tier editor — six places a stray "/mo" could survive
      // a partial fix.
      for (final f in const [
        'lib/screens/public_feed_screen.dart',
        'lib/screens/marketplace_screen.dart',
        'lib/screens/edit_profile_screen.dart',
      ]) {
        final src = File(f).readAsStringSync();
        expect(endsPriceStringWithMo(src), isFalse, reason: f);
      }
    });
  });

  group('A one-time code is one length, and the server has to agree', () {
    // Found live (2026-08-16) with the owner's own token: the project's
    // mailer_otp_length was 8 while this screen's field was hard-limited to
    // 6 and auto-submitted at exactly 6 — so an emailed sign-in code could
    // not be typed in AT ALL, and answered "That code is wrong or has
    // expired." every time. The project is now 6. Nothing in a test can
    // reach that setting, so what is pinned here is the client half: one
    // number, read everywhere, so the three sites cannot drift apart again
    // and so there is one place to change if the server's ever moves.

    test('every site reads the one constant, and none carries a bare 6', () {
      final src =
          File('lib/screens/auth/phone_login_screen.dart').readAsStringSync();
      expect(PhoneLoginScreen.otpLength, 6);
      expect(
          src.contains(
              'LengthLimitingTextInputFormatter(PhoneLoginScreen.otpLength)'),
          isTrue,
          reason: 'the input limit');
      expect(src.contains('v.length == PhoneLoginScreen.otpLength'), isTrue,
          reason: 'the verify-as-soon-as-it-is-full rule');
      expect(src.contains('i < PhoneLoginScreen.otpLength'), isTrue,
          reason: 'the row of boxes');
      // The bare forms that used to sit in all three.
      expect(src.contains('LengthLimitingTextInputFormatter(6)'), isFalse);
      expect(src.contains('v.length == 6'), isFalse);
    });
  });

